const _t_body_language_extracted = [
{
    id: "body-language-extracted",
    name: "18. The Dictionary of Body Language",
    categories: [
      { id: "body-language-extracted", name: "Body Language Terms", color: "#fde68a" }
    ],
    entries: [      { concept: "SILENCE AND FREEZE RESPONSE", definition: "When a person suddenly goes silent and stops moving or undergoes breathing changes upon hearing or seeing something, take note", category: "body-language-extracted", real_world_scenario: "At the police station, a suspect who had been talking freely went suddenly quiet and sat completely still when asked where he had been on Friday night; his stillness and silence flagged the question as a threat.", case_study_cloze: "In the negotiation, the buyer's sudden ____ and motionlessness signaled that the price point had triggered something important.", sv: { concept: "Tystnad och frysrespons", definition: "N\u00e4r en person pl\u00f6tsligt tystnar och slutar r\u00f6ra sig eller \u00e4ndrar andning efter att ha h\u00f6rt eller sett n\u00e5got, b\u00f6r man l\u00e4gga m\u00e4rke till det", real_world_scenario: "P\u00e5 polisstationen tystnade en misst\u00e4nkt som tidigare pratat fritt och satt helt stilla n\u00e4r han fick fr\u00e5gan om var han varit fredagskv\u00e4llen \u2013 stillheten och tystnaden avsl\u00f6jade att fr\u00e5gan uppfattades som ett hot.", case_study_cloze: "I f\u00f6rhandlingen signalerade k\u00f6parens pl\u00f6tsliga ____ och stillhet att priset hade utl\u00f6st n\u00e5got viktigt." } },
      { concept: "SPEED OF RESPONSE", definition: "Some people will take their time answering a question, starting, then stopping, then continuing", category: "body-language-extracted", real_world_scenario: "In the courtroom, the witness began answering the lawyer's question, stopped mid-word, stared at the ceiling, and only then finished her sentence; the halting delivery suggested she was carefully constructing her answer.", case_study_cloze: "When asked about the missing money, the accountant started to answer, ____, and continued only after a long pause.", sv: { concept: "Svarstakt", definition: "En del m\u00e4nniskor tar god tid p\u00e5 sig att svara p\u00e5 en fr\u00e5ga \u2013 de b\u00f6rjar, avbryter sig och forts\u00e4tter sedan", real_world_scenario: "I r\u00e4ttssalen b\u00f6rjade vittnet besvara advokatens fr\u00e5ga, avbr\u00f6t sig mitt i en mening, stirrade i taket och fortsatte f\u00f6rst d\u00e4refter; det haltande framf\u00f6randet antydde att hon noga byggde upp sitt svar.", case_study_cloze: "N\u00e4r revisorn fick fr\u00e5gan om de f\u00f6rsvunna pengarna b\u00f6rjade han svara, ____, och fortsatte f\u00f6rst efter en l\u00e5ng paus." } },
      { concept: "WRIST BEHAVIORS", definition: "We might not think of the wrists as a window into the mind, but they can be", category: "body-language-extracted", real_world_scenario: "On their first date, the woman kept placing her hands on the table with her palms up and her wrists exposed toward her date, letting the thin skin of her wrists show; her comfort was visible in a body part she never thought about.", case_study_cloze: "During the interview, the relaxed candidate rested her hands palm up with her ____ exposed, a sign that she felt at ease.", sv: { concept: "Handledsbeteenden", definition: "Vi t\u00e4nker s\u00e4llan p\u00e5 handlederna som ett f\u00f6nster in i sinnet, men det kan de vara", real_world_scenario: "P\u00e5 sin f\u00f6rsta dejt lade kvinnan upprepade g\u00e5nger h\u00e4nderna p\u00e5 bordet med handflatorna upp\u00e5t och handlederna blottade mot sin dejt, s\u00e5 att den tunna huden p\u00e5 handlederna syntes; hennes v\u00e4lbefinnande syntes i en kroppsdel hon sj\u00e4lv aldrig t\u00e4nkte p\u00e5.", case_study_cloze: "Under intervjun satt den avslappnade kandidaten med handflatorna upp\u00e5t och blottade ____, ett tecken p\u00e5 att hon k\u00e4nde sig trygg." } },
      { concept: "TOUCH AND SOCIAL STATUS", definition: "In most cultures, whom we can touch, and how, is dictated by social convention", category: "body-language-extracted", real_world_scenario: "At the company gala, the senior vice president rested a hand on the shoulder of a young trainee while congratulating him, yet no one at the table would have dreamed of touching the vice president the same way.", case_study_cloze: "The director touched the intern's shoulder warmly, but the intern would never touch him back, because ____ is dictated by social convention.", sv: { concept: "Ber\u00f6ring och social status", definition: "I de flesta kulturer avg\u00f6r sociala konventioner vem vi f\u00e5r r\u00f6ra vid, och hur", real_world_scenario: "P\u00e5 f\u00f6retagets galamiddag lade vice vd:n en hand p\u00e5 axeln av en ung praktikant n\u00e4r han gratulerade honom, men ingen vid bordet skulle ens ha dr\u00f6mt om att ber\u00f6ra vice vd:n p\u00e5 samma s\u00e4tt.", case_study_cloze: "Regiss\u00f6ren r\u00f6rde varmt vid praktikantens axel, men praktikanten skulle aldrig r\u00f6ra tillbaka, eftersom ____ styrs av sociala konventioner." } },
      { concept: "CLINGING BEHAVIORS", definition: "When children are under stress, they will grab the clothing of the nearest relative for comfort", category: "body-language-extracted", real_world_scenario: "At the crowded airport, the little boy gripped his mother's jacket sleeve and pulled himself against her leg every time an announcement blared over the speakers; the fabric in his fist was his safety anchor.", case_study_cloze: "In the hospital waiting room, the frightened girl grabbed the clothing of her nearest relative, a classic ____ under stress.", sv: { concept: "Klammerbeteenden", definition: "N\u00e4r barn uts\u00e4tts f\u00f6r stress griper de tag i den n\u00e4rmaste anh\u00f6rigens kl\u00e4der f\u00f6r att f\u00e5 tr\u00f6st", real_world_scenario: "P\u00e5 den myllrande flygplatsen grep den lilla pojken tag i mammans jack\u00e4rm och tryckte sig mot hennes ben varje g\u00e5ng ett utrop h\u00f6rdes i h\u00f6gtalarna; tyget i hans hand var hans trygghetsankare.", case_study_cloze: "I sjukhusets v\u00e4ntrum grep den skr\u00e4mda flickan tag i sin n\u00e4rmaste anh\u00f6rigs kl\u00e4der \u2013 ett klassiskt ____ under stress." } },
      { concept: "WALKING BEHAVIORS", definition: "The way we walk communicates a lot", category: "body-language-extracted", real_world_scenario: "The manager recognized her employee's mood before he said a word: the slow shuffle through the office door, shoulders rolled forward and eyes on the floor, said more than any greeting could.", case_study_cloze: "Before he even spoke, the slumped shoulders and dragging step told the boss that the meeting would not go well \u2013 the way we ____ communicates a lot.", sv: { concept: "G\u00e5ngbeteenden", definition: "S\u00e4ttet vi g\u00e5r p\u00e5 kommunicerar mycket", real_world_scenario: "Chefen k\u00e4nde igen sin medarbetares hum\u00f6r innan han sagt ett ord: det l\u00e5ngsamma, sl\u00e4pande steget genom kontorsd\u00f6rren med fram\u00e5tlutade axlar och blicken i golvet sa mer \u00e4n n\u00e5gon h\u00e4lsning kunde g\u00f6ra.", case_study_cloze: "Innan han ens talade avsl\u00f6jade de sjunkna axlarna och det sl\u00e4pande steget f\u00f6r chefen att m\u00f6tet inte skulle g\u00e5 bra \u2013 s\u00e4ttet vi ____ p\u00e5 kommunicerar mycket." } },
      { concept: "SITTING BEHAVIORS", definition: "Each culture sits differently", category: "body-language-extracted", real_world_scenario: "At the international conference, the Japanese delegates sat upright with hands resting on their knees while the Scandinavian visitors leaned back and crossed their legs \u2013 each culture has its own way of sitting.", case_study_cloze: "In the meeting the differences were striking: some sat cross-legged, others bolt upright, because each culture ____ differently.", sv: { concept: "Sittbeteenden", definition: "Varje kultur sitter p\u00e5 olika s\u00e4tt", real_world_scenario: "P\u00e5 den internationella konferensen satt de japanska delegaterna raka i ryggen med h\u00e4nderna vilande p\u00e5 kn\u00e4na medan de skandinaviska bes\u00f6karna lutade sig tillbaka och lade benen i kors \u2013 varje kultur har sitt eget s\u00e4tt att sitta.", case_study_cloze: "Under m\u00f6tet var skillnaderna sl\u00e5ende: n\u00e5gra satt med benen i kors, andra spikrakt, eftersom varje kultur ____ p\u00e5 olika s\u00e4tt." } },
      { concept: "TRUE SMILE -A topic", definition: "the mouth and the muscles around the eyes", category: "body-language-extracted", real_world_scenario: "When the grandmother opened the birthday gift, her eyes crinkled and the muscles around her eyes tightened along with her mouth \u2013 a true smile that no one could fake.", case_study_cloze: "The real smile reaches not only the mouth but also the ____ around the eyes.", sv: { concept: "\u00c4kta leende", definition: "Det \u00e4kta leendet syns i munnen och i musklerna runt \u00f6gonen", real_world_scenario: "N\u00e4r mormor \u00f6ppnade f\u00f6delsedagspresenten rynkades hennes \u00f6gon i skratt och musklerna runt \u00f6gonen sp\u00e4ndes tillsammans med munnen \u2013 ett \u00e4kta leende som ingen kan fejka.", case_study_cloze: "Det \u00e4kta leendet n\u00e5r inte bara munnen utan ocks\u00e5 ____ runt \u00f6gonen." } },
      { concept: "HEAD ADORNMENT", definition: "Head adornment is used across all cultures for a variety of reasons. It can communicate leadership status (Native American chiefs' feather headdresses), occupation (a hard hat or miner's hat), social status (a bowler hat or an Yves Saint Laurent pillbox hat), hobbies (bicycle or rock- climbing helmet), religion (cardinal's cap, Jewish yarmulke), or allegiance (favorite sports team, labor union). Head adornments may offer insight into individuals: where they fit in society, their allegiances, their socioeconomic status, what they believe, how they see themselves, or even the degree to which they defy convention.", category: "body-language-extracted", real_world_scenario: "At the construction site, the foreman could tell at a glance who belonged there: every worker wore a hard hat, while the architect in the suit carried his helmet under his arm \u2013 head adornment marks occupation and status.", case_study_cloze: "The Native American chief's feather headdress and the miner's hard hat both use ____ to communicate rank and role.", sv: { concept: "Huvudprydnader", definition: "Huvudprydnader anv\u00e4nds i alla kulturer av m\u00e5nga olika sk\u00e4l; de kan f\u00f6rmedla ledarskap, yrke, social status, hobby, religion eller lojalitet", real_world_scenario: "P\u00e5 byggarbetsplatsen kunde arbetsledaren med ett \u00f6gonkast se vem som h\u00f6rde hemma d\u00e4r: alla arbetare bar hj\u00e4lm medan arkitekten i kostym h\u00f6ll sin hj\u00e4lm under armen \u2013 huvudprydnader markerar b\u00e5de yrke och status.", case_study_cloze: "H\u00f6vdingens fj\u00e4derprydnad och gruvarbetarens hj\u00e4lm \u00e4r b\u00e5da exempel p\u00e5 ____ som f\u00f6rmedlar rang och roll." } },
      { concept: "PLAYING WITH PHILTRUM", definition: "The grooved area just above the upper lip and below the nose is the philtrum. People will play with this area by plucking at it, scratching it, or pulling on it when stressed-sometimes rather energetically. The philtrum is also revealing in other ways-sweat tends to gather there when people are stressed. They might also place the tongue between the teeth and the back of the philtrum, pushing it out. Stimulation of this area with the tongue is an easily spotted pacifier.", category: "body-language-extracted", real_world_scenario: "During the audit meeting, the accountant plucked at the skin between his nose and upper lip again and again while the numbers on the screen did not add up, and a fine film of sweat gathered in the groove.", case_study_cloze: "When the difficult question came, the applicant scratched the small groove above his upper lip, the ____, a sure sign of stress.", sv: { concept: "Att leka med filtrum", definition: "Det f\u00e5rade omr\u00e5det strax ovanf\u00f6r \u00f6verl\u00e4ppen och under n\u00e4san kallas filtrum. M\u00e4nniskor som \u00e4r stressade plockar, kliar eller drar i detta omr\u00e5de, ibland ganska energiskt, och svett samlas ofta d\u00e4r", real_world_scenario: "Under granskningen plockade revisorn g\u00e5ng p\u00e5 g\u00e5ng i huden mellan n\u00e4san och \u00f6verl\u00e4ppen medan siffrorna p\u00e5 sk\u00e4rmen inte gick ihop, och en tunn hinna av svett samlades i f\u00e5ran.", case_study_cloze: "N\u00e4r den sv\u00e5ra fr\u00e5gan kom kliade sig den s\u00f6kande i den lilla f\u00e5ran ovanf\u00f6r \u00f6verl\u00e4ppen, ____, ett s\u00e4kert tecken p\u00e5 stress." } },
      { concept: "VENTILATING HAIR (WOMEN)", definition: "The ventilating of hair is a powerful pacifier, relieving both heat and stress. Women ventilate their hair differently than men. Women lift up the hair at the back of their neck quickly when concerned, upset, stressed, or flustered. If they do it repeatedly, most likely they are overly stressed. Nevertheless, we cannot discount overheating due to physical activity or ambient temperature as a cause. Men tend to ventilate on the top of the head by running their fingers through the hair.", category: "body-language-extracted", real_world_scenario: "In the hospital corridor, the anxious new mother lifted the hair at the back of her neck over and over while waiting for test results; each lift let the trapped heat and tension escape.", case_study_cloze: "The stressed woman repeatedly lifted the hair at the back of her ____ to cool down and soothe herself.", sv: { concept: "Lufta h\u00e5ret (kvinnor)", definition: "Att lufta h\u00e5ret \u00e4r en kraftfull lugnande gest som lindrar b\u00e5de v\u00e4rme och stress. Kvinnor lyfter snabbt upp h\u00e5ret i nacken n\u00e4r de \u00e4r bekymrade, uppr\u00f6rda, stressade eller f\u00f6rvirrade; g\u00f6r de det upprepat \u00e4r de troligen h\u00e5rt stressade. M\u00e4n brukar i st\u00e4llet f\u00f6ra fingrarna genom h\u00e5ret p\u00e5 hj\u00e4ssan", real_world_scenario: "I sjukhuskorridoren lyfte den oroliga nyblivna mamman g\u00e5ng p\u00e5 g\u00e5ng h\u00e5ret i nacken medan hon v\u00e4ntade p\u00e5 provsvar; varje lyft sl\u00e4ppte ut v\u00e4rme och sp\u00e4nning.", case_study_cloze: "Den stressade kvinnan lyfte upprepade g\u00e5nger h\u00e5ret i ____ f\u00f6r att svalka sig och lugna sig." } },
      { concept: "HAIR FLIPPING/TOUCHING", definition: "Hair flipping, touching, or pulling is common", category: "body-language-extracted", real_world_scenario: "At the party, the woman tossed her hair back over her shoulder and ran a hand through it each time the man she liked glanced her way \u2013 a common and easy signal of interest.", case_study_cloze: "The woman kept flipping and touching her ____ while talking to the man at the bar, a classic sign of flirting.", sv: { concept: "H\u00e5rkastning och h\u00e5rber\u00f6ring", definition: "Att kasta, r\u00f6ra vid eller dra i h\u00e5ret \u00e4r vanligt", real_world_scenario: "P\u00e5 festen kastade kvinnan h\u00e5ret bak\u00e5t \u00f6ver axeln och f\u00f6rde handen genom det varje g\u00e5ng mannen hon gillade tittade \u00e5t hennes h\u00e5ll \u2013 en vanlig och tydlig signal av intresse.", case_study_cloze: "Kvinnan kastade och r\u00f6rde st\u00e4ndigt vid sitt ____ medan hon pratade med mannen i baren, en klassisk flirtsignal." } },
      { concept: "HAIR PULLING", definition: "The intentional and repetitive pulling out of hair is called trichotillomania. Hair pulling is more often seen in children and teenagers who are experiencing stress, but it is also occasionally seen in adults. Men tend to pluck hair from the corners of their eyebrows, while women are far more wide-ranging: plucking their eyelids, head hair, eyebrows, and arm hair. This is a stress response; even birds will pull out their own feathers when stressed. The repetitive pulling out of the hair, like a nervous tic, pacifies by stimulating nerve endings; unfortunately, when it becomes severe, it requires medical intervention.", category: "body-language-extracted", real_world_scenario: "In the back row of the classroom, the stressed teenager pulled out strands of hair from her eyebrows one by one during the exam, a nervous tic she could not control.", case_study_cloze: "The intentional and repetitive pulling out of hair, called ____, is a stress response seen most often in children and teenagers.", sv: { concept: "H\u00e5rdragning", definition: "Att avsiktligt och upprepat dra ut h\u00e5r kallas trichotillomani. Det \u00e4r vanligast hos stressade barn och ton\u00e5ringar men f\u00f6rekommer ibland hos vuxna. M\u00e4n plockar oftast i \u00f6gonbrynens ytterkanter medan kvinnor plockar fr\u00e5n \u00f6gonlock, h\u00e5rbotten, \u00f6gonbryn och armar. Det \u00e4r en stressrespons som lugnar genom att stimulera nerv\u00e4ndar", real_world_scenario: "I klassrummets sista b\u00e4nkrad drog den stressade ton\u00e5ringen under provet ut h\u00e5rstr\u00e5n ur \u00f6gonbrynen ett efter ett, en nerv\u00f6s tic som hon inte kunde styra.", case_study_cloze: "Att avsiktligt och upprepat dra ut h\u00e5r, s\u00e5 kallad ____, \u00e4r en stressrespons som oftast ses hos barn och ton\u00e5ringar." } },
      { concept: "HEAD NODDING", definition: "During conversations nodding serves to affirm, usually in cadence, that the person is hearing and receptive to a message. Generally, it signals agreement, except in those situations where the head nodding is accompanied by lip pursing ( see #154), which might suggest disagreement.", category: "body-language-extracted", real_world_scenario: "During the presentation, the client nodded along in a steady rhythm as the saleswoman explained the new pricing, signaling that she was hearing and accepting the message.", case_study_cloze: "The student's steady ____ told the teacher that she was hearing and receptive to the message.", sv: { concept: "Nickningar", definition: "Under samtal tj\u00e4nar nickningar till att bekr\u00e4fta, oftast i takt, att man h\u00f6r och \u00e4r mottaglig f\u00f6r budskapet. I regel signalerar de samtycke, utom n\u00e4r nickandet \u00e5tf\u00f6ljs av sammandragna l\u00e4ppar, vilket kan tyda p\u00e5 oenighet", real_world_scenario: "Under presentationen nickade kunden i j\u00e4mn takt medan s\u00e4ljaren f\u00f6rklarade det nya priset, en signal om att hon h\u00f6rde och accepterade budskapet.", case_study_cloze: "Elevens stadiga ____ ber\u00e4ttade f\u00f6r l\u00e4raren att hon h\u00f6rde och var mottaglig f\u00f6r budskapet." } },
      { concept: "HEAD NODDING (CONTRADICTION)", definition: "We usually see this in young children, as when a parent asks a child \\\"Did you break the lamp?\\\" and the child answers \\\"No\\\" but nods. This contradictory behavior betrays the truth. I have seen this with kids, teenagers, and even adults.", category: "body-language-extracted", real_world_scenario: "When the father asked his six-year-old 'Did you take the cookies?', the boy answered 'No' while nodding his head up and down \u2013 the contradiction betrayed the truth.", case_study_cloze: "The child said 'No' but ____ at the same time, a contradictory behavior that betrays the truth.", sv: { concept: "Nickning som mots\u00e4ger orden", definition: "Detta ser vi oftast hos sm\u00e5 barn, till exempel n\u00e4r en f\u00f6r\u00e4lder fr\u00e5gar 'Var det du som slog s\u00f6nder lampan?' och barnet svarar 'Nej' men nickar. Det mots\u00e4gelsefulla beteendet avsl\u00f6jar sanningen", real_world_scenario: "N\u00e4r pappan fr\u00e5gade sin sex\u00e5ring 'Var det du som tog kakorna?' svarade pojken 'Nej' samtidigt som han nickade \u2013 mots\u00e4gelsen avsl\u00f6jade sanningen.", case_study_cloze: "Barnet sa 'Nej' men ____ samtidigt, ett mots\u00e4gelsefullt beteende som avsl\u00f6jar sanningen." } },
      { concept: "HEAD SCRATCHING", definition: "Head scratching soothes us when we have doubts or feel frustrated, stressed, or concerned. You see it with people trying to remember information or when they are perplexed. This explains why it is", category: "body-language-extracted", real_world_scenario: "Stuck on the final question of the quiz, the student scratched his head while trying to recall the answer, the gesture soothing his frustration.", case_study_cloze: "The man scratched his ____ while trying to remember where he had parked, a common gesture when we are perplexed.", sv: { concept: "Klia sig i huvudet", definition: "Att klia sig i huvudet lugnar oss n\u00e4r vi tvivlar, k\u00e4nner oss frustrerade, stressade eller bekymrade. Man ser det hos m\u00e4nniskor som f\u00f6rs\u00f6ker minnas information eller \u00e4r f\u00f6rbryllade", real_world_scenario: "Fast p\u00e5 den sista fr\u00e5gan i tipspromenaden kliade sig eleven i huvudet medan han f\u00f6rs\u00f6kte minnas svaret \u2013 gesten lindrade frustrationen.", case_study_cloze: "Mannen kliade sig i ____ medan han f\u00f6rs\u00f6kte minnas var han parkerat, en vanlig gest n\u00e4r man \u00e4r f\u00f6rbryllad." } },
      { concept: "HEAD STROKING", definition: "Beyond the function of keeping one's hair in place, people will stroke their hair with the palm of the hand to soothe themselves when stressed or confronted with a dilemma or while pondering how to answer a question. This is not dissimilar to a mother comforting her child by stroking the child's head. This pacifying behavior can have an immediate calming effect. Once more, this behavior may signal doubt or conflict, especially if done to the back of the head.", category: "body-language-extracted", real_world_scenario: "The witness stroked her hair back with the palm of her hand before answering, calming herself as she pondered how to respond to the prosecutor's question.", case_study_cloze: "As she pondered how to answer, she stroked her hair with the palm of her hand to ____ herself.", sv: { concept: "Stryka sig \u00f6ver h\u00e5ret", definition: "Ut\u00f6ver att h\u00e5lla h\u00e5ret p\u00e5 plats stryker m\u00e4nniskor sig \u00f6ver h\u00e5ret med handflatan f\u00f6r att lugna sig n\u00e4r de \u00e4r stressade, st\u00e5r inf\u00f6r ett dilemma eller funderar p\u00e5 hur de ska svara p\u00e5 en fr\u00e5ga. Beteendet kan ha en omedelbar lugnande effekt och kan signalera tvivel eller inre konflikt, s\u00e4rskilt om det g\u00f6rs mot bakhuvudet", real_world_scenario: "Vittnet str\u00f6k sig \u00f6ver h\u00e5ret med handflatan innan hon svarade och lugnade sig medan hon funderade p\u00e5 hur hon skulle besvara \u00e5klagarens fr\u00e5ga.", case_study_cloze: "Medan hon funderade p\u00e5 hur hon skulle svara str\u00f6k hon sig \u00f6ver h\u00e5ret med handflatan f\u00f6r att ____ sig." } },
      { concept: "REACHING FOR HEAD (STUPEFIED)", definition: "People who are shocked, in disbelief, or stupefied might suddenly reach for their head with both hands so that the hands are near the ears but not touching them, with the elbows out toward the front. They might hold this position for several seconds as they try to make sense of what happened. This primitive, self-protective response might follow when someone has made a major faux pas, such as a driver crashing into his own mailbox, or a player running toward the wrong goal line.", category: "body-language-extracted", real_world_scenario: "When the final whistle blew and the striker realized he had scored into his own goal, he grabbed his head with both hands, elbows out, and stood frozen for several seconds in disbelief.", case_study_cloze: "Stunned by his mistake, the player reached for his head with both ____ and held the position for several seconds.", sv: { concept: "Gripa sig om huvudet (f\u00f6rstummad)", definition: "M\u00e4nniskor som \u00e4r chockade, tvivlande eller f\u00f6rstummade griper pl\u00f6tsligt tag om huvudet med b\u00e5da h\u00e4nderna s\u00e5 att h\u00e4nderna hamnar n\u00e4ra \u00f6ronen utan att r\u00f6ra dem, med armb\u00e5garna fram\u00e5t. De kan h\u00e5lla den st\u00e4llningen i flera sekunder medan de f\u00f6rs\u00f6ker f\u00f6rst\u00e5 vad som h\u00e4nt. Det \u00e4r en primitiv, sj\u00e4lvskyddande respons", real_world_scenario: "N\u00e4r slutsignalen g\u00e5tt och anfallaren ins\u00e5g att han gjort sj\u00e4lvm\u00e5l grep han tag i huvudet med b\u00e5da h\u00e4nderna, armb\u00e5garna ut\u00e5t, och stod stelfrusen i flera sekunder i misstro.", case_study_cloze: "Chockad av sitt misstag grep spelaren tag i huvudet med b\u00e5da ____ och h\u00f6ll kvar st\u00e4llningen i flera sekunder." } },
      { concept: "FOREHEAD TENSION", definition: "On some individuals, stress manifests as sudden tension of the forehead, a result of the stiffening and tensing of underlying muscles. The face has more than twenty distinct muscle groups that can create more than four thousand distinct expressions, according to Dr. Paul Ekman. Six muscles in particular, including the large occipitofrontalis, the procerus, and the temporalis, account for the tightening or furrowing of the forehead when we are stressed. Obviously, one has to see people in a calm environment to get a baseline read on their forehead, but when people are stressed, tension of the forehead is frequently very noticeable and is an excellent indicator that something is wrong.", category: "body-language-extracted", real_world_scenario: "The manager's forehead went tight the moment he opened the budget report and saw the red numbers, the sudden stiffening of his face muscles betraying his alarm before he said a word.", case_study_cloze: "The sudden ____ of the forehead, caused by stiffening muscles, is often the first sign that something is wrong.", sv: { concept: "Pannsp\u00e4nning", definition: "Hos en del m\u00e4nniskor visar sig stress som pl\u00f6tslig sp\u00e4nning i pannan n\u00e4r de underliggande musklerna stelnar. N\u00e4r m\u00e4nniskor \u00e4r stressade \u00e4r pannan ofta m\u00e4rkbart sp\u00e4nd, vilket \u00e4r en utm\u00e4rkt indikator p\u00e5 att n\u00e5got \u00e4r fel", real_world_scenario: "Chefens panna stelnade i samma \u00f6gonblick som han \u00f6ppnade budgetrapporten och s\u00e5g de r\u00f6da siffrorna \u2013 den pl\u00f6tsliga sp\u00e4nningen i ansiktsmusklerna avsl\u00f6jade hans oro innan han sagt ett ord.", case_study_cloze: "Den pl\u00f6tsliga ____ i pannan, som orsakas av stelnande muskler, \u00e4r ofta det f\u00f6rsta tecknet p\u00e5 att n\u00e5got \u00e4r fel." } },
      { concept: "FOREHEAD FURROWING", definition: "Furrowing of the forehead in response to a stimulus is usually a good indicator that something is amiss, there are issues, or a person is insecure. It is also seen when people are concentrating or trying to make sense of something. Furrowing of the forehead is usually associated with doubt, tension, anxiety, or concern. Keep in mind that Botox, which many use for cosmetic purposes to obscure stress lines on the forehead, might mask true sentiments.", category: "body-language-extracted", real_world_scenario: "During the board meeting, the CFO furrowed his brow when the quarterly numbers were presented, a clear sign that something was amiss in the figures.", case_study_cloze: "When the invoice showed a different total than expected, the customer's brow ____ \u2013 something was amiss.", sv: { concept: "Rynka pannan", definition: "Att pannan rynkas som svar p\u00e5 en stimulans \u00e4r oftast en god indikator p\u00e5 att n\u00e5got inte st\u00e5r r\u00e4tt till, att det finns problem eller att en person k\u00e4nner sig os\u00e4ker. Det ses ocks\u00e5 n\u00e4r m\u00e4nniskor koncentrerar sig eller f\u00f6rs\u00f6ker f\u00f6rst\u00e5 n\u00e5got. Rynkning f\u00f6rknippas vanligen med tvivel, sp\u00e4nning, \u00e5ngest eller oro", real_world_scenario: "Under styrelsem\u00f6tet rynkade ekonomichefen pannan n\u00e4r kvartalssiffrorna presenterades, ett tydligt tecken p\u00e5 att n\u00e5got inte st\u00e4mde i siffrorna.", case_study_cloze: "N\u00e4r fakturan visade en annan summa \u00e4n v\u00e4ntat rynkade kunden ____ \u2013 n\u00e5got var inte som det skulle." } },
      { concept: "BOTOXED FOREHEAD (ISSUES)", definition: "Both men and women are now taking advantage of Botox injections to erase stress lines on their foreheads. This has created problems for couples and even for children who would normally look to the forehead for information as to how a person might feel. Babies as young as four weeks old will respond to a furrowed forehead as something negative. Interestingly, both children and adults have reported an inability to read their parents or their spouses who have used Botox for emotional cues as easily as they could before.", category: "body-language-extracted", real_world_scenario: "Since her mother's Botox treatment, the daughter felt she could no longer read her mother's feelings \u2013 the smooth, unresponsive forehead hid the emotions she used to see at a glance.", case_study_cloze: "The smooth, immobile forehead from ____ made it harder for the children to read their mother's emotions.", sv: { concept: "Botoxad panna (problem)", definition: "B\u00e5de m\u00e4n och kvinnor anv\u00e4nder numera Botox-injektioner f\u00f6r att sudda ut stresslinjer i pannan. Det har skapat problem f\u00f6r par och till och med f\u00f6r barn, som normalt s\u00f6ker information i pannan om hur en person m\u00e5r. B\u00e5de barn och vuxna har rapporterat att de har sv\u00e5rare att l\u00e4sa sina f\u00f6r\u00e4ldrars eller makars k\u00e4nslor sedan de behandlats med Botox", real_world_scenario: "Sedan mammans botoxbehandling tyckte dottern att hon inte l\u00e4ngre kunde l\u00e4sa mammans k\u00e4nslor \u2013 den sl\u00e4ta, or\u00f6rliga pannan dolde de k\u00e4nslor hon f\u00f6rr s\u00e5g i ett \u00f6gonkast.", case_study_cloze: "Den sl\u00e4ta, or\u00f6rliga pannan efter ____ gjorde det sv\u00e5rare f\u00f6r barnen att l\u00e4sa mammans k\u00e4nslor." } },
      { concept: "STRESS LINES", definition: "On some individuals, their life struggles are marked by deep grooves on their forehead, even at a young age. Life experiences often etch our foreheads with lines, furrows, and other indentations. The forehead can reflect a difficult or stressful life or a life that has been spent outdoors in the sun, which tends to make forehead markings more prevalent.", category: "body-language-extracted", real_world_scenario: "The young waitress looked older than her years; deep grooves across her forehead told of a life spent worrying, etched into her skin by years of struggle.", case_study_cloze: "Deep grooves across the forehead can reflect a difficult or ____ life, marked on the skin over time.", sv: { concept: "Stressrynkor", definition: "Hos en del m\u00e4nniskor \u00e4r livets pr\u00f6vningar pr\u00e4glade som djupa f\u00e5ror i pannan, \u00e4ven i unga \u00e5r. Livserfarenheter ristar linjer, rynkor och andra f\u00f6rdjupningar i v\u00e5ra pannor. Pannan kan spegla ett sv\u00e5rt eller stressigt liv eller ett liv tillbringat utomhus i solen, vilket g\u00f6r m\u00e4rkena i pannan vanligare", real_world_scenario: "Den unga servitrisen s\u00e5g \u00e4ldre ut \u00e4n sina \u00e5r; djupa f\u00e5ror tv\u00e4rs \u00f6ver pannan ber\u00e4ttade om ett liv fyllt av bekymmer, inristade i huden av \u00e5r av slit.", case_study_cloze: "Djupa f\u00e5ror \u00f6ver pannan kan spegla ett sv\u00e5rt eller ____ liv, inristat i huden \u00f6ver tid." } },
      { concept: "FOREHEAD SWEATING", definition: "If the degree of stress is high enough, some people begin to spontaneously sweat. Sweating is very individual. Some sweat profusely with their first sip of coffee, or climbing a flight of stairs, so make sure to get a baseline of this behavior before jumping to any conclusion. Baseline behaviors are those behaviors we equate with \\\"normal,\\\" when a person is not stressed or overly affected by emotions.", category: "body-language-extracted", real_world_scenario: "The traveler's forehead was beaded with sweat as security asked him to open his bag, but he always sweated easily, so the officer noted his baseline before drawing any conclusion.", case_study_cloze: "Before judging a sweaty forehead as a sign of stress, make sure you know the person's ____, since some people sweat easily at any moment.", sv: { concept: "Pannsvett", definition: "Om stressen \u00e4r tillr\u00e4ckligt h\u00f6g b\u00f6rjar vissa m\u00e4nniskor spontant svettas. Svettning \u00e4r mycket individuell \u2013 en del svettas ymnigt redan av sin f\u00f6rsta kopp kaffe eller av att g\u00e5 uppf\u00f6r en trappa. Skaffa d\u00e4rf\u00f6r en baslinje f\u00f6r beteendet innan du drar n\u00e5gra slutsatser", real_world_scenario: "Resen\u00e4rens panna var t\u00e4ckt av svettp\u00e4rlor n\u00e4r s\u00e4kerhetspersonalen bad honom \u00f6ppna v\u00e4skan, men han svettades alltid l\u00e4tt, s\u00e5 vakten noterade hans baslinje innan han drog n\u00e5gra slutsatser.", case_study_cloze: "Innan man bed\u00f6mer en svettig panna som ett tecken p\u00e5 stress b\u00f6r man k\u00e4nna till personens ____, eftersom en del m\u00e4nniskor svettas l\u00e4tt hela tiden." } },
      { concept: "TEMPLE VEIN THROBBING", definition: "When a person is under stress, the superficial temporal veins (those nearest the skin on the sides of our heads and just behind the eyes) might pulse or throb visibly. It is a very accurate indicator of autonomic arousal due to anxiety, concern, fear, anger, or, occasionally, excitement. Autonomic arousal is the brain's way of automatically going into survival mode-compelling the heart and the lungs to work faster in anticipation of physical activity such as running or fighting.", category: "body-language-extracted", real_world_scenario: "In the interrogation room, the suspect's temple vein pulsed visibly under the light as he denied knowing anything about the robbery, a reliable sign of autonomic arousal.", case_study_cloze: "The visibly throbbing vein at the ____ is an accurate indicator of stress and autonomic arousal.", sv: { concept: "Pulserande tinningven", definition: "N\u00e4r en person \u00e4r stressad kan de ytliga tinningvenerna, n\u00e4rmast huden p\u00e5 sidorna av huvudet strax bakom \u00f6gonen, pulsera eller sl\u00e5 synligt. Det \u00e4r en mycket tillf\u00f6rlitlig indikator p\u00e5 autonom aktivering p\u00e5 grund av \u00e5ngest, oro, r\u00e4dsla, ilska eller ibland upphetsning", real_world_scenario: "I f\u00f6rh\u00f6rsrummet pulserade den misst\u00e4nktes tinningven synligt i ljuset medan han nekade till att veta n\u00e5got om r\u00e5net, ett tillf\u00f6rlitligt tecken p\u00e5 autonom aktivering.", case_study_cloze: "Den synligt pulserande venen i ____ \u00e4r en tillf\u00f6rlitlig indikator p\u00e5 stress och autonom aktivering." } },
      { concept: "FOREHEAD MASSAGING", definition: "We tend to massage our foreheads when we have headaches (literally), when we are processing information, or when we have worries, concerns, doubts, or anxiety. It is a pacifying behavior, which helps to soothe tension or apprehension.", category: "body-language-extracted", real_world_scenario: "At her desk, the analyst massaged her forehead slowly as she worked through the worrying email, the pressure of her fingers easing the tension.", case_study_cloze: "Worried about the deadline, he massaged his ____ to soothe the tension and anxiety.", sv: { concept: "Massera pannan", definition: "Vi masserar ofta pannan n\u00e4r vi har huvudv\u00e4rk, n\u00e4r vi bearbetar information eller n\u00e4r vi har bekymmer, oro, tvivel eller \u00e5ngest. Det \u00e4r en lugnande gest som hj\u00e4lper till att mildra sp\u00e4nning och oro", real_world_scenario: "Vid sitt skrivbord masserade analytikern l\u00e5ngsamt sin panna medan hon bearbetade det oroande mejlet \u2013 fingrarnas tryck lindrade sp\u00e4nningen.", case_study_cloze: "Bekymrad \u00f6ver deadline masserade han sin ____ f\u00f6r att lindra sp\u00e4nningen och oron." } },
      { concept: "PRESSING HAND ON FOREHEAD", definition: "Pressing the hand flat against the forehead helps relieve tension caused by stress, doubt, or insecurity. This is different from slapping the hand on the forehead; it looks as though the person is trying to push his head backward. As with so many other behaviors, this is intended to soothe the individual psychologically through tactile pressure on the skin.", category: "body-language-extracted", real_world_scenario: "When the judge announced the verdict, the defendant pressed his hand flat against his forehead, as if pushing his head backward, trying to hold back the wave of distress.", case_study_cloze: "Rather than slapping his forehead, he pressed his hand flat against it, as if pushing his ____ backward, to soothe himself.", sv: { concept: "Trycka handen mot pannan", definition: "Att trycka handflatan platt mot pannan hj\u00e4lper till att lindra sp\u00e4nning som orsakats av stress, tvivel eller os\u00e4kerhet. Det skiljer sig fr\u00e5n att sl\u00e5 sig f\u00f6r pannan; det ser ut som om personen f\u00f6rs\u00f6ker trycka huvudet bak\u00e5t. Precis som m\u00e5nga andra beteenden \u00e4r avsikten att lugna sig sj\u00e4lv genom taktilt tryck p\u00e5 huden", real_world_scenario: "N\u00e4r domaren meddelade domen tryckte den \u00e5talade handflatan h\u00e5rt mot pannan, som om han f\u00f6rs\u00f6kte trycka huvudet bak\u00e5t f\u00f6r att h\u00e5lla tillbaka den v\u00e5g av f\u00f6rtvivlan som sk\u00f6ljde \u00f6ver honom.", case_study_cloze: "I st\u00e4llet f\u00f6r att sl\u00e5 sig f\u00f6r pannan tryckte han handflatan platt mot den, som om han f\u00f6rs\u00f6kte trycka ____ bak\u00e5t f\u00f6r att lugna sig." } },
      { concept: "PUZZLED LOOK", definition: "The area between the eyes is pulled together, often causing furrowing or knitting of the eyebrows. The eyes may squint or look away, and sometimes the head is canted slightly to the side. We often see this distressed look when someone is struggling with something mentally or trying to work through a problem. It usually results from a high cognitive load (arduous thinking or recalling).", category: "body-language-extracted", real_world_scenario: "In the lecture hall, the student knitted her brows, squinted, and canted her head slightly as she struggled to follow the professor's logic \u2013 the classic puzzled look of a mind under heavy load.", case_study_cloze: "The student's knitted brows and slight head tilt showed she was ____, struggling to work through the problem.", sv: { concept: "F\u00f6rbryllad min", definition: "Omr\u00e5det mellan \u00f6gonen dras ihop, ofta med rynkade eller ihopdragna \u00f6gonbryn. \u00d6gonen kan kisa eller v\u00e4nda bort blicken, och ibland lutas huvudet n\u00e5got \u00e5t sidan. Vi ser ofta denna min n\u00e4r n\u00e5gon k\u00e4mpar mentalt med n\u00e5got eller f\u00f6rs\u00f6ker l\u00f6sa ett problem; den beror vanligen p\u00e5 h\u00f6g kognitiv belastning", real_world_scenario: "I f\u00f6rel\u00e4sningssalen rynkade studenten \u00f6gonbrynen, kisade och lutade huvudet en aning \u00e5t sidan n\u00e4r hon f\u00f6rs\u00f6kte f\u00f6lja professorns resonemang \u2013 den klassiska f\u00f6rbryllade minen hos en h\u00e5rt anstr\u00e4ngd hj\u00e4rna.", case_study_cloze: "Studentens rynkade \u00f6gonbryn och l\u00e4tt lutade huvud visade att hon var ____ och k\u00e4mpade med problemet." } },
      { concept: "COVERING FOREHEAD WITH HAT", definition: "Stress or embarrassment will cause some to actually cover their forehead with headgear (a hat, visor, or hood). We generally see this in children and teenagers but also sometimes in adults. I have often watched drivers do this when being ticketed for speeding. It is almost as if they are trying to hide in shame.", category: "body-language-extracted", real_world_scenario: "Pulled over for speeding, the driver raised the brim of his cap over his eyes and forehead as the officer walked up, as if trying to hide in shame.", case_study_cloze: "Stress or embarrassment can make some people cover their ____ with a hat, visor, or hood, almost as if hiding in shame.", sv: { concept: "T\u00e4cka pannan med huvudbonad", definition: "Stress eller skam kan f\u00e5 vissa m\u00e4nniskor att faktiskt t\u00e4cka pannan med huvudbonader som hatt, keps eller luva. Det ser vi oftast hos barn och ton\u00e5ringar men ibland \u00e4ven hos vuxna. Det \u00e4r n\u00e4stan som om de f\u00f6rs\u00f6ker g\u00f6mma sig av skam", real_world_scenario: "Stannad f\u00f6r fortk\u00f6rning drog f\u00f6raren ner kepsen \u00f6ver \u00f6gonen och pannan n\u00e4r polisen gick fram, som om han f\u00f6rs\u00f6kte g\u00f6mma sig av skam.", case_study_cloze: "Stress eller skam kan f\u00e5 en del m\u00e4nniskor att t\u00e4cka ____ med hatt, keps eller luva, n\u00e4stan som om de g\u00f6mde sig av skam." } },
      { concept: "EYEBROW ARCHING/FLASHING (HAPPY)", definition: "Eyebrow arching or flashing conveys excitement (such as when greeting a close friend) or the recognition of something pleasing. We arch our brows in less than one-fifth of a second. It is a gravity-defying behavior, as it is performed in an upward direction, and as with most gravity-defying behaviors, it signifies something positive. Babies just a few months old light up when their mother flashes her eyebrows. Here is a great behavior to let others know we care and are happy to see them. A happy eyebrow flash can be immensely useful and powerful in everyday situations both at home and at work.", category: "body-language-extracted", real_world_scenario: "When the old friends spotted each other at the airport, both arched their eyebrows in a quick upward flash before they even smiled \u2013 a lightning-fast signal of delight.", case_study_cloze: "The quick upward ____ of the brows is a gravity-defying sign of happiness and excitement.", sv: { concept: "\u00d6gonbrynslyft (glad)", definition: "\u00d6gonbrynsh\u00f6jning eller \u00f6gonbrynsblixt f\u00f6rmedlar upphetsning, till exempel n\u00e4r man h\u00e4lsar en n\u00e4ra v\u00e4n, eller igenk\u00e4nning av n\u00e5got gl\u00e4djande. Vi h\u00f6jer \u00f6gonbrynen p\u00e5 mindre \u00e4n en femtedels sekund. Eftersom r\u00f6relsen g\u00e5r upp\u00e5t, mot tyngdkraften, signalerar den n\u00e5got positivt", real_world_scenario: "N\u00e4r de gamla v\u00e4nnerna fick syn p\u00e5 varandra p\u00e5 flygplatsen h\u00f6jde b\u00e5da \u00f6gonbrynen i en snabb upp\u00e5tg\u00e5ende blixt innan de ens hunnit le \u2013 en blixtsnabb signal av f\u00f6rtjusning.", case_study_cloze: "Den snabba upp\u00e5tg\u00e5ende ____ av \u00f6gonbrynen \u00e4r ett tecken p\u00e5 gl\u00e4dje och upphetsning som g\u00e5r emot tyngdkraften." } },
      { concept: "EYEBROW GREETINGS", definition: "We flash our eyebrows when we recognize someone we know and cannot speak up at that moment, or simply to recognize a person's presence, with or without a smile, depending on circumstances. We are quick to notice when this courtesy is not extended to us, for example, when we enter a store and the clerk makes no effort to establish any kind of eye contact. We can let others know we value them, though we may be occupied, with a very simple eyebrow flash.", category: "body-language-extracted", real_world_scenario: "Across the crowded restaurant, the man recognized his colleague and gave a quick eyebrow flash, a silent hello across the room when calling out was impossible.", case_study_cloze: "When she could not speak to her friend across the room, she used a quick ____ to recognize her presence.", sv: { concept: "\u00d6gonbryns-h\u00e4lsning", definition: "Vi blixtrar med \u00f6gonbrynen n\u00e4r vi k\u00e4nner igen n\u00e5gon vi inte kan prata med just d\u00e5, eller helt enkelt f\u00f6r att bekr\u00e4fta en persons n\u00e4rvaro, med eller utan leende beroende p\u00e5 omst\u00e4ndigheterna. Vi m\u00e4rker snabbt n\u00e4r denna artighet inte ges tillbaka, till exempel n\u00e4r en butiksbitr\u00e4de inte etablerar n\u00e5gon \u00f6gonkontakt alls", real_world_scenario: "Tv\u00e4rs \u00f6ver den fullsatta restaurangen k\u00e4nde mannen igen sin kollega och gav en snabb \u00f6gonbrynsblixt \u2013 en tyst h\u00e4lsning \u00f6ver lokalen n\u00e4r det inte gick att ropa.", case_study_cloze: "N\u00e4r hon inte kunde prata med sin v\u00e4ninna tv\u00e4rs \u00f6ver rummet anv\u00e4nde hon en snabb ____ f\u00f6r att bekr\u00e4fta hennes n\u00e4rvaro." } },
      { concept: "EYEBROW ARCHING (TENSE)", definition: "This occurs when a person is presented with an unwanted surprise or shock. Coupled with other behaviors such as a tense face or lip compression, it can let us know someone has experienced something very negative. It is the tension in the muscles that control the eyebrows that differentiates this behavior from the eyebrow greeting described above and it is held for a few seconds longer.", category: "body-language-extracted", real_world_scenario: "When the employee told her boss that the project had been cancelled, his eyebrows shot up and stayed raised, held a few seconds longer than a greeting flash, while his jaw tightened.", case_study_cloze: "The eyebrows arched and were held for a few seconds longer than usual, signaling an unwanted ____ or shock.", sv: { concept: "\u00d6gonbrynslyft (sp\u00e4nt)", definition: "Detta intr\u00e4ffar n\u00e4r en person uts\u00e4tts f\u00f6r en ov\u00e4lkommen \u00f6verraskning eller chock. Tillsammans med andra beteenden, som sp\u00e4nda ansiktsdrag eller sammanpressade l\u00e4ppar, kan det avsl\u00f6ja att n\u00e5gon upplevt n\u00e5got mycket negativt. Det \u00e4r sp\u00e4nningen i musklerna som styr \u00f6gonbrynen som skiljer detta fr\u00e5n h\u00e4lsningsblixten, och det h\u00e5lls kvar n\u00e5gra sekunder l\u00e4ngre", real_world_scenario: "N\u00e4r medarbetaren ber\u00e4ttade f\u00f6r chefen att projektet var inst\u00e4llt for \u00f6gonbrynen upp och blev kvar, h\u00e5llna n\u00e5gra sekunder l\u00e4ngre \u00e4n en h\u00e4lsningsblixt, medan k\u00e4ken sp\u00e4ndes.", case_study_cloze: "\u00d6gonbrynen h\u00f6jdes och h\u00f6lls kvar n\u00e5gra sekunder l\u00e4ngre \u00e4n vanligt, en signal om en ov\u00e4lkommen ____ eller chock." } },
      { concept: "EYEBROW ASYMMETRY", definition: "People use this signal when they have doubts or uncertainty. One eyebrow will arch high, while the other remains in the normal position or sinks lower. Asymmetry signals that the person is questioning or doubting what is being said. The actor Jack Nicholson is famous for questioning what others say, on- and offscreen, by this method.", category: "body-language-extracted", real_world_scenario: "When his colleague promised the deal would close by Friday, the manager raised only one eyebrow while the other stayed in place \u2013 a silent question mark about the promise.", case_study_cloze: "One eyebrow arched high while the other stayed level, the classic ____ signal that the person is doubting what is being said.", sv: { concept: "Asymmetriska \u00f6gonbryn", definition: "M\u00e4nniskor anv\u00e4nder denna signal n\u00e4r de tvivlar eller \u00e4r os\u00e4kra. Det ena \u00f6gonbrynet h\u00f6js h\u00f6gt medan det andra f\u00f6rblir i normall\u00e4ge eller sjunker l\u00e4gre. Asymmetrin signalerar att personen ifr\u00e5gas\u00e4tter eller tvivlar p\u00e5 det som s\u00e4gs", real_world_scenario: "N\u00e4r kollegan lovade att aff\u00e4ren skulle vara klar till fredag h\u00f6jde chefen bara ett \u00f6gonbryn medan det andra f\u00f6rblev i vanligt l\u00e4ge \u2013 ett tyst fr\u00e5getecken inf\u00f6r l\u00f6ftet.", case_study_cloze: "Det ena \u00f6gonbrynet h\u00f6jdes h\u00f6gt medan det andra f\u00f6rblev i normall\u00e4ge, den klassiska ____ som visar att personen tvivlar p\u00e5 det som s\u00e4gs." } },
      { concept: "PUPIL DILATION", definition: "When we are comfortable or like something or someone we encounter, our pupils dilate. We have no control over this. When couples are at ease around each other their pupils dilate as their eyes try to soak up as much light as possible. This is why dimly lit restaurants are a good place to meet, as it naturally softens the eyes and makes the pupils larger-an effect that makes us relax even more around others.", category: "body-language-extracted", real_world_scenario: "At the dimly lit restaurant, the couple leaned closer across the table; the soft light made their pupils widen, and each saw in the other's eyes a warmth that neither dared to name.", case_study_cloze: "When we like something or someone, our pupils ____, an involuntary response we cannot control.", sv: { concept: "Pupillutvidgning", definition: "N\u00e4r vi k\u00e4nner oss bekv\u00e4ma eller gillar n\u00e5got eller n\u00e5gon vi m\u00f6ter vidgas v\u00e5ra pupiller. Vi har ingen kontroll \u00f6ver detta. D\u00e4rf\u00f6r \u00e4r restauranger med d\u00e4mpad belysning en bra plats att tr\u00e4ffas p\u00e5, eftersom ljuset naturligt mjukar upp blicken och g\u00f6r pupillerna st\u00f6rre", real_world_scenario: "P\u00e5 restaurangen med d\u00e4mpad belysning lutade paret sig n\u00e4rmare varandra \u00f6ver bordet; det mjuka ljuset vidgade deras pupiller, och var och en s\u00e5g i den andres \u00f6gon en v\u00e4rme som ingen v\u00e5gade s\u00e4tta ord p\u00e5.", case_study_cloze: "N\u00e4r vi gillar n\u00e5got eller n\u00e5gon ____ v\u00e5ra pupiller, en ofrivillig reaktion som vi inte kan kontrollera." } },
      { concept: "PUPIL CONSTRICTION", definition: "Our pupils constrict when we see something we don't like or when we have negative emotions. Pupil constriction is easier to detect in light-colored eyes. Pupils suddenly shrinking to pinpoints suggest something negative has just transpired. Interestingly, our brain governs this activity to make sure that our eyes are focused in times of distress, as the smaller the aperture, the greater the clarity. This is why squinting improves focus.", category: "body-language-extracted", real_world_scenario: "As the accountant read the tax letter that demanded a re-audit, her pupils shrank to pinpoints \u2013 a sudden negative reaction she could not hide.", case_study_cloze: "When something negative happens, our pupils ____, sometimes shrinking to pinpoints, an involuntary response.", sv: { concept: "Pupillsammandragning", definition: "V\u00e5ra pupiller drar ihop sig n\u00e4r vi ser n\u00e5got vi inte tycker om eller har negativa k\u00e4nslor. Sammandragningen \u00e4r l\u00e4ttast att uppt\u00e4cka hos ljusa \u00f6gon. Att pupillerna pl\u00f6tsligt krymper till knappn\u00e5lsstorlek tyder p\u00e5 att n\u00e5got negativt just intr\u00e4ffat", real_world_scenario: "N\u00e4r revisorn l\u00e4ste skattebrevet som kr\u00e4vde en ny granskning krympte hennes pupiller till knappn\u00e5lsstorlek \u2013 en pl\u00f6tslig negativ reaktion som hon inte kunde d\u00f6lja.", case_study_cloze: "N\u00e4r n\u00e5got negativt intr\u00e4ffar ____ v\u00e5ra pupiller, ibland till knappn\u00e5lsstorlek, en ofrivillig reaktion." } },
      { concept: "RELAXED EYES", definition: "Relaxed eyes signal comfort and confidence. When we are at ease, the muscles around the eyes, the forehead, and the cheeks relax-", category: "body-language-extracted", real_world_scenario: "On stage, the speaker's eyes were soft and relaxed as she answered questions, the muscles around her eyes, forehead, and cheeks loose \u2013 the look of someone confident and at ease.", case_study_cloze: "With the muscles around the eyes and forehead relaxed, the speaker conveyed ____ and confidence without a word.", sv: { concept: "Avslappnade \u00f6gon", definition: "Avslappnade \u00f6gon signalerar v\u00e4lbefinnande och sj\u00e4lvf\u00f6rtroende. N\u00e4r vi \u00e4r tillfreds slappnar musklerna runt \u00f6gonen, pannan och kinderna av", real_world_scenario: "P\u00e5 scenen var talarens \u00f6gon mjuka och avslappnade medan hon besvarade fr\u00e5gorna, musklerna runt \u00f6gon, panna och kinder l\u00f6sa \u2013 blicken hos n\u00e5gon som k\u00e4nner sig trygg.", case_study_cloze: "Med musklerna runt \u00f6gonen och pannan avslappnade f\u00f6rmedlade talaren ____ och sj\u00e4lvf\u00f6rtroende utan ett ord." } },
      { concept: "EYE SOCKET NARROWING", definition: "When we feel stressed, upset, threatened, or other negative emotions, the orbits of the eyes will narrow due to the contraction of underlying muscles. The brain immediately makes the eye orbits smaller in response to apprehension, concern, or doubt. It is a good indicator that there is an issue or something is wrong.", category: "body-language-extracted", real_world_scenario: "In the performance review, the employee's eye orbits narrowed as the manager brought up the missed deadline, a tightening that showed the topic stung.", case_study_cloze: "The eyes narrowed in their sockets as a sign of ____, a good indicator that there is an issue.", sv: { concept: "Sammandragna \u00f6gonh\u00e5lor", definition: "N\u00e4r vi k\u00e4nner oss stressade, uppr\u00f6rda, hotade eller har andra negativa k\u00e4nslor dras \u00f6gonh\u00e5lorna samman genom att de underliggande musklerna drar ihop sig. Hj\u00e4rnan g\u00f6r omedelbart \u00f6gonh\u00e5lorna mindre vid oro, bekymmer eller tvivel. Det \u00e4r en god indikator p\u00e5 att n\u00e5got \u00e4r fel", real_world_scenario: "Under medarbetarsamtalet drogs den anst\u00e4lldes \u00f6gonh\u00e5lor samman n\u00e4r chefen tog upp den missade deadline, en \u00e5tstramning som visade att \u00e4mnet svidit.", case_study_cloze: "Att \u00f6gonen dras samman i sina h\u00e5lor \u00e4r ett tecken p\u00e5 ____, en god indikator p\u00e5 att n\u00e5got inte st\u00e5r r\u00e4tt till." } },
      { concept: "QUIVERING UNDER EYES", definition: "The tiny muscles directly under the eyes (the inferior underside of the Obicularis oculi) and just above the cheekbones, as well as the surrounding tissue, can be very sensitive to stress. When there is concern, anxiety, or fear, these soft areas will quiver or twitch, revealing the person's true emotional state.", category: "body-language-extracted", real_world_scenario: "During the cross-examination, the tiny muscles beneath the witness's eyes began to quiver as fear crept in, revealing the tension her calm face tried to hide.", case_study_cloze: "The tiny muscles just under the eyes began to ____, revealing the witness's true fear despite her calm expression.", sv: { concept: "Darrningar under \u00f6gonen", definition: "De sm\u00e5 musklerna direkt under \u00f6gonen och strax ovanf\u00f6r kindbenen, liksom den omgivande v\u00e4vnaden, kan vara mycket k\u00e4nsliga f\u00f6r stress. Vid oro, \u00e5ngest eller r\u00e4dsla darrar eller rycker dessa mjuka omr\u00e5den, vilket avsl\u00f6jar personens verkliga k\u00e4nslotillst\u00e5nd", real_world_scenario: "Under korsf\u00f6rh\u00f6ret b\u00f6rjade de sm\u00e5 musklerna under vittnets \u00f6gon darra n\u00e4r r\u00e4dslan sm\u00f6g sig p\u00e5, och avsl\u00f6jade den sp\u00e4nning som hennes lugna ansikte f\u00f6rs\u00f6kte d\u00f6lja.", case_study_cloze: "De sm\u00e5 musklerna strax under \u00f6gonen b\u00f6rjade ____ och avsl\u00f6jade vittnets verkliga r\u00e4dsla trots det lugna ansiktsuttrycket." } },
      { concept: "BLINK RATE", definition: "Blink rates can vary depending on environment and the amount of stress or arousal a person is experiencing. Each individual is different, but a typical rate is between sixteen and twenty blinks per minute, depending on lighting conditions and humidity. People looking at computers blink less (many of whom complain of dry eyes or eye infections -tears have antibacterial properties), while those who work where there is dust or pollen will blink more. Also, be aware that wearing contact lenses can increase how often we blink. When we are around someone who arouses us, our blink rate also tends to increase.", category: "body-language-extracted", real_world_scenario: "The programmer blinked far less than usual during the four-hour shift at the screen, and by evening his dry, irritated eyes reminded him why the typical rate is sixteen to twenty blinks per minute.", case_study_cloze: "People staring at computer screens blink ____ than normal, which is why so many complain of dry eyes.", sv: { concept: "Blinkfrekvens", definition: "Blinkfrekvensen kan variera beroende p\u00e5 milj\u00f6 och hur stressad eller upphetsad en person \u00e4r. Varje individ \u00e4r unik, men en typisk takt ligger mellan sexton och tjugo blinkningar per minut beroende p\u00e5 ljus och luftfuktighet. De som tittar p\u00e5 datorsk\u00e4rmar blinkar mindre, medan de som arbetar i dammiga eller pollenrika milj\u00f6er blinkar mer", real_world_scenario: "Programmeraren blinkade l\u00e5ngt mindre \u00e4n vanligt under de fyra timmarna framf\u00f6r sk\u00e4rmen, och p\u00e5 kv\u00e4llen p\u00e5minde hans torra, irriterade \u00f6gon honom om varf\u00f6r den typiska takten \u00e4r sexton till tjugo blinkningar per minut.", case_study_cloze: "M\u00e4nniskor som tittar p\u00e5 datorsk\u00e4rmar blinkar ____ \u00e4n normalt, vilket \u00e4r anledningen till att s\u00e5 m\u00e5nga klagar p\u00e5 torra \u00f6gon." } },
      { concept: "FREQUENT BLINKING", definition: "People who are nervous, tense, or stressed will generally blink more rapidly than those who are not. Frequent blinking is erroneously associated with deception. It is only indicative of stress or other factors noted above as even the honest blink more frequently when being questioned aggressively.", category: "body-language-extracted", real_world_scenario: "In the security line, the nervous passenger blinked rapidly as the agent asked about the contents of his bag; the fast blinking showed stress, not necessarily dishonesty.", case_study_cloze: "Rapid blinking is often wrongly linked to lying; in fact it is only a sign of ____ or tension.", sv: { concept: "Frekvent blinkande", definition: "M\u00e4nniskor som \u00e4r nerv\u00f6sa, sp\u00e4nda eller stressade blinkar i allm\u00e4nhet snabbare \u00e4n andra. Frekvent blinkande f\u00f6rknippas felaktigt med l\u00f6gn \u2013 det \u00e4r bara en indikator p\u00e5 stress eller andra faktorer, eftersom \u00e4ven \u00e4rliga m\u00e4nniskor blinkar oftare n\u00e4r de utfr\u00e5gas h\u00e5rt", real_world_scenario: "I s\u00e4kerhetsk\u00f6n blinkade den nerv\u00f6sa passageraren snabbt medan kontrollanten fr\u00e5gade om inneh\u00e5llet i v\u00e4skan; det snabba blinkandet visade stress, inte n\u00f6dv\u00e4ndigtvis o\u00e4rlighet.", case_study_cloze: "Snabbt blinkande kopplas ofta felaktigt ihop med l\u00f6gn; i sj\u00e4lva verket \u00e4r det bara ett tecken p\u00e5 ____ eller sp\u00e4nning." } },
      { concept: "EYE CONTACT", definition: "Eye contact is governed by cultural norms and personal", category: "body-language-extracted", real_world_scenario: "During a business meeting in Tokyo, the visiting manager from Sweden kept direct eye contact with everyone, while his Japanese counterparts looked mostly at his chin or the table \u2014 what he took for shyness was simply a cultural norm that reserves intense eye contact for close equals.", case_study_cloze: "In some cultures, steady ____ is expected during a conversation, while in others it is considered rude and disrespectful.", sv: { concept: "\u00d6gonkontakt", definition: "\u00d6gonkontakt styrs av kulturella normer och personliga preferenser. I vissa kulturer f\u00f6rv\u00e4ntas direkt \u00f6gonkontakt, medan den i andra anses of\u00f6rsk\u00e4md och respektl\u00f6s.", real_world_scenario: "Under ett aff\u00e4rsm\u00f6te i Tokyo h\u00f6ll den bes\u00f6kande chefen fr\u00e5n Sverige \u00f6gonkontakt med alla, medan hans japanska kollegor mest s\u00e5g p\u00e5 hans haka eller bordet \u2014 vad han tolkade som blyghet var helt enkelt en kulturell norm som sparar intensiv \u00f6gonkontakt f\u00f6r n\u00e4ra j\u00e4mlikar.", case_study_cloze: "I vissa kulturer f\u00f6rv\u00e4ntas stadig ____ under ett samtal, medan den i andra anses of\u00f6rsk\u00e4md och respektl\u00f6s." } },
      { concept: "EYE AVOIDANCE", definition: "We avoid eye contact when it is inconvenient to talk to someone, or when we find a person unlikable, obnoxious, or repressive. In prison, for example, inmates will avoid eye contact with jailers or inmates known to be aggressive. Eye avoidance can be temporary or long term. Temporarily, people might avert their eyes when a person does something embarrassing. And in the United States, unlike other parts of the world, when we are in close proximity, as in an elevator, we tend to avoid making eye contact with strangers and even with those we know, especially if there are strangers present. Eye avoidance is not indicative of deception, but it can indicate shame or embarrassment.", category: "body-language-extracted", real_world_scenario: "In a crowded elevator, Maya stared at the floor indicator for the whole ride and never once looked at her neighbors, even though she knew the woman beside her from work \u2014 a familiar pattern of eye avoidance that had nothing to do with deception.", case_study_cloze: "Inmates often practice ____ with jailers and aggressive inmates to avoid conflict or unwelcome attention.", sv: { concept: "Undvikande av \u00f6gonkontakt", definition: "Vi undviker \u00f6gonkontakt n\u00e4r det \u00e4r obekv\u00e4mt att prata med n\u00e5gon, eller n\u00e4r vi tycker att en person \u00e4r osympatisk, otrevlig eller f\u00f6rtryckande. I f\u00e4ngelse undviker intagna till exempel \u00f6gonkontakt med vakter eller aggressiva intagna. Undvikandet kan vara tillf\u00e4lligt eller l\u00e5ngvarigt. Tillf\u00e4lligt kan m\u00e4nniskor v\u00e4nda bort blicken n\u00e4r n\u00e5gon g\u00f6r n\u00e5got pinsamt. I USA, till skillnad fr\u00e5n andra delar av v\u00e4rlden, undviker vi ofta \u00f6gonkontakt med fr\u00e4mlingar i hissen, till och med med dem vi k\u00e4nner, s\u00e4rskilt om det finns fr\u00e4mlingar n\u00e4rvarande. Undvikande av \u00f6gonkontakt tyder inte p\u00e5 l\u00f6gn, men det kan tyda p\u00e5 skam eller f\u00f6rl\u00e4genhet.", real_world_scenario: "I en tr\u00e5ng hiss stirrade Maya p\u00e5 v\u00e5ningsindikatorn hela resan och s\u00e5g aldrig p\u00e5 sina grannar, trots att hon k\u00e4nde igen kvinnan bredvid sig fr\u00e5n jobbet \u2014 ett v\u00e4lbekant m\u00f6nster av undvikande av \u00f6gonkontakt som inte hade n\u00e5got med l\u00f6gn att g\u00f6ra.", case_study_cloze: "Intagna undviker ofta ____ med vakter och aggressiva intagna f\u00f6r att slippa konflikter eller o\u00f6nskad uppm\u00e4rksamhet." } },
      { concept: "GAZE SUPERIORITY", definition: "All over the world, studies have shown that high- status individuals engage in more eye contact, while both speaking and listening. Less powerful people tend to make more eye contact with these higher-status individuals while listening but less while speaking. In Japan as well as other Asian Pacific countries this is even more pronounced. Incidentally, we tend to favor individuals who make direct eye contact with us, especially if they are of higher status. Eye contact from high social status individuals, movie stars, for instance, makes us feel favored.", category: "body-language-extracted", real_world_scenario: "In the university seminar, the professor held her gaze on every student who spoke, while the nervous exchange student dropped his eyes the moment he finished a sentence \u2014 a classic gaze superiority pattern in which the higher-status person freely looks and the lower-status person looks while listening but not while speaking.", case_study_cloze: "Studies show that high-status people engage in more ____ than those with less power, especially while speaking.", sv: { concept: "Blick\u00f6verl\u00e4gsenhet", definition: "\u00d6ver hela v\u00e4rlden visar studier att personer med h\u00f6g status har mer \u00f6gonkontakt, b\u00e5de n\u00e4r de talar och n\u00e4r de lyssnar. Mindre m\u00e4ktiga personer har mer \u00f6gonkontakt med dessa personer n\u00e4r de lyssnar, men mindre n\u00e4r de talar. I Japan och andra asiatiska stillahavsl\u00e4nder \u00e4r detta \u00e4nnu mer uttalat. Vi gillar dessutom m\u00e4nniskor som ser oss rakt i \u00f6gonen, s\u00e4rskilt om de har h\u00f6gre status. \u00d6gonkontakt fr\u00e5n personer med h\u00f6g social status, till exempel filmstj\u00e4rnor, f\u00e5r oss att k\u00e4nna oss utvalda.", real_world_scenario: "I universitetsseminariet h\u00f6ll professorn blicken p\u00e5 varje student som talade, medan den nerv\u00f6sa utbytesstudenten s\u00e4nkte blicken i samma \u00f6gonblick som han avslutat en mening \u2014 ett klassiskt m\u00f6nster av blick\u00f6verl\u00e4gsenhet d\u00e4r personen med h\u00f6gre status tittar fritt medan den med l\u00e4gre status tittar n\u00e4r den lyssnar men inte n\u00e4r den talar.", case_study_cloze: "Studier visar att personer med h\u00f6g status har mer ____ \u00e4n de med mindre makt, s\u00e4rskilt n\u00e4r de talar." } },
      { concept: "GAZE AND SENTIMENTS", definition: "Around the world, those who study dating cues have noted that oftentimes the first clue that people's feeling for each other have changed is how they look at each other. Long before words are exchanged, the look of increased interest telegraphs that the relationship is changing from friendly to more intimate. How Julie Andrews (as Maria) began to change the way she looked at Christopher Plummer (Captain Von", category: "body-language-extracted", real_world_scenario: "Long before they admitted anything, Laura noticed that her colleague began holding her gaze a beat longer and smiling with her eyes during lunch \u2014 the change in how they looked at each other told her the friendship was slowly becoming something more.", case_study_cloze: "The first clue that feelings between two people have changed is often a shift in how they ____ at each other, long before any words are exchanged.", sv: { concept: "Blick och k\u00e4nslor", definition: "Runt om i v\u00e4rlden har de som studerar dejting-signaler noterat att det ofta f\u00f6rsta tecknet p\u00e5 att m\u00e4nniskors k\u00e4nslor f\u00f6r varandra har f\u00f6r\u00e4ndrats \u00e4r hur de ser p\u00e5 varandra. L\u00e5ngt innan ord v\u00e4xlas signalerar blicken av \u00f6kat intresse att relationen h\u00e5ller p\u00e5 att f\u00f6r\u00e4ndras fr\u00e5n v\u00e4nskaplig till mer intim. S\u00e5 h\u00e4r b\u00f6rjade Julie Andrews (som Maria) \u00e4ndra sitt s\u00e4tt att se p\u00e5 Christopher Plummer (Kapten Von Trapp) och signalerade sin v\u00e4xande k\u00e4rlek till honom.", real_world_scenario: "L\u00e5ngt innan de erk\u00e4nde n\u00e5got m\u00e4rkte Laura att hennes kollega b\u00f6rjade h\u00e5lla blicken en aning l\u00e4ngre och le med \u00f6gonen under lunchen \u2014 f\u00f6r\u00e4ndringen i hur de s\u00e5g p\u00e5 varandra ber\u00e4ttade att v\u00e4nskapen sakta h\u00f6ll p\u00e5 att bli n\u00e5got mer.", case_study_cloze: "Det f\u00f6rsta tecknet p\u00e5 att k\u00e4nslorna mellan tv\u00e5 m\u00e4nniskor har f\u00f6r\u00e4ndrats \u00e4r ofta en f\u00f6r\u00e4ndring i hur de ____ p\u00e5 varandra, l\u00e5ngt innan n\u00e5gra ord v\u00e4xlas." } },
      { concept: "GAZE ENGAGING", definition: "This is a behavior intended to get the attention of another person in a warm or romantic way. What makes this behavior stand out is the softness of the face and the repeated attempts to connect, eye to eye, always with a gentleness of the eyes, face, and mouth. We most often see this in dating settings, where it lets the other person know you are interested in further contact or proximity. I have seen strangers engage gazes across broad spaces, communicating their yearning.", category: "body-language-extracted", real_world_scenario: "At the wedding reception, the bridesmaid caught the best man's eye twice across the dance floor, holding each gaze just a moment with a soft, open face \u2014 a gentle gaze engaging that wordlessly asked whether he might come over.", case_study_cloze: "With a soft face and repeated attempts to catch his eye across the room, she was ____ with him, a warm invitation to closer contact.", sv: { concept: "Inbjudande blick", definition: "Detta \u00e4r ett beteende som syftar till att f\u00e5nga en annan persons uppm\u00e4rksamhet p\u00e5 ett varmt eller romantiskt s\u00e4tt. Det som f\u00e5r beteendet att sticka ut \u00e4r mjukheten i ansiktet och de upprepade f\u00f6rs\u00f6ken att f\u00e5 \u00f6gonkontakt, alltid med en mildhet i \u00f6gon, ansikte och mun. Vi ser det oftast i dejting-sammanhang, d\u00e4r det l\u00e5ter den andra personen veta att du \u00e4r intresserad av fortsatt kontakt eller n\u00e4rhet. Jag har sett fr\u00e4mlingar utbyta inbjudande blickar \u00f6ver stora avst\u00e5nd och kommunicera sin l\u00e4ngtan.", real_world_scenario: "P\u00e5 br\u00f6llopsfesten f\u00e5ngade brudt\u00e4rnan brudgummens v\u00e4ns blick tv\u00e5 g\u00e5nger \u00f6ver dansgolvet och h\u00f6ll varje blick bara ett \u00f6gonblick med ett mjukt, \u00f6ppet ansikte \u2014 en f\u00f6rsiktig inbjudande blick som ordl\u00f6st fr\u00e5gade om han ville komma \u00f6ver.", case_study_cloze: "Med ett mjukt ansikte och upprepade f\u00f6rs\u00f6k att f\u00e5nga hans blick \u00f6ver rummet ____ hon med honom, en varm inbjudan till n\u00e4rmare kontakt." } },
      { concept: "GAZING VERSUS STARING", definition: "There is a big difference between gazing at someone and staring at someone. Staring tends to be more impersonal, distant, or confrontational, signaling that we find someone suspicious, alarming, or odd. On the other hand, gazing signals that we take comfort in someone, a much more inviting behavior. When we stare we are on alert; when we gaze we are intrigued, even welcoming. Staring can trigger offense, especially in close quarters such as a bus or subway.", category: "body-language-extracted", real_world_scenario: "On the subway, the man across the aisle fixed his eyes on a teenage girl without blinking, and she could feel the offense of his stare; the woman beside her, in contrast, glanced over with a relaxed, open gaze that simply acknowledged her presence.", case_study_cloze: "Unlike ____, which signals alertness or confrontation, gazing at someone signals that we take comfort in them.", sv: { concept: "Att se kontra att stirra", definition: "Det \u00e4r stor skillnad mellan att se p\u00e5 n\u00e5gon och att stirra p\u00e5 n\u00e5gon. Stirrande tenderar att vara mer opersonligt, distanserat eller konfrontativt och signalerar att vi tycker att n\u00e5gon \u00e4r misst\u00e4nkt, oroande eller konstig. Att se p\u00e5 n\u00e5gon signalerar d\u00e4remot att vi k\u00e4nner oss trygga med personen, ett betydligt mer inbjudande beteende. N\u00e4r vi stirrar \u00e4r vi p\u00e5 sp\u00e4nn; n\u00e4r vi ser p\u00e5 n\u00e5gon \u00e4r vi nyfikna, till och med v\u00e4lkomnande. Stirrande kan v\u00e4cka anst\u00f6t, s\u00e4rskilt p\u00e5 n\u00e4ra h\u00e5ll som p\u00e5 buss eller tunnelbana.", real_world_scenario: "I tunnelbanan f\u00e4ste mannen p\u00e5 andra sidan g\u00e5ngen blicken p\u00e5 en ton\u00e5rsflicka utan att blinka, och hon k\u00e4nde hur ofredande stirrandet var; kvinnan bredvid henne kastade d\u00e4remot en avslappnad, \u00f6ppen blick som bara bekr\u00e4ftade hennes n\u00e4rvaro.", case_study_cloze: "Till skillnad fr\u00e5n ____, som signalerar uppm\u00e4rksamhet eller konfrontation, signalerar det att se p\u00e5 n\u00e5gon att vi k\u00e4nner oss trygga med personen." } },
      { concept: "CLOSED EYES", definition: "During a meeting, someone with closed eyes that take a long time to open or that suddenly shut and remain so for longer than usual is probably having issues. It is a blocking behavior that reveals dislike, concern, disbelief, or worries-some form of psychological discomfort. Long delays in eye opening reveal deep concern. Conversely, in an intimate setting, closed eyes say, \\\"I trust you, I am blocking everything else out, and I am in the moment with my other senses.\\\" Notably, even children born blind will cover their eyes when they hear things they don't like or they find troubling.", category: "body-language-extracted", real_world_scenario: "When the CFO announced the budget cuts, the department head shut her eyes for several long seconds and only slowly opened them again \u2014 a blocking behavior that revealed her deep concern about the decision.", case_study_cloze: "Eyes that suddenly shut and stay shut longer than usual are a ____ behavior that reveals dislike, concern, disbelief, or worry.", sv: { concept: "Slutna \u00f6gon", definition: "Under ett m\u00f6te har n\u00e5gon med slutna \u00f6gon som tar l\u00e5ng tid att \u00f6ppna, eller som pl\u00f6tsligt sluts och f\u00f6rblir st\u00e4ngda l\u00e4ngre \u00e4n vanligt, troligen problem. Det \u00e4r ett blockerande beteende som avsl\u00f6jar motvilja, oro, misstro eller bekymmer \u2014 n\u00e5gon form av psykiskt obehag. L\u00e5ng f\u00f6rdr\u00f6jning innan \u00f6gonen \u00f6ppnas avsl\u00f6jar djup oro. I en intim situation s\u00e4ger slutna \u00f6gon d\u00e4remot: 'Jag litar p\u00e5 dig, jag st\u00e4nger ute allt annat och jag \u00e4r h\u00e4r och nu med mina andra sinnen.' Anm\u00e4rkningsv\u00e4rt nog t\u00e4cker till och med barn som f\u00f6ds blinda f\u00f6r \u00f6gonen n\u00e4r de h\u00f6r saker de inte tycker om eller finner oroande.", real_world_scenario: "N\u00e4r ekonomichefen tillk\u00e4nnagav budgetnedsk\u00e4rningarna sl\u00f6t avdelningschefen \u00f6gonen i flera l\u00e5nga sekunder och \u00f6ppnade dem bara l\u00e5ngsamt igen \u2014 ett blockerande beteende som avsl\u00f6jade hennes djupa oro f\u00f6r beslutet.", case_study_cloze: "\u00d6gon som pl\u00f6tsligt sluts och f\u00f6rblir st\u00e4ngda l\u00e4ngre \u00e4n vanligt \u00e4r ett ____ beteende som avsl\u00f6jar motvilja, oro, misstro eller bekymmer." } },
      { concept: "EYES CLOSING FOR EMPHASIS", definition: "Oftentimes, when we want to emphasize something or agree in congruence, we will close the eyes ever so briefly. It is a way of affirming what is being said. As with all behaviors, context is key to ensure it is not a reflection of disagreement.", category: "body-language-extracted", real_world_scenario: "While the coach explained the game plan, the quarterback nodded and briefly closed his eyes each time he agreed, a subtle signal that he was fully on board with the strategy.", case_study_cloze: "When we want to affirm what someone is saying, we may briefly ____ our eyes as a way of emphasizing our agreement.", sv: { concept: "Slutna \u00f6gon f\u00f6r eftertryck", definition: "Ofta n\u00e4r vi vill betona n\u00e5got eller h\u00e5ller med i samklang sluter vi \u00f6gonen helt kort. Det \u00e4r ett s\u00e4tt att bekr\u00e4fta det som s\u00e4gs. Som med alla beteenden \u00e4r sammanhanget avg\u00f6rande f\u00f6r att s\u00e4kerst\u00e4lla att det inte \u00e4r ett tecken p\u00e5 oenighet.", real_world_scenario: "Medan tr\u00e4naren f\u00f6rklarade matchplanen nickade quarterbacken och sl\u00f6t \u00f6gonen helt kort varje g\u00e5ng han h\u00f6ll med, en subtil signal om att han fullt ut st\u00f6dde strategin.", case_study_cloze: "N\u00e4r vi vill bekr\u00e4fta det n\u00e5gon s\u00e4ger sluter vi ofta ____ helt kort som ett s\u00e4tt att betona v\u00e5r \u00f6verensst\u00e4mmelse." } },
      { concept: "COVERING OF EYES", definition: "Sudden covering of the eyes with a hand or fingers is a blocking behavior associated with a negative event, such as the revelation of bad news or threatening information. It also indicates negative emotions,", category: "body-language-extracted", real_world_scenario: "When the referee showed the red card, the goalkeeper immediately slapped both hands over his eyes, a blocking response to the bad news he had just seen.", case_study_cloze: "The sudden ____ of the eyes with a hand or fingers is a blocking behavior typically seen when someone receives bad or threatening news.", sv: { concept: "Att t\u00e4cka \u00f6gonen", definition: "Att pl\u00f6tsligt t\u00e4cka \u00f6gonen med handen eller fingrarna \u00e4r ett blockerande beteende som f\u00f6rknippas med en negativ h\u00e4ndelse, till exempel n\u00e4r d\u00e5liga nyheter eller hotfull information avsl\u00f6jas. Det tyder ocks\u00e5 p\u00e5 negativa k\u00e4nslor.", real_world_scenario: "N\u00e4r domaren visade det r\u00f6da kortet slog m\u00e5lvakten direkt b\u00e5da h\u00e4nderna f\u00f6r \u00f6gonen, ett blockerande svar p\u00e5 den d\u00e5liga nyheten han just sett.", case_study_cloze: "Att pl\u00f6tsligt ____ \u00f6gonen med handen eller fingrarna \u00e4r ett blockerande beteende som typiskt ses n\u00e4r n\u00e5gon f\u00e5r d\u00e5liga eller hotfulla nyheter." } },
      { concept: "EYES DARTING", definition: "Eyes that dart back and forth feverishly are usually associated with the processing of negative information, doubt, anxiety, fear, or concern. Use this behavior in conjunction with other information such as facial tension or chin withdrawal ( see #184) to provide a more accurate assessment. It should be noted that some people will dart their eyes back and forth as they analyze a situation, consider options, or think of solutions. This behavior alone is not itself indicative of deception.", category: "body-language-extracted", real_world_scenario: "During the police interview, the witness's eyes darted back and forth between the officer and the wall each time the suspect's name came up \u2014 a sign of anxiety and information processing, not necessarily proof of lying.", case_study_cloze: "Eyes that dart feverishly back and forth often signal the processing of negative information, but the behavior alone is not proof of ____.", sv: { concept: "Rastl\u00f6sa \u00f6gon", definition: "\u00d6gon som febrilt far fram och tillbaka brukar f\u00f6rknippas med bearbetning av negativ information, tvivel, \u00e5ngest, r\u00e4dsla eller oro. Anv\u00e4nd detta beteende tillsammans med annan information, s\u00e5som ansiktssp\u00e4nning eller att hakan dras tillbaka, f\u00f6r en mer tillf\u00f6rlitlig bed\u00f6mning. Det b\u00f6r noteras att vissa m\u00e4nniskor r\u00f6r \u00f6gonen fram och tillbaka n\u00e4r de analyserar en situation, \u00f6verv\u00e4ger alternativ eller t\u00e4nker ut l\u00f6sningar. Beteendet i sig \u00e4r inte ett tecken p\u00e5 l\u00f6gn.", real_world_scenario: "Under polisf\u00f6rh\u00f6ret fl\u00f6g vittnets blick fram och tillbaka mellan polisen och v\u00e4ggen varje g\u00e5ng den misst\u00e4nktes namn kom upp \u2014 ett tecken p\u00e5 \u00e5ngest och tankebearbetning, inte n\u00f6dv\u00e4ndigtvis bevis f\u00f6r l\u00f6gn.", case_study_cloze: "\u00d6gon som febrilt far fram och tillbaka signalerar ofta bearbetning av negativ information, men beteendet i sig \u00e4r inte bevis f\u00f6r ____." } },
      { concept: "EYE ROLLING", definition: "Rolling of the eyes communicates contempt, disagreement, or dislike. Children often do it to their parents to communicate contention or rebellion. It has no place in a professional setting.", category: "body-language-extracted", real_world_scenario: "When the grandmother reminded everyone for the third time to bring a dish to the holiday dinner, her teenage grandson rolled his eyes at his sister \u2014 a silent display of contempt that did nothing for family harmony.", case_study_cloze: "Rolling the eyes communicates ____, disagreement, or dislike, and it has no place in a professional setting.", sv: { concept: "Att rulla med \u00f6gonen", definition: "Att rulla med \u00f6gonen f\u00f6rmedlar f\u00f6rakt, oenighet eller motvilja. Barn g\u00f6r det ofta mot sina f\u00f6r\u00e4ldrar f\u00f6r att uttrycka opposition eller rebelliskhet. Det har ingen plats i ett professionellt sammanhang.", real_world_scenario: "N\u00e4r mormodern f\u00f6r tredje g\u00e5ngen p\u00e5minde alla om att ta med en r\u00e4tt till julmiddagen rullade ton\u00e5rssonsonen med \u00f6gonen \u00e5t sin syster \u2014 en tyst f\u00f6raktfullhet som inte gynnade familjefriden.", case_study_cloze: "Att rulla med \u00f6gonen f\u00f6rmedlar ____, oenighet eller motvilja, och det har ingen plats i ett professionellt sammanhang." } },
      { concept: "EYELID TOUCHING", definition: "Eyelid touching can be a form of eye blocking coupled with tension relief. Often when people say something they shouldn't have, people nearby will touch or scratch their closed eyelid-this is a good indicator that something improper was uttered. You see this often with politicians when one misspeaks and another catches it.", category: "body-language-extracted", real_world_scenario: "During the press conference, the press secretary inadvertently called the minister 'the governor,' and the minister's aide immediately touched his own closed eyelid, a tell that something improper had just been said.", case_study_cloze: "When someone nearby touches or scratches a closed eyelid after a remark, it is often a sign that something ____ was just said.", sv: { concept: "Att r\u00f6ra vid \u00f6gonlocket", definition: "Att r\u00f6ra vid \u00f6gonlocket kan vara en form av \u00f6gonblockering i kombination med sp\u00e4nningslindring. Ofta n\u00e4r n\u00e5gon sagt n\u00e5got de inte borde har n\u00e4rst\u00e5ende personer f\u00f6r vana att r\u00f6ra vid eller klia sig p\u00e5 det slutna \u00f6gonlocket \u2014 detta \u00e4r en bra indikator p\u00e5 att n\u00e5got ol\u00e4mpligt yttrades. Man ser det ofta med politiker n\u00e4r en feluttalar sig och en annan uppt\u00e4cker det.", real_world_scenario: "Under presskonferensen kallade pressekreteraren av misstag ministern 'guvern\u00f6ren', och ministerns medarbetare r\u00f6rde omedelbart vid sitt slutna \u00f6gonlock, ett avsl\u00f6jande tecken p\u00e5 att n\u00e5got ol\u00e4mpligt just hade sagts.", case_study_cloze: "N\u00e4r n\u00e5gon i n\u00e4rheten r\u00f6r vid eller kliar sig p\u00e5 ett slutet \u00f6gonlock efter en kommentar \u00e4r det ofta ett tecken p\u00e5 att n\u00e5got ____ just sades." } },
      { concept: "FATIGUED EYES", definition: "Fatigue usually shows in the eyes first. The eyes and the area around them look strained, puffy, weathered, even discolored. This may be due to long hours working; external factors, such as stress; or crying.", category: "body-language-extracted", real_world_scenario: "The night-shift nurse looked down at the young mother and saw strained, puffy eyes with dark circles after twelve hours of caring for a crying newborn \u2014 the fatigue she tried to hide was plain to read in her eyes.", case_study_cloze: "Fatigue usually shows first in the ____, which may look strained, puffy, or discolored.", sv: { concept: "Tr\u00f6tta \u00f6gon", definition: "Tr\u00f6tthet syns oftast f\u00f6rst i \u00f6gonen. \u00d6gonen och omr\u00e5det runt dem ser anstr\u00e4ngda, svullna, v\u00e4derbitna eller till och med missf\u00e4rgade ut. Det kan bero p\u00e5 l\u00e5nga arbetsdagar, yttre faktorer som stress, eller gr\u00e5t.", real_world_scenario: "Nattsk\u00f6terskan s\u00e5g ner p\u00e5 den unga mamman och s\u00e5g anstr\u00e4ngda, svullna \u00f6gon med m\u00f6rka ringar efter tolv timmar med en gr\u00e5tande nyf\u00f6dd \u2014 tr\u00f6ttheten hon f\u00f6rs\u00f6kte d\u00f6lja gick rakt att l\u00e4sa i \u00f6gonen.", case_study_cloze: "Tr\u00f6tthet syns oftast f\u00f6rst i ____, som kan se anstr\u00e4ngda, svullna eller missf\u00e4rgade ut." } },
      { concept: "GLAZED EYES", definition: "Any number of things can cause the eyes to look glazed, including drugs such as marijuana and alcohol as well as more dangerous substances. When trying to assess whether a person is under the influence of drugs or alcohol, an observer will want to take other behaviors into consideration, such as slurred speech or slowness to respond.", category: "body-language-extracted", real_world_scenario: "Pulled over late at night, the driver's eyes had a glazed, unfocused look, and the officer noted slurred speech and slow reactions before concluding that the man had been drinking.", case_study_cloze: "When assessing whether someone is intoxicated, a ____ look in the eyes should be weighed together with other signs such as slurred speech and slow responses.", sv: { concept: "Glasartade \u00f6gon", definition: "M\u00e5nga saker kan f\u00e5 \u00f6gonen att se glasartade ut, bland annat droger som marijuana och alkohol samt farligare substanser. N\u00e4r man f\u00f6rs\u00f6ker bed\u00f6ma om en person \u00e4r p\u00e5verkad av droger eller alkohol b\u00f6r observat\u00f6ren ta h\u00e4nsyn till andra beteenden, s\u00e5som sluddrigt tal eller l\u00e5ngsamhet att svara.", real_world_scenario: "N\u00e4r han stoppades sent p\u00e5 natten hade f\u00f6raren ett glasartat, fr\u00e5nvarande uttryck i \u00f6gonen, och polisen noterade sluddrigt tal och l\u00e5ngsamma reaktioner innan han drog slutsatsen att mannen hade druckit.", case_study_cloze: "N\u00e4r man bed\u00f6mer om n\u00e5gon \u00e4r p\u00e5verkad b\u00f6r ett ____ uttryck i \u00f6gonen v\u00e4gas mot andra tecken som sluddrigt tal och l\u00e5ngsamma reaktioner." } },
      { concept: "LOOKING ASKANCE", definition: "Looking askance (sideways) is often used to show a person's doubt, reluctance to commit, disregard, suspiciousness, or even contempt. It is a universal look that reflects disbelief, concerns, or incredulity.", category: "body-language-extracted", real_world_scenario: "When the salesman quoted the final price, the customer looked askance at him from the corner of her eye, a sideways glance that said she had serious doubts about the offer.", case_study_cloze: "A sideways look, known as looking ____, often reveals doubt, suspicion, or reluctance to commit.", sv: { concept: "Sned blick", definition: "Att se snett p\u00e5 n\u00e5gon anv\u00e4nds ofta f\u00f6r att visa tvivel, ovilja att f\u00f6rbinda sig, f\u00f6rakt, misst\u00e4nksamhet eller till och med f\u00f6raktfullhet. Det \u00e4r en universell blick som \u00e5terspeglar misstro, oro eller f\u00f6rv\u00e5ning.", real_world_scenario: "N\u00e4r s\u00e4ljaren angav slutpriset s\u00e5g kunden snett p\u00e5 honom ur \u00f6gonvr\u00e5n, en sidoblick som sa att hon hade allvarliga tvivel p\u00e5 erbjudandet.", case_study_cloze: "En sidoblick, att se ____ p\u00e5 n\u00e5gon, avsl\u00f6jar ofta tvivel, misst\u00e4nksamhet eller ovilja att f\u00f6rbinda sig." } },
      { concept: "LOOKING FOR ACCEPTANCE", definition: "When individuals lack confidence or lie, they tend to scrutinize their audience, scanning faces to see if they are being believed. This behavior is not necessarily demonstrative of deception, only of seeking acceptance for what is said. A rule of thumb: the truth teller merely conveys, while the liar often tries to convince.", category: "body-language-extracted", real_world_scenario: "During the job interview, the candidate kept scanning the panel's faces after every answer, searching for a nod of approval \u2014 the behavior suggested he was looking for acceptance rather than simply telling his story.", case_study_cloze: "People who lack confidence, or who lie, often scan their audience's faces, ____ for signs that they are being believed.", sv: { concept: "Att s\u00f6ka bekr\u00e4ftelse", definition: "N\u00e4r individer saknar sj\u00e4lvf\u00f6rtroende eller ljuger tenderar de att granska sin publik och s\u00f6ka i ansiktena efter tecken p\u00e5 att de blir trodda. Detta beteende \u00e4r inte n\u00f6dv\u00e4ndigtvis ett tecken p\u00e5 l\u00f6gn, bara p\u00e5 att s\u00f6ka bekr\u00e4ftelse f\u00f6r det som s\u00e4gs. En tumregel: den som talar sanning f\u00f6rmedlar bara, medan l\u00f6gnaren ofta f\u00f6rs\u00f6ker \u00f6vertyga.", real_world_scenario: "Under anst\u00e4llningsintervjun svepte kandidaten blicken \u00f6ver panelens ansikten efter varje svar och letade efter ett godk\u00e4nnande nickande \u2014 beteendet antydde att han s\u00f6kte bekr\u00e4ftelse snarare \u00e4n att bara ber\u00e4tta sin historia.", case_study_cloze: "M\u00e4nniskor som saknar sj\u00e4lvf\u00f6rtroende, eller som ljuger, granskar ofta sin publiks ansikten och ____ efter tecken p\u00e5 att de blir trodda." } },
      { concept: "EYES LOWERED", definition: "This is different from eye avoidance in that the individual does not break eye contact but rather shows deference, piety, humility, or contriteness by slightly lowering the eyes so that eye contact is not direct or intense. This is often culture based, and we see it frequently with children who are taught not to look back at elders or authority figures when being chastised. Black and Latino children are often taught to look down as a form of respect, which should in no circumstances be confused for an attempt to deceive. In Japan it is rude to stare intently at the eyes of a person you meet for the first time; at a minimum, the eyelids must be lowered out of social deference.", category: "body-language-extracted", real_world_scenario: "When the teacher scolded him in front of the class, the boy lowered his eyes and studied his shoes, a culturally taught sign of respect and contrition rather than an attempt to deceive.", case_study_cloze: "In many cultures, children are taught to ____ their eyes when chastised by elders, as a sign of deference rather than deception.", sv: { concept: "S\u00e4nkta \u00f6gon", definition: "Detta skiljer sig fr\u00e5n undvikande av \u00f6gonkontakt genom att individen inte bryter \u00f6gonkontakten utan snarare visar v\u00f6rdnad, fromhet, \u00f6dmjukhet eller \u00e5nger genom att s\u00e4nka \u00f6gonen n\u00e5got s\u00e5 att \u00f6gonkontakten inte \u00e4r direkt eller intensiv. Detta \u00e4r ofta kulturrelaterat, och vi ser det ofta hos barn som l\u00e4rts att inte se tillbaka p\u00e5 \u00e4ldre eller auktoriteter n\u00e4r de blir tillr\u00e4ttavisade. Svarta och latinamerikanska barn l\u00e4rs ofta att se ner som en form av respekt, vilket inte i n\u00e5got fall b\u00f6r f\u00f6rv\u00e4xlas med ett f\u00f6rs\u00f6k att lura. I Japan \u00e4r det oartigt att stirra intensivt i \u00f6gonen p\u00e5 en person man tr\u00e4ffar f\u00f6r f\u00f6rsta g\u00e5ngen; som minst ska \u00f6gonlocken s\u00e4nkas av social v\u00f6rdnad.", real_world_scenario: "N\u00e4r l\u00e4raren tillr\u00e4ttavisade honom inf\u00f6r klassen s\u00e4nkte pojken blicken och studerade sina skor, ett kulturellt inl\u00e4rt tecken p\u00e5 respekt och \u00e5nger snarare \u00e4n ett f\u00f6rs\u00f6k att lura.", case_study_cloze: "I m\u00e5nga kulturer l\u00e4rs barn att ____ \u00f6gonen n\u00e4r de tillr\u00e4ttavisas av \u00e4ldre, som ett tecken p\u00e5 v\u00f6rdnad snarare \u00e4n bedr\u00e4geri." } },
      { concept: "SAD EYES", definition: "Eyes look sad, dejected, or depressed when the upper eyelids", category: "body-language-extracted", real_world_scenario: "At the airport departure gate, his mother's eyes looked sad and heavy, the upper lids drooping, even though she kept a brave smile for the farewell.", case_study_cloze: "Sadness shows in the face when the upper eyelids ____, making the eyes look dejected or depressed.", sv: { concept: "Sorgsna \u00f6gon", definition: "\u00d6gonen ser sorgsna, nedst\u00e4mda eller deprimerade ut n\u00e4r de \u00f6vre \u00f6gonlocken sjunker eller h\u00e5lls l\u00e4gre \u00e4n normalt.", real_world_scenario: "Vid avg\u00e5ngsporten p\u00e5 flygplatsen s\u00e5g hans mammas \u00f6gon sorgsna och tunga ut med h\u00e4ngande \u00f6vre \u00f6gonlock, trots att hon h\u00f6ll ett modigt leende f\u00f6r avskedet.", case_study_cloze: "Sorg syns i ansiktet n\u00e4r de \u00f6vre \u00f6gonlocken ____, s\u00e5 att \u00f6gonen ser nedst\u00e4mda eller deprimerade ut." } },
      { concept: "LOOKING AWAY", definition: "Looking away when conversing has to be viewed in context. When there is psycho logical comfort, such as when talking to friends, we may feel relaxed enough to look away as we tell a story or remember something from the past. Many individuals find looking away helps them recall details. Looking away is not an indication of deception or lying.", category: "body-language-extracted", real_world_scenario: "While telling his friends about his childhood summer camp, Daniel looked away toward the window and paused \u2014 not because he was hiding anything, but because looking away helped him recall the details of the story.", case_study_cloze: "Looking away during a conversation is not necessarily a sign of deception; many people find it helps them ____ details from the past.", sv: { concept: "Att titta bort", definition: "Att titta bort under ett samtal m\u00e5ste bed\u00f6mas i sitt sammanhang. N\u00e4r det finns psykologisk trygghet, som n\u00e4r man talar med v\u00e4nner, kan vi k\u00e4nna oss avslappnade nog att titta bort medan vi ber\u00e4ttar en historia eller minns n\u00e5got fr\u00e5n f\u00f6rr. M\u00e5nga upplever att det hj\u00e4lper dem att minnas detaljer. Att titta bort \u00e4r inte ett tecken p\u00e5 l\u00f6gn eller bedr\u00e4geri.", real_world_scenario: "Medan Daniel ber\u00e4ttade f\u00f6r sina v\u00e4nner om sitt barndoms sommarl\u00e4ger tittade han bort mot f\u00f6nstret och tystnade \u2014 inte f\u00f6r att han dolde n\u00e5got, utan f\u00f6r att det hj\u00e4lpte honom att minnas detaljerna i historien.", case_study_cloze: "Att titta bort under ett samtal \u00e4r inte n\u00f6dv\u00e4ndigtvis ett tecken p\u00e5 l\u00f6gn; m\u00e5nga tycker att det hj\u00e4lper dem att ____ detaljer fr\u00e5n f\u00f6rr." } },
      { concept: "LONG STARE", definition: "In conversations, silence is often accompanied by a long stare. It can be directed at a person or at something in the distance; it merely indicates that the person is in deep thought or processing information.", category: "body-language-extracted", real_world_scenario: "When the engineer was asked whether the project could meet the deadline, she went quiet and stared at the whiteboard for several seconds, processing the numbers before she answered.", case_study_cloze: "A long stare during a silence usually means the person is in deep ____ or processing information, not that they are ignoring you.", sv: { concept: "L\u00e5ng blick", definition: "I samtal \u00e5tf\u00f6ljs tystnad ofta av en l\u00e5ng blick. Den kan riktas mot en person eller mot n\u00e5got i fj\u00e4rran; den anger bara att personen \u00e4r f\u00f6rdjupad i tankar eller bearbetar information.", real_world_scenario: "N\u00e4r ingenj\u00f6ren fick fr\u00e5gan om projektet kunde klara tidsfristen blev hon tyst och stirrade l\u00e4nge p\u00e5 whiteboarden i flera sekunder, medan hon bearbetade siffrorna innan hon svarade.", case_study_cloze: "En l\u00e5ng blick under en tystnad betyder oftast att personen \u00e4r f\u00f6rdjupad i ____ eller bearbetar information, inte att den ignorerar dig." } },
      { concept: "SQUINTING (SLIGHT)", definition: "Often when we are subduing anger we will squint slightly with lowered eyelids. This behavior (narrowing of the slits of the eyes) must be considered in context with other behaviors such as facial tension or, in extreme circumstances, the making of a fist.", category: "body-language-extracted", real_world_scenario: "When the manager publicly took credit for her idea, Anna kept her mouth shut but slightly squinted her eyes with lowered lids, the only outward sign of the anger she was suppressing.", case_study_cloze: "When we are subduing anger, we often ____ slightly with lowered eyelids, narrowing the slits of the eyes.", sv: { concept: "L\u00e4tt knipta \u00f6gon", definition: "Ofta n\u00e4r vi d\u00e4mpar ilska kniper vi l\u00e4tt ihop \u00f6gonen med s\u00e4nkta \u00f6gonlock. Detta beteende (att minska \u00f6gonspringorna) m\u00e5ste bed\u00f6mas i sammanhang tillsammans med andra beteenden som ansiktssp\u00e4nning eller, i extrema fall, att knyta n\u00e4ven.", real_world_scenario: "N\u00e4r chefen offentligt tog \u00e5t sig \u00e4ran f\u00f6r hennes id\u00e9 h\u00f6ll Anna tyst men knipte l\u00e4tt ihop \u00f6gonen med s\u00e4nkta \u00f6gonlock, det enda synliga tecknet p\u00e5 ilskan hon d\u00e4mpade.", case_study_cloze: "N\u00e4r vi d\u00e4mpar ilska ____ vi ofta l\u00e4tt med \u00f6gonen med s\u00e4nkta \u00f6gonlock, s\u00e5 att \u00f6gonspringorna minskar." } },
      { concept: "STARING AGGRESSIVELY", definition: "A stare can intimidate or serve as the prelude to an altercation. Aggression is signaled by the laser-like focus on the eyes, with no attempt to look away or even blink. Interestingly, other primates also engage in this behavior when observing behaviors that are not tolerated or when there is about to be a physical confrontation.", category: "body-language-extracted", real_world_scenario: "In the crowded bar, the two men locked eyes without blinking or looking away for nearly a minute, a laser-like stare that everyone around them recognized as the prelude to a fight.", case_study_cloze: "A stare that locks onto another person's eyes without blinking and without looking away signals ____ and can serve as the prelude to an altercation.", sv: { concept: "Aggressivt stirrande", definition: "En blick kan skr\u00e4mma eller fungera som inledning till ett br\u00e5k. Aggression signaleras genom ett laserliknande fokus p\u00e5 \u00f6gonen, utan f\u00f6rs\u00f6k att titta bort eller ens blinka. Intressant nog g\u00f6r \u00e4ven andra primater detta n\u00e4r de observerar beteenden som inte tolereras eller n\u00e4r ett fysiskt br\u00e5k \u00e4r p\u00e5 v\u00e4g.", real_world_scenario: "P\u00e5 den tr\u00e5nga baren l\u00e5ste de tv\u00e5 m\u00e4nnen varandras blickar utan att blinka eller titta bort i n\u00e4stan en minut, ett laserliknande stirrande som alla runt omkring k\u00e4nde igen som inledningen till ett slagsm\u00e5l.", case_study_cloze: "En blick som l\u00e5ser fast vid en annan persons \u00f6gon utan att blinka och utan att titta bort signalerar ____ och kan vara inledningen till ett br\u00e5k." } },
      { concept: "ANGRY EYES", definition: "Anger is usually displayed by a constellation of facial cues beginning with the distinctive narrowing of the eyes near the nose (like this: > < ), coupled with a wrinkled or dilated nose and sometimes the pulling back of the lips to reveal clenched teeth.", category: "body-language-extracted", real_world_scenario: "When the car cut him off at the intersection, the driver in the next lane narrowed his eyes into the angry 'greater than and less than' shape, wrinkled his nose, and pulled back his lips to show clenched teeth.", case_study_cloze: "Anger is often shown by a distinctive narrowing of the eyes near the ____, sometimes with a wrinkled nose and clenched teeth.", sv: { concept: "Arga \u00f6gon", definition: "Ilska visas vanligtvis genom en konstellation av ansiktssignaler som b\u00f6rjar med den karakteristiska hopsmala av \u00f6gonen n\u00e4ra n\u00e4san (s\u00e5 h\u00e4r: > <), i kombination med en rynkad eller utvidgad n\u00e4sa och ibland att l\u00e4pparna dras tillbaka s\u00e5 att t\u00e4nderna blottas ihopbitna.", real_world_scenario: "N\u00e4r bilen skar av honom vid korsningen smalnade f\u00f6raren i filen bredvid \u00f6gonen till det arga 'st\u00f6rre \u00e4n och mindre \u00e4n'-m\u00f6nstret, rynkade n\u00e4san och drog tillbaka l\u00e4pparna s\u00e5 att ihopbitna t\u00e4nder syntes.", case_study_cloze: "Ilska visas ofta genom en karakteristisk hopsmalning av \u00f6gonen n\u00e4ra ____, ibland med rynkad n\u00e4sa och ihopbitna t\u00e4nder." } },
      { concept: "EYES WIDENING (STIFF)", definition: "Eyes that remain wide usually indicate stress, surprise, fear, or a significant issue. If the eyes remain stiffly wide longer than usual, something is definitely wrong. This is usually caused by an", category: "body-language-extracted", real_world_scenario: "In the emergency room, the patient's eyes stayed stiffly wide as the doctor explained the diagnosis, and the doctor knew from that unblinking, frozen look that the news had landed hard.", case_study_cloze: "Eyes that remain stiffly wide longer than usual usually indicate stress, surprise, or fear, and they signal that something is ____.", sv: { concept: "Uppsp\u00e4rrade \u00f6gon (stel)", definition: "\u00d6gon som f\u00f6rblir vid\u00f6ppna tyder vanligtvis p\u00e5 stress, f\u00f6rv\u00e5ning, r\u00e4dsla eller en betydande fr\u00e5ga. Om \u00f6gonen f\u00f6rblir stelt vid\u00f6ppna l\u00e4ngre \u00e4n vanligt \u00e4r n\u00e5got definitivt fel. Detta orsakas vanligtvis av en ov\u00e4ntad h\u00e4ndelse eller en stark oro.", real_world_scenario: "P\u00e5 akutmottagningen f\u00f6rblev patientens \u00f6gon stelt vid\u00f6ppna medan l\u00e4karen f\u00f6rklarade diagnosen, och l\u00e4karen f\u00f6rstod av den d\u00e4r or\u00f6rliga, frusna blicken att nyheten hade tagit h\u00e5rt.", case_study_cloze: "\u00d6gon som f\u00f6rblir stelt vid\u00f6ppna l\u00e4ngre \u00e4n vanligt tyder oftast p\u00e5 stress, f\u00f6rv\u00e5ning eller r\u00e4dsla, och de signalerar att n\u00e5got \u00e4r ____." } },
      { concept: "EARLOBE PULLING OR MASSAGING", definition: "Pulling on or massaging the earlobe tends to have a subtle, soothing effect when we are stressed or merely contemplating something. I also associate earlobe rubbing with doubt, hesitation, or weighing of options. In some cultures it means that a person has reservations or is not sure about what is being said. Actor Humphrey Bogart was notorious for playing with his earlobe as he pondered questions.", category: "body-language-extracted", real_world_scenario: "While the buyer studied the contract, he tugged and massaged his earlobe for a full minute, and the sales rep read the gesture as hesitation about the terms.", case_study_cloze: "Pulling or massaging the earlobe has a soothing effect and often accompanies doubt, hesitation, or the weighing of ____.", sv: { concept: "Att dra eller massera \u00f6rsnibben", definition: "Att dra i eller massera \u00f6rsnibben har en subtil, lugnande effekt n\u00e4r vi \u00e4r stressade eller bara begrundar n\u00e5got. Jag f\u00f6rknippar ocks\u00e5 \u00f6rsnibbgnidning med tvivel, tvekan eller v\u00e4gande av alternativ. I vissa kulturer betyder det att en person har inv\u00e4ndningar eller inte \u00e4r s\u00e4ker p\u00e5 det som s\u00e4gs. Sk\u00e5despelaren Humphrey Bogart var \u00f6k\u00e4nd f\u00f6r att leka med sin \u00f6rsnibb n\u00e4r han begrundade fr\u00e5gor.", real_world_scenario: "Medan k\u00f6paren studerade kontraktet drog och masserade han sin \u00f6rsnibb i en hel minut, och s\u00e4ljaren l\u00e4ste gesten som tvekan inf\u00f6r villkoren.", case_study_cloze: "Att dra i eller massera \u00f6rsnibben har en lugnande effekt och \u00e5tf\u00f6ljer ofta tvivel, tvekan eller v\u00e4gande av ____." } },
      { concept: "EAR FLUSHING OR BLUSHING", definition: "Sudden, noticeable flushing of the skin of the ear, as with other parts of the body (face, neck) may be caused by anger, embarrassment, hormonal changes, reactions to medicine, or autonomic arousal caused by fear or anxiety. The skin covering the ear turns pink, red, or purplish. The skin might also feel hot to the touch. Just having one's personal space violated might cause this reaction. Most people have no control over skin blushing ( hyperemia) and for some it is very embarrassing.", category: "body-language-extracted", real_world_scenario: "When the teacher called out the boy for talking during class, his ears turned bright pink within seconds, an involuntary blush that betrayed his embarrassment no matter how cool he tried to act.", case_study_cloze: "A sudden reddening of the ears, known as ear ____, can be caused by embarrassment or anger and is almost impossible to control.", sv: { concept: "R\u00f6dflammande \u00f6ron", definition: "Pl\u00f6tslig, m\u00e4rkbar rodnad av huden p\u00e5 \u00f6rat, liksom p\u00e5 andra kroppsdelar (ansikte, hals), kan orsakas av ilska, f\u00f6rl\u00e4genhet, hormonella f\u00f6r\u00e4ndringar, reaktioner p\u00e5 medicin eller autonom upphetsning orsakad av r\u00e4dsla eller \u00e5ngest. Huden \u00f6ver \u00f6rat blir rosa, r\u00f6d eller purpurf\u00e4rgad. Huden kan ocks\u00e5 k\u00e4nnas het vid ber\u00f6ring. Bara att f\u00e5 sitt personliga utrymme kr\u00e4nkt kan framkalla reaktionen. De flesta har ingen kontroll \u00f6ver hudrodnad (hyperemi), och f\u00f6r vissa \u00e4r det mycket pinsamt.", real_world_scenario: "N\u00e4r l\u00e4raren tillsade pojken f\u00f6r att han pratade under lektionen blev hans \u00f6ron knallrosa inom n\u00e5gra sekunder, en ofrivillig rodnad som avsl\u00f6jade hans f\u00f6rl\u00e4genhet hur cool han \u00e4n f\u00f6rs\u00f6kte vara.", case_study_cloze: "En pl\u00f6tslig rodnad av \u00f6ronen, s\u00e5 kallad ____ av \u00f6ronen, kan orsakas av f\u00f6rl\u00e4genhet eller ilska och \u00e4r n\u00e4stan om\u00f6jlig att kontrollera." } },
      { concept: "EAR LEANING", definition: "Turning or leaning our ear toward a speaker conveys that", category: "body-language-extracted", real_world_scenario: "In the noisy caf\u00e9, the grandmother leaned her ear toward her granddaughter and cupped her hand behind it, letting her know she genuinely wanted to catch every word of the story.", case_study_cloze: "Turning or leaning an ear toward a speaker conveys that we ____ what they have to say.", sv: { concept: "Att luta \u00f6rat fram\u00e5t", definition: "Att v\u00e4nda eller luta \u00f6rat mot en talare f\u00f6rmedlar att vi vill h\u00f6ra vad som s\u00e4gs eller att vi \u00e4r intresserade.", real_world_scenario: "I det bullriga kaf\u00e9et lutade mormodern \u00f6rat mot sitt barnbarn och kupade handen bakom det, s\u00e5 att barnbarnet f\u00f6rstod att hon verkligen ville h\u00f6ra vartenda ord i historien.", case_study_cloze: "Att v\u00e4nda eller luta ____ mot en talare f\u00f6rmedlar att vi vill h\u00f6ra vad som s\u00e4gs." } },
      { concept: "EAR ORNAMENTATION", definition: "There are any number of ways to decorate, deform, perforate, color, plug, or change the natural look of the ears to fit cultural norms. Ear ornamentation is mostly culture-specific and serves a clear purpose-to communicate social status, courtship availability, or group identification. Ear ornamentation often gives us very accurate insight into a person's background, occupation, social status, heritage, or personality.", category: "body-language-extracted", real_world_scenario: "At the family wedding, the groom's grandfather wore small gold hoops in both ears, ornaments that spoke of his seafaring background, while the bride's pearl studs told a quieter story of her own.", case_study_cloze: "Ear ornamentation is mostly culture-specific and is used to communicate social status, courtship availability, or ____ identification.", sv: { concept: "\u00d6rsmyckning", definition: "Det finns hur m\u00e5nga s\u00e4tt som helst att dekorera, deformera, perforera, f\u00e4rga, plugga eller f\u00f6r\u00e4ndra \u00f6ronens naturliga utseende f\u00f6r att passa kulturella normer. \u00d6rsmyckning \u00e4r mestadels kulturspecifik och tj\u00e4nar ett tydligt syfte \u2014 att kommunicera social status, frihetsstatus eller grupptillh\u00f6righet. \u00d6rsmyckning ger oss ofta mycket korrekt inblick i en persons bakgrund, yrke, sociala status, arv eller personlighet.", real_world_scenario: "P\u00e5 familjebr\u00f6llopet bar brudgummens morfar sm\u00e5 guldringar i b\u00e5da \u00f6ronen, smycken som talade om hans sj\u00f6mansbakgrund, medan brudens p\u00e4rl\u00f6rh\u00e4ngen ber\u00e4ttade en tystare historia om henne sj\u00e4lv.", case_study_cloze: "\u00d6rsmyckning \u00e4r mestadels kulturspecifik och anv\u00e4nds f\u00f6r att kommunicera social status, frihetsstatus eller ____-tillh\u00f6righet." } },
      { concept: "SCARRED EARS", definition: "Heat, chemicals, or trauma can damage ear cartilage and tissue. Rugby players, wrestlers, and judokas are susceptible to damaged ears, sometimes called \\\"cauliflower ears.\\\"", category: "body-language-extracted", real_world_scenario: "The judo coach's ears had the lumpy, flattened shape of cauliflower ears, a badge of a lifetime of grappling that told the new students he had paid his dues on the mat.", case_study_cloze: "Rugby players, wrestlers, and judokas are prone to damaged ears, sometimes called ____ ears.", sv: { concept: "\u00c4rr p\u00e5 \u00f6ronen", definition: "V\u00e4rme, kemikalier eller trauma kan skada \u00f6rats brosk och v\u00e4vnad. Rugby- och brottningsspelare samt judout\u00f6vare \u00e4r mottagliga f\u00f6r skadade \u00f6ron, ibland kallade 'blomk\u00e5ls\u00f6ron'.", real_world_scenario: "Judotr\u00e4narens \u00f6ron hade den kn\u00f6liga, tillplattade formen av blomk\u00e5ls\u00f6ron, ett tecken p\u00e5 ett liv med brottning som talade om f\u00f6r de nya eleverna att han hade betalat sitt pris p\u00e5 mattan.", case_study_cloze: "Rugby- och brottningsspelare samt judout\u00f6vare \u00e4r mottagliga f\u00f6r skadade \u00f6ron, ibland kallade ____ \u00f6ron." } },
      { concept: "NOSE WRINKLING UPWARD (DISGUST)", definition: "The signal or cue for disgust usually involves the nose wrinkling upward (also known as a \\\"bunny nose\\\"), while the skin contracts along with the underlying muscle (the nasalis), which is very sensitive to negative emotions. Often this gesture will cause the", category: "body-language-extracted", real_world_scenario: "When her mother-in-law served the fermented herring, Elsa's nose wrinkled upward in the classic bunny nose of disgust before she could stop herself.", case_study_cloze: "The universal signal for disgust is the nose wrinkling ____, sometimes called a bunny nose, with the skin contracting over the nasalis muscle.", sv: { concept: "N\u00e4srynkning upp\u00e5t (\u00e4ckel)", definition: "Signalet eller tecknet p\u00e5 \u00e4ckel inneb\u00e4r vanligtvis att n\u00e4san rynkas upp\u00e5t (\u00e4ven kallat 'kaninn\u00e4sa'), medan huden drar ihop sig tillsammans med den underliggande muskeln (nasalis), som \u00e4r mycket k\u00e4nslig f\u00f6r negativa k\u00e4nslor. Ofta f\u00e5r denna gest f\u00f6ljdverkningar i \u00f6vriga ansiktet.", real_world_scenario: "N\u00e4r hennes sv\u00e4rmor serverade den fermenterade str\u00f6mmingen rynkades Elsas n\u00e4sa upp\u00e5t i den klassiska kaninn\u00e4san av \u00e4ckel innan hon hann hejda sig.", case_study_cloze: "Den universella signalen f\u00f6r \u00e4ckel \u00e4r att n\u00e4san rynkas ____, ibland kallad kaninn\u00e4sa, med huden som drar ihop sig \u00f6ver nasalismuskeln." } },
      { concept: "UNILATERAL NOSE WRINKLING", definition: "As noted above, nose wrinkling or crinkling upward is an accurate indicator of dislike or displeasure and usually occurs on both sides of the nose. However, there are people in whom this occurs only on one side of the nose (uni laterally). As the nose muscles pull upward, wrinkling just one side, they also tend to pull the upper lip of that side of the face. Some people call it the Elvis effect. When the side of the nose is noticeably pulled up, it means the same thing as the full nose wrinkle-dislike.", category: "body-language-extracted", real_world_scenario: "During the budget meeting, the finance director listened as the proposal was praised and wrinkled just the right side of his nose, the one-sided 'Elvis' wrinkle that said he disliked what he was hearing.", case_study_cloze: "When the nose wrinkle appears on only one side of the face, it is called the ____ effect, and it means the same as a full nose wrinkle: dislike.", sv: { concept: "Ensidig n\u00e4srynkning", definition: "Som n\u00e4mnts ovan \u00e4r n\u00e4srynkning eller n\u00e4sveckning upp\u00e5t en korrekt indikator p\u00e5 motvilja eller missn\u00f6je och sker vanligtvis p\u00e5 b\u00e5da sidor av n\u00e4san. Det finns dock m\u00e4nniskor d\u00e4r detta bara sker p\u00e5 ena sidan av n\u00e4san. N\u00e4r n\u00e4sans muskler drar upp\u00e5t och bara rynkar ena sidan, tenderar de ocks\u00e5 att dra upp \u00f6verl\u00e4ppen p\u00e5 den sidan av ansiktet. Vissa kallar det Elviseffekten. N\u00e4r sidan av n\u00e4san tydligt dras upp\u00e5t betyder det samma sak som en full n\u00e4srynkning \u2014 motvilja.", real_world_scenario: "Under budgetm\u00f6tet lyssnade ekonomichefen n\u00e4r f\u00f6rslaget hyllades och rynkade bara den h\u00f6gra sidan av n\u00e4san, den ensidiga 'Elvis'-rynkan som sa att han ogillade det han h\u00f6rde.", case_study_cloze: "N\u00e4r n\u00e4srynkan bara syns p\u00e5 ena sidan av ansiktet kallas det ____ effekten, och det betyder samma sak som en full n\u00e4srynkning: motvilja." } },
      { concept: "NOSE TWITCHING (CARIBBEAN)", definition: "This behavior is somewhat similar to the disgust display above (see #86) but occurs much faster, sometimes in as little as th of a second. When a person looks directly at someone, the nose 1/25 muscle will contract rapidly, wrinkling the nose upward-but without the eyes squinting as in the disgust cue above. This behavior is a linguistic shortcut that wordlessly asks \\\"What's going on?\\\" \\\"What happened?\\\" \\\"What do you need?\\\" It is seen throughout the Caribbean, including in Cuba, Puerto Rico, and the Dominican Republic, and thus also found in U.S. cities that have large Caribbean populations such as Miami and New York. At the Miami International Airport, I'm frequently greeted at the coffee counter with this nose twitch, which means \\\"What can I get you?\\\" If you see it, just place your order.", category: "body-language-extracted", real_world_scenario: "At the coffee counter at the Miami airport, the barista looked at the traveler and twitched her nose in a quick upward flash, wordlessly asking what she could get him \u2014 a familiar Caribbean greeting.", case_study_cloze: "In the Caribbean, a rapid nose twitch is a linguistic shortcut that wordlessly asks, 'What's ____?'", sv: { concept: "N\u00e4sryckning (karibisk)", definition: "Detta beteende liknar \u00e4ckeluttrycket ovan men sker mycket snabbare, ibland p\u00e5 s\u00e5 lite som en 25-del av en sekund. N\u00e4r en person ser direkt p\u00e5 n\u00e5gon drar n\u00e4sans muskel ihop sig snabbt och rynkar n\u00e4san upp\u00e5t \u2014 men utan att \u00f6gonen kniper ihop som i \u00e4ckelsignalen ovan. Detta beteende \u00e4r en spr\u00e5klig genv\u00e4g som ordl\u00f6st fr\u00e5gar 'Vad \u00e4r p\u00e5 g\u00e5ng?', 'Vad h\u00e4nde?', 'Vad beh\u00f6ver du?'. Det ses i hela Karibien, inklusive Kuba, Puerto Rico och Dominikanska republiken, och finns d\u00e4rf\u00f6r ocks\u00e5 i amerikanska st\u00e4der med stora karibiska befolkningar som Miami och New York. P\u00e5 Miamis internationella flygplats blir jag ofta h\u00e4lsad vid kaffedisken med denna n\u00e4sryckning, som betyder 'Vad kan jag ta \u00e5t dig?'. Om du ser den \u00e4r det bara att best\u00e4lla.", real_world_scenario: "Vid kaffedisken p\u00e5 flygplatsen i Miami tittade baristan p\u00e5 resen\u00e4ren och ryckte snabbt med n\u00e4san i en liten upp\u00e5triktad r\u00f6relse, en ordl\u00f6s fr\u00e5ga om vad hon kunde ta \u00e5t honom \u2014 en v\u00e4lbekant karibisk h\u00e4lsning.", case_study_cloze: "I Karibien \u00e4r en snabb n\u00e4sryckning en spr\u00e5klig genv\u00e4g som ordl\u00f6st fr\u00e5gar: 'Vad \u00e4r ____?'" } },
      { concept: "HOLDING NOSE HIGH", definition: "A high nose profile-an intentional tilting of the head, with the nose pointed upward-indicates confidence, superiority, arrogance, or even indignation. It is a cultural display, seen in some countries and societies more than in others. It may signal superiority, such as when high-status individuals affirm their rank at the start of a meeting. Italian dictator Mussolini was famous for this, as was General Charles de Gaulle of France. In Russia, the ceremonial guards at the Kremlin are notorious for this nose-high behavior.", category: "body-language-extracted", real_world_scenario: "At the start of the board meeting, the chairman tilted his head back so his nose pointed high in the air, a display of rank that seemed to remind everyone in the room of his superiority.", case_study_cloze: "Tilting the head so the nose points upward, or ____, signals confidence, superiority, or even indignation.", sv: { concept: "N\u00e4san i v\u00e4dret", definition: "En h\u00f6g n\u00e4sprofil \u2014 en avsiktlig huvudlutning med n\u00e4san pekande upp\u00e5t \u2014 tyder p\u00e5 sj\u00e4lvf\u00f6rtroende, \u00f6verl\u00e4gsenhet, arrogans eller till och med indignation. Det \u00e4r en kulturell mark\u00f6r som syns mer i vissa l\u00e4nder och samh\u00e4llen \u00e4n i andra. Det kan signalera \u00f6verl\u00e4gsenhet, som n\u00e4r personer med h\u00f6g status bekr\u00e4ftar sin rang i b\u00f6rjan av ett m\u00f6te. Den italienske diktatorn Mussolini var k\u00e4nd f\u00f6r detta, liksom general Charles de Gaulle fr\u00e5n Frankrike. I Ryssland \u00e4r ceremonivakterna vid Kreml \u00f6k\u00e4nda f\u00f6r detta n\u00e4san-i-v\u00e4dret-beteende.", real_world_scenario: "I b\u00f6rjan av styrelsem\u00f6tet lutade ordf\u00f6randen huvudet bak\u00e5t s\u00e5 att n\u00e4san pekade h\u00f6gt upp i luften, en rangdemonstration som verkade p\u00e5minna alla i rummet om hans \u00f6verl\u00e4gsenhet.", case_study_cloze: "Att luta huvudet s\u00e5 att n\u00e4san pekar upp\u00e5t, att h\u00e5lla ____ i v\u00e4dret, signalerar sj\u00e4lvf\u00f6rtroende, \u00f6verl\u00e4gsenhet eller till och med indignation." } },
      { concept: "RAPID NOSE INHALING", definition: "Many people, when about to deliver bad or unpleasant news, will rapidly inhale through the nose, loudly enough to be", category: "body-language-extracted", real_world_scenario: "The foreman drew a quick, loud breath through his nose before telling the crew that the night shift had been cancelled \u2014 a tell that bad news was coming.", case_study_cloze: "Many people will ____ rapidly through the nose just before they deliver bad or unpleasant news.", sv: { concept: "Snabb inandning genom n\u00e4san", definition: "M\u00e5nga m\u00e4nniskor som ska l\u00e4mna d\u00e5liga eller obehagliga nyheter drar snabbt in luft genom n\u00e4san, tillr\u00e4ckligt h\u00f6gt f\u00f6r att h\u00f6ras av andra. Det \u00e4r ett f\u00f6rberedande beteende som ofta f\u00f6reg\u00e5r de sv\u00e5ra orden.", real_world_scenario: "Arbetsledaren drog ett snabbt, h\u00f6gt andetag genom n\u00e4san innan han talade om f\u00f6r arbetslaget att nattskiftet var inst\u00e4llt \u2014 ett tecken p\u00e5 att d\u00e5liga nyheter var p\u00e5 v\u00e4g.", case_study_cloze: "M\u00e5nga m\u00e4nniskor ____ snabbt genom n\u00e4san strax innan de ska l\u00e4mna d\u00e5liga eller obehagliga nyheter." } },
      { concept: "LOUD, SHORT EXHALING", definition: "This type of exhale, where the lips are left slightly open, indicates high stress or frustration. People exhibit this behavior when hearing bad news or when confronted with a difficult situation. It helps relieve stress, especially when we are angry.", category: "body-language-extracted", real_world_scenario: "When the father opened the credit card statement, he let out a loud, short exhale through slightly parted lips, frustration escaping before he said a single word.", case_study_cloze: "A loud, short exhale with the lips slightly open indicates high ____ or frustration, often when hearing bad news.", sv: { concept: "H\u00f6gljudd kort utandning", definition: "Denna typ av utandning, d\u00e4r l\u00e4pparna l\u00e4mnas n\u00e5got \u00f6ppna, tyder p\u00e5 h\u00f6g stress eller frustration. M\u00e4nniskor uppvisar detta beteende n\u00e4r de h\u00f6r d\u00e5liga nyheter eller st\u00e4lls inf\u00f6r en sv\u00e5r situation. Det hj\u00e4lper till att lindra stress, s\u00e4rskilt n\u00e4r vi \u00e4r arga.", real_world_scenario: "N\u00e4r pappan \u00f6ppnade kreditkortsutdraget l\u00e4t han en h\u00f6gljudd, kort utandning komma genom l\u00e4tt \u00e5tskilda l\u00e4ppar, frustration som slapp ut innan han sagt ett enda ord.", case_study_cloze: "En h\u00f6gljudd, kort utandning med l\u00e4tt \u00e5tskilda l\u00e4ppar tyder p\u00e5 h\u00f6g ____ eller frustration, ofta n\u00e4r man h\u00f6r d\u00e5liga nyheter." } },
      { concept: "CATHARTIC EXHALING", definition: "Exhaling with puffed-out cheeks and tight lips indicates that stress is being experienced or has passed. You might see this when a test or an interview is over or after a near accident. This exhale is very audible and takes longer to perform than the above version.", category: "body-language-extracted", real_world_scenario: "After the driving test ended, Sofia blew out a long, audible breath with puffed cheeks and tight lips in the parking lot, the stress of the last hour finally leaving her body.", case_study_cloze: "Exhaling with puffed-out cheeks and tight lips shows that stress is being released, as you might see when a test or ____ is over.", sv: { concept: "Befriande utandning", definition: "Att andas ut med uppbl\u00e5sta kinder och hoptryckta l\u00e4ppar tyder p\u00e5 att stress upplevs eller har passerat. Du kan se det n\u00e4r ett prov eller en intervju \u00e4r \u00f6ver eller efter en n\u00e4stan-olycka. Denna utandning \u00e4r mycket h\u00f6rbar och tar l\u00e4ngre tid \u00e4n den ovan n\u00e4mnda varianten.", real_world_scenario: "Efter att k\u00f6rprovet var slut bl\u00e5ste Sofia ut ett l\u00e5ngt, h\u00f6rbart andetag med uppbl\u00e5sta kinder och hoptryckta l\u00e4ppar p\u00e5 parkeringsplatsen, stressen fr\u00e5n den senaste timmen l\u00e4mnade slutligen hennes kropp.", case_study_cloze: "Att andas ut med uppbl\u00e5sta kinder och hoptryckta l\u00e4ppar visar att stress sl\u00e4pps ut, som man kan se n\u00e4r ett prov eller en ____ \u00e4r \u00f6ver." } },
      { concept: "AFFIRMATIVE INHALING", definition: "A sudden loud inhaling makes a distinct sound that is used in Scandinavian countries, parts of the United Kingdom, and Ireland to signify \\\"Yes\\\" or \\\"Yes, I agree.\\\" It is a linguistic shortcut, as no words need to be used. The person quickly inhales loudly enough to sound as if she is gasping for air. Once, after a car ride in Sweden, when I asked if we had arrived, the driver merely did an affirmative inhale-and that was it.", category: "body-language-extracted", real_world_scenario: "When asked in Swedish whether the bus stopped at the city center, the driver simply drew a short, sharp breath in \u2014 an affirmative inhale that meant yes, as clear as any word.", case_study_cloze: "In Scandinavian countries, a sudden loud inhale is used as a linguistic shortcut to signify ____ or agreement.", sv: { concept: "Bekr\u00e4ftande inandning", definition: "En pl\u00f6tslig h\u00f6gljudd inandning ger ett distinkt ljud som anv\u00e4nds i skandinaviska l\u00e4nder, delar av Storbritannien och Irland f\u00f6r att beteckna 'Ja' eller 'Ja, jag h\u00e5ller med'. Det \u00e4r en spr\u00e5klig genv\u00e4g, eftersom inga ord beh\u00f6ver anv\u00e4ndas. Personen drar snabbt in luft tillr\u00e4ckligt h\u00f6gt f\u00f6r att l\u00e5ta som om hon fl\u00e4mtar efter luft. En g\u00e5ng, efter en bilresa i Sverige, n\u00e4r jag fr\u00e5gade om vi hade kommit fram, gjorde f\u00f6raren bara en bekr\u00e4ftande inandning \u2014 och det var allt.", real_world_scenario: "N\u00e4r f\u00f6raren fick fr\u00e5gan p\u00e5 svenska om bussen stannade vid centrum drog han bara ett kort, skarpt andetag in\u00e5t \u2014 en bekr\u00e4ftande inandning som betydde ja, lika tydligt som n\u00e5got ord.", case_study_cloze: "I skandinaviska l\u00e4nder anv\u00e4nds en pl\u00f6tslig h\u00f6gljudd inandning som en spr\u00e5klig genv\u00e4g f\u00f6r att beteckna ____ eller samtycke." } },
      { concept: "HOLDING THE BREATH", definition: "Polygraphers know this well: when stressed, many people have an impulse to hold their breath to try to contain their nervous breathing. Often they even have to be told to breathe. Holding one's breath is part of the freeze, flight, fight response. If you see someone restraining their breathing or actually holding their breath when asked a question, most likely they are experiencing fear or apprehension.", category: "body-language-extracted", real_world_scenario: "When the detective asked where he had been on Saturday night, the suspect stopped breathing for a few seconds, and the silence told the detective that the question had hit something the man was afraid to discuss.", case_study_cloze: "Holding one's breath when asked a question is part of the freeze, flight, fight response and suggests the person feels ____ or apprehension.", sv: { concept: "Att h\u00e5lla andan", definition: "Polygrafteknikerna k\u00e4nner v\u00e4l till detta: n\u00e4r man \u00e4r stressad har m\u00e5nga en impuls att h\u00e5lla andan f\u00f6r att f\u00f6rs\u00f6ka kontrollera sin nerv\u00f6sa andning. Ofta m\u00e5ste de till och med tills\u00e4gas att andas. Att h\u00e5lla andan \u00e4r en del av frys-, flykt- och kampresponsen. Om du ser n\u00e5gon h\u00e5lla igen andningen eller faktiskt h\u00e5lla andan n\u00e4r de f\u00e5r en fr\u00e5ga, upplever de troligen r\u00e4dsla eller oro.", real_world_scenario: "N\u00e4r detektiven fr\u00e5gade var han hade varit l\u00f6rdag kv\u00e4ll slutade den misst\u00e4nkte att andas i n\u00e5gra sekunder, och tystnaden ber\u00e4ttade f\u00f6r detektiven att fr\u00e5gan hade tr\u00e4ffat n\u00e5got mannen var r\u00e4dd f\u00f6r att diskutera.", case_study_cloze: "Att h\u00e5lla andan n\u00e4r man f\u00e5r en fr\u00e5ga \u00e4r en del av frys-, flykt- och kampresponsen och tyder p\u00e5 att personen k\u00e4nner ____ eller oro." } },
      { concept: "DRY MOUTH", definition: "Stress, fear, and apprehension can cause our mouths to dry out (the clinical term for this is xerostomia). Some prescribed medicines as well as illicit drugs may also cause dryness of the mouth. A dry mouth is not, as some believe, indicative of deception. It can, however, indicate that someone is stressed or anxious.", category: "body-language-extracted", real_world_scenario: "Before her big presentation, Maya's mouth went so dry that she could barely swallow, a familiar nervous reaction that had nothing to do with whether she was telling the truth.", case_study_cloze: "A dry mouth, clinically called ____, often indicates stress or anxiety, but it is not proof of deception.", sv: { concept: "Torr mun", definition: "Stress, r\u00e4dsla och oro kan g\u00f6ra att munnen torkar ut (den kliniska termen \u00e4r xerostomi). Vissa receptbelagda l\u00e4kemedel samt olagliga droger kan ocks\u00e5 orsaka muntorrhet. En torr mun \u00e4r inte, som vissa tror, ett tecken p\u00e5 l\u00f6gn. Den kan d\u00e4remot tyda p\u00e5 att n\u00e5gon \u00e4r stressad eller orolig.", real_world_scenario: "F\u00f6re sin stora presentation blev Mayas mun s\u00e5 torr att hon knappt kunde sv\u00e4lja, en v\u00e4lbekant nerv\u00f6s reaktion som inte hade n\u00e5got med sanningen att g\u00f6ra.", case_study_cloze: "En torr mun, kliniskt kallad ____, tyder ofta p\u00e5 stress eller oro, men det \u00e4r inte bevis f\u00f6r bedr\u00e4geri." } },
      { concept: "SALIVA BALLS OF MOUTH", definition: "A dry mouth due to stress, medication, or illness can cause saliva to become dry and clumpy; these clumps-they often look like little cotton balls-tend to collect in the corners of the mouth. They are sometimes noticeable in speakers who are nervous. It is quite distracting. If you are nervous, it is a good habit to pinch and wipe the corners of your mouth to avoid saliva balls as well as drink water. The clinical term for a dry mouth is xerostomia.", category: "body-language-extracted", real_world_scenario: "During her first big presentation, Maria noticed the audience staring at the corners of her mouth; her dry, clumpy saliva had gathered into little cotton-ball-like clumps while she spoke, a sure sign of nerves.", case_study_cloze: "The nervous speaker's mouth was so dry that ____ gathered in the corners of her mouth like little cotton balls.", sv: { concept: "Salivklumpar i munnen", definition: "En torr mun p\u00e5 grund av stress, mediciner eller sjukdom kan g\u00f6ra att saliven blir torr och klumpig; dessa klumpar \u2013 som ofta ser ut som sm\u00e5 bomullsbollar \u2013 samlas g\u00e4rna i mungiporna. De syns ibland hos talare som \u00e4r nerv\u00f6sa. Det \u00e4r ganska distraherande. Om du \u00e4r nerv\u00f6s \u00e4r det en god vana att nypa och torka bort saliv i mungiporna samt att dricka vatten. Den kliniska termen f\u00f6r muntorrhet \u00e4r xerostomi.", real_world_scenario: "Under sin f\u00f6rsta stora presentation m\u00e4rkte Maria att publiken tittade p\u00e5 mungiporna; hennes torra, klumpiga saliv hade samlats i sm\u00e5 bomullsbollsliknande klumpar i mungiporna medan hon talade, ett s\u00e4kert tecken p\u00e5 nervositet.", case_study_cloze: "Den nerv\u00f6sa talarens mun var s\u00e5 torr att ____ samlades i mungiporna som sm\u00e5 bomullsbollar." } },
      { concept: "CHEWING GUM", definition: "Gum chewing is an effective pacifier. Chewing vigorously might signal concern or anxiety. Some people, when stressed, will chew rapidly out of habit even if they don't have gum in their mouths.", category: "body-language-extracted", real_world_scenario: "At the job interview, the applicant chewed his gum with such force that his jaw worked visibly under his ears, a vigorous chewing that betrayed far more anxiety than his calm answers showed.", case_study_cloze: "Chewing ____ vigorously during a difficult meeting can signal concern or anxiety.", sv: { concept: "Tuggummituggning", definition: "Tuggummituggning \u00e4r en effektiv lugnare. Kraftigt tuggande kan signalera oro eller \u00e5ngest. En del personer tuggar snabbt av ren vana n\u00e4r de \u00e4r stressade, \u00e4ven om de inte har n\u00e5got tuggummi i munnen.", real_world_scenario: "P\u00e5 anst\u00e4llningsintervjun tuggade s\u00f6kanden p\u00e5 sitt tuggummi s\u00e5 kraftigt att k\u00e4karna arbetade synligt under \u00f6ronen; det kraftiga tuggandet avsl\u00f6jade betydligt mer oro \u00e4n vad hans lugna svar visade.", case_study_cloze: "Att tugga ____ kraftigt under ett sv\u00e5rt m\u00f6te kan signalera oro eller \u00e5ngest." } },
      { concept: "VOCAL TICS", definition: "Sudden vocal projection of noises, clicks, chirps, or throat clearing can be alarming if one is not acquainted with Tourette's syndrome (TS), or other disorders that contribute to vocal tics. Stress and anxiety may be the catalysts for Tourette's outbursts, and there is nothing for us to do but recognize that this is out of the person's control. It is also not uncommon to see the arms move erratically. The best we can do is encourage others not to stare, as this is embarrassing for the person with TS.", category: "body-language-extracted", real_world_scenario: "In the team meeting, Lars repeatedly cleared his throat and let out short chirping sounds that he could not control; his colleagues knew about his Tourette's syndrome and tried not to stare, since stress and anxiety tend to trigger the outbursts.", case_study_cloze: "Sudden, uncontrollable ____ such as clicks, chirps, or throat clearing can be alarming to those unfamiliar with Tourette's syndrome.", sv: { concept: "Vokala tics", definition: "Pl\u00f6tsliga ljud, klickningar, kvittrande eller harklingar kan vara skr\u00e4mmande om man inte k\u00e4nner till Tourettes syndrom (TS) eller andra tillst\u00e5nd som ger vokala tics. Stress och \u00e5ngest kan vara utl\u00f6sande faktorer f\u00f6r Tourettes utbrott, och det enda vi kan g\u00f6ra \u00e4r att f\u00f6rst\u00e5 att detta ligger utanf\u00f6r personens kontroll. Det \u00e4r inte heller ovanligt att armarna r\u00f6r sig ryckigt. Det b\u00e4sta vi kan g\u00f6ra \u00e4r att uppmuntra andra att inte stirra, eftersom det \u00e4r pinsamt f\u00f6r personen med TS.", real_world_scenario: "P\u00e5 teamm\u00f6tet harklade sig Lars upprepade g\u00e5nger och gav ifr\u00e5n sig korta kvittrande ljud som han inte kunde kontrollera; hans kollegor k\u00e4nde till hans Tourettes syndrom och f\u00f6rs\u00f6kte att inte stirra, eftersom stress och \u00e5ngest tenderar att utl\u00f6sa utbrotten.", case_study_cloze: "Pl\u00f6tsliga, okontrollerbara ____ som klickningar, kvittrande eller harklingar kan vara skr\u00e4mmande f\u00f6r den som inte k\u00e4nner till Tourettes syndrom." } },
      { concept: "TONGUE BITING/CHEWING", definition: "Some individuals under stress will bite their tongue or the inside of their cheeks in order to soothe their nerves. It is very pronounced in those for whom it has become a nervous tic. The tongue will appear wounded or even ulcerated in places. Under stress the behavior is of course heightened. Unfortunately, tongue and cheek biting, like repeated hair pulling, can become pathological.", category: "body-language-extracted", real_world_scenario: "During the tense contract negotiation, the lawyer chewed on the side of her tongue, a habit that had left it slightly raw, whenever her counterpart raised the delivery deadline.", case_study_cloze: "Under stress, some people bite or chew their ____ or the inside of their cheeks to soothe their nerves.", sv: { concept: "Tungbitning", definition: "En del m\u00e4nniskor biter sig i tungan eller i kindernas insida under stress f\u00f6r att lugna nerverna. Det \u00e4r mycket tydligt hos dem d\u00e4r det har blivit en nerv\u00f6s vana. Tungan kan se s\u00e5rig eller till och med ulcererad ut p\u00e5 vissa st\u00e4llen. Beteendet f\u00f6rst\u00e4rks naturligtvis under stress. Tyv\u00e4rr kan tung- och kindbitning, liksom upprepat h\u00e5rdragande, bli patologiskt.", real_world_scenario: "Under den sp\u00e4nda kontraktsf\u00f6rhandlingen tuggade juristen p\u00e5 sidan av tungan, en vana som hade gjort den l\u00e4tt s\u00e5rig, varje g\u00e5ng motparten tog upp leveransdatumet.", case_study_cloze: "Under stress biter eller tuggar en del m\u00e4nniskor sig i ____ eller i kindernas insida f\u00f6r att lugna nerverna." } },
      { concept: "TONGUE IN CHEEK", definition: "Pushing the tongue firmly against one cheek and holding it in place serves to relieve tension. This is most often seen in individuals facing high stress or in those hiding information or who are getting away with something. It can also be seen in those who are being playful or cheeky.", category: "body-language-extracted", real_world_scenario: "At the poker table, Sam pressed his tongue firmly against his cheek and held it there after a risky bluff succeeded, betraying the tension he was hiding from the other players.", case_study_cloze: "Pressing the tongue firmly against one ____ and holding it there is a way to relieve tension, seen in people who are stressed or getting away with something.", sv: { concept: "Tungan i kinden", definition: "Att trycka tungan h\u00e5rt mot ena kinden och h\u00e5lla den d\u00e4r lindrar sp\u00e4nning. Detta ses oftast hos personer som uts\u00e4tts f\u00f6r h\u00f6g stress eller som d\u00f6ljer information eller kommer undan med n\u00e5got. Det kan ocks\u00e5 ses hos den som \u00e4r lekfull eller n\u00e4svis.", real_world_scenario: "Vid pokerbordet tryckte Sam tungan h\u00e5rt mot kinden och h\u00f6ll den d\u00e4r efter att en riskabel bluff hade lyckats, vilket avsl\u00f6jade den sp\u00e4nning han f\u00f6rs\u00f6kte d\u00f6lja f\u00f6r de andra spelarna.", case_study_cloze: "Att trycka tungan h\u00e5rt mot ena ____ och h\u00e5lla den d\u00e4r lindrar sp\u00e4nning och ses hos den som \u00e4r stressad eller kommer undan med n\u00e5got." } },
      { concept: "TONGUE JUTTING", definition: "When the tongue suddenly protrudes between the teeth, sometimes without touching the lips, it means \\\"I got away with something\\\" or \\\"Oops, I got caught.\\\" You also see it when people catch themselves making a mistake. The tongue jut is universal and is remarkable in its consistency, whether it is indicating that you got away with a great bargain or an extra cookie, a higher grade, or a whopper of a lie.", category: "body-language-extracted", real_world_scenario: "When the toddler got caught reaching for the cookie jar, she quickly shot her tongue out between her teeth, the universal 'Oops, I got caught' sign that adults also show after landing a great bargain.", case_study_cloze: "When people catch themselves making a mistake, they often show a quick ____ of the tongue between the teeth, meaning 'Oops, I got caught.'", sv: { concept: "Tungst\u00f6t", definition: "N\u00e4r tungan pl\u00f6tsligt sticker ut mellan t\u00e4nderna, ibland utan att r\u00f6ra l\u00e4pparna, betyder det 'jag kom undan med n\u00e5got' eller 'hoppsan, jag \u00e5kte fast'. Man ser det ocks\u00e5 n\u00e4r m\u00e4nniskor ertappar sig sj\u00e4lva med ett misstag. Tungst\u00f6ten \u00e4r universell och anm\u00e4rkningsv\u00e4rt konsekvent, oavsett om den visar att man kom undan med ett fynd, en extra kaka, ett h\u00f6gre betyg eller en riktig l\u00f6gn.", real_world_scenario: "N\u00e4r sm\u00e5barnet \u00e5kte fast med handen i kakburkan stack hon snabbt ut tungan mellan t\u00e4nderna, den universella signalen f\u00f6r 'hoppsan, jag \u00e5kte fast' som \u00e4ven vuxna visar efter att ha f\u00e5tt ett bra fynd.", case_study_cloze: "N\u00e4r m\u00e4nniskor ertappar sig sj\u00e4lva med ett misstag visar de ofta en snabb ____ av tungan mellan t\u00e4nderna, som betyder 'hoppsan, jag \u00e5kte fast.'" } },
      { concept: "TONGUE LICKING TEETH", definition: "As with lip licking (see #145), we lick our teeth when our mouth is dry-usually due to nervousness, anxiety, or fear. The rubbing of the tongue across the teeth and/or gums is a universal stress reliever, as well as a potential sign of dehydration. Incidentally, when this is done with the mouth closed, you can see the tongue track across the teeth under the lips.", category: "body-language-extracted", real_world_scenario: "In the exam hall, the student repeatedly ran his tongue across his front teeth, a visible track moving under his lips, because his mouth had gone dry from test anxiety.", case_study_cloze: "When our mouth is dry due to nervousness, we may rub the tongue across the ____ as a universal stress reliever.", sv: { concept: "Att slicka t\u00e4nderna", definition: "Precis som vid l\u00e4ppslickning slickar vi t\u00e4nderna n\u00e4r munnen \u00e4r torr \u2013 oftast p\u00e5 grund av nervositet, \u00e5ngest eller r\u00e4dsla. Att f\u00f6ra tungan \u00f6ver t\u00e4nderna och/eller tandk\u00f6ttet \u00e4r en universell stressavlastare och ett potentiellt tecken p\u00e5 uttorkning. N\u00e4r detta g\u00f6rs med st\u00e4ngd mun kan man se tungan r\u00f6ra sig \u00f6ver t\u00e4nderna under l\u00e4pparna.", real_world_scenario: "I tentamenssalen f\u00f6rde studenten upprepade g\u00e5nger tungan \u00f6ver framt\u00e4nderna, en synlig r\u00f6relse under l\u00e4pparna, eftersom munnen hade torkat av tentanervositet.", case_study_cloze: "N\u00e4r munnen \u00e4r torr p\u00e5 grund av nervositet f\u00f6r vi ofta tungan \u00f6ver ____ som en universell stressavlastare." } },
      { concept: "TONGUE DARTING", definition: "To relieve stress some people will dart their tongue back and forth from corner to corner of their mouth (noticeable through the cheeks) in nervous or worried anticipation. Usually they think they are not being noticed or that the meaning of this behavior cannot be deciphered.", category: "body-language-extracted", real_world_scenario: "Waiting in the security line, the traveler darted his tongue back and forth from one corner of his mouth to the other, a nervous movement visible through his cheeks that he believed nobody could see.", case_study_cloze: "In nervous or worried anticipation, some people ____ their tongue from corner to corner of the mouth, thinking no one notices.", sv: { concept: "Tungdans", definition: "F\u00f6r att lindra stress f\u00f6r en del m\u00e4nniskor tungan fram och tillbaka fr\u00e5n den ena mungipan till den andra (synligt genom kinderna) i nerv\u00f6s eller orolig v\u00e4ntan. Vanligtvis tror de att ingen m\u00e4rker det eller att beteendets inneb\u00f6rd inte kan tydas.", real_world_scenario: "I s\u00e4kerhetsk\u00f6n f\u00f6rde resen\u00e4ren tungan fram och tillbaka fr\u00e5n den ena mungipan till den andra, en nerv\u00f6s r\u00f6relse synlig genom kinderna som han trodde att ingen kunde se.", case_study_cloze: "I nerv\u00f6s eller orolig v\u00e4ntan ____ en del m\u00e4nniskor tungan fr\u00e5n mungipa till mungipa och tror att ingen ser det." } },
      { concept: "TEETH TAPPING", definition: "When stressed, bored, or frustrated, some people will shift their jaw slightly and tap their canines together, favoring one side of the mouth or the other. This sends repetitive signals to the brain that help soothe us.", category: "body-language-extracted", real_world_scenario: "Stuck in the boring committee meeting, the deputy chair shifted his jaw slightly and tapped his canines together on one side, a rhythmic clacking that helped him endure the endless budget report.", case_study_cloze: "When stressed, bored, or frustrated, some people tap their ____ together on one side of the mouth to send soothing repetitive signals to the brain.", sv: { concept: "Tandknackning", definition: "N\u00e4r m\u00e4nniskor \u00e4r stressade, uttr\u00e5kade eller frustrerade kan de f\u00f6rskjuta k\u00e4ken n\u00e5got och knacka h\u00f6rnt\u00e4nderna mot varandra, med f\u00f6rk\u00e4rlek f\u00f6r ena sidan av munnen. Detta skickar repetitiva signaler till hj\u00e4rnan som hj\u00e4lper till att lugna oss.", real_world_scenario: "Fast i det tr\u00e5kiga kommitt\u00e9m\u00f6tet f\u00f6rsk\u00f6t vice ordf\u00f6randen k\u00e4ken n\u00e5got och knackade h\u00f6rnt\u00e4nderna mot varandra p\u00e5 ena sidan, ett rytmiskt klickande som hj\u00e4lpte honom att uth\u00e4rda den \u00e4ndl\u00f6sa budgetrapporten.", case_study_cloze: "Vid stress, uttr\u00e5kning eller frustration knackar en del m\u00e4nniskor ____ mot varandra p\u00e5 ena sidan av munnen f\u00f6r att skicka lugnande repetitiva signaler till hj\u00e4rnan." } },
      { concept: "VOICE TONE", definition: "The tone of our voice can make people comfortable or feel like we are challenging them. We can use the tone of our voice to alter or enhance how we are perceived. You can come off as nice, sweet, kind, loving, and knowledgeable, depending on your tone of voice or alternatively as suspicious, indignant, or arrogant. Tone of voice matters greatly. Ironically, if you want to get people's attention, lowering your tone of voice will work best. A lower voice is also soothing, as any parent who has put a child to bed will attest.", category: "body-language-extracted", real_world_scenario: "At bedtime, the father spoke to his restless daughter in a low, gentle tone, and her breathing slowed as she finally settled; a lower voice is soothing, just as a sharp tone could have sparked another protest.", case_study_cloze: "If you want to get people's attention, ____ your tone of voice is what works best.", sv: { concept: "R\u00f6stton", definition: "Tonfallet i v\u00e5r r\u00f6st kan f\u00e5 m\u00e4nniskor att k\u00e4nna sig bekv\u00e4ma eller f\u00e5 dem att k\u00e4nna att vi utmanar dem. Vi kan anv\u00e4nda r\u00f6stens ton f\u00f6r att f\u00f6r\u00e4ndra eller f\u00f6rst\u00e4rka hur vi uppfattas. Du kan framst\u00e5 som trevlig, sn\u00e4ll, v\u00e4nlig, k\u00e4rleksfull och kunnig beroende p\u00e5 r\u00f6stens ton, eller alternativt som misst\u00e4nksam, f\u00f6rn\u00e4rmad eller arrogant. R\u00f6stens ton betyder mycket. Ironiskt nog fungerar det b\u00e4st att s\u00e4nka r\u00f6sten om du vill f\u00e5nga m\u00e4nniskors uppm\u00e4rksamhet. En l\u00e4gre r\u00f6st \u00e4r ocks\u00e5 lugnande, vilket vilken f\u00f6r\u00e4lder som helst som har lagt sitt barn kan intyga.", real_world_scenario: "N\u00e4r barnet skulle sova talade pappan till sin rastl\u00f6sa dotter med l\u00e5g, mjuk ton och hennes andning blev lugnare tills hon somnade; en l\u00e4gre r\u00f6st \u00e4r lugnande, precis som en skarp ton hade kunnat utl\u00f6sa \u00e4nnu en protest.", case_study_cloze: "Om du vill f\u00e5nga m\u00e4nniskors uppm\u00e4rksamhet \u00e4r det att ____ r\u00f6sten som fungerar b\u00e4st." } },
      { concept: "VOICE PITCH", definition: "When we are nervous our voices tend to rise in pitch. Listen for voices that rise or crack when a person is stressed, nervous, or insecure. This is caused by vocal-cord tension.", category: "body-language-extracted", real_world_scenario: "During the police interview, the suspect's voice rose half an octave whenever the missing money was mentioned, and it cracked at the edges, a pitch change caused by vocal-cord tension.", case_study_cloze: "When we are nervous, our voices tend to ____ in pitch, caused by tension in the vocal cords.", sv: { concept: "Tonh\u00f6jd", definition: "N\u00e4r vi \u00e4r nerv\u00f6sa tenderar v\u00e5r r\u00f6st att stiga i tonh\u00f6jd. Lyssna efter r\u00f6ster som stiger eller spricker n\u00e4r en person \u00e4r stressad, nerv\u00f6s eller os\u00e4ker. Detta orsakas av sp\u00e4nning i st\u00e4mbanden.", real_world_scenario: "Under polisf\u00f6rh\u00f6ret steg den misst\u00e4nktes r\u00f6st n\u00e4stan en halv oktav varje g\u00e5ng de f\u00f6rsvunna pengarna n\u00e4mndes och den sprack i kanten, en h\u00f6jning av tonh\u00f6jden som orsakades av sp\u00e4nda st\u00e4mband.", case_study_cloze: "N\u00e4r vi \u00e4r nerv\u00f6sa tenderar r\u00f6sten att ____ i tonh\u00f6jd, orsakat av sp\u00e4nning i st\u00e4mbanden." } },
      { concept: "DELAY IN ANSWERING", definition: "Many people erroneously believe that a delay in answering a question signals that a person is lying or is buying time in an attempt to muster a credible answer. Unfortunately, both the honest and the dishonest may delay an answer but for different reasons. The guilty may in fact have to think about what to say while the innocent may be thinking about how best to say it. In my experience, a delay in answering should make us take note but is not indicative of deception. In some cultures-for instance, among many Native Americans-a delay in answering is not unusual as the person contemplates the complexity and nuance of a question. Stress or fatigue can also make us slow to answer. A formal inquiry may also cause us to delay answering because of the seriousness of the hearing.", category: "body-language-extracted", real_world_scenario: "When the tax auditor asked about the large deposit, the business owner paused for almost ten seconds before replying; the delay made the auditor take note, though he knew from experience that a pause alone proves nothing about deception.", case_study_cloze: "A ____ in answering a question should make us take note, but it is not in itself indicative of deception.", sv: { concept: "Dr\u00f6jsm\u00e5l med svaret", definition: "M\u00e5nga tror felaktigt att ett dr\u00f6jsm\u00e5l med att svara p\u00e5 en fr\u00e5ga signalerar att personen ljuger eller k\u00f6per tid f\u00f6r att \u00e5stadkomma ett trov\u00e4rdigt svar. Tyv\u00e4rr kan b\u00e5de den \u00e4rliga och den o\u00e4rliga dr\u00f6ja med svaret, men av olika sk\u00e4l. Den skyldige kanske faktiskt m\u00e5ste fundera p\u00e5 vad den ska s\u00e4ga medan den oskyldiga kanske funderar p\u00e5 hur den b\u00e4st ska s\u00e4ga det. I min erfarenhet ska ett dr\u00f6jsm\u00e5l med svaret f\u00e5 oss att l\u00e4gga m\u00e4rke till det, men det tyder inte p\u00e5 bedr\u00e4geri. I vissa kulturer \u2013 till exempel bland m\u00e5nga ursprungsamerikaner \u2013 \u00e4r ett dr\u00f6jsm\u00e5l med svaret inte ovanligt, eftersom personen begrundar fr\u00e5gans komplexitet och nyanser. Stress eller tr\u00f6tthet kan ocks\u00e5 g\u00f6ra oss l\u00e5ngsamma att svara. En formell f\u00f6rh\u00f6rssituation kan ocks\u00e5 f\u00e5 oss att dr\u00f6ja med svaret p\u00e5 grund av f\u00f6rh\u00f6rets allvar.", real_world_scenario: "N\u00e4r skatterevisorn fr\u00e5gade om den stora ins\u00e4ttningen dr\u00f6jde f\u00f6retagaren n\u00e4stan tio sekunder innan han svarade; dr\u00f6jsm\u00e5let fick revisorn att notera det, \u00e4ven om han av erfarenhet visste att en paus i sig inte bevisar n\u00e5got om bedr\u00e4geri.", case_study_cloze: "Ett ____ med att svara p\u00e5 en fr\u00e5ga b\u00f6r f\u00e5 oss att l\u00e4gga m\u00e4rke till det, men det tyder i sig inte p\u00e5 bedr\u00e4geri." } },
      { concept: "INTERRUPTIVE ARGUMENTS", definition: "Arguing for the sole purpose of disrupting a", category: "body-language-extracted", real_world_scenario: "At the family dinner, the teenage son argued with every point his mother made, not because he disagreed but purely to disrupt her story, cutting her off so she could never finish a sentence.", case_study_cloze: "Sometimes people argue for the sole purpose of ____ a conversation, not because they actually believe what they are saying.", sv: { concept: "Avbrytande argumentation", definition: "Att argumentera i det enda syftet att st\u00f6ra en", real_world_scenario: "Vid familjemiddagen argumenterade ton\u00e5rssonen emot allt mamman sa, inte f\u00f6r att han var oenig utan enbart f\u00f6r att st\u00f6ra hennes ber\u00e4ttelse, genom att avbryta henne s\u00e5 att hon aldrig fick avsluta en mening.", case_study_cloze: "Ibland argumenterar m\u00e4nniskor i det enda syftet att ____ ett samtal, inte f\u00f6r att de faktiskt tror p\u00e5 det de s\u00e4ger." } },
      { concept: "CATHARTIC UTTERANCES", definition: "In this form of a cathartic exhale, we come close to saying a word but never get there. \\\"Ohhhh\\\" or \\\"woooo\\\" or \\\"fuuuuh\\\" is uttered but never completed. These are considered nonverbals because the actual words are not spoken, though we can often intuit their meaning. Often these utterances don't make sense, especially to foreigners, but they help us to relieve stress without offending anyone.", category: "body-language-extracted", real_world_scenario: "When the mechanic handed him the bill for the repair, Johan let out a long 'Ohhhh' that trailed off into nothing, a cathartic utterance that said everything without his ever forming the word.", case_study_cloze: "A long 'Ohhhh' or 'woooo' that is never completed is a ____ utterance that relieves stress without offending anyone.", sv: { concept: "Katartiska utrop", definition: "I denna form av katartisk utandning kommer vi n\u00e4ra att s\u00e4ga ett ord men kommer aldrig dit. 'Ohhhh' eller 'woooo' eller 'fuuuuh' uttalas men fullbordas aldrig. Dessa r\u00e4knas som icke-verbala eftersom de faktiska orden inte uttalas, \u00e4ven om vi ofta kan ana deras inneb\u00f6rd. Ofta verkar dessa utrop inte ha n\u00e5gon mening, s\u00e4rskilt f\u00f6r utl\u00e4nningar, men de hj\u00e4lper oss att avreagera stress utan att f\u00f6rol\u00e4mpa n\u00e5gon.", real_world_scenario: "N\u00e4r mekanikern l\u00e4mnade \u00f6ver r\u00e4kningen f\u00f6r reparationen l\u00e4t Johan ett l\u00e5ngt 'Ohhhh' rinna ut i ingenting, ett katartiskt utrop som sa allt utan att han n\u00e5gonsin formulerade ordet.", case_study_cloze: "Ett l\u00e5ngt 'Ohhhh' eller 'woooo' som aldrig fullbordas \u00e4r ett ____ utrop som lindrar stress utan att f\u00f6rol\u00e4mpa n\u00e5gon." } },
      { concept: "SPEED OF TALKING", definition: "How fast we speak is a key nonverbal indicator. In some parts of America people speak very slowly and deliberately, while in others speech is fast and clipped. These styles communicate something about the personality of the speakers-where they are from, where they went to school, and more. Changes in a person's normal speed of talking may indicate stress or reluctance to answer a sensitive question.", category: "body-language-extracted", real_world_scenario: "The normally slow-speaking salesman sped through his answer when the client asked about the warranty dispute, and the sudden change in tempo told the client the question had made him uncomfortable.", case_study_cloze: "A change in a person's normal ____ of talking may indicate stress or reluctance to answer a sensitive question.", sv: { concept: "Prathastighet", definition: "Hur snabbt vi talar \u00e4r en viktig icke-verbal indikator. I vissa delar av Amerika talar m\u00e4nniskor mycket l\u00e5ngsamt och eftert\u00e4nksamt, medan talet i andra delar \u00e4r snabbt och kortfattat. Dessa stilar ber\u00e4ttar n\u00e5got om talarens personlighet \u2013 var de kommer ifr\u00e5n, var de gick i skola och mer. F\u00f6r\u00e4ndringar i en persons normala prathastighet kan tyda p\u00e5 stress eller motvilja att svara p\u00e5 en k\u00e4nslig fr\u00e5ga.", real_world_scenario: "Den annars l\u00e5ngsamt talande f\u00f6rs\u00e4ljaren svarade i rasande fart n\u00e4r kunden fr\u00e5gade om garantitvisten, och det pl\u00f6tsliga tempobyte avsl\u00f6jade f\u00f6r kunden att fr\u00e5gan gjorde honom obekv\u00e4m.", case_study_cloze: "En f\u00f6r\u00e4ndring i en persons normala ____ kan tyda p\u00e5 stress eller motvilja att svara p\u00e5 en k\u00e4nslig fr\u00e5ga." } },
      { concept: "INCONGRUENT TALK", definition: "After an accident or tragic event, a person may begin to speak incoherently. This is a result of stress and the emotional side of the brain being overwhelmed. Depending on the circumstances of the event or tragedy, this may last for hours or even days, as we have seen with soldiers and refugees in combat zones.", category: "body-language-extracted", real_world_scenario: "After the car accident, the shaken driver spoke incoherently, mixing fragments of the morning's errands with the crash, her emotional brain overwhelmed by the shock.", case_study_cloze: "After a tragic event, a person may begin to speak ____, a result of stress and the emotional side of the brain being overwhelmed.", sv: { concept: "Osammanh\u00e4ngande tal", definition: "Efter en olycka eller tragisk h\u00e4ndelse kan en person b\u00f6rja tala osammanh\u00e4ngande. Detta \u00e4r ett resultat av stress och att hj\u00e4rnans k\u00e4nslom\u00e4ssiga sida \u00e4r \u00f6verv\u00e4ldigad. Beroende p\u00e5 omst\u00e4ndigheterna kring h\u00e4ndelsen eller tragedin kan detta p\u00e5g\u00e5 i timmar eller till och med dagar, som vi har sett hos soldater och flyktingar i krigszoner.", real_world_scenario: "Efter bilolyckan talade den skakade f\u00f6raren osammanh\u00e4ngande och blandade fragment fr\u00e5n morgonens \u00e4renden med krocken, hennes k\u00e4nslom\u00e4ssiga hj\u00e4rna var \u00f6verv\u00e4ldigad av chocken.", case_study_cloze: "Efter en tragisk h\u00e4ndelse kan en person b\u00f6rja tala ____, ett resultat av stress och att hj\u00e4rnans k\u00e4nslom\u00e4ssiga sida \u00e4r \u00f6verv\u00e4ldigad." } },
      { concept: "REPETITION OF WORDS", definition: "Under high stress, people may repeat certain words over and over in a nonsensical way. Efforts on your part to get them to say more may not work. It is as if they are stuck in a loop. I once heard a victim struck by a vehicle say the word \\\"metal\\\" over and over again, with a look of fright upon her face. That was all she could say.", category: "body-language-extracted", real_world_scenario: "On the sidewalk after the collision, the injured cyclist kept repeating the word 'metal' over and over with a look of fright, stuck in a loop and unable to say anything more despite the paramedic's gentle questions.", case_study_cloze: "Under high stress, people may repeat certain ____ over and over in a nonsensical way, as if stuck in a loop.", sv: { concept: "Ordrepetition", definition: "Vid h\u00f6g stress kan m\u00e4nniskor upprepa vissa ord om och om igen p\u00e5 ett meningsl\u00f6st s\u00e4tt. Dina f\u00f6rs\u00f6k att f\u00e5 dem att s\u00e4ga mer kanske inte fungerar. Det \u00e4r som om de sitter fast i en loop. Jag h\u00f6rde en g\u00e5ng ett offer som blivit p\u00e5k\u00f6rd s\u00e4ga ordet 'metall' om och om igen med en skr\u00e4ckslagen blick. Det var allt hon kunde s\u00e4ga.", real_world_scenario: "P\u00e5 trottoaren efter kollisionen upprepade den skadade cyklisten ordet 'metall' om och om igen med en skr\u00e4ckslagen blick, fast i en loop och of\u00f6rm\u00f6gen att s\u00e4ga n\u00e5got mer trots ambulanspersonalens f\u00f6rsiktiga fr\u00e5gor.", case_study_cloze: "Vid h\u00f6g stress kan m\u00e4nniskor upprepa vissa ____ om och om igen p\u00e5 ett meningsl\u00f6st s\u00e4tt, som om de satt fast i en loop." } },
      { concept: "SPEEDING THROUGH COMMENTS", definition: "Fast is not always good when answering a question. When a person speeds through an apology, the apology loses its meaning-it seems mechanical and contrived. A similar principle applies in praising or welcoming people. It is at these moments that we should take our time. Speeding through an apology or recognition of another suggests there are issues, such as social anxiety, reluctance, or lack of conviction. It is the speed of talking that is the nonverbal here-as if glancing over what is important.", category: "body-language-extracted", real_world_scenario: "When the hostess finally apologized for forgetting the birthday reservation, she rushed through the words so fast that the apology lost all meaning and sounded mechanical and contrived.", case_study_cloze: "When a person ____ through an apology, it loses its meaning and seems mechanical and contrived.", sv: { concept: "Att rusa igenom kommentarer", definition: "Snabbhet \u00e4r inte alltid bra n\u00e4r man svarar p\u00e5 en fr\u00e5ga. N\u00e4r en person rafsar igenom en urs\u00e4kt tappar urs\u00e4kten sin mening \u2013 den verkar mekanisk och tillgjord. En liknande princip g\u00e4ller vid ber\u00f6m eller n\u00e4r man v\u00e4lkomnar m\u00e4nniskor. Det \u00e4r i dessa \u00f6gonblick vi b\u00f6r ta god tid p\u00e5 oss. Att skynda igenom en urs\u00e4kt eller ett erk\u00e4nnande av n\u00e5gon annan tyder p\u00e5 problem, s\u00e5som social \u00e5ngest, motvilja eller bristande \u00f6vertygelse. Det \u00e4r talets hastighet som \u00e4r det icke-verbala h\u00e4r \u2013 som att bara glida f\u00f6rbi det som \u00e4r viktigt.", real_world_scenario: "N\u00e4r v\u00e4rdinnan till slut bad om urs\u00e4kt f\u00f6r att hon gl\u00f6mt f\u00f6delsedagsbokningen rafsade hon fram orden s\u00e5 snabbt att urs\u00e4kten tappade all mening och l\u00e4t mekanisk och tillgjord.", case_study_cloze: "N\u00e4r en person ____ igenom en urs\u00e4kt tappar den sin mening och verkar mekanisk och tillgjord." } },
      { concept: "FILLER SOUNDS", definition: "Sounds such as \\\"aah,\\\" \\\"hum,\\\" \\\"hum,\\\" coughing or throat clearing, and hesitations in speaking may indicate people are momentarily at a loss for words and feeling they have to fill the void with at least a sound. Americans are notorious for using filler sounds as they figure out what to say, struggle to find the right words, or bide their time while they recall an experience. Because these are not actual words, they are considered a paralanguage or a nonverbal.", category: "body-language-extracted", real_world_scenario: "On the phone with an important client, the young consultant said 'um' and 'ah' repeatedly while searching for the right figures, filling the void with sounds while she tried to recall the report.", case_study_cloze: "Sounds such as 'aah' or 'hum' and hesitations in speaking are ____ sounds people use when they are at a loss for words.", sv: { concept: "Fyllnadsljud", definition: "Ljud som 'aah', 'hum', 'hum', hostningar eller harklingar och tvekan i talet kan tyda p\u00e5 att m\u00e4nniskor f\u00f6r stunden saknar ord och k\u00e4nner att de m\u00e5ste fylla tomrummet med \u00e5tminstone ett ljud. Amerikaner \u00e4r \u00f6k\u00e4nda f\u00f6r att anv\u00e4nda fyllnadsljud medan de funderar p\u00e5 vad de ska s\u00e4ga, k\u00e4mpar f\u00f6r att hitta r\u00e4tt ord eller k\u00f6per tid medan de f\u00f6rs\u00f6ker minnas en upplevelse. Eftersom dessa inte \u00e4r riktiga ord r\u00e4knas de som paralanguage eller icke-verbal kommunikation.", real_world_scenario: "I telefon med en viktig kund sa den unga konsulten '\u00f6h' och 'hm' upprepade g\u00e5nger medan hon s\u00f6kte efter r\u00e4tt siffror och fyllde tomrummet med ljud medan hon f\u00f6rs\u00f6kte minnas rapporten.", case_study_cloze: "Ljud som 'aah' eller 'hum' och tvekan i talet \u00e4r ____ som m\u00e4nniskor anv\u00e4nder n\u00e4r de f\u00f6r tillf\u00e4llet saknar ord." } },
      { concept: "WHISTLING NERVOUSLY", definition: "Whistling is a form of cathartic exhaling (see #98), and it helps us relieve stress. It's a good pacifier and that's why people tend to do it when traveling by themselves through a dark or desolate area or when they feel uncomfortably alone. In movies and cartoons, people or characters are often portrayed whistling while walking through a cemetery to ward off their apprehension.", category: "body-language-extracted", real_world_scenario: "Walking alone through the deserted parking garage late at night, Elin whistled a cheery tune to ward off her apprehension, the sound helping her feel less alone in the dark.", case_study_cloze: "Whistling is a good pacifier, which is why people do it when walking through a dark or desolate area or when they feel uncomfortably ____.", sv: { concept: "Nerv\u00f6st visslande", definition: "Visslande \u00e4r en form av katartisk utandning och hj\u00e4lper oss att lindra stress. Det \u00e4r en bra lugnare, och det \u00e4r d\u00e4rf\u00f6r m\u00e4nniskor tenderar att vissla n\u00e4r de f\u00e4rdas ensamma genom ett m\u00f6rkt eller \u00f6de omr\u00e5de eller n\u00e4r de k\u00e4nner sig obehagligt ensamma. I filmer och tecknade serier portr\u00e4tteras m\u00e4nniskor eller karakt\u00e4rer ofta visslande n\u00e4r de g\u00e5r genom en kyrkog\u00e5rd f\u00f6r att avv\u00e4rja sin oro.", real_world_scenario: "N\u00e4r Elin gick ensam genom det \u00f6de parkeringshuset sent p\u00e5 kv\u00e4llen visslade hon en glad melodi f\u00f6r att avv\u00e4rja sin oro; ljudet hj\u00e4lpte henne att k\u00e4nna sig mindre ensam i m\u00f6rkret.", case_study_cloze: "Visslande \u00e4r en bra lugnare, vilket \u00e4r anledningen till att m\u00e4nniskor g\u00f6r det n\u00e4r de g\u00e5r genom ett m\u00f6rkt eller \u00f6de omr\u00e5de eller n\u00e4r de k\u00e4nner sig obehagligt ____." } },
      { concept: "LIP FULLNESS", definition: "Our lips change size and dimensions according to our emotional state. They get small when we're stressed, larger when we're comfortable. Full, pliable lips indicate relaxation and contentment. When we're under stress, blood flows out of the lips to other parts of the body where it is needed. Lip fullness can serve as a barometer of a person's emotional state.", category: "body-language-extracted", real_world_scenario: "At the family reunion, Anna's lips looked full and pliable as she relaxed among relatives, a visible change from the thin, drawn lips she had worn all week during the stressful deadline at work.", case_study_cloze: "Lips get small when we are stressed and larger when we are comfortable, so ____ can serve as a barometer of a person's emotional state.", sv: { concept: "L\u00e4ppfyllighet", definition: "V\u00e5ra l\u00e4ppar \u00e4ndrar storlek och form beroende p\u00e5 v\u00e5rt k\u00e4nslotillst\u00e5nd. De blir sm\u00e5 n\u00e4r vi \u00e4r stressade, st\u00f6rre n\u00e4r vi \u00e4r bekv\u00e4ma. Fylliga, mjuka l\u00e4ppar tyder p\u00e5 avslappning och v\u00e4lbefinnande. N\u00e4r vi \u00e4r stressade str\u00f6mmar blodet bort fr\u00e5n l\u00e4pparna till andra delar av kroppen d\u00e4r det beh\u00f6vs. L\u00e4pparnas fyllighet kan fungera som en barometer f\u00f6r en persons k\u00e4nslotillst\u00e5nd.", real_world_scenario: "P\u00e5 familje\u00e5tertr\u00e4ffen s\u00e5g Annas l\u00e4ppar fylliga och mjuka ut n\u00e4r hon kopplade av bland sl\u00e4ktingarna, en tydlig f\u00f6r\u00e4ndring fr\u00e5n de tunna, smala l\u00e4pparna hon burit hela veckan under den stressiga deadline p\u00e5 jobbet.", case_study_cloze: "L\u00e4pparna blir sm\u00e5 n\u00e4r vi \u00e4r stressade och st\u00f6rre n\u00e4r vi \u00e4r bekv\u00e4ma, s\u00e5 ____ kan fungera som en barometer f\u00f6r en persons k\u00e4nslotillst\u00e5nd." } },
      { concept: "FINGERTIPS TO LIPS", definition: "Covering one's lips with one's fingers can indicate insecurity or doubt and should be considered in context. Watch for this behavior, especially as people hear a question they need to process. This behavior is also seen when people carefully ponder an issue. Keep in mind that some people do this frequently, in all sorts of situations-it is a stress reliever harking back to when they sucked their thumbs, so be careful with what inference is drawn.", category: "body-language-extracted", real_world_scenario: "In the boardroom, the CFO covered his lips with his fingertips as the question about the failed acquisition reached him, a lingering gesture while he carefully processed what to say.", case_study_cloze: "Covering one's lips with the ____ can indicate insecurity or doubt and should be considered in context.", sv: { concept: "Fingertoppar mot l\u00e4pparna", definition: "Att t\u00e4cka l\u00e4pparna med fingrarna kan tyda p\u00e5 os\u00e4kerhet eller tvivel och b\u00f6r bed\u00f6mas i sitt sammanhang. Var uppm\u00e4rksam p\u00e5 detta beteende, s\u00e4rskilt n\u00e4r m\u00e4nniskor h\u00f6r en fr\u00e5ga de beh\u00f6ver bearbeta. Beteendet ses ocks\u00e5 n\u00e4r m\u00e4nniskor noga begrundar en fr\u00e5ga. T\u00e4nk p\u00e5 att en del m\u00e4nniskor g\u00f6r detta ofta, i alla m\u00f6jliga situationer \u2013 det \u00e4r en stressavlastare som g\u00e5r tillbaka till n\u00e4r de s\u00f6g p\u00e5 tummen \u2013 s\u00e5 var f\u00f6rsiktig med vilka slutsatser du drar.", real_world_scenario: "I styrelserummet t\u00e4ckte finanschefen sina l\u00e4ppar med fingertopparna n\u00e4r fr\u00e5gan om den misslyckade uppk\u00f6psaff\u00e4ren n\u00e5dde honom, en dr\u00f6jande gest medan han noga bearbetade vad han skulle s\u00e4ga.", case_study_cloze: "Att t\u00e4cka l\u00e4pparna med ____ kan tyda p\u00e5 os\u00e4kerhet eller tvivel och b\u00f6r bed\u00f6mas i sitt sammanhang." } },
      { concept: "LIP LICKING", definition: "Rubbing the tongue on the lips helps to pacify us in the same way that lip biting does. This behavior is usually associated with concerns, anxiety, or negative emotions; however, it could just be that the person has dry lips, so be careful when drawing conclusions. For some people, however, this is a very reliable indicator that they are very stressed. As an educator, I see this all the time when an unprepared student sits down for a test.", category: "body-language-extracted", real_world_scenario: "As the unprepared student sat down for the midterm, she licked her lips repeatedly while the exam papers were passed out, a reliable sign to her teacher that she was very stressed.", case_study_cloze: "____ the lips helps to pacify us in the same way that lip biting does, though it could also just mean the person has dry lips.", sv: { concept: "L\u00e4ppslickning", definition: "Att f\u00f6ra tungan \u00f6ver l\u00e4pparna lugnar oss p\u00e5 samma s\u00e4tt som l\u00e4ppbitning. Detta beteende f\u00f6rknippas oftast med oro, \u00e5ngest eller negativa k\u00e4nslor; men det kan ocks\u00e5 bara vara s\u00e5 att personen har torra l\u00e4ppar, s\u00e5 var f\u00f6rsiktig n\u00e4r du drar slutsatser. F\u00f6r vissa m\u00e4nniskor \u00e4r detta dock en mycket tillf\u00f6rlitlig indikator p\u00e5 att de \u00e4r mycket stressade. Som l\u00e4rare ser jag detta hela tiden n\u00e4r en of\u00f6rberedd elev s\u00e4tter sig f\u00f6r ett prov.", real_world_scenario: "N\u00e4r den of\u00f6rberedda studenten satte sig f\u00f6r tentan slickade hon sig om l\u00e4pparna upprepade g\u00e5nger medan provpapperen delades ut, ett tillf\u00f6rlitligt tecken f\u00f6r hennes l\u00e4rare p\u00e5 att hon var mycket stressad.", case_study_cloze: "Att ____ p\u00e5 l\u00e4pparna hj\u00e4lper oss att lugna oss p\u00e5 samma s\u00e4tt som l\u00e4ppbitning, \u00e4ven om det ocks\u00e5 bara kan betyda att personen har torra l\u00e4ppar." } },
      { concept: "LIP BITING", definition: "Lip biting is a pacifier, usually seen when people are under stress or have concerns. We bite our lips because, after a certain age, it is no longer socially acceptable to suck our thumbs, and biting our lips stimulates the same nerves in the mouth. We might also bite our lips when we want to say something but can't or shouldn't. Note also that some people, when angry, will bite their lips as a means of self-restraint.", category: "body-language-extracted", real_world_scenario: "In the meeting, the junior designer bit her lip hard as the manager praised her colleague's idea, wanting to say that it was actually hers but knowing she couldn't.", case_study_cloze: "We may bite our ____ when we want to say something but can't or shouldn't, as a means of self-restraint.", sv: { concept: "L\u00e4ppbitning", definition: "L\u00e4ppbitning \u00e4r en lugnare, vanligtvis n\u00e4r m\u00e4nniskor \u00e4r stressade eller oroliga. Vi biter oss i l\u00e4ppen f\u00f6r att det efter en viss \u00e5lder inte l\u00e4ngre \u00e4r socialt acceptabelt att suga p\u00e5 tummen, och att bita sig i l\u00e4ppen stimulerar samma nerver i munnen. Vi kan ocks\u00e5 bita oss i l\u00e4ppen n\u00e4r vi vill s\u00e4ga n\u00e5got men inte kan eller inte borde. Notera ocks\u00e5 att en del m\u00e4nniskor, n\u00e4r de \u00e4r arga, biter sig i l\u00e4ppen som ett s\u00e4tt att h\u00e5lla sig tillbaka.", real_world_scenario: "P\u00e5 m\u00f6tet bet den yngre formgivaren h\u00e5rt i l\u00e4ppen n\u00e4r chefen ber\u00f6mde kollegans id\u00e9, f\u00f6r hon ville s\u00e4ga att det faktiskt var hennes id\u00e9 men visste att hon inte kunde.", case_study_cloze: "Vi kan bita oss i ____ n\u00e4r vi vill s\u00e4ga n\u00e5got men inte kan eller inte borde, som ett s\u00e4tt att h\u00e5lla oss tillbaka." } },
      { concept: "LIP NARROWING", definition: "The narrowing of the lips is mostly associated with negative thoughts, concerns, fears, anxiety, or lack of confidence. As we process issues or experience stress, the lips tend to narrow.", category: "body-language-extracted", real_world_scenario: "When the coach heard the referee's controversial decision, his lips narrowed to a thin line as he processed the call, a brief flash of anger and frustration he didn't voice.", case_study_cloze: "The ____ of the lips is mostly associated with negative thoughts, concerns, fears, anxiety, or lack of confidence.", sv: { concept: "Smalnande l\u00e4ppar", definition: "Att l\u00e4pparna smalnar f\u00f6rknippas oftast med negativa tankar, oro, r\u00e4dslor, \u00e5ngest eller brist p\u00e5 sj\u00e4lvf\u00f6rtroende. N\u00e4r vi bearbetar problem eller upplever stress tenderar l\u00e4pparna att smalna.", real_world_scenario: "N\u00e4r coachen h\u00f6rde domarens kontroversiella beslut smalnade hans l\u00e4ppar till en tunn linje medan han bearbetade beslutet, en kort glimt av ilska och frustration som han inte gav r\u00f6st \u00e5t.", case_study_cloze: "Att l\u00e4pparna ____ f\u00f6rknippas oftast med negativa tankar, oro, r\u00e4dslor, \u00e5ngest eller brist p\u00e5 sj\u00e4lvf\u00f6rtroende." } },
      { concept: "LIP COMPRESSING", definition: "Throughout the day, as we encounter negative events or uncomfortable thoughts, and concerns, our lips will narrow and press together, accurately transmitting, even if only for an instant, our concerns. Lip compression can be very subtle or can reach a point where the lips noticeably change color as blood is forced out. Lip compression can be very fleeting ( th of a second), and yet it reveals accurately a negative 1 / 20 emotion suddenly registered.", category: "body-language-extracted", real_world_scenario: "At the market, the buyer's lips compressed into a pale line for a split second when the seller quoted the price, a fleeting negative reaction that vanished before the seller even noticed.", case_study_cloze: "When we encounter negative events or uncomfortable thoughts, our lips narrow and press together in a brief ____ that can last only a twentieth of a second.", sv: { concept: "L\u00e4ppkompression", definition: "Under dagen, n\u00e4r vi st\u00f6ter p\u00e5 negativa h\u00e4ndelser, obehagliga tankar eller oro, smalnar v\u00e5ra l\u00e4ppar och pressas ihop, och f\u00f6rmedlar exakt \u2013 \u00e4ven om bara f\u00f6r ett \u00f6gonblick \u2013 v\u00e5r oro. L\u00e4ppkompression kan vara mycket subtil eller n\u00e5 en punkt d\u00e4r l\u00e4pparna m\u00e4rkbart byter f\u00e4rg n\u00e4r blodet pressas ut. L\u00e4ppkompression kan vara mycket flyktig (en tjugondels sekund), och \u00e4nd\u00e5 avsl\u00f6jar den exakt en negativ k\u00e4nsla som pl\u00f6tsligt registrerats.", real_world_scenario: "P\u00e5 marknaden pressades k\u00f6parens l\u00e4ppar samman till en blek linje i en br\u00e5kdels sekund n\u00e4r s\u00e4ljaren angav priset, en flyktig negativ reaktion som f\u00f6rsvann innan s\u00e4ljaren ens hann m\u00e4rka den.", case_study_cloze: "N\u00e4r vi st\u00f6ter p\u00e5 negativa h\u00e4ndelser eller obehagliga tankar smalnar l\u00e4pparna och pressas samman i en kort ____ som bara kan vara en tjugondels sekund." } },
      { concept: "SLIGHT PRESSING OF LIPS", definition: "Sometimes we show our annoyance with others by slightly compressing the lips. Unlike full lip compression, where both lips are involved, this usually involves only the upper lip. Still, a slight lip compression might reveal something, when considered along with the rest of a person's body language.", category: "body-language-extracted", real_world_scenario: "When her coworker claimed credit for the report once again, Petra showed her annoyance with a slight pressing of the upper lip, a subtle signal she thought no one could read.", case_study_cloze: "Unlike full lip compression, a slight pressing usually involves only the ____ lip and can show annoyance.", sv: { concept: "L\u00e4tt l\u00e4pppressning", definition: "Ibland visar vi v\u00e5r irritation \u00f6ver andra genom att pressa ihop l\u00e4pparna l\u00e4tt. Till skillnad fr\u00e5n full l\u00e4ppkompression, d\u00e4r b\u00e5da l\u00e4pparna \u00e4r inblandade, brukar detta oftast bara involvera \u00f6verl\u00e4ppen. \u00c4nd\u00e5 kan en l\u00e4tt l\u00e4ppkompression avsl\u00f6ja n\u00e5got, n\u00e4r den bed\u00f6ms tillsammans med resten av en persons kroppsspr\u00e5k.", real_world_scenario: "N\u00e4r hennes kollega \u00e4nnu en g\u00e5ng tog \u00e5t sig \u00e4ran f\u00f6r rapporten visade Petra sin irritation genom en l\u00e4tt pressning av \u00f6verl\u00e4ppen, en subtil signal som hon trodde att ingen kunde tyda.", case_study_cloze: "Till skillnad fr\u00e5n full l\u00e4ppkompression brukar en l\u00e4tt pressning oftast bara involvera ____ l\u00e4ppen och kan visa irritation." } },
      { concept: "RELUCTANCE TO DECOMPRESS LIPS", definition: "People who hold their compressed lips together for a long time, reluctant to decompress them, are signaling a high degree of stress or concern. Lip compression is, in a way, a battening down of our hatches, much like covering our eyes with our hands to block out something negative. The greater the tension or apprehension, the greater the need to keep the lips compressed.", category: "body-language-extracted", real_world_scenario: "In the hospital waiting room, the man kept his lips pressed tightly together long after the doctor finished speaking, reluctant to decompress them, signaling how deeply the diagnosis had shaken him.", case_study_cloze: "People who hold their compressed lips together for a long time, reluctant to ____ them, are signaling a high degree of stress or concern.", sv: { concept: "Att h\u00e5lla ihop l\u00e4pparna", definition: "M\u00e4nniskor som h\u00e5ller sina sammanpressade l\u00e4ppar ihop under l\u00e5ng tid, motvilliga att sl\u00e4ppa ihop dem igen, signalerar en h\u00f6g grad av stress eller oro. L\u00e4ppkompression \u00e4r p\u00e5 s\u00e4tt och vis att bomma till luckorna, ungef\u00e4r som att t\u00e4cka \u00f6gonen med h\u00e4nderna f\u00f6r att st\u00e4nga ute n\u00e5got negativt. Ju st\u00f6rre sp\u00e4nning eller oro, desto st\u00f6rre behov av att h\u00e5lla l\u00e4pparna sammanpressade.", real_world_scenario: "I v\u00e4ntrummet p\u00e5 sjukhuset h\u00f6ll mannen l\u00e4pparna h\u00e5rt sammanpressade l\u00e5ngt efter att l\u00e4karen slutat tala, motvillig att sl\u00e4ppa ihop dem igen, vilket signalerade hur djupt diagnosen hade skakat honom.", case_study_cloze: "M\u00e4nniskor som h\u00e5ller sina sammanpressade l\u00e4ppar ihop under l\u00e5ng tid, motvilliga att ____ dem, signalerar en h\u00f6g grad av stress eller oro." } },
      { concept: "LIP WITHDRAWING", definition: "When we have deep concerns or anxiety, we might suck our lips into our mouth to the point where they are no longer visible. This signals something very different from lip compressing ( see #147), where much of the lips remain visible. This behavior is often reserved for when there is severe stress, significant physical pain, or great emotional turmoil.", category: "body-language-extracted", real_world_scenario: "As the surgeon explained the risks of the operation, the patient slowly sucked her lips into her mouth until they disappeared, a sign of severe stress that the nurse quietly noted.", case_study_cloze: "When we have deep concerns or anxiety, we might suck our ____ into our mouth to the point where they are no longer visible.", sv: { concept: "Indragna l\u00e4ppar", definition: "N\u00e4r vi har djup oro eller \u00e5ngest kan vi suga in l\u00e4pparna i munnen tills de inte l\u00e4ngre syns. Detta signalerar n\u00e5got helt annat \u00e4n l\u00e4ppkompression, d\u00e4r stora delar av l\u00e4pparna fortfarande syns. Detta beteende \u00e4r ofta f\u00f6rbeh\u00e5llet tillf\u00e4llen med allvarlig stress, betydande fysisk sm\u00e4rta eller stor k\u00e4nslom\u00e4ssig turbulens.", real_world_scenario: "Medan kirurgen f\u00f6rklarade riskerna med operationen s\u00f6g patienten l\u00e5ngsamt in l\u00e4pparna i munnen tills de inte l\u00e4ngre syntes, ett tecken p\u00e5 sv\u00e5r stress som sk\u00f6terskan tyst noterade.", case_study_cloze: "N\u00e4r vi har djup oro eller \u00e5ngest kan vi suga in ____ i munnen tills de inte l\u00e4ngre syns." } },
      { concept: "LIP PURSING", definition: "We purse our lips (pinching them tightly toward the front of the mouth) when we disagree with something or when we are thinking of an alternative. When audiences take issue with what a speaker is saying or know it is wrong, you often see this behavior. The more outward the movement of the pursed lips, the stronger the negative emotion or sentiment. This is an extremely reliable behavior you also see in poker when players don't like their own hole cards.", category: "body-language-extracted", real_world_scenario: "During the town hall meeting, several residents pursed their lips when the mayor defended the new parking fees, pinching them tightly toward the front of the mouth to show their disagreement.", case_study_cloze: "We purse our lips when we ____ with something or when we are thinking of an alternative, as poker players do when they don't like their hole cards.", sv: { concept: "L\u00e4pptrutning", definition: "Vi trutar med l\u00e4pparna (nyper ihop dem h\u00e5rt mot munh\u00e5lans framkant) n\u00e4r vi inte h\u00e5ller med om n\u00e5got eller n\u00e4r vi t\u00e4nker p\u00e5 ett alternativ. N\u00e4r publiken inv\u00e4nder mot vad en talare s\u00e4ger eller vet att det \u00e4r fel, ser man ofta detta beteende. Ju mer ut\u00e5triktad r\u00f6relsen hos de trutande l\u00e4pparna \u00e4r, desto starkare \u00e4r den negativa k\u00e4nslan eller inst\u00e4llningen. Detta \u00e4r ett ytterst tillf\u00f6rlitligt beteende som man ocks\u00e5 ser i poker n\u00e4r spelare inte gillar sina egna h\u00e5lkort.", real_world_scenario: "Under kommunm\u00f6tet trutade flera inv\u00e5nare med l\u00e4pparna n\u00e4r borgm\u00e4staren f\u00f6rsvarade de nya parkeringsavgifterna, n\u00f6p ihop dem h\u00e5rt fram\u00e5t i munnen f\u00f6r att visa sin oenighet.", case_study_cloze: "Vi trutar med l\u00e4pparna n\u00e4r vi inte ____ med n\u00e5got eller n\u00e4r vi t\u00e4nker p\u00e5 ett alternativ, precis som pokerspelare g\u00f6r n\u00e4r de inte gillar sina h\u00e5lkort." } },
      { concept: "SAD MOUTH", definition: "The mouth, like the eyes, can be a window into our emotional state. Sadness is usually shown with the corners of the lips turned down slightly, usually in concert with lowered upper eyelids. This is sometimes referred to as a \\\"grouper\\\" mouth or face. It should be noted that some people naturally look this way-the corners of their mouths perpetually turned down-and for them, it has nothing to do with negative emotions.", category: "body-language-extracted", real_world_scenario: "In the courtroom, the widow's mouth showed her grief plainly: the corners of her lips turned slightly down, in concert with lowered upper eyelids, though some people naturally look this way all the time.", case_study_cloze: "Sadness is usually shown with the ____ of the lips turned down slightly, often in concert with lowered upper eyelids.", sv: { concept: "Sorgsen mun", definition: "Munnen, liksom \u00f6gonen, kan vara ett f\u00f6nster till v\u00e5rt k\u00e4nslotillst\u00e5nd. Sorg visas vanligtvis genom att l\u00e4pparnas mungipor v\u00e4nds n\u00e5got ned\u00e5t, oftast i samverkan med s\u00e4nkta \u00f6vre \u00f6gonlock. Detta kallas ibland f\u00f6r en 'sur' mun eller ett 'surt' ansikte. Det b\u00f6r noteras att en del m\u00e4nniskor naturligt ser ut s\u00e5 h\u00e4r \u2013 med mungipor som st\u00e4ndigt pekar ned\u00e5t \u2013 och f\u00f6r dem har det ingenting med negativa k\u00e4nslor att g\u00f6ra.", real_world_scenario: "I r\u00e4ttssalen visade \u00e4nkan sin sorg tydligt: mungiporna var l\u00e4tt v\u00e4nda ned\u00e5t, i samverkan med s\u00e4nkta \u00f6vre \u00f6gonlock, \u00e4ven om en del m\u00e4nniskor naturligt ser ut s\u00e5 h\u00e4r hela tiden.", case_study_cloze: "Sorg visas vanligtvis genom att l\u00e4pparnas ____ v\u00e4nds n\u00e5got ned\u00e5t, ofta i samverkan med s\u00e4nkta \u00f6vre \u00f6gonlock." } },
      { concept: "TRUE SMILE", definition: "A topic of much research; a genuine smile involves the mouth and the muscles around the eyes. This is called a Duchenne smile, according to body-language researcher Paul Ekman. The face is visibly more relaxed in a true smile, as the facial muscles reflect actual joy rather than tension. Studies have shown that a genuine smile can be truly \\\"contagious,\\\" in both professional and personal environments, and is often a trait we associate with charismatic individuals.", category: "body-language-extracted", real_world_scenario: "When the old friends met at the airport after years apart, both broke into genuine smiles that reached their eyes, the relaxed Duchenne smile that studies show is contagious even in professional settings.", case_study_cloze: "A genuine smile, called a ____ smile, involves both the mouth and the muscles around the eyes.", sv: { concept: "\u00c4kta leende", definition: "Ett v\u00e4lbeforskat \u00e4mne: ett \u00e4kta leende involverar munnen och musklerna runt \u00f6gonen. Detta kallas f\u00f6r ett Duchenne-leende, enligt kroppsspr\u00e5ksforskaren Paul Ekman. Ansiktet \u00e4r synligt mer avslappnat vid ett \u00e4kta leende, eftersom ansiktsmusklerna speglar verklig gl\u00e4dje snarare \u00e4n sp\u00e4nning. Studier har visat att ett \u00e4kta leende kan vara verkligt 'smittsamt', b\u00e5de i professionella och personliga milj\u00f6er, och det \u00e4r ofta en egenskap som vi f\u00f6rknippar med karismatiska personer.", real_world_scenario: "N\u00e4r de gamla v\u00e4nnerna m\u00f6ttes p\u00e5 flygplatsen efter flera \u00e5r brast b\u00e5da ut i \u00e4kta leenden som n\u00e5dde \u00f6gonen, det avslappnade Duchenne-leendet som studier visar \u00e4r smittsamt \u00e4ven i professionella sammanhang.", case_study_cloze: "Ett \u00e4kta leende, som kallas f\u00f6r ett ____-leende, involverar b\u00e5de munnen och musklerna runt \u00f6gonen." } },
      { concept: "FALSE SMILE", definition: "False smiles, like nervous smiles, are used for perception management to make others believe everything is OK. They are fairly easy to distinguish from a true smile; however, in a false smile, sometimes only one side of the face is involved, or the smile goes toward the ear rather than the eyes. It looks contrived. A true smile engages the eyes and the facial muscles smoothly on both sides of the face.", category: "body-language-extracted", real_world_scenario: "At the department store, the customer's complaint was met with a broad smile from the floor manager, but the smile went toward her ears rather than her eyes and looked contrived, a classic false smile meant to make everything seem OK.", case_study_cloze: "A ____ smile is used for perception management and looks contrived, sometimes involving only one side of the face or going toward the ear rather than the eyes.", sv: { concept: "Falskt leende", definition: "Falska leenden, liksom nerv\u00f6sa leenden, anv\u00e4nds f\u00f6r att hantera intryck och f\u00e5 andra att tro att allt \u00e4r okej. De \u00e4r ganska l\u00e4tta att skilja fr\u00e5n ett \u00e4kta leende; dock involverar ett falskt leende ibland bara ena sidan av ansiktet, eller s\u00e5 g\u00e5r leendet mot \u00f6rat snarare \u00e4n \u00f6gonen. Det ser tillgjort ut. Ett \u00e4kta leende engagerar \u00f6gonen och ansiktsmusklerna j\u00e4mnt p\u00e5 b\u00e5da sidor av ansiktet.", real_world_scenario: "P\u00e5 varuhuset bem\u00f6ttes kundens klagom\u00e5l av ett brett leende fr\u00e5n butikschefen, men leendet gick mot \u00f6ronen snarare \u00e4n \u00f6gonen och s\u00e5g tillgjort ut, ett klassiskt falskt leende f\u00f6r att f\u00e5 allt att verka okej.", case_study_cloze: "Ett ____ leende anv\u00e4nds f\u00f6r att hantera intryck och ser tillgjort ut, ibland med bara ena sidan av ansiktet eller med leendet mot \u00f6rat snarare \u00e4n \u00f6gonen." } },
      { concept: "NERVOUS SMILE", definition: "A nervous or tense smile shows anxiety, concern, or stress. The nervous smile is performed to make others think everything is fine. You often see this on visitors clearing customs at the airport; they nervously smile at the inquisitive officer asking questions.", category: "body-language-extracted", real_world_scenario: "At the airport, the traveler nervously smiled at the customs officer asking about her luggage, her tense smile betraying anxiety even as she insisted everything was fine.", case_study_cloze: "A tense, ____ smile shows anxiety, concern, or stress and is performed to make others think everything is fine.", sv: { concept: "Nerv\u00f6st leende", definition: "Ett nerv\u00f6st eller sp\u00e4nt leende visar \u00e5ngest, oro eller stress. Det nerv\u00f6sa leendet utf\u00f6rs f\u00f6r att f\u00e5 andra att tro att allt \u00e4r bra. Du ser det ofta hos bes\u00f6kare som passerar tullen p\u00e5 flygplatsen; de ler nerv\u00f6st mot den fr\u00e5gvisa tj\u00e4nstemannen.", real_world_scenario: "P\u00e5 flygplatsen log resen\u00e4ren nerv\u00f6st mot tulltj\u00e4nstemannen som fr\u00e5gade om hennes bagage; hennes sp\u00e4nda leende avsl\u00f6jade \u00e5ngest trots att hon f\u00f6rs\u00e4krade att allt var bra.", case_study_cloze: "Ett sp\u00e4nt, ____ leende visar \u00e5ngest, oro eller stress och utf\u00f6rs f\u00f6r att f\u00e5 andra att tro att allt \u00e4r bra." } },
      { concept: "SUDDEN FACIAL TICS", definition: "Facial tics can erupt anywhere on the face (the cheek, a corner of the mouth, the eyes, the forehead) and are specific to each individual. If you suddenly see a nervous twitch, it is usually caused by tension or anxiety. Facial tics often occur on or near the cheeks because of the interconnecting muscles that traverse this area.", category: "body-language-extracted", real_world_scenario: "During the questioning, the witness's left cheek twitched suddenly every time the lawyer mentioned the nightclub, a nervous tic caused by tension that erupted only around that topic.", case_study_cloze: "If you suddenly see a nervous twitch on someone's face, it is usually caused by ____ or anxiety.", sv: { concept: "Pl\u00f6tsliga ansiktstics", definition: "Ansiktstics kan bryta ut var som helst i ansiktet (p\u00e5 kinden, i en mungipa, vid \u00f6gonen, p\u00e5 pannan) och \u00e4r specifika f\u00f6r varje individ. Om du pl\u00f6tsligt ser en nerv\u00f6s ryckning beror det vanligtvis p\u00e5 sp\u00e4nning eller \u00e5ngest. Ansiktstics upptr\u00e4der ofta p\u00e5 eller n\u00e4ra kinderna p\u00e5 grund av de sammankopplade muskler som korsar detta omr\u00e5de.", real_world_scenario: "Under f\u00f6rh\u00f6ret ryckte vittnets v\u00e4nstra kind till pl\u00f6tsligt varje g\u00e5ng advokaten n\u00e4mnde nattklubben, ett nerv\u00f6st tics orsakat av sp\u00e4nning som bara br\u00f6t ut i anslutning till det \u00e4mnet.", case_study_cloze: "Om du pl\u00f6tsligt ser en nerv\u00f6s ryckning i n\u00e5gons ansikte beror det vanligtvis p\u00e5 ____ eller \u00e5ngest." } },
      { concept: "CHEEK OR FACIAL MASSAGING", definition: "Cheek or facial massaging is a good way to release stress. Usually done very softly, it can also signal contemplation.", category: "body-language-extracted", real_world_scenario: "At her desk, the accountant gently massaged her cheek with two fingers while staring at the spreadsheets, a soft, slow stroking that both released her stress and marked her deep contemplation.", case_study_cloze: "Gently massaging the cheek or face is a good way to ____ stress and can also signal contemplation.", sv: { concept: "Kind- eller ansiktsmassage", definition: "Kind- eller ansiktsmassage \u00e4r ett bra s\u00e4tt att sl\u00e4ppa stress. Den utf\u00f6rs vanligtvis mycket mjukt och kan ocks\u00e5 signalera eftertanke.", real_world_scenario: "Vid sitt skrivbord masserade revisorn mjukt kinden med tv\u00e5 fingrar medan hon stirrade p\u00e5 kalkylbladen, en l\u00e5ngsam, mjuk strykning som b\u00e5de sl\u00e4ppte stressen och markerade djup eftertanke.", case_study_cloze: "Att mjukt massera kinden eller ansiktet \u00e4r ett bra s\u00e4tt att ____ stress och kan ocks\u00e5 signalera eftertanke." } },
      { concept: "CHEEK STRUMMING", definition: "Strumming the fingers on the cheek indicates that someone is bored and wanting to move things along. Verify with other behaviors, such as looking bored or seat shifting.", category: "body-language-extracted", real_world_scenario: "Twenty minutes into the status meeting, the analyst began strumming his fingers on his cheek, clearly bored and wanting to move things along while the manager kept repeating the same point.", case_study_cloze: "Strumming the fingers on the ____ indicates that someone is bored and wanting to move things along.", sv: { concept: "Att trumma p\u00e5 kinden", definition: "Att trumma med fingrarna p\u00e5 kinden tyder p\u00e5 att n\u00e5gon \u00e4r uttr\u00e5kad och vill komma vidare. Bekr\u00e4fta med andra beteenden, som en uttr\u00e5kad blick eller att personen flyttar sig i stolen.", real_world_scenario: "Tjugo minuter in i statusm\u00f6tet b\u00f6rjade analytikern trumma med fingrarna p\u00e5 kinden, tydligt uttr\u00e5kad och angel\u00e4gen om att komma vidare medan chefen upprepade samma sak.", case_study_cloze: "Att trumma med fingrarna p\u00e5 ____ tyder p\u00e5 att n\u00e5gon \u00e4r uttr\u00e5kad och vill komma vidare." } },
      { concept: "CHEEK WIPING", definition: "Under extreme stress, it is not unusual to see people press their hands on their face and drag them downward, as if wiping their faces clean. Typically, the motion starts just in front of the ears and concludes near the jawbone. The harder and longer the person presses down, the more acute the stress. I've seen stockbrokers do this at the closing bell after a poor day of trading or when a team loses in the final second of a game.", category: "body-language-extracted", real_world_scenario: "After the stock market closed on a disastrous Friday, the trader pressed both hands on his face and dragged them downward past his jawbone, a long, hard wipe that revealed how acute his stress was.", case_study_cloze: "Under extreme stress, people may press their hands on their face and drag them ____, as if wiping their faces clean.", sv: { concept: "Ansiktsavtorkning", definition: "Vid extrem stress \u00e4r det inte ovanligt att se m\u00e4nniskor trycka h\u00e4nderna mot ansiktet och dra dem ned\u00e5t, som om de torkade ansiktet rent. Vanligtvis b\u00f6rjar r\u00f6relsen strax framf\u00f6r \u00f6ronen och slutar n\u00e4ra k\u00e4kbenet. Ju h\u00e5rdare och l\u00e4ngre personen trycker, desto akutare \u00e4r stressen. Jag har sett b\u00f6rsm\u00e4klare g\u00f6ra detta vid st\u00e4ngningsklockan efter en d\u00e5lig handelsdag, eller n\u00e4r ett lag f\u00f6rlorar i den sista sekunden av en match.", real_world_scenario: "Efter att b\u00f6rsen st\u00e4ngt en katastrofal fredag tryckte handlaren b\u00e5da h\u00e4nderna mot ansiktet och drog dem ned\u00e5t f\u00f6rbi k\u00e4kbenet, en l\u00e5ng, h\u00e5rd avtorkning som avsl\u00f6jade hur akut stressen var.", case_study_cloze: "Vid extrem stress kan m\u00e4nniskor trycka h\u00e4nderna mot ansiktet och dra dem ____, som om de torkade ansiktet rent." } },
      { concept: "JAW TENSING", definition: "When we are upset, angry, or fearful, the jaw muscles near the ears tend to tense up. Look for jaw tension when there is stress, defiance, or emotions are becoming heated.", category: "body-language-extracted", real_world_scenario: "When the boss announced yet another round of layoffs, the team leader's jaw muscles near his ears visibly tensed, betraying the anger he was trying hard not to show in front of his team.", case_study_cloze: "When we are upset, angry, or fearful, the ____ muscles near the ears tend to tense up.", sv: { concept: "K\u00e4ksp\u00e4nning", definition: "N\u00e4r vi \u00e4r uppr\u00f6rda, arga eller r\u00e4dda tenderar k\u00e4kmusklerna n\u00e4ra \u00f6ronen att sp\u00e4nnas. Titta efter k\u00e4ksp\u00e4nning vid stress, trots eller n\u00e4r k\u00e4nslorna b\u00f6rjar hettas upp.", real_world_scenario: "N\u00e4r chefen meddelade \u00e4nnu en omg\u00e5ng upps\u00e4gningar sp\u00e4ndes gruppchefens k\u00e4kmuskler n\u00e4ra \u00f6ronen tydligt, vilket avsl\u00f6jade den ilska han f\u00f6rs\u00f6kte d\u00f6lja inf\u00f6r sitt team.", case_study_cloze: "N\u00e4r vi \u00e4r uppr\u00f6rda, arga eller r\u00e4dda tenderar ____ musklerna n\u00e4ra \u00f6ronen att sp\u00e4nnas." } },
      { concept: "JAW DISPLACING/SHIFTING", definition: "Jaw displacement or repetitive jaw shifting (from side to side) is an effective pacifier. This is also simply a compulsive behavior in some people, so note when and how often it occurs and look for other confirming behaviors that something is amiss. Most people do this infrequently, and thus when you do see it, it is very accurate in communicating that something is bothering them.", category: "body-language-extracted", real_world_scenario: "During the budget meeting, the finance director shifted his jaw side to side while the cost overruns were being detailed \u2014 a repetitive motion that betrayed his mounting stress even though he said nothing.", case_study_cloze: "In the team meeting, the manager's repetitive ____ from side to side betrayed his stress as the costs were discussed.", sv: { concept: "K\u00e4kskiftande", definition: "K\u00e4kf\u00f6rskjutning eller upprepat k\u00e4kskiftande (fr\u00e5n sida till sida) \u00e4r en effektiv lugnande gest. F\u00f6r vissa m\u00e4nniskor \u00e4r det helt enkelt ett tv\u00e5ngsm\u00e4ssigt beteende, s\u00e5 notera n\u00e4r och hur ofta det sker och leta efter andra bekr\u00e4ftande beteenden som tyder p\u00e5 att n\u00e5got \u00e4r fel. De flesta g\u00f6r detta s\u00e4llan, och n\u00e4r du v\u00e4l ser det \u00e4r det en mycket tillf\u00f6rlitlig signal p\u00e5 att n\u00e5got st\u00f6r dem.", real_world_scenario: "Under budgetm\u00f6tet skiftade ekonomichefen k\u00e4ken fr\u00e5n sida till sida medan kostnads\u00f6verskridandena gicks igenom \u2014 en upprepad r\u00f6relse som avsl\u00f6jade hans v\u00e4xande stress trots att han inte sa ett ord.", case_study_cloze: "P\u00e5 teamm\u00f6tet avsl\u00f6jade chefens upprepade ____ fr\u00e5n sida till sida hans stress n\u00e4r kostnaderna diskuterades." } },
      { concept: "JAW DROPPING", definition: "A sudden drop of the jaw, leaving the mouth open and the teeth exposed, communicates great surprise. This behavior is often seen when people are shocked or are confronted with an embarrassing revelation. Why our jaws drop is not completely understood, but the action is quite accurate in revealing total surprise.", category: "body-language-extracted", real_world_scenario: "At the family dinner, Grandma's jaw dropped when her son announced they were moving to New Zealand the following month \u2014 the sudden drop of the jaw revealed her total shock before she said a word.", case_study_cloze: "When the boss revealed the surprise promotion, the employee's sudden ____ left his mouth open and his teeth exposed in disbelief.", sv: { concept: "K\u00e4knedfall", definition: "Ett pl\u00f6tsligt fall av k\u00e4ken, s\u00e5 att munnen l\u00e4mnas \u00f6ppen och t\u00e4nderna syns, f\u00f6rmedlar stor f\u00f6rv\u00e5ning. Beteendet ses ofta n\u00e4r m\u00e4nniskor chockeras eller konfronteras med en pinsam avsl\u00f6jande situation. Varf\u00f6r k\u00e4ken faller \u00e4r inte helt klarlagt, men handlingen avsl\u00f6jar total f\u00f6rv\u00e5ning med ganska stor tillf\u00f6rlitlighet.", real_world_scenario: "Vid familjemiddagen f\u00f6ll mormors k\u00e4ke n\u00e4r sonen meddelade att de skulle flytta till Nya Zeeland n\u00e4sta m\u00e5nad \u2014 det pl\u00f6tsliga k\u00e4knedfallet avsl\u00f6jade hennes totala chock innan hon hann s\u00e4ga ett ord.", case_study_cloze: "N\u00e4r chefen avsl\u00f6jade den ov\u00e4ntade befordran l\u00e4mnade medarbetarens pl\u00f6tsliga ____ munnen \u00f6ppen och t\u00e4nderna blottade i misstro." } },
      { concept: "JAW MUSCLES PULSING", definition: "Jaw muscles that pulse, throb, or become tight and pronounced indicate impatience, tension, concern, worries, anger, or negative emotions.", category: "body-language-extracted", real_world_scenario: "At the traffic stop, the driver's jaw muscles pulsed visibly as the officer asked him to repeat his story twice \u2014 the throbbing tension betrayed his anger long before his voice rose.", case_study_cloze: "As the customer complained about the wait, her tight and pulsing ____ muscles revealed her growing impatience.", sv: { concept: "Pulserande k\u00e4kmuskler", definition: "K\u00e4kmuskler som pulserar, bultar eller blir sp\u00e4nda och tydligt framtr\u00e4dande tyder p\u00e5 ot\u00e5lighet, sp\u00e4nning, oro, bekymmer, ilska eller negativa k\u00e4nslor.", real_world_scenario: "Vid trafikkontrollen pulserade f\u00f6rarens k\u00e4kmuskler synligt n\u00e4r polisen bad honom upprepa sin historia tv\u00e5 g\u00e5nger \u2014 den bultande sp\u00e4nningen avsl\u00f6jade ilskan l\u00e5ngt innan r\u00f6sten h\u00f6jdes.", case_study_cloze: "Medan kunden klagade p\u00e5 v\u00e4ntetiden avsl\u00f6jade hennes sp\u00e4nda och pulserande ____ muskler en v\u00e4xande ot\u00e5lighet." } },
      { concept: "JAW JUTTING", definition: "When we are angry, we tend to move or jut the jaw slightly forward. In conjunction with lowered upper eyelids or tense lips, this behavior makes anger difficult for a person to hide entirely.", category: "body-language-extracted", real_world_scenario: "In the principal's office, the teenager jutted his jaw forward while being scolded \u2014 combined with tense lips and lowered eyelids, the anger was impossible to hide despite his silence.", case_study_cloze: "With his ____ pushed forward and his lips tight, the coach's anger was hard for him to hide after the referee's call.", sv: { concept: "K\u00e4ken framskjuten", definition: "N\u00e4r vi \u00e4r arga tenderar vi att f\u00f6ra k\u00e4ken n\u00e5got fram\u00e5t. I kombination med s\u00e4nkta \u00f6vre \u00f6gonlock eller sp\u00e4nda l\u00e4ppar g\u00f6r beteendet att ilska blir sv\u00e5r att helt d\u00f6lja.", real_world_scenario: "P\u00e5 rektorns kontor sk\u00f6t ton\u00e5ringen k\u00e4ken fram\u00e5t n\u00e4r han fick en utsk\u00e4llning \u2014 i kombination med sp\u00e4nda l\u00e4ppar och s\u00e4nkta \u00f6gonlock var ilskan om\u00f6jlig att d\u00f6lja trots tystnaden.", case_study_cloze: "Med k\u00e4ken ____ och l\u00e4pparna sp\u00e4nda var tr\u00e4narens ilska sv\u00e5r att d\u00f6lja efter domslutet." } },
      { concept: "CHIN POINTING DOWN", definition: "If the chin suddenly points downward in response to a question, most likely the person lacks confidence or feels threatened. In some people, this is a highly reliable tell; they literally drop their chin when they get bad news or as they think about something painful or negative.", category: "body-language-extracted", real_world_scenario: "When the defense attorney asked about the night in question, the witness's chin suddenly pointed down toward her chest \u2014 she lacked confidence and felt threatened before she even answered.", case_study_cloze: "Asked about the missing documents, the accountant's chin pointed ____, revealing that he felt threatened and lacked confidence.", sv: { concept: "Hakan pekar ned\u00e5t", definition: "Om hakan pl\u00f6tsligt pekar ned\u00e5t som svar p\u00e5 en fr\u00e5ga saknar personen troligen sj\u00e4lvf\u00f6rtroende eller k\u00e4nner sig hotad. Hos vissa m\u00e4nniskor \u00e4r detta ett mycket tillf\u00f6rlitligt tecken; de s\u00e4nker bokstavligen hakan n\u00e4r de f\u00e5r d\u00e5liga nyheter eller t\u00e4nker p\u00e5 n\u00e5got sm\u00e4rtsamt eller negativt.", real_world_scenario: "N\u00e4r f\u00f6rsvarsadvokaten fr\u00e5gade om den aktuella natten pekade vittnets haka pl\u00f6tsligt ned\u00e5t mot br\u00f6stet \u2014 hon saknade sj\u00e4lvf\u00f6rtroende och k\u00e4nde sig hotad redan innan hon svarade.", case_study_cloze: "N\u00e4r revisorn fick fr\u00e5gan om de f\u00f6rsvunna dokumenten pekade hans haka ____, vilket avsl\u00f6jade att han k\u00e4nde sig hotad och saknade sj\u00e4lvf\u00f6rtroende." } },
      { concept: "CHIN SHIFTING", definition: "Moving the chin left to right against the palm of the hand is a subconscious conveyance of disagreement. I have seen people sitting around a conference room table show their silent displeasure by shifting their chin while resting on the palm of their hand.", category: "body-language-extracted", real_world_scenario: "Around the conference table, the senior partner listened silently with his chin resting on his palm, shifting it left to right \u2014 a quiet display of disagreement with the marketing proposal.", case_study_cloze: "During the presentation, the investor shifted his ____ left and right against his palm, silently signaling his disagreement.", sv: { concept: "Hakskiftande", definition: "Att flytta hakan fr\u00e5n v\u00e4nster till h\u00f6ger mot handflatan \u00e4r ett omedvetet tecken p\u00e5 oenighet. Jag har sett m\u00e4nniskor runt ett konferensbord visa sitt tysta missn\u00f6je genom att skifta hakan medan de vilar den p\u00e5 handflatan.", real_world_scenario: "Runt konferensbordet lyssnade den \u00e4ldre partnern tyst med hakan vilande p\u00e5 handflatan och skiftade den fr\u00e5n v\u00e4nster till h\u00f6ger \u2014 ett stillsamt tecken p\u00e5 oenighet med marknadsf\u00f6ringsf\u00f6rslaget.", case_study_cloze: "Under presentationen skiftade investeraren sin ____ fr\u00e5n v\u00e4nster till h\u00f6ger mot handflatan och signalerade d\u00e4rmed tyst sin oenighet." } },
      { concept: "CHIN TOUCHING", definition: "We touch our chins when we are thinking or evaluating something. This is usually done with the tips of the fingers. It is not necessarily a sign of doubt but is something to note when a person is processing information. When coupled with other behaviors, such as lip pursing, it suggests that the person is contemplating something negative, or an alternative to what has been discussed.", category: "body-language-extracted", real_world_scenario: "In the interview, the candidate touched her chin with her fingertips while considering the question about her greatest weakness \u2014 a sign she was carefully processing the information before replying.", case_study_cloze: "The doctor touched his ____ with his fingertips while evaluating the test results, a sign that he was weighing the information.", sv: { concept: "Hakber\u00f6ring", definition: "Vi r\u00f6r vid hakan n\u00e4r vi t\u00e4nker eller utv\u00e4rderar n\u00e5got, oftast med fingertopparna. Det \u00e4r inte n\u00f6dv\u00e4ndigtvis ett tecken p\u00e5 tvivel men n\u00e5got att notera n\u00e4r en person bearbetar information. I kombination med andra beteenden, som att pressa ihop l\u00e4pparna, tyder det p\u00e5 att personen funderar p\u00e5 n\u00e5got negativt eller p\u00e5 ett alternativ till det som diskuterats.", real_world_scenario: "Under intervjun r\u00f6rde kandidaten vid hakan med fingertopparna n\u00e4r hon funderade p\u00e5 fr\u00e5gan om sin st\u00f6rsta svaghet \u2014 ett tecken p\u00e5 att hon noggrant bearbetade informationen innan hon svarade.", case_study_cloze: "L\u00e4karen r\u00f6rde vid sin ____ med fingertopparna medan han utv\u00e4rderade provresultaten, ett tecken p\u00e5 att han v\u00e4gde informationen." } },
      { concept: "CHIN CRADLING", definition: "Placing one's chin on the palm of the hand, coupled with relaxation of the facial muscles, suggests boredom. But in a law enforcement context, it might signal a range of possibilities, depending on the circumstances. In a forensic setting, I have seen the guilty strike this pose while sitting in a room alone as a form of perception management, to make authorities think they are so innocent, they are practically bored.", category: "body-language-extracted", real_world_scenario: "In the interrogation room, the suspect cradled his chin in his palm with relaxed facial muscles, looking thoroughly bored \u2014 but the detective knew the pose could be a calculated performance of innocence rather than genuine boredom.", case_study_cloze: "With his chin ____ in his palm and his facial muscles relaxed, the student's boredom during the lecture was obvious.", sv: { concept: "Hakan i handflatan", definition: "Att vila hakan p\u00e5 handflatan, i kombination med avslappnade ansiktsmuskler, tyder p\u00e5 uttr\u00e5kning. Men i en brottsbek\u00e4mpande kontext kan det signalera en rad m\u00f6jligheter beroende p\u00e5 omst\u00e4ndigheterna. I en kriminalteknisk milj\u00f6 har jag sett skyldiga inta denna pose n\u00e4r de sitter ensamma i ett rum som en form av perceptionsstyrning, f\u00f6r att f\u00e5 myndigheterna att tro att de \u00e4r s\u00e5 oskyldiga att de i princip \u00e4r uttr\u00e5kade.", real_world_scenario: "I f\u00f6rh\u00f6rsrummet vilade den misst\u00e4nkte hakan i handflatan med avslappnade ansiktsmuskler och s\u00e5g fullst\u00e4ndigt uttr\u00e5kad ut \u2014 men f\u00f6rh\u00f6rsledaren visste att posen kunde vara ett kalkylerat spel p\u00e5 oskuld snarare \u00e4n genuin uttr\u00e5kning.", case_study_cloze: "Med hakan ____ i handflatan och avslappnade ansiktsmuskler var studentens uttr\u00e5kning under f\u00f6rel\u00e4sningen uppenbar." } },
      { concept: "ANGRY CHIN PERCHING", definition: "This chin perch is performed by placing the chin on the knuckles of the fists, while the elbows are wide and resting on a table as the person stares into the distance or at a computer screen. Usually the forehead is furrowed or the eyes are narrowed or squinting, as a result of something difficult they are pondering or momentary anger. When you see someone posed like this, it is wise to not interrupt.", category: "body-language-extracted", real_world_scenario: "At his desk, the analyst perched his chin on his knuckles with his elbows spread wide on the table, staring at the flawed spreadsheet with narrowed eyes \u2014 his colleague wisely chose not to interrupt.", case_study_cloze: "With his chin perched on his ____ and his elbows wide on the table, the analyst's narrowed eyes showed he was pondering something difficult \u2014 a moment not to interrupt.", sv: { concept: "Hakan p\u00e5 knogarna", definition: "Denna hakposition utf\u00f6rs genom att man vilar hakan p\u00e5 knogarna av knutna h\u00e4nder, medan armb\u00e5garna \u00e4r brett utplacerade p\u00e5 ett bord och personen stirrar ut i fj\u00e4rran eller p\u00e5 en datorsk\u00e4rm. Vanligtvis \u00e4r pannan rynkad eller \u00f6gonen smalare eller kisande, som ett resultat av n\u00e5got sv\u00e5rt man grunnar p\u00e5 eller tillf\u00e4llig ilska. N\u00e4r du ser n\u00e5gon i denna st\u00e4llning \u00e4r det klokt att inte avbryta.", real_world_scenario: "Vid sitt skrivbord vilade analytikern hakan p\u00e5 knogarna med armb\u00e5garna brett utplacerade p\u00e5 bordet och stirrade med smala \u00f6gon p\u00e5 det bristf\u00e4lliga kalkylbladet \u2014 kollegan valde klokt nog att inte avbryta.", case_study_cloze: "Med hakan p\u00e5 ____ och armb\u00e5garna brett p\u00e5 bordet visade analytikerns smala \u00f6gon att han grunnade p\u00e5 n\u00e5got sv\u00e5rt \u2014 ett tillf\u00e4lle att inte avbryta." } },
      { concept: "BEARD/MUSTACHE STROKING", definition: "Stroking a mustache or a beard can be highly effective for pacifying stress. As with any repetitive behavior, ignore it if you see it too often, as some people with facial hair do this compulsively. If you see it occur suddenly for the first time or it increases after a topic is mentioned, perhaps the person has an issue. Cultural context must also be taken into account; for instance, beard stroking is common among many men from the Middle East as they pass the time talking. Note that many men with beards find it soothing to stroke their beards as they pass the time of day.", category: "body-language-extracted", real_world_scenario: "In the dealership, the customer began stroking his beard the moment the salesman mentioned the additional warranty fee \u2014 the sudden increase in the gesture suggested the subject caused him stress.", case_study_cloze: "When the topic of the overdue invoice came up, the client began ____ his beard, a sign the subject was causing him stress.", sv: { concept: "Sk\u00e4gg-/mustaschstrykning", definition: "Att stryka \u00f6ver en mustasch eller ett sk\u00e4gg kan vara mycket effektivt f\u00f6r att lugna stress. Som med alla repetitiva beteenden b\u00f6r du ignorera det om du ser det f\u00f6r ofta, eftersom vissa m\u00e4nniskor med ansiktsh\u00e5r g\u00f6r det tv\u00e5ngsm\u00e4ssigt. Om det pl\u00f6tsligt sker f\u00f6r f\u00f6rsta g\u00e5ngen eller \u00f6kar efter att ett \u00e4mne n\u00e4mnts kan personen ha ett problem. Kulturell kontext m\u00e5ste ocks\u00e5 beaktas; till exempel \u00e4r sk\u00e4ggstrykning vanligt bland m\u00e5nga m\u00e4n fr\u00e5n Mellan\u00f6stern n\u00e4r de sm\u00e5pratar. Notera att m\u00e5nga sk\u00e4ggiga m\u00e4n finner det lugnande att stryka sk\u00e4gget n\u00e4r de f\u00f6rdriver tiden.", real_world_scenario: "P\u00e5 bilfirman b\u00f6rjade kunden stryka sig \u00f6ver sk\u00e4gget i samma \u00f6gonblick som s\u00e4ljaren n\u00e4mnde avgiften f\u00f6r till\u00e4ggsgarantin \u2014 den pl\u00f6tsliga \u00f6kningen av gesten tydde p\u00e5 att \u00e4mnet orsakade honom stress.", case_study_cloze: "N\u00e4r \u00e4mnet f\u00f6r den obetalda fakturan kom upp b\u00f6rjade kunden ____ p\u00e5 sk\u00e4gget, ett tecken p\u00e5 att \u00e4mnet orsakade honom stress." } },
      { concept: "CHIN DIMPLING", definition: "When people are stressed, experiencing emotional turmoil, or about to cry, their chin will dimple. This is true for even the most stoic of individuals.", category: "body-language-extracted", real_world_scenario: "In the counselor's office, the boy's chin dimpled as he described the bullying, even though he fought to keep a stoic face \u2014 the dimpling revealed how close he was to tears.", case_study_cloze: "As she recounted the breakup, her chin ____ even though she fought to stay composed, revealing the emotional turmoil beneath.", sv: { concept: "Hakgroppning", definition: "N\u00e4r m\u00e4nniskor \u00e4r stressade, genomg\u00e5r k\u00e4nslom\u00e4ssig turbulens eller \u00e4r p\u00e5 v\u00e4g att gr\u00e5ta, f\u00e5r hakan en grop. Detta g\u00e4ller \u00e4ven de mest stoiska av individer.", real_world_scenario: "P\u00e5 kuratorns mottagning fick pojkens haka en grop n\u00e4r han beskrev mobbningen, trots att han k\u00e4mpade f\u00f6r att h\u00e5lla masken \u2014 gropen avsl\u00f6jade hur n\u00e4ra gr\u00e5ten han var.", case_study_cloze: "N\u00e4r hon ber\u00e4ttade om uppbrottet fick hennes haka en ____ trots att hon k\u00e4mpade f\u00f6r att vara samlad, vilket avsl\u00f6jade den k\u00e4nslom\u00e4ssiga turbulensen d\u00e4r under." } },
      { concept: "CHIN TO SHOULDER", definition: "We often see this with people who are embarrassed or emotionally vulnerable. They will, in a very childlike manner, place their chin against one shoulder, looking demure. You should especially note when someone does this while answering a question. It usually means the person has great difficulty discussing a subject, perhaps because she possesses knowledge she does not wish to reveal.", category: "body-language-extracted", real_world_scenario: "Asked where her brother was that night, the young woman pressed her chin against her shoulder in a childlike, demure way \u2014 the posture suggested she knew more than she wanted to reveal.", case_study_cloze: "Pressing her ____ against her shoulder as she answered the question, the employee looked demure, a sign the topic was difficult for her to discuss.", sv: { concept: "Hakan mot axeln", definition: "Vi ser ofta detta hos m\u00e4nniskor som \u00e4r generade eller k\u00e4nslom\u00e4ssigt s\u00e5rbara. De l\u00e4gger, p\u00e5 ett mycket barnsligt s\u00e4tt, hakan mot ena axeln och ser blyga ut. Du b\u00f6r s\u00e4rskilt notera n\u00e4r n\u00e5gon g\u00f6r detta medan de svarar p\u00e5 en fr\u00e5ga. Det brukar inneb\u00e4ra att personen har stora sv\u00e5righeter att diskutera ett \u00e4mne, kanske f\u00f6r att hon besitter kunskap hon inte vill avsl\u00f6ja.", real_world_scenario: "N\u00e4r den unga kvinnan fick fr\u00e5gan om var hennes bror var den natten lade hon hakan mot axeln p\u00e5 ett barnsligt, blygt vis \u2014 h\u00e5llningen antydde att hon visste mer \u00e4n hon ville avsl\u00f6ja.", case_study_cloze: "Med hakan pressad mot ____ medan hon svarade p\u00e5 fr\u00e5gan s\u00e5g medarbetaren blyg ut, ett tecken p\u00e5 att \u00e4mnet var sv\u00e5rt f\u00f6r henne att diskutera." } },
      { concept: "FACE AVOIDANCE", definition: "For a variety of reasons, we sometimes try to avoid face-to-face contact with others, even when we are in their immediate proximity. You see this in court between victim and suspect, or during contentious divorce proceedings. The avoidance becomes obvious by how quickly people will change their demeanor, where they are looking, and how stiff they become, not wishing to look about.", category: "body-language-extracted", real_world_scenario: "In the courthouse hallway, the suspect sat stiffly on the same bench as the victim, his eyes fixed on the floor and refusing to look around \u2014 his avoidance of her face was obvious to the officers.", case_study_cloze: "During the divorce mediation, the couple's stiff posture and averted eyes as they sat in each other's proximity was a textbook case of ____.", sv: { concept: "Ansiktsundvikande", definition: "Av olika sk\u00e4l f\u00f6rs\u00f6ker vi ibland undvika ansikte-mot-ansikte-kontakt med andra, \u00e4ven n\u00e4r vi befinner oss i deras omedelbara n\u00e4rhet. Du ser detta i r\u00e4tten mellan offer och misst\u00e4nkt, eller under bittra skilsm\u00e4ssoprocesser. Undvikandet blir tydligt genom hur snabbt m\u00e4nniskor \u00e4ndrar sitt s\u00e4tt, var de tittar och hur stela de blir, eftersom de inte vill se sig om.", real_world_scenario: "I r\u00e4ttshusets korridor satt den misst\u00e4nkte stelt p\u00e5 samma b\u00e4nk som offret, med blicken f\u00e4st i golvet och utan att vilja se sig om \u2014 hans undvikande av hennes ansikte var uppenbart f\u00f6r poliserna.", case_study_cloze: "Under skilsm\u00e4ssof\u00f6rlikningen var parets stela h\u00e5llning och bortv\u00e4nda blick n\u00e4r de satt i varandras n\u00e4rhet ett typexempel p\u00e5 ____." } },
      { concept: "FACE BLOCKING", definition: "This behavior is noted by the person placing their elbows on top of a table and holding their hands together in front of their face.", category: "body-language-extracted", real_world_scenario: "In the performance review, the manager placed his elbows on the desk and held his hands together in front of his face as the conversation turned to the failed project \u2014 a posture that blocked his face from view.", case_study_cloze: "Sitting across from the interviewer, she placed her elbows on the table and held her hands together in front of her ____, a posture the observer noted.", sv: { concept: "Ansiktsblockering", definition: "Detta beteende k\u00e4nnetecknas av att personen placerar armb\u00e5garna ovanp\u00e5 ett bord och h\u00e5ller h\u00e4nderna tillsammans framf\u00f6r ansiktet.", real_world_scenario: "Under medarbetarsamtalet lade chefen armb\u00e5garna p\u00e5 skrivbordet och h\u00f6ll h\u00e4nderna tillsammans framf\u00f6r ansiktet n\u00e4r samtalet kom in p\u00e5 det misslyckade projektet \u2014 en h\u00e5llning som blockerade ansiktet fr\u00e5n insyn.", case_study_cloze: "Sittande mittemot intervjuaren lade hon armb\u00e5garna p\u00e5 bordet och h\u00f6ll h\u00e4nderna tillsammans framf\u00f6r sitt ____, en h\u00e5llning som observat\u00f6ren noterade." } },
      { concept: "FACE SHIELDING", definition: "Around the world, people will cup their hands over their face or use objects to hide their face, usually as a result of shame, embarrassment, fear, anxiety, or apprehension. Oftentimes when arrestees are being led to the waiting police car, they will use articles of clothing to face shield.", category: "body-language-extracted", real_world_scenario: "As the officers led the handcuffed man toward the waiting police car, he lifted his jacket to shield his face from the camera crews outside the station.", case_study_cloze: "Hiding her face behind her hands, the woman's ____ revealed her deep embarrassment after tripping in front of the crowd.", sv: { concept: "Ansiktsskyddande", definition: "\u00d6ver hela v\u00e4rlden kupar m\u00e4nniskor h\u00e4nderna \u00f6ver ansiktet eller anv\u00e4nder f\u00f6rem\u00e5l f\u00f6r att d\u00f6lja det, vanligtvis p\u00e5 grund av skam, f\u00f6rl\u00e4genhet, r\u00e4dsla, \u00e5ngest eller oro. N\u00e4r gripna leds till den v\u00e4ntande polisbilen anv\u00e4nder de ofta kl\u00e4desplagg f\u00f6r att skydda ansiktet.", real_world_scenario: "N\u00e4r poliserna ledde den handf\u00e4ngslade mannen mot den v\u00e4ntande polisbilen lyfte han jackan f\u00f6r att skydda ansiktet fr\u00e5n kamerateamen utanf\u00f6r stationen.", case_study_cloze: "Med h\u00e4nderna kupade \u00f6ver ansiktet avsl\u00f6jade kvinnans ____ hennes djupa f\u00f6rl\u00e4genhet efter att ha snubblat inf\u00f6r publiken." } },
      { concept: "FACIAL INCONGRUENCE", definition: "Incongruence between what a person says and how it is reflected in the face is not uncommon. People might say one thing, but their face is already telegraphing another. During an exchange of pleasantries, a very tense face or a face displaying dislike or discomfort betrays true sentiments, though the person might be obliged to say something nice or offer a polite greeting.", category: "body-language-extracted", real_world_scenario: "At the reception, the host smiled and said, 'Wonderful to see you again,' yet his tense face and tight mouth betrayed real displeasure \u2014 a clear facial incongruence.", case_study_cloze: "The client said he was happy with the proposal, but his tense face told a different story \u2014 a clear ____ between his words and his expression.", sv: { concept: "Ansiktsinkongruens", definition: "Inkongruens mellan vad en person s\u00e4ger och hur det \u00e5terspeglas i ansiktet \u00e4r inte ovanligt. M\u00e4nniskor kan s\u00e4ga en sak, men ansiktet signalerar redan en annan. Under ett artigt sm\u00e5prat kan ett mycket sp\u00e4nt ansikte eller ett ansikte som visar ogillande eller obehag avsl\u00f6ja de verkliga k\u00e4nslorna, \u00e4ven om personen \u00e4r tvungen att s\u00e4ga n\u00e5got trevligt eller h\u00e4lsa artigt.", real_world_scenario: "P\u00e5 mottagningen log v\u00e4rden och sa 'S\u00e5 trevligt att se dig igen', men hans sp\u00e4nda ansikte och sammanpressade mun avsl\u00f6jade verkligt ogillande \u2014 en tydlig ansiktsinkongruens.", case_study_cloze: "Kunden sa att han var n\u00f6jd med f\u00f6rslaget, men hans sp\u00e4nda ansikte ber\u00e4ttade en annan historia \u2014 en tydlig ____ mellan orden och minspelen." } },
      { concept: "ODD FACE IN CROWD", definition: "In dealing with the United States Secret Service on protection details as well as various private-sector companies over the years, I have learned that in a crowd it is often worth trusting our intuition about the odd face that stands out. By that I mean the one that looks angry when everyone else is happy, or that seems transfixed and rigid when the rest of the crowd is displaying a variety of moods. Airline personnel tell me that in a long queue at the airport, it is the odd emotionally charged face, the one that is not fitting in with the others, that often causes the most problems at the counter.", category: "body-language-extracted", real_world_scenario: "In the airport security line, an agent noticed a man whose face was rigid and transfixed while everyone around him chatted and smiled \u2014 the odd face in the crowd made the agent watch him closely.", case_study_cloze: "In the festive concert crowd, the one face that looked angry while everyone else was happy was the ____ that the guard's intuition told him to watch.", sv: { concept: "Avvikande ansikte i folkmassan", definition: "I mitt arbete med USA:s Secret Service p\u00e5 skyddsuppdrag, liksom med olika f\u00f6retag genom \u00e5ren, har jag l\u00e4rt mig att det i en folkmassa ofta l\u00f6nar sig att lita p\u00e5 intuitionen n\u00e4r det g\u00e4ller det avvikande ansiktet som sticker ut. Jag menar den som ser arg ut n\u00e4r alla andra \u00e4r glada, eller som verkar fixerad och stel n\u00e4r resten av folkmassan visar en rad olika st\u00e4mningar. Flygpersonal har ber\u00e4ttat f\u00f6r mig att det i en l\u00e5ng k\u00f6 p\u00e5 flygplatsen ofta \u00e4r det avvikande, k\u00e4nslom\u00e4ssigt laddade ansiktet \u2014 det som inte passar in med de andra \u2014 som orsakar flest problem vid disken.", real_world_scenario: "I s\u00e4kerhetsk\u00f6n p\u00e5 flygplatsen lade en agent m\u00e4rke till en man vars ansikte var stelt och fixerat medan alla runt omkring sm\u00e5pratade och log \u2014 det avvikande ansiktet i folkmassan fick agenten att h\u00e5lla ett \u00f6ga p\u00e5 honom.", case_study_cloze: "I den festliga konsertpubliken var det enda ansikte som s\u00e5g argt ut medan alla andra var glada det ____ som vakten intuitionellt h\u00f6ll koll p\u00e5." } },
      { concept: "FACE TOUCHING", definition: "Face touching serves a multitude of purposes. It can attract others-we often see models touching their face on magazine covers. Or it can help us relax by stimulating the myriad of nerves on the face. Context is key.", category: "body-language-extracted", real_world_scenario: "During the live broadcast, the news anchor touched her cheek lightly with her fingertips between segments \u2014 a gesture that calmed her nerves while the camera, like a magazine cover, drew attention to her face.", case_study_cloze: "The model's light ____ on the magazine cover was designed to attract attention, while for others the same gesture simply calms the nerves.", sv: { concept: "Ansiktsber\u00f6ring", definition: "Ansiktsber\u00f6ring tj\u00e4nar m\u00e5nga syften. Det kan dra till sig uppm\u00e4rksamhet \u2014 vi ser ofta modeller r\u00f6ra vid ansiktet p\u00e5 tidningsomslag. Eller s\u00e5 kan det hj\u00e4lpa oss att slappna av genom att stimulera de m\u00e5nga nerverna i ansiktet. Sammanhanget \u00e4r avg\u00f6rande.", real_world_scenario: "Under direkts\u00e4ndningen r\u00f6rde nyhetsankaret l\u00e4tt vid kinden med fingertopparna mellan inslagen \u2014 en gest som lugnade nerverna medan kameran, precis som ett tidningsomslag, riktade uppm\u00e4rksamheten mot ansiktet.", case_study_cloze: "Modellens l\u00e4tta ____ p\u00e5 omslaget var utformad f\u00f6r att dra till sig uppm\u00e4rksamhet, medan samma gest f\u00f6r andra helt enkelt lugnar nerverna." } },
      { concept: "NECK TOUCHING", definition: "Beyond scratching an itch, neck touching serves as an excellent indicator of insecurities, apprehension, anxiety, worries, or issues. However slightly, we tend to touch our neck when something bothers us or we are concerned. Neck touching, in all its forms is often overlooked, and yet, it is one of the most accurate when it comes to revealing that something is bothering us.", category: "body-language-extracted", real_world_scenario: "In the negotiation, the buyer touched his neck as the seller quoted the final price \u2014 a small gesture that revealed his concern and one of the most accurate signs that something was bothering him.", case_study_cloze: "When the subject of layoffs came up, the manager's hand moved to his ____, a reliable sign that the topic made him uneasy.", sv: { concept: "Halsber\u00f6ring", definition: "Ut\u00f6ver att klia en kl\u00e5da \u00e4r halsber\u00f6ring en utm\u00e4rkt indikator p\u00e5 os\u00e4kerhet, oro, \u00e5ngest, bekymmer eller problem. Hur l\u00e4tt det \u00e4n \u00e4r tenderar vi att r\u00f6ra vid halsen n\u00e4r n\u00e5got st\u00f6r oss eller n\u00e4r vi \u00e4r bekymrade. Halsber\u00f6ring i alla dess former f\u00f6rbises ofta, och \u00e4nd\u00e5 \u00e4r den en av de mest tillf\u00f6rlitliga signalerna p\u00e5 att n\u00e5got st\u00f6r oss.", real_world_scenario: "I f\u00f6rhandlingen r\u00f6rde k\u00f6paren vid halsen n\u00e4r s\u00e4ljaren angav slutpriset \u2014 en liten gest som avsl\u00f6jade hans oro och som \u00e4r en av de mest tillf\u00f6rlitliga signalerna p\u00e5 att n\u00e5got st\u00f6r honom.", case_study_cloze: "N\u00e4r \u00e4mnet upps\u00e4gningar kom upp f\u00f6rde chefen handen till sin ____, ett tillf\u00f6rlitligt tecken p\u00e5 att \u00e4mnet gjorde honom illa till mods." } },
      { concept: "COVERING OF SUPRASTERNAL NOTCH", definition: "Touching or covering of the \\\"neck dimple\\\" or suprasternal notch (the indented area of the neck below the Adam's apple and just above the upper chest) indicates concern, issues, worries, insecurities, or fear. Men tend to grab their neck or throat robustly or cover this area with their full hand as they adjust their tie or grab their collar. Women touch this area more frequently than men, and they tend to do so more lightly, with the tips of their fingers. Whether done delicately or strongly, covering the weakest point of the body signifies that something is", category: "body-language-extracted", real_world_scenario: "In the manager's office, the junior employee covered her suprasternal notch \u2014 the dimple below her throat \u2014 with her fingertips as she explained the missed deadline, betraying her fear.", case_study_cloze: "As the athlete discussed her injury, she covered her ____ notch with her full hand, a sign of deep concern about the upcoming match.", sv: { concept: "T\u00e4ckande av halsgropen", definition: "Att r\u00f6ra vid eller t\u00e4cka 'halsgropen' eller suprasternala gropen (den indragna delen av halsen nedanf\u00f6r adams\u00e4pplet och strax ovanf\u00f6r \u00f6vre delen av br\u00f6stkorgen) indikerar oro, problem, bekymmer, os\u00e4kerhet eller r\u00e4dsla. M\u00e4n tenderar att gripa tag i halsen eller svalget kraftfullt eller t\u00e4cka detta omr\u00e5de med hela handen medan de justerar slipsen eller tar tag i kragen. Kvinnor r\u00f6r vid detta omr\u00e5de oftare \u00e4n m\u00e4n, och de g\u00f6r det l\u00e4ttare, med fingertopparna. Oavsett om det g\u00f6rs f\u00f6rsiktigt eller kraftfullt, signalerar t\u00e4ckandet av kroppens svagaste punkt att n\u00e5got \u00e4r fel.", real_world_scenario: "P\u00e5 chefens kontor t\u00e4ckte den yngre medarbetaren sin suprasternala grop \u2014 gropen nedanf\u00f6r halsen \u2014 med fingertopparna medan hon f\u00f6rklarade den missade deadline, vilket avsl\u00f6jade hennes r\u00e4dsla.", case_study_cloze: "N\u00e4r idrottaren pratade om sin skada t\u00e4ckte hon sin ____ grop med hela handen, ett tecken p\u00e5 djup oro inf\u00f6r den kommande matchen." } },
      { concept: "PLAYING WITH NECKLACE", definition: "Playing with a necklace serves the same purpose for women as covering the neck dimple with the hand. It protects a vulnerable area and relieves stress through repetitive movement.", category: "body-language-extracted", real_world_scenario: "During the tense call with the bank, the aunt twisted her necklace between her fingers \u2014 like covering her neck dimple, the repetitive movement protected the vulnerable area and relieved her stress.", case_study_cloze: "During the difficult phone call, she played with her ____, using the repetitive movement to relieve the stress of the conversation.", sv: { concept: "Leka med halsbandet", definition: "Att leka med ett halsband tj\u00e4nar samma syfte f\u00f6r kvinnor som att t\u00e4cka halsgropen med handen. Det skyddar ett s\u00e5rbart omr\u00e5de och lindrar stress genom upprepad r\u00f6relse.", real_world_scenario: "Under det sp\u00e4nda samtalet med banken snurrade mostern p\u00e5 sitt halsband mellan fingrarna \u2014 precis som att t\u00e4cka halsgropen skyddade den upprepade r\u00f6relsen ett s\u00e5rbart omr\u00e5de och lindrade stressen.", case_study_cloze: "Under det sv\u00e5ra telefonsamtalet lekte hon med sitt ____ och anv\u00e4nde den upprepade r\u00f6relsen f\u00f6r att lindra stressen i samtalet." } },
      { concept: "PLAYING WITH SHIRT COLLAR", definition: "Touching or playing with the front shirt collar serves to pacify or relieve stress in three ways: by covering the neck area; as a tactile repetitive behavior; and by moving clothing to ventilate the skin underneath.", category: "body-language-extracted", real_world_scenario: "In the interview room, the candidate played with his shirt collar repeatedly as the interviewer pressed him on the gap in his CV \u2014 the gesture covered his neck, soothed his nerves and ventilated his warming skin.", case_study_cloze: "When the boss asked about the missing report, he began playing with his ____, a pacifying gesture that covered his neck and relieved his stress.", sv: { concept: "Leka med skjortkragen", definition: "Att r\u00f6ra vid eller leka med den fr\u00e4mre skjortkragen tj\u00e4nar till att lugna eller lindra stress p\u00e5 tre s\u00e4tt: genom att t\u00e4cka halsomr\u00e5det; som ett taktilt, repetitivt beteende; och genom att flytta kl\u00e4derna s\u00e5 att huden under ventileras.", real_world_scenario: "I intervjurummet lekte kandidaten upprepat med skjortkragen n\u00e4r intervjuaren pressade honom om luckan i CV:t \u2014 gesten t\u00e4ckte halsen, lugnade nerverna och ventilerade den uppv\u00e4rmda huden.", case_study_cloze: "N\u00e4r chefen fr\u00e5gade om den f\u00f6rsvunna rapporten b\u00f6rjade han leka med sin ____, en lugnande gest som t\u00e4ckte halsen och lindrade stressen." } },
      { concept: "NECK MASSAGING", definition: "People often massage the sides or back of their neck to relieve stress. It is easy for many people to dismiss this sort of behavior, but the fact is that people usually only do it when something is bothering them.", category: "body-language-extracted", real_world_scenario: "After the tense meeting with the auditors, the accountant massaged the back of his neck as he walked back to his desk \u2014 a behavior people usually only perform when something is bothering them.", case_study_cloze: "She massaged the sides of her ____ while reading the lawyer's letter, a telltale sign the news was stressful.", sv: { concept: "Halsmassage", definition: "M\u00e4nniskor masserar ofta sidorna eller baksidan av halsen f\u00f6r att lindra stress. Det \u00e4r l\u00e4tt att avf\u00e4rda den h\u00e4r typen av beteende, men faktum \u00e4r att m\u00e4nniskor vanligtvis bara g\u00f6r det n\u00e4r n\u00e5got st\u00f6r dem.", real_world_scenario: "Efter det sp\u00e4nda m\u00f6tet med revisorerna masserade ekonomen baksidan av halsen n\u00e4r han gick tillbaka till sitt skrivbord \u2014 ett beteende som m\u00e4nniskor vanligtvis bara g\u00f6r n\u00e4r n\u00e5got st\u00f6r dem.", case_study_cloze: "Hon masserade sidorna av sin ____ medan hon l\u00e4ste advokatens brev, ett avsl\u00f6jande tecken p\u00e5 att nyheterna var stressande." } },
      { concept: "MASSAGING VAGUS NERVE", definition: "The vagus (Latin for \\\"wandering\\\") nerve connects the brain to our major organs, including the heart. Under stress, you might find yourself massaging the side of the neck, near where you check your pulse. There is a reason for this: stimulation of the vagus nerve results in the release of acetylcholine, a neurotransmitter that in turn sends signals to the heart, specifically the atrioventricular node, which causes your heart rate to go down.", category: "body-language-extracted", real_world_scenario: "Before his court presentation, the attorney caught himself massaging the side of his neck near his pulse point \u2014 the stimulation of the vagus nerve was slowing his racing heart.", case_study_cloze: "Under stress, people may massage the side of the neck near the pulse, stimulating the ____ nerve, which sends calming signals to the heart.", sv: { concept: "Massera vagusnerven", definition: "Vagusnerven (latin f\u00f6r 'vandrande') f\u00f6rbinder hj\u00e4rnan med v\u00e5ra viktigaste organ, inklusive hj\u00e4rtat. Under stress kan du m\u00e4rka att du masserar sidan av halsen, n\u00e4ra d\u00e4r du k\u00e4nner pulsen. Det finns en anledning till detta: stimulering av vagusnerven leder till fris\u00e4ttning av acetylkolin, en signalsubstans som i sin tur skickar signaler till hj\u00e4rtat, specifikt till atrioventrikul\u00e4rknutan, vilket g\u00f6r att hj\u00e4rtfrekvensen sjunker.", real_world_scenario: "Innan sin framst\u00e4llan i r\u00e4tten kom advokaten p\u00e5 sig sj\u00e4lv med att massera sidan av halsen n\u00e4ra pulspunkten \u2014 stimuleringen av vagusnerven s\u00e4nkte hans rusande hj\u00e4rta.", case_study_cloze: "Under stress kan m\u00e4nniskor massera sidan av halsen n\u00e4ra pulsen och d\u00e4rmed stimulera ____ nerven, som skickar lugnande signaler till hj\u00e4rtat." } },
      { concept: "SKIN PULLING", definition: "Pulling at the fleshy area of the neck under the chin serves to calm some men. Sometimes, under great stress, the pulling becomes extreme. It is rare to see in women. I have seen men under stress pull with such vigor, it makes their skin blanch.", category: "body-language-extracted", real_world_scenario: "As the homeowner explained the water damage to the inspector, he repeatedly pulled at the fleshy skin under his chin \u2014 a rare, calming gesture some men use under stress.", case_study_cloze: "In the meeting, he pulled at the ____ under his chin with such vigor that his skin blanched \u2014 a rare calming gesture seen in some men under great stress.", sv: { concept: "Huddragning", definition: "Att dra i det k\u00f6ttiga omr\u00e5det p\u00e5 halsen under hakan tj\u00e4nar till att lugna vissa m\u00e4n. Ibland, under stor stress, blir dragandet extremt. Det \u00e4r ovanligt att se hos kvinnor. Jag har sett stressade m\u00e4n dra med s\u00e5dan kraft att huden blir blek.", real_world_scenario: "Medan hus\u00e4garen f\u00f6rklarade vattenskadan f\u00f6r besiktningsmannen drog han upprepat i den k\u00f6ttiga huden under hakan \u2014 en ovanlig, lugnande gest som vissa m\u00e4n anv\u00e4nder under stress.", case_study_cloze: "P\u00e5 m\u00f6tet drog han i ____ under hakan med s\u00e5dan kraft att huden blev blek \u2014 en ovanlig lugnande gest hos vissa m\u00e4n under stor stress." } },
      { concept: "VENTILATING NECK", definition: "When we are under stress, our skin warms, a physiological reaction controlled by our autonomic nervous system and over which we have little control. This often takes place in less than 1/250th", category: "body-language-extracted", real_world_scenario: "In the crowded exam hall, a student tugged at her blouse collar and fanned her neck as the stress built \u2014 her warming skin, controlled by her autonomic nervous system, made her seek air.", case_study_cloze: "As the witness grew anxious under questioning, she pulled at her collar to ____ her neck, which had warmed from stress.", sv: { concept: "Ventilera halsen", definition: "N\u00e4r vi \u00e4r stressade v\u00e4rms v\u00e5r hud upp, en fysiologisk reaktion som styrs av v\u00e5rt autonoma nervsystem och som vi har liten kontroll \u00f6ver. Detta sker ofta p\u00e5 mindre \u00e4n 1/250-del.", real_world_scenario: "I den fullsatta tentasalen ryckte en student i blusens krage och fl\u00e4ktade halsen n\u00e4r stressen steg \u2014 den uppv\u00e4rmda huden, styrd av det autonoma nervsystemet, fick henne att s\u00f6ka luft.", case_study_cloze: "N\u00e4r vittnet blev alltmer oroligt under f\u00f6rh\u00f6ret ryckte hon i kragen f\u00f6r att ____ halsen, som blivit varm av stressen." } },
      { concept: "NECK VEINS PULSING", definition: "Noticeable pulsing of veins in the neck indicates stress or anxiety. When a person is fearful or angry, the pulsing can be very noticeable in some.", category: "body-language-extracted", real_world_scenario: "In the locker room before the final, the goalkeeper's neck veins pulsed visibly as the coach reviewed the opponents' tactics \u2014 his anxiety was written on his neck.", case_study_cloze: "When the CEO heard the takeover rumor, the pulsing of the veins in his ____ revealed his anxiety to the board members watching him.", sv: { concept: "Pulserande halsvener", definition: "M\u00e4rkbart pulserande vener i halsen tyder p\u00e5 stress eller \u00e5ngest. N\u00e4r en person \u00e4r r\u00e4dd eller arg kan pulserandet vara mycket p\u00e5tagligt hos vissa.", real_world_scenario: "I omkl\u00e4dningsrummet f\u00f6re finalen pulserade m\u00e5lvaktens halsvener synligt n\u00e4r coachen gick igenom motst\u00e5ndarnas taktik \u2014 hans \u00e5ngest stod skriven i halsen.", case_study_cloze: "N\u00e4r vd:n h\u00f6rde ryktena om uppk\u00f6pet avsl\u00f6jade pulseringen i venerna i hans ____ hans \u00e5ngest f\u00f6r styrelsemedlemmarna som iakttog honom." } },
      { concept: "HARD SWALLOWING", definition: "A hard swallow is highly visible and sometimes audible. It is a spontaneous reaction to something unsavory, dangerous, or extremely stressful, and a reliable indicator of distress. The muscles and ligaments that surround the throat tighten, which causes the Adam's apple to move energetically up and down.", category: "body-language-extracted", real_world_scenario: "When the detective placed the photograph on the table, the suspect swallowed hard, his Adam's apple bobbing energetically up and down \u2014 the audible swallow was a reliable sign of distress.", case_study_cloze: "Before answering the officer's question, the driver swallowed ____, his Adam's apple moving visibly up and down.", sv: { concept: "H\u00e5rd sv\u00e4ljning", definition: "En h\u00e5rd sv\u00e4ljning \u00e4r mycket synlig och ibland h\u00f6rbar. Det \u00e4r en spontan reaktion p\u00e5 n\u00e5got obehagligt, farligt eller extremt stressande och en tillf\u00f6rlitlig indikator p\u00e5 oro. Musklerna och ligamenten som omger svalget stramas \u00e5t, vilket f\u00e5r adams\u00e4pplet att r\u00f6ra sig energiskt upp och ner.", real_world_scenario: "N\u00e4r kriminalaren lade fram fotografiet p\u00e5 bordet svalde den misst\u00e4nkte h\u00e5rt och adams\u00e4pplet r\u00f6rde sig energiskt upp och ner \u2014 den h\u00f6rbara sv\u00e4ljningen var ett tillf\u00f6rlitligt tecken p\u00e5 oro.", case_study_cloze: "Innan f\u00f6raren svarade p\u00e5 polisens fr\u00e5ga svalde han ____ och adams\u00e4pplet r\u00f6rde sig synligt upp och ner." } },
      { concept: "NECK STRETCHING", definition: "Neck stretching or cracking in a circular motion is a stress reliever and pacifier. This is often seen when people are asked difficult questions they would rather not answer.", category: "body-language-extracted", real_world_scenario: "When the journalist asked about the failed acquisition, the CEO stretched and cracked his neck in a slow circular motion \u2014 a pacifier for a question he would rather not answer.", case_study_cloze: "Asked about his whereabouts on the night in question, he stretched his ____ in a circular motion, a stress reliever when facing questions he would rather avoid.", sv: { concept: "Nackstr\u00e4ckning", definition: "Att str\u00e4cka eller kn\u00e4cka nacken i en cirkul\u00e4r r\u00f6relse \u00e4r en stresslindrare och lugnande gest. Detta ses ofta n\u00e4r m\u00e4nniskor f\u00e5r sv\u00e5ra fr\u00e5gor som de helst inte vill svara p\u00e5.", real_world_scenario: "N\u00e4r journalisten fr\u00e5gade om den misslyckade upphandlingen str\u00e4ckte vd:n p\u00e5 nacken med l\u00e5ngsamma cirkul\u00e4ra r\u00f6relser \u2014 en lugnande gest inf\u00f6r en fr\u00e5ga han helst inte ville besvara.", case_study_cloze: "P\u00e5 fr\u00e5gan om var han befunnit sig den aktuella natten str\u00e4ckte han p\u00e5 ____ i en cirkul\u00e4r r\u00f6relse, en stresslindrare n\u00e4r man f\u00e5r fr\u00e5gor man helst undviker." } },
      { concept: "NECK EXPOSURE", definition: "The canting of the head to the side, exposing the side of the neck, is one of the most used yet least understood body-language behaviors. We instinctively tilt our head when we hold or even see a newborn baby-something the child recognizes and rewards over time with a smile and relaxed face. As we get older, the head tilt features in courtship behavior, as we stare into a lover's eyes with our head canted to the side, exposing our vulnerable neck. In personal and professional relationships this behavior also signifies that a person is listening and interested. It is a powerfully disarming behavior-extremely useful during a confrontation. Coupled with a smile, this is one of the most effective ways to win others over.", category: "body-language-extracted", real_world_scenario: "At the cafe on their third date, she tilted her head to the side as she smiled at him, exposing the vulnerable side of her neck \u2014 the disarming gesture showed she felt safe and was genuinely interested.", case_study_cloze: "As she listened to her friend, she canted her head to the side, ____ the vulnerable side of her neck, a sign of trust and interest.", sv: { concept: "Halsexponering", definition: "Att luta huvudet \u00e5t sidan och blotta sidan av halsen \u00e4r ett av de mest anv\u00e4nda men minst f\u00f6rst\u00e5dda kroppsspr\u00e5ksbeteendena. Vi lutar instinktivt p\u00e5 huvudet n\u00e4r vi h\u00e5ller eller till och med ser ett nyf\u00f6tt barn \u2014 n\u00e5got som barnet k\u00e4nner igen och s\u00e5 sm\u00e5ningom bel\u00f6nar med ett leende och ett avslappnat ansikte. N\u00e4r vi blir \u00e4ldre \u00e4r huvudlutningen en del av uppvaktningen, n\u00e4r vi ser in i en \u00e4lskares \u00f6gon med huvudet lutat \u00e5t sidan och blottar v\u00e5r s\u00e5rbara hals. I personliga och professionella relationer signalerar detta beteende ocks\u00e5 att en person lyssnar och \u00e4r intresserad. Det \u00e4r en oerh\u00f6rt avv\u00e4pnande gest \u2014 ytterst anv\u00e4ndbar under en konfrontation. I kombination med ett leende \u00e4r detta ett av de mest effektiva s\u00e4tten att vinna andra f\u00f6r sig.", real_world_scenario: "P\u00e5 kaf\u00e9et under deras tredje dejt lutade hon huvudet \u00e5t sidan n\u00e4r hon log mot honom och blottade den s\u00e5rbara sidan av halsen \u2014 den avv\u00e4pnande gesten visade att hon k\u00e4nde sig trygg och var genuint intresserad.", case_study_cloze: "Medan hon lyssnade p\u00e5 sin v\u00e4ninna lutade hon huvudet \u00e5t sidan och ____ den s\u00e5rbara sidan av halsen, ett tecken p\u00e5 tillit och intresse." } },
      { concept: "RAISING ONE SHOULDER", definition: "One shoulder raised toward the ear as a person answers a question usually represents insecurity or doubt. In conjunction with other behaviors (hesitation in answering, arms drawing closer to the body), this is a good indication that the person lacks confidence in what he is saying. In negotiations, when one party raises a single shoulder in response to a query, such as \\\"Is that your best price? ,\\\" it generally signals there is room for negotiation. A one-shoulder-up answer suggests a lack of full commitment to what is being said.", category: "body-language-extracted", real_world_scenario: "In the car showroom, when the buyer asked 'Is that your best price?', the salesman raised one shoulder toward his ear as he answered \u2014 a one-shoulder-up response suggesting there was still room to negotiate.", case_study_cloze: "When asked if he was sure about his story, he raised a single ____ as he hesitated \u2014 a sign he lacked full confidence in what he was saying.", sv: { concept: "Lyfta ena axeln", definition: "En axel som h\u00f6js mot \u00f6rat n\u00e4r en person svarar p\u00e5 en fr\u00e5ga representerar vanligtvis os\u00e4kerhet eller tvivel. I kombination med andra beteenden (tvekan inf\u00f6r svaret, armarna som dras n\u00e4rmare kroppen) \u00e4r detta en bra indikation p\u00e5 att personen saknar tilltro till det han s\u00e4ger. I f\u00f6rhandlingar signalerar det generellt att det finns utrymme att f\u00f6rhandla n\u00e4r en part h\u00f6jer en enda axel som svar p\u00e5 en fr\u00e5ga som '\u00c4r det ditt b\u00e4sta pris?'. Ett enaxelsvar tyder p\u00e5 bristande fullt engagemang f\u00f6r det som s\u00e4gs.", real_world_scenario: "P\u00e5 bilfirman, n\u00e4r k\u00f6paren fr\u00e5gade '\u00c4r det ditt b\u00e4sta pris?', h\u00f6jde s\u00e4ljaren ena axeln mot \u00f6rat medan han svarade \u2014 ett enaxelsvar som antydde att det fortfarande fanns utrymme att f\u00f6rhandla.", case_study_cloze: "N\u00e4r han fick fr\u00e5gan om han var s\u00e4ker p\u00e5 sin historia h\u00f6jde han en enda ____ medan han tvekade \u2014 ett tecken p\u00e5 att han inte fullt trodde p\u00e5 det han sa." } },
      { concept: "SHOULDER INTEREST", definition: "The slow, intentional rise of a single shoulder, coupled with a head tilt toward the same shoulder while making direct eye contact, signifies a personal interest. We mostly see this in dating situations, usually in women as they eye someone they like.", category: "body-language-extracted", real_world_scenario: "Across the crowded bar, a woman slowly raised one shoulder and tilted her head toward it while holding eye contact with the man she found attractive \u2014 a classic signal of personal interest.", case_study_cloze: "She raised one shoulder slowly and tilted her head toward it while meeting his gaze, a gesture of personal ____ most often seen in dating situations.", sv: { concept: "Axelintresse", definition: "En l\u00e5ngsam, avsiktlig h\u00f6jning av en enda axel, i kombination med en huvudlutning mot samma axel och direkt \u00f6gonkontakt, signalerar personligt intresse. Vi ser detta oftast i dejting-sammanhang, vanligtvis hos kvinnor n\u00e4r de iakttar n\u00e5gon de gillar.", real_world_scenario: "P\u00e5 andra sidan den fullsatta baren h\u00f6jde en kvinna l\u00e5ngsamt ena axeln och lutade huvudet mot den medan hon h\u00f6ll \u00f6gonkontakt med mannen hon fann attraktiv \u2014 en klassisk signal p\u00e5 personligt intresse.", case_study_cloze: "Hon h\u00f6jde l\u00e5ngsamt ena axeln och lutade huvudet mot den medan hon m\u00f6tte hans blick, en gest av personligt ____ som oftast ses i dejting-sammanhang." } },
      { concept: "HOLDING SHOULDERS HIGH", definition: "When people raise and keep both shoulders", category: "body-language-extracted", real_world_scenario: "At the school gate, the shy new student walked into the playground with both shoulders raised and held high, looking small and anxious among the rushing children.", case_study_cloze: "Standing in front of the angry crowd, he held both ____ high in a protective posture, as if trying to shield himself.", sv: { concept: "H\u00e5lla axlarna h\u00f6gt", definition: "N\u00e4r m\u00e4nniskor h\u00f6jer och h\u00e5ller b\u00e5da axlarna", real_world_scenario: "Vid skolgrinden gick den blyga nya eleven in p\u00e5 skolg\u00e5rden med b\u00e5da axlarna h\u00f6jda och h\u00e5llna h\u00f6gt, liten och orolig bland de springande barnen.", case_study_cloze: "St\u00e5ende inf\u00f6r den arga folkmassan h\u00f6ll han b\u00e5da ____ h\u00f6gt i en skyddande st\u00e4llning, som om han f\u00f6rs\u00f6kte skydda sig." } },
      { concept: "QUICK SHOULDER SHRUGGING", definition: "When people are asked a question and don't know the answer, they often raise both shoulders quickly and prominently. The quick upward movement is a gravity-defying behavior and those are usually associated with positive feelings-in this case they really don't know. This tends to be more honest than a slow shoulder shrug (as they answer \\\"I don't know\\\") or a shrug of just one hesitating shoulder.", category: "body-language-extracted", real_world_scenario: "When the teacher asked who had left the window open, the student quickly raised both shoulders in a fast shrug \u2014 the quick, gravity-defying movement signaled he genuinely did not know.", case_study_cloze: "Asked where the car keys were, he quickly raised both shoulders in a fast ____, a more honest gesture than the slow, hesitating version.", sv: { concept: "Snabba axelryckningar", definition: "N\u00e4r m\u00e4nniskor f\u00e5r en fr\u00e5ga och inte vet svaret h\u00f6jer de ofta b\u00e5da axlarna snabbt och tydligt. Den snabba upp\u00e5tr\u00f6relsen \u00e4r ett gravitationstrotsande beteende, och s\u00e5dana brukar f\u00f6rknippas med positiva k\u00e4nslor \u2014 i det h\u00e4r fallet vet de verkligen inte. Detta tenderar att vara \u00e4rligare \u00e4n en l\u00e5ngsam axelryckning (som n\u00e4r de svarar 'Jag vet inte') eller en ryckning med bara en tveksam axel.", real_world_scenario: "N\u00e4r l\u00e4raren fr\u00e5gade vem som hade l\u00e4mnat f\u00f6nstret \u00f6ppet h\u00f6jde eleven snabbt b\u00e5da axlarna i en hastig ryckning \u2014 den snabba, gravitationstrotsande r\u00f6relsen signalerade att han verkligen inte visste.", case_study_cloze: "P\u00e5 fr\u00e5gan om var bilnycklarna var h\u00f6jde han snabbt b\u00e5da axlarna i en hastig ____, en \u00e4rligare gest \u00e4n den l\u00e5ngsamma, tveksamma varianten." } },
      { concept: "SITTING LOWER AND LOWER", definition: "People who sink lower and lower into their chairs during a meeting are revealing apprehension or lack of confidence. Like the turtle effect, this is a way of hiding in the open-they might also be hoping not to get called on. But note also that in some people this might be simply a sign of indifference or disinterest. This behavior stands out because the shoulders are lower in relation to the table.", category: "body-language-extracted", real_world_scenario: "During the board meeting, the new analyst sank lower and lower into her chair as the discussion turned to her overdue report, hoping she would not be called on.", case_study_cloze: "As the teacher scanned the room for a volunteer, the student sank lower and lower in his ____, hoping to avoid being noticed.", sv: { concept: "Sjunka allt l\u00e4gre", definition: "M\u00e4nniskor som sjunker allt l\u00e4ngre ner i sina stolar under ett m\u00f6te avsl\u00f6jar oro eller brist p\u00e5 sj\u00e4lvf\u00f6rtroende. Precis som sk\u00f6ldpaddseffekten \u00e4r detta ett s\u00e4tt att g\u00f6mma sig i det \u00f6ppna \u2014 de kanske ocks\u00e5 hoppas att inte bli tillfr\u00e5gade. Men notera ocks\u00e5 att det hos vissa m\u00e4nniskor helt enkelt kan vara ett tecken p\u00e5 likgiltighet eller ointresse. Beteendet utm\u00e4rker sig eftersom axlarna \u00e4r l\u00e4gre i f\u00f6rh\u00e5llande till bordet.", real_world_scenario: "Under styrelsem\u00f6tet sj\u00f6nk den nya analytikern allt l\u00e4ngre ner i stolen n\u00e4r diskussionen kom in p\u00e5 hennes f\u00f6rsenade rapport, i hopp om att inte bli tillfr\u00e5gad.", case_study_cloze: "Medan l\u00e4raren s\u00f6kte efter en frivillig sj\u00f6nk eleven allt l\u00e4ngre ner i sin ____ i hopp om att slippa bli uppm\u00e4rksammad." } },
      { concept: "SHOULDER/CLAVICLE RUBBING", definition: "During intense or stressful interviews, interviewees will reach across their chest and press their hand against their opposite shoulder, then slowly move their hand across their clavicle toward the chest. Sometimes the hand will then hover pressed against the chest area, or the process may be repeated. The tactile and repetitive nature of the behavior help to relieve stress or apprehension.", category: "body-language-extracted", real_world_scenario: "During the tense job interview, the candidate reached across her chest, pressed her hand against her opposite shoulder and slowly moved it across her clavicle \u2014 the repetitive rubbing relieved her growing apprehension.", case_study_cloze: "Pressing his hand against his opposite shoulder and moving it across his ____, the interviewee's repetitive rubbing revealed his stress.", sv: { concept: "Gnidning av axel/nyckelben", definition: "Under intensiva eller stressande intervjuer str\u00e4cker sig intervjupersonen \u00f6ver br\u00f6stet, trycker handen mot motsatt axel och f\u00f6r sedan l\u00e5ngsamt handen \u00f6ver nyckelbenet mot br\u00f6stet. Ibland vilar handen sedan tryckt mot br\u00f6stomr\u00e5det, eller s\u00e5 upprepas processen. Beteendets taktila och repetitiva karakt\u00e4r hj\u00e4lper till att lindra stress eller oro.", real_world_scenario: "Under den sp\u00e4nda jobbintervjun str\u00e4ckte kandidaten handen \u00f6ver br\u00f6stet, tryckte den mot motsatt axel och f\u00f6rde den l\u00e5ngsamt \u00f6ver nyckelbenet \u2014 den upprepade gnidningen lindrade hennes v\u00e4xande oro.", case_study_cloze: "Med handen tryckt mot motsatt axel och f\u00f6rd \u00f6ver sitt ____ avsl\u00f6jade intervjupersonens upprepade gnidning hans stress." } },
      { concept: "SHOULDERS WIDENING", definition: "The amplification of the shoulders from relaxed to broad can be a perceptible display of authority and confidence that signals a person is in charge. We often see this with athletes and military personnel. This is why business suits have padded shoulders-to make their wearers look more powerful and authoritative.", category: "body-language-extracted", real_world_scenario: "Before stepping into the boardroom to deliver the bad news, the CEO squared his shoulders, widening them from relaxed to broad \u2014 an authoritative display that signaled he was in charge.", case_study_cloze: "The soldier widened his ____ as he stood before the general, an amplification of the shoulders that displayed authority and confidence.", sv: { concept: "Axelbreddning", definition: "F\u00f6rstoringen av axlarna, fr\u00e5n avslappnade till breda, kan vara en m\u00e4rkbar uppvisning av auktoritet och sj\u00e4lvf\u00f6rtroende som signalerar att personen best\u00e4mmer. Vi ser detta ofta hos idrottare och milit\u00e4r personal. Det \u00e4r d\u00e4rf\u00f6r kostymer har vadderade axlar \u2014 f\u00f6r att f\u00e5 b\u00e4rarna att se kraftfullare och mer auktoritativa ut.", real_world_scenario: "Innan han steg in i styrelserummet f\u00f6r att l\u00e4mna de d\u00e5liga nyheterna r\u00e4tade vd:n p\u00e5 axlarna, fr\u00e5n avslappnade till breda \u2014 en auktorit\u00e4r uppvisning som signalerade att han hade kontroll.", case_study_cloze: "Soldaten breddade sina ____ n\u00e4r han st\u00e4llde sig framf\u00f6r generalen, en f\u00f6rstoring av axlarna som visade auktoritet och sj\u00e4lvf\u00f6rtroende." } },
      { concept: "ANIMATED GESTURES", definition: "Animated gestures reflect our emotions and also get us noticed. Broad gestures are powerful displays when we're speaking and are essential to dynamic communication. In many cultures, emphasis requires exaggerated gestures. To an outsider, people making such gestures might look like they're about to fight when in fact they are just being emphatic.", category: "body-language-extracted", real_world_scenario: "At the farmers' market, the vendor gestured broadly with his arms while praising the sweetness of his peaches \u2014 to a tourist it almost looked like an argument, but he was simply being emphatic.", case_study_cloze: "In the passionate debate, he used broad, ____ gestures to emphasize every point, a dynamic display that got him noticed.", sv: { concept: "Animerade gester", definition: "Animerade gester speglar v\u00e5ra k\u00e4nslor och g\u00f6r ocks\u00e5 att vi blir uppm\u00e4rksammade. Breda gester \u00e4r kraftfulla framtr\u00e4danden n\u00e4r vi talar och v\u00e4sentliga f\u00f6r dynamisk kommunikation. I m\u00e5nga kulturer kr\u00e4ver eftertryck \u00f6verdrivna gester. F\u00f6r en utomst\u00e5ende kan m\u00e4nniskor som g\u00f6r s\u00e5dana gester se ut som om de \u00e4r p\u00e5 v\u00e4g att sl\u00e5ss n\u00e4r de i sj\u00e4lva verket bara \u00e4r eftertryckliga.", real_world_scenario: "P\u00e5 bondens marknad gestikulerade f\u00f6rs\u00e4ljaren brett med armarna n\u00e4r han lovordade sina persikors s\u00f6tma \u2014 f\u00f6r en turist s\u00e5g det n\u00e4stan ut som ett br\u00e5k, men han var helt enkelt bara eftertrycklig.", case_study_cloze: "I den passionerade debatten anv\u00e4nde han breda, ____ gester f\u00f6r att understryka varje po\u00e4ng, en dynamisk uppvisning som gjorde att han blev uppm\u00e4rksammad." } },
      { concept: "ELATION/TRIUMPH DISPLAYS", definition: "Displays of elation or triumph tend to be gravity-defying-in other words, the gesture is made upward or outward away from the body. Sometimes we actually jump out of our seats into the air with our arms and fingers extended. Positive emotions drive gravity- defying gestures, and so around the world triumph displays at sporting events tend to be similar: arms up in the air.", category: "body-language-extracted", real_world_scenario: "When the final whistle blew and the underdogs had won, the fans jumped out of their seats with arms and fingers extended high above their heads \u2014 gravity-defying displays of triumph.", case_study_cloze: "After scoring the winning goal, she threw her arms up in the air and jumped, a gravity-defying ____ display that matched celebrations of fans worldwide.", sv: { concept: "Triumf- och gl\u00e4djegester", definition: "Gl\u00e4dje- eller triumfgester tenderar att vara gravitationstrotsande \u2014 med andra ord g\u00f6rs gesten upp\u00e5t eller ut\u00e5t fr\u00e5n kroppen. Ibland hoppar vi faktiskt upp fr\u00e5n stolarna i luften med utstr\u00e4ckta armar och fingrar. Positiva k\u00e4nslor driver gravitationstrotsande gester, och d\u00e4rf\u00f6r tenderar triumfgester vid sportevenemang \u00f6ver hela v\u00e4rlden att vara likadana: armarna i luften.", real_world_scenario: "N\u00e4r slutsignalen lj\u00f6d och underdogen hade vunnit hoppade fansen upp fr\u00e5n sina platser med armar och fingrar str\u00e4ckta h\u00f6gt \u00f6ver huvudet \u2014 gravitationstrotsande triumfgester.", case_study_cloze: "Efter att ha gjort det avg\u00f6rande m\u00e5let kastade hon armarna i luften och hoppade, en gravitationstrotsande ____ gest som st\u00e4mde \u00f6verens med fansens firanden v\u00e4rlden \u00f6ver." } },
      { concept: "ARMS HELD BEHIND BACK", definition: "The regal stance is performed by placing the arms and hands behind the back. Queen Elizabeth, Prince Charles, and other British royals often walk this way when they want others to remain at a distance. For the rest of us, too, it signals to others to give us space. It is not a good way to endear yourself to others as we tend to associate aloofness with this behavior. Interestingly, young children don't like when their parents hide their hands behind their back.", category: "body-language-extracted", real_world_scenario: "The new school principal walked through the corridor with his hands held behind his back, and both students and teachers instinctively kept their distance \u2014 the regal stance signaled that he wanted space.", case_study_cloze: "The new CEO walked through the office with her hands held ____, and employees instinctively gave her more room.", sv: { concept: "Armar bakom ryggen", definition: "Den regala st\u00e4llningen utf\u00f6rs genom att placera armarna och h\u00e4nderna bakom ryggen. Drottning Elizabeth, prins Charles och andra brittiska kungligheter g\u00e5r ofta s\u00e5 h\u00e4r n\u00e4r de vill att andra ska h\u00e5lla avst\u00e5nd. \u00c4ven f\u00f6r oss andra signalerar det att andra ska ge oss utrymme. Det \u00e4r inte ett bra s\u00e4tt att g\u00f6ra sig omtyckt eftersom vi tenderar att f\u00f6rknippa detta beteende med distans och kyla. Intressant nog tycker sm\u00e5 barn inte om n\u00e4r f\u00f6r\u00e4ldrarna g\u00f6mmer h\u00e4nderna bakom ryggen.", real_world_scenario: "Den nya skolrektorn gick genom korridoren med h\u00e4nderna bakom ryggen, och b\u00e5de elever och l\u00e4rare h\u00f6ll instinktivt avst\u00e5nd \u2014 den regala st\u00e4llningen signalerade att han ville ha utrymme.", case_study_cloze: "Den nya vd:n gick genom kontoret med h\u00e4nderna ____, och medarbetarna gav henne instinktivt mer utrymme." } },
      { concept: "ARMS STIFFENING", definition: "People's arms will frequently stiffen when they are scared or overwhelmed by an event. Their arms lie dormant at their sides, making them look unnatural or robotic. Stiff arms are a strong indicator that something negative has just transpired.", category: "body-language-extracted", real_world_scenario: "In the hospital waiting room, the man sat with stiff, unmoving arms at his sides after receiving the news \u2014 the robotic stillness of his limbs betrayed that something terrible had just happened.", case_study_cloze: "After the accident, the driver sat with his arms ____ at his sides, looking unnatural and robotic.", sv: { concept: "Styvnade armar", definition: "M\u00e4nniskors armar styvnar ofta n\u00e4r de \u00e4r r\u00e4dda eller \u00f6verv\u00e4ldigade av en h\u00e4ndelse. Armarna ligger or\u00f6rliga l\u00e4ngs sidorna och f\u00e5r personen att se onaturlig eller robotlik ut. Stela armar \u00e4r en stark indikator p\u00e5 att n\u00e5got negativt just har intr\u00e4ffat.", real_world_scenario: "P\u00e5 sjukhusets v\u00e4ntrum satt mannen med styvnade, or\u00f6rliga armar l\u00e4ngs sidorna efter att ha f\u00e5tt beskedet \u2014 armarnas robotlika stillhet avsl\u00f6jade att n\u00e5got hemskt just h\u00e4nt.", case_study_cloze: "Efter olyckan satt f\u00f6raren med armarna ____ l\u00e4ngs sidorna, onaturlig och robotlik." } },
      { concept: "ARMPIT EXPOSING", definition: "The exposure of our inner arm, including the armpit", category: "body-language-extracted", real_world_scenario: "On their date at the outdoor caf\u00e9, she stretched her arm up and exposed her armpit while laughing at his story \u2014 a relaxed gesture that showed she felt at ease.", case_study_cloze: "While laughing at the bar, she raised her arm and exposed her ____ \u2014 a relaxed and open display.", sv: { concept: "Armh\u00e5leblottande", definition: "Blottandet av v\u00e5r inre arm, inklusive armh\u00e5lan.", real_world_scenario: "P\u00e5 dejten vid uteserveringen str\u00e4ckte hon upp armen och blottade armh\u00e5lan medan hon skrattade \u00e5t hans historia \u2014 en avslappnad gest som visade att hon trivdes.", case_study_cloze: "N\u00e4r hon skrattade p\u00e5 baren str\u00e4ckte hon upp armen och blottade sin ____ \u2014 ett avslappnat och \u00f6ppet tecken." } },
      { concept: "ARM CROSSING/SELF", definition: "HUGGING -Self-hugging is an effective way to comfort ourselves while waiting for someone to arrive, while watching a movie in public, or when we need a little bit of self-comforting. This explains why so many passengers on a plane will cross their arms while standing in line to use the restroom. We cross our arms for many reasons. Here are some of the reasons reported to me: \\\"It's comfortable\\\"; \\\"It's useful when my arms are tired\\\"; \\\"It hides my boobs\\\"; \\\"I do it when I am inquisitive\\\"; \\\"It hides by belly.\\\" Everyone has a good reason and most of the time, it gives them comfort. There are a lot of people that mis takenly equate crossing the arms with keeping people further away-that is usually not the case.", category: "body-language-extracted", real_world_scenario: "In the queue for the airplane restroom, the passenger stood with her arms crossed over her chest in a self-hug \u2014 a quiet way of comforting herself while waiting.", case_study_cloze: "While waiting for her friend to arrive, she crossed her arms in a soothing ____ hug across her chest.", sv: { concept: "Armkorsning/sj\u00e4lvkram", definition: "Sj\u00e4lvkram \u00e4r ett effektivt s\u00e4tt att tr\u00f6sta oss sj\u00e4lva medan vi v\u00e4ntar p\u00e5 att n\u00e5gon ska komma, tittar p\u00e5 en film offentligt eller n\u00e4r vi beh\u00f6ver lite sj\u00e4lvtr\u00f6st. Det f\u00f6rklarar varf\u00f6r s\u00e5 m\u00e5nga passagerare p\u00e5 ett flygplan korsar armarna medan de st\u00e5r i k\u00f6 till toaletten. Vi korsar armarna av m\u00e5nga anledningar. H\u00e4r \u00e4r n\u00e5gra sk\u00e4l som rapporterats till mig: 'Det \u00e4r bekv\u00e4mt'; 'Det \u00e4r praktiskt n\u00e4r armarna \u00e4r tr\u00f6tta'; 'Det d\u00f6ljer mina br\u00f6st'; 'Jag g\u00f6r det n\u00e4r jag \u00e4r nyfiken'; 'Det d\u00f6ljer min mage.' Alla har en bra anledning och oftast ger det dem tr\u00f6st. Det \u00e4r m\u00e5nga som felaktigt likst\u00e4ller att korsa armarna med att h\u00e5lla andra p\u00e5 avst\u00e5nd \u2014 s\u00e5 \u00e4r oftast inte fallet.", real_world_scenario: "I k\u00f6n till flygplanets toalett stod passageraren med armarna korsade \u00f6ver br\u00f6stet i en sj\u00e4lvkram \u2014 ett stillsamt s\u00e4tt att tr\u00f6sta sig sj\u00e4lv medan hon v\u00e4ntade.", case_study_cloze: "Medan hon v\u00e4ntade p\u00e5 att v\u00e4nnen skulle komma korsade hon armarna i en lugnande ____ kram \u00f6ver br\u00f6stet." } },
      { concept: "ARM CROSSING/PROTECTION", definition: "In some instances the arm cross is a means of protection, rather than a comforting gesture. We might subconsciously seek to shield our vulnerable ventral (belly) side when we feel insecure or threatened. In those cases, we will see more tension in the arms and psychological discomfort in the face.", category: "body-language-extracted", real_world_scenario: "During the salary negotiation, the young employee crossed his arms tightly over his belly the moment the reorganization was mentioned \u2014 the tension in his arms and the worry in his face revealed that he felt threatened.", case_study_cloze: "When he heard the question about the audit, he crossed his arms tightly over his chest to shield his vulnerable ____ side.", sv: { concept: "Armkorsning/skydd", definition: "I vissa fall \u00e4r armkorsningen ett s\u00e4tt att skydda sig snarare \u00e4n en tr\u00f6stande gest. Vi kan undermedvetet f\u00f6rs\u00f6ka skydda v\u00e5r s\u00e5rbara ventrala (mag-) sida n\u00e4r vi k\u00e4nner oss otrygga eller hotade. I s\u00e5dana fall ser vi mer sp\u00e4nning i armarna och psykiskt obehag i ansiktet.", real_world_scenario: "Under l\u00f6nef\u00f6rhandlingen korsade den unge medarbetaren armarna h\u00e5rt \u00f6ver magen i samma stund som omorganisationen n\u00e4mndes \u2014 sp\u00e4nningen i armarna och oron i ansiktet avsl\u00f6jade att han k\u00e4nde sig hotad.", case_study_cloze: "N\u00e4r han h\u00f6rde fr\u00e5gan om revisionen korsade han armarna h\u00e5rt \u00f6ver br\u00f6stet f\u00f6r att skydda sin s\u00e5rbara ____ sida." } },
      { concept: "ARM CROSSING/DISLIKE", definition: "In the presence of someone we don't like, we might draw our arms across our belly, attempting to distance or insulate ourselves from that person. Usually this occurs as soon as we see someone objectionable, and that is what distinguishes this behavior and communicates our dislike very accurately. This should be differentiated from self-hugging behaviors by other cues that accompany it, such as a tense face and feet that also turn away.", category: "body-language-extracted", real_world_scenario: "At the Friday staff meeting, Anna drew her arms across her belly the moment the new consultant walked into the room \u2014 with a tense face and feet turned toward the door, her dislike was unmistakable.", case_study_cloze: "The moment the rival walked in, she drew her arms across her ____ with a tense face and turned feet \u2014 she did not like him.", sv: { concept: "Armkorsning/ogillande", definition: "I n\u00e4rvaro av n\u00e5gon vi inte gillar kan vi dra armarna \u00f6ver magen i ett f\u00f6rs\u00f6k att distansera eller isolera oss fr\u00e5n den personen. Vanligtvis sker detta s\u00e5 fort vi ser n\u00e5gon vi inte t\u00e5l, och det \u00e4r just detta som utm\u00e4rker beteendet och kommunicerar v\u00e5rt ogillande mycket tr\u00e4ffs\u00e4kert. Det b\u00f6r skiljas fr\u00e5n sj\u00e4lvkramsbeteenden genom andra signaler som \u00e5tf\u00f6ljer det, s\u00e5som ett sp\u00e4nt ansikte och f\u00f6tter som ocks\u00e5 v\u00e4nds bort.", real_world_scenario: "P\u00e5 fredagsm\u00f6tet drog Anna armarna \u00f6ver magen i samma stund som den nya konsulten klev in i rummet \u2014 med sp\u00e4nt ansikte och f\u00f6tterna v\u00e4nda mot d\u00f6rren var hennes ogillande omissk\u00e4nnligt.", case_study_cloze: "S\u00e5 fort rivalen klev in i rummet drog hon armarna i kors \u00f6ver ____ med sp\u00e4nt ansikte och v\u00e4nda f\u00f6tter \u2014 hon tyckte inte om honom." } },
      { concept: "ARM CROSSING/MASSAGING", definition: "Crossing the arms at the chest can be comfortable for many people. However, massaging the opposite shoulder or arm suggests that a person is stressed or concerned. This is most likely to occur when the person is seated at a table with her elbows on the surface, but I have also seen it in people sitting in a chair, a form of self-hugging while they massage the opposite arm to relieve stress or worry.", category: "body-language-extracted", real_world_scenario: "At the board meeting, the finance director sat with her elbows on the table and massaged her opposite shoulder while the quarterly results were reviewed \u2014 a sure sign that something was worrying her.", case_study_cloze: "Sitting at the table, she massaged her opposite ____ while she listened \u2014 a sign of stress or concern.", sv: { concept: "Armkorsning/massage", definition: "Att korsa armarna \u00f6ver br\u00f6stet kan vara bekv\u00e4mt f\u00f6r m\u00e5nga. Att d\u00e4remot massera den motsatta axeln eller armen tyder p\u00e5 att en person \u00e4r stressad eller orolig. Detta sker oftast n\u00e4r personen sitter vid ett bord med armb\u00e5garna p\u00e5 ytan, men jag har ocks\u00e5 sett det hos personer som sitter i en stol, en form av sj\u00e4lvkram medan de masserar den motsatta armen f\u00f6r att lindra stress eller oro.", real_world_scenario: "Vid styrelsem\u00f6tet satt ekonomichefen med armb\u00e5garna p\u00e5 bordet och masserade sin motsatta axel medan kvartalsresultatet gicks igenom \u2014 ett s\u00e4kert tecken p\u00e5 att n\u00e5got oroade henne.", case_study_cloze: "Sittande vid bordet masserade hon den motsatta ____ medan hon lyssnade \u2014 ett tecken p\u00e5 stress eller oro." } },
      { concept: "ARM CROSSING, HOLDING WRIST", definition: "When confronted with damaging information in a forensic setting, interviewees will suddenly reach across their belly and hold the wrist of the opposite hand while sitting. Look for it immediately after a person has been asked a difficult question or is accused of something. Poker players have been observed displaying this behavior when their hand is weak or marginal.", category: "body-language-extracted", real_world_scenario: "When the detective asked about the night in question, the suspect suddenly reached across his belly and gripped the wrist of his opposite hand \u2014 the gesture came right after the difficult question.", case_study_cloze: "Accused of the theft, the suspect suddenly reached across his belly and held his opposite ____.", sv: { concept: "Armkorsning, h\u00e5lla handleden", definition: "N\u00e4r de konfronteras med skadlig information i en r\u00e4ttsmedicinsk milj\u00f6 str\u00e4cker sig intervjuade pl\u00f6tsligt \u00f6ver magen och h\u00e5ller handleden p\u00e5 den motsatta handen medan de sitter. Titta efter det omedelbart efter att en person har f\u00e5tt en sv\u00e5r fr\u00e5ga eller anklagats f\u00f6r n\u00e5got. Pokerspelare har observerats uppvisa detta beteende n\u00e4r deras hand \u00e4r svag eller marginell.", real_world_scenario: "N\u00e4r detektiven fr\u00e5gade om den aktuella kv\u00e4llen str\u00e4ckte sig den misst\u00e4nkte pl\u00f6tsligt \u00f6ver magen och grep handleden p\u00e5 sin motsatta hand \u2014 gesten kom precis efter den sv\u00e5ra fr\u00e5gan.", case_study_cloze: "Anklagad f\u00f6r st\u00f6lden str\u00e4ckte den misst\u00e4nkte sig \u00f6ver magen och h\u00f6ll om sin motsatta ____." } },
      { concept: "ARM SPREADING", definition: "People who spread out their arms over several chairs or a couch are demonstrating confidence through a territorial display. Senior executives will do this more often than junior staffers. Observe when someone of higher rank or status walks in whether the person withdraws his arms to his sides.", category: "body-language-extracted", real_world_scenario: "At the board meeting, the senior director spread his arms across two empty chairs as a territorial display \u2014 and pulled them back to his sides the moment the CEO entered the room.", case_study_cloze: "The senior executive spread his arms across the empty chairs, a ____ display of confidence \u2014 until the CEO walked in.", sv: { concept: "Armar brett utstr\u00e4ckta", definition: "M\u00e4nniskor som breder ut armarna \u00f6ver flera stolar eller en soffa visar sj\u00e4lvf\u00f6rtroende genom en territoriell markering. H\u00f6gre chefer g\u00f6r detta oftare \u00e4n yngre medarbetare. L\u00e4gg m\u00e4rke till om en person med h\u00f6gre rang eller status drar in armarna n\u00e4r personen g\u00e5r in i rummet.", real_world_scenario: "Vid styrelsem\u00f6tet bredde den \u00e4ldre direkt\u00f6ren ut armarna \u00f6ver tv\u00e5 tomma stolar som en territoriell markering \u2014 och drog in dem till sidorna i samma stund som vd:n klev in i rummet.", case_study_cloze: "Den h\u00f6gre chefen bredde ut armarna \u00f6ver de tomma stolarna som en ____ markering av sj\u00e4lvf\u00f6rtroende \u2014 tills vd:n klev in." } },
      { concept: "ELBOWS NARROWING", definition: "When we're sitting with our arms on a table, the moment we feel insecure or threatened, we will narrow our elbows on the table. We can use this metric to help us assess how committed or confident others are as different topics are discussed.", category: "body-language-extracted", real_world_scenario: "During the negotiation, the buyer's elbows lay wide on the table, but the moment the delivery date was mentioned they narrowed inward \u2014 a clear measure of how his confidence had dropped.", case_study_cloze: "As the price was announced, the buyer's elbows ____ on the table, revealing his discomfort.", sv: { concept: "Armb\u00e5gar som dras in", definition: "N\u00e4r vi sitter med armarna p\u00e5 ett bord och i samma stund k\u00e4nner oss otrygga eller hotade, drar vi ihop armb\u00e5garna p\u00e5 bordet. Vi kan anv\u00e4nda detta m\u00e5tt f\u00f6r att bed\u00f6ma hur engagerade eller sj\u00e4lvs\u00e4kra andra \u00e4r n\u00e4r olika \u00e4mnen diskuteras.", real_world_scenario: "Under f\u00f6rhandlingen l\u00e5g k\u00f6parens armb\u00e5gar brett p\u00e5 bordet, men i samma sekund som leveranstiden n\u00e4mndes drogs de ihop \u2014 ett tydligt m\u00e5tt p\u00e5 att sj\u00e4lvf\u00f6rtroendet sj\u00f6nk.", case_study_cloze: "N\u00e4r priset meddelades drogs k\u00f6parens ____ ihop p\u00e5 bordet och avsl\u00f6jade hans obehag." } },
      { concept: "ELBOW FLEXING", definition: "The elbow flex is performed by placing hands on the hips, arms akimbo, and flexing the elbows forward (like a butterfly flapping its wings) each time we want to emphasize what we're saying. This is a territorial display that also projects confidence. I have seen senior managers, coaches, and military officers do the elbow flex as they emphasize a particular point.", category: "body-language-extracted", real_world_scenario: "On the pitch, the coach placed his hands on his hips and flexed his elbows forward like a butterfly flapping its wings every time he wanted to emphasize a tactical point.", case_study_cloze: "The coach placed his hands on his hips and flexed his ____ forward to emphasize the play.", sv: { concept: "Armb\u00e5gsflex", definition: "Armb\u00e5gsflexen utf\u00f6rs genom att placera h\u00e4nderna p\u00e5 h\u00f6fterna, med armarna i sidled (akimbo), och b\u00f6ja armb\u00e5garna fram\u00e5t (som en fj\u00e4ril som sl\u00e5r med vingarna) varje g\u00e5ng vi vill betona det vi s\u00e4ger. Detta \u00e4r en territoriell markering som ocks\u00e5 utstr\u00e5lar sj\u00e4lvf\u00f6rtroende. Jag har sett h\u00f6gre chefer, coacher och milit\u00e4ra officerare utf\u00f6ra armb\u00e5gsflexen n\u00e4r de betonar en s\u00e4rskild po\u00e4ng.", real_world_scenario: "P\u00e5 planen st\u00e4llde sig coachen med h\u00e4nderna p\u00e5 h\u00f6fterna och flexade armb\u00e5garna fram\u00e5t som en fj\u00e4ril varje g\u00e5ng han ville betona en taktisk po\u00e4ng.", case_study_cloze: "Coachen satte h\u00e4nderna p\u00e5 h\u00f6fterna och flexade ____ fram\u00e5t f\u00f6r att betona po\u00e4ngen." } },
      { concept: "ELBOWS INTERLOCKING", definition: "In many parts of the world the interlocking of arms at the elbows with another person as you walk or sit is a sign that you", category: "body-language-extracted", real_world_scenario: "In the old town, the couple walked arm in arm with their elbows interlocked \u2014 the intimate contact told everyone around them that they were a couple.", case_study_cloze: "Walking through the park, they interlocked their arms at the ____ with each other \u2014 a sign of closeness.", sv: { concept: "Fl\u00e4tade armb\u00e5gar", definition: "I m\u00e5nga delar av v\u00e4rlden \u00e4r att fl\u00e4ta armarna vid armb\u00e5garna med en annan person n\u00e4r man g\u00e5r eller sitter ett tecken p\u00e5 n\u00e4rhet och samh\u00f6righet.", real_world_scenario: "I gamla stan gick paret arm i arm med fl\u00e4tade armb\u00e5gar \u2014 den intima kontakten ber\u00e4ttade f\u00f6r alla runt omkring att de var ett par.", case_study_cloze: "N\u00e4r de promenerade genom parken fl\u00e4tade de armarna vid ____ med varandra \u2014 ett tecken p\u00e5 n\u00e4rhet." } },
      { concept: "GOOSE BUMPS", definition: "Also called \\\"goose pimples\\\" or \\\"gooseflesh,\\\" this is an involuntary reaction to cold or perhaps even fear-usually visible on the arms and legs. The formation of goose bumps causes hair to stand up on the surface of the skin, which is why the medical term for it is horripilation or piloerection ( see #253). In primates, this display is even more noticeable when they are scared, as their hair stands up to make them automatically look larger. Because we as a species have lost most of our hair, we only see the remnants of piloerection through goose bumps.", category: "body-language-extracted", real_world_scenario: "At the concert premiere, he got goose bumps on his arms the moment the orchestra began to play \u2014 an involuntary reaction that had nothing to do with the temperature.", case_study_cloze: "When she heard the frightening sound in the dark, her arms broke out in ____.", sv: { concept: "G\u00e5shud", definition: "\u00c4ven kallad g\u00e5shud, \u00e4r detta en ofrivillig reaktion p\u00e5 kyla eller kanske till och med r\u00e4dsla \u2014 vanligtvis synlig p\u00e5 armar och ben. G\u00e5shud f\u00e5r h\u00e5ren att resa sig p\u00e5 hudens yta, vilket \u00e4r varf\u00f6r det medicinska namnet \u00e4r horripilation eller piloerektion. Hos primater \u00e4r denna markering \u00e4nnu mer m\u00e4rkbar n\u00e4r de \u00e4r r\u00e4dda, eftersom h\u00e5ren reser sig f\u00f6r att f\u00e5 dem att automatiskt se st\u00f6rre ut. Eftersom vi som art har f\u00f6rlorat det mesta av v\u00e5rt h\u00e5r ser vi bara resterna av piloerektion genom g\u00e5shud.", real_world_scenario: "P\u00e5 premi\u00e4rkv\u00e4llen fick han g\u00e5shud p\u00e5 armarna i samma stund som orkestern b\u00f6rjade spela \u2014 en ofrivillig reaktion som inte hade n\u00e5got med temperaturen att g\u00f6ra.", case_study_cloze: "N\u00e4r hon h\u00f6rde det skr\u00e4mmande ljudet i m\u00f6rkret fick hon ____ p\u00e5 armarna." } },
      { concept: "EXCESSIVE SWEATING", definition: "People under stress may suddenly sweat profusely as their body attempts to ventilate itself through evaporation. Many a drug trafficker has been stopped at the border because he is the only one with sweat rings around his armpits and his neck glistens with moisture when he pulls up to the customs officer. Excessive perspiration may signal that a person is hiding something or is about to commit a crime. That doesn't", category: "body-language-extracted", real_world_scenario: "When the car rolled up to the border checkpoint, the driver was the only one whose shirt was soaked with sweat under the arms, even though the air conditioning was on \u2014 he was clearly hiding something.", case_study_cloze: "At the border crossing, the driver's neck glistened with moisture and he was the only one with ____ rings under his armpits.", sv: { concept: "Kraftig svettning", definition: "M\u00e4nniskor under stress kan pl\u00f6tsligt svettas ymnigt n\u00e4r kroppen f\u00f6rs\u00f6ker ventilera sig genom avdunstning. M\u00e5ngen knarksmugglare har stoppats vid gr\u00e4nsen f\u00f6r att han \u00e4r den enda med svettringar under armarna och att halsen gl\u00e4nser av fukt n\u00e4r han k\u00f6r fram till tulltj\u00e4nstemannen. Kraftig svettning kan signalera att en person d\u00f6ljer n\u00e5got eller \u00e4r p\u00e5 v\u00e4g att beg\u00e5 ett brott. Det betyder inte att alla som svettas \u00e4r skyldiga.", real_world_scenario: "N\u00e4r bilen rullade fram till gr\u00e4nskontrollen var f\u00f6raren den ende vars skjorta var genomv\u00e5t av svett under armarna, trots att luftkonditioneringen var p\u00e5 \u2014 han dolde tydligt n\u00e5got.", case_study_cloze: "Vid gr\u00e4nskontrollen gl\u00e4nste f\u00f6rarens hals av fukt och han var den ende med ____ under armarna." } },
      { concept: "NEEDLE TRACKS", definition: "Individuals who use heroin and other intravenous drugs will have scars tracking their veins on the inside of their arms. On long- term abusers, this can be very evident.", category: "body-language-extracted", real_world_scenario: "At the emergency room, the nurse noticed clear scars tracking the veins on the inside of the patient's arms \u2014 a long history of intravenous drug use.", case_study_cloze: "The officer noticed the ____ along the veins on the inside of the man's arms.", sv: { concept: "N\u00e5lstickm\u00e4rken", definition: "Personer som anv\u00e4nder heroin och andra intraven\u00f6sa droger har \u00e4rr som f\u00f6ljer venerna p\u00e5 insidan av armarna. Hos l\u00e5ngtidsmissbrukare kan detta vara mycket tydligt.", real_world_scenario: "P\u00e5 akutmottagningen lade sjuksk\u00f6terskan m\u00e4rke till tydliga \u00e4rr som f\u00f6ljde venerna p\u00e5 insidan av patientens armar \u2014 en l\u00e5ng historia av intraven\u00f6st missbruk.", case_study_cloze: "Polisen lade m\u00e4rke till ____ l\u00e4ngs venerna p\u00e5 insidan av mannens armar." } },
      { concept: "CONDITION OF HANDS", definition: "You can tell a lot from a person's hands. Grooming, scars, and calluses might indicate what kind of work the person does; an office worker's hands look quite different from a cement mixer's. Similarly, arthritis as well as neurological disorders can sometimes be discerned from the condition of the hands as well as finger movement or agitation.", category: "body-language-extracted", real_world_scenario: "When the bricklayer reached out his hand at the contract meeting, the deep calluses and scars told his profession long before he introduced himself.", case_study_cloze: "The rough ____ on his palms gave away his job as a construction worker before he said a word.", sv: { concept: "H\u00e4ndernas skick", definition: "Man kan utl\u00e4sa mycket av en persons h\u00e4nder. V\u00e5rdat utseende, \u00e4rr och f\u00f6rh\u00e5rdnader kan avsl\u00f6ja vilket arbete personen utf\u00f6r; en kontorsarbetares h\u00e4nder ser helt annorlunda ut \u00e4n en betongarbetares. P\u00e5 samma s\u00e4tt kan artrit s\u00e5v\u00e4l som neurologiska sjukdomar ibland avl\u00e4sas fr\u00e5n h\u00e4ndernas skick samt fingerr\u00f6relser eller oro.", real_world_scenario: "N\u00e4r muraren str\u00e4ckte fram handen vid kontraktsm\u00f6tet avsl\u00f6jade de djupa f\u00f6rh\u00e5rdnaderna och \u00e4rren hans yrke l\u00e5ngt innan han presenterade sig.", case_study_cloze: "De grova ____ p\u00e5 hans handflator avsl\u00f6jade hans yrke som byggarbetare innan han sa ett ord." } },
      { concept: "HAND GROOMING", definition: "Well-groomed hands are a sign of a healthy individual. Clean fingers, with nails of proper length, indicate that people care about themselves. This contrasts with people who have dirty or long nails, unkempt cuticles, or flesh that has been chewed off the fingers. In dating and even in the workplace, we often draw conclusions from how well- groomed or healthy-looking a person's hands appear.", category: "body-language-extracted", real_world_scenario: "On the first date, she noticed his clean, neatly trimmed nails and smooth skin \u2014 to her, a sign that he took care of himself.", case_study_cloze: "On the date, she noticed his clean, well-kept ____ and took it as a sign that he cared about himself.", sv: { concept: "V\u00e5rdade h\u00e4nder", definition: "V\u00e4lv\u00e5rdade h\u00e4nder \u00e4r ett tecken p\u00e5 en frisk individ. Rena fingrar med naglar av r\u00e4tt l\u00e4ngd visar att m\u00e4nniskor bryr sig om sig sj\u00e4lva. Detta kontrasterar med personer som har smutsiga eller l\u00e5nga naglar, ov\u00e5rdade nagelband eller k\u00f6tt som gnagts av fingrarna. Vid dejter och \u00e4ven p\u00e5 arbetsplatsen drar vi ofta slutsatser utifr\u00e5n hur v\u00e4lv\u00e5rdade eller h\u00e4lsosamma en persons h\u00e4nder ser ut.", real_world_scenario: "P\u00e5 f\u00f6rsta dejten lade hon m\u00e4rke till hans rena, v\u00e4lklippta naglar och mjuka hud \u2014 f\u00f6r henne ett tecken p\u00e5 att han tog hand om sig sj\u00e4lv.", case_study_cloze: "P\u00e5 dejten lade hon m\u00e4rke till hans rena, v\u00e4lklippta ____ och tog det som ett tecken p\u00e5 att han brydde sig om sig sj\u00e4lv." } },
      { concept: "FREQUENCY OF TOUCH", definition: "How frequently we touch others is a good way of communicating how we feel about them. While on some level the degree of", category: "body-language-extracted", real_world_scenario: "At the second sales meeting, the salesperson noticed that the customer touched his arm noticeably more often than the first time \u2014 the rising frequency of touch revealed that she liked him.", case_study_cloze: "How often we touch others communicates how we feel about them, so when her ____ increased, he understood that she was comfortable with him.", sv: { concept: "Ber\u00f6ringsfrekvens", definition: "Hur ofta vi r\u00f6r vid andra \u00e4r ett bra s\u00e4tt att kommunicera hur vi k\u00e4nner f\u00f6r dem. \u00c4ven graden av ber\u00f6ring spelar roll i sammanhanget.", real_world_scenario: "P\u00e5 det andra s\u00e4ljm\u00f6tet m\u00e4rkte s\u00e4ljaren att kunden r\u00f6rde vid hans arm m\u00e4rkbart oftare \u00e4n f\u00f6rsta g\u00e5ngen \u2014 den \u00f6kande ber\u00f6ringsfrekvensen avsl\u00f6jade att hon tyckte om honom.", case_study_cloze: "Hur ofta vi r\u00f6r vid andra kommunicerar hur vi k\u00e4nner f\u00f6r dem, s\u00e5 n\u00e4r hennes ____ \u00f6kade f\u00f6rstod han att hon trivdes med honom." } },
      { concept: "HOW WE TOUCH", definition: "A touch can be respectful, loving, playful, sensuous, reserved, tender, caring, or palliative. A light touch of the skin can send shivers down our spine, stimulating sexual desire. In fact, a light touch stimulates the brain differently than a heavier touch. The loving touch of a caring person with a full palm, warm from the presence of blood near the surface of the skin, can communicate so much to a newborn as well as a lover. And yet when our boss pats us on the shoulder with just the fingertips and says \\\"Good job,\\\" our skin crawls because the gesture doesn't feel right; we know it is contrived and empty.", category: "body-language-extracted", real_world_scenario: "When the boss patted her on the shoulder with just his fingertips and said 'Good job,' her skin crawled \u2014 the touch felt contrived and empty despite the friendly words.", case_study_cloze: "The boss's light ____ on her shoulder with just his fingertips made her skin crawl \u2014 the gesture felt contrived.", sv: { concept: "Hur vi ber\u00f6r", definition: "En ber\u00f6ring kan vara respektfull, k\u00e4rleksfull, lekfull, sensuell, \u00e5terh\u00e5llsam, \u00f6m, omt\u00e4nksam eller lugnande. En l\u00e4tt ber\u00f6ring av huden kan skicka rysningar l\u00e4ngs ryggraden och v\u00e4cka sexuell lust. Faktum \u00e4r att en l\u00e4tt ber\u00f6ring stimulerar hj\u00e4rnan annorlunda \u00e4n en tyngre. Den k\u00e4rleksfulla ber\u00f6ringen fr\u00e5n en omt\u00e4nksam person med en hel handflata, varm fr\u00e5n blodet n\u00e4ra hudens yta, kan kommunicera s\u00e5 mycket till b\u00e5de ett nyf\u00f6tt barn och en \u00e4lskare. Men n\u00e4r chefen klappar oss p\u00e5 axeln med bara fingertopparna och s\u00e4ger 'Bra jobbat' ryser vi, f\u00f6r gesten k\u00e4nns inte r\u00e4tt; vi vet att den \u00e4r tillgjord och tom.", real_world_scenario: "N\u00e4r chefen klappade henne p\u00e5 axeln med bara fingertopparna och sa 'Bra jobbat' r\u00f6s hon av obehag \u2014 ber\u00f6ringen k\u00e4ndes tillgjord och tom trots de v\u00e4nliga orden.", case_study_cloze: "Chefens l\u00e4tta ____ mot hennes axel med bara fingertopparna fick hennes hud att krypa \u2014 gesten k\u00e4ndes tillgjord." } },
      { concept: "PRESSING THE FLESH", definition: "This is a term that is often used by politicians to mean shaking hands, gripping an arm, hugging, holding or kissing babies. Hand shaking can be an opportunity for politicians to humanize themselves and establish physical bonds. The connection is literally chemical, as oxytocin (a powerful hormone that serves to socially bind us) is released when we touch others.", category: "body-language-extracted", real_world_scenario: "During the campaign tour, the candidate shook hands with everyone in line, hugged retirees and held up babies \u2014 each handshake released oxytocin and built a physical bond with the voters.", case_study_cloze: "At the rally, the politician shook hands and held babies \u2014 the oxytocin released by ____ helps create physical bonds.", sv: { concept: "Trycka folk p\u00e5 handen", definition: "Detta \u00e4r en term som ofta anv\u00e4nds av politiker f\u00f6r att betyda handskakningar, att greppa en arm, kramar, att h\u00e5lla eller kyssa bebisar. Handskakning kan vara en m\u00f6jlighet f\u00f6r politiker att bli mer m\u00e4nskliga och skapa fysiska band. Kontakten \u00e4r bokstavligen kemisk, eftersom oxytocin (ett kraftfullt hormon som socialt binder oss samman) fris\u00e4tts n\u00e4r vi r\u00f6r vid andra.", real_world_scenario: "Under valturn\u00e9n skakade kandidaten hand med alla i k\u00f6n, kramade pension\u00e4rer och h\u00f6ll upp bebisar \u2014 varje handtryck frisatte oxytocin och skapade ett fysiskt band med v\u00e4ljarna.", case_study_cloze: "P\u00e5 valm\u00f6tet skakade politikern h\u00e4nder och h\u00f6ll bebisar \u2014 oxytocinet som fris\u00e4tts vid ____ hj\u00e4lper till att skapa fysiska band." } },
      { concept: "TERRITORIAL HAND DISPLAY", definition: "As a form of mild intimidation, a person will splay out their hands on a desk or table. You see this often at a return counter, where angry customers take up increasingly more space with their hands as they argue with the representative. As emotions increase, note how the hands grow further and further apart.", category: "body-language-extracted", real_world_scenario: "At the return counter, the angry customer splayed his hands on the desk and spread them further apart with every objection \u2014 a mild territorial display as his emotions rose.", case_study_cloze: "The angry customer splayed his hands on the counter and took up more and more ____ as he argued with the representative.", sv: { concept: "Territoriell handmarkering", definition: "Som en form av mild hotfullhet breder en person ut sina h\u00e4nder p\u00e5 ett skrivbord eller ett bord. Du ser detta ofta vid en returdisk, d\u00e4r arga kunder tar upp allt mer plats med sina h\u00e4nder medan de argumenterar med representanten. N\u00e4r k\u00e4nslorna \u00f6kar, l\u00e4gg m\u00e4rke till hur h\u00e4nderna hamnar allt l\u00e4ngre ifr\u00e5n varandra.", real_world_scenario: "Vid returdisken bredde den arga kunden ut h\u00e4nderna p\u00e5 disken och spred dem allt l\u00e4ngre is\u00e4r f\u00f6r varje inv\u00e4ndning \u2014 en mild territoriell markering n\u00e4r k\u00e4nslorna steg.", case_study_cloze: "Den arga kunden bredde ut h\u00e4nderna p\u00e5 disken och tog upp allt mer ____ medan han argumenterade med representanten." } },
      { concept: "PUSHING AWAY FROM TABLE", definition: "A sudden stiff-arm pushing away from the table is a very accurate indicator the person disagrees with something said or discussed or might feel threatened. The speed of the motion matters: the more quickly it happens, the more concerning.", category: "body-language-extracted", real_world_scenario: "At the family dinner, the father-in-law suddenly pushed his chair back with stiff arms the moment the children suggested selling the summer cottage \u2014 the message was clear.", case_study_cloze: "The moment the proposal was made, he pushed himself away from the table with stiff ____ \u2014 he clearly disagreed.", sv: { concept: "St\u00f6ta sig fr\u00e5n bordet", definition: "Ett pl\u00f6tsligt stelt armtryck som skjuter en ifr\u00e5n bordet \u00e4r en mycket tillf\u00f6rlitlig indikator p\u00e5 att personen inte h\u00e5ller med om n\u00e5got som sagts eller diskuterats, eller kanske k\u00e4nner sig hotad. Hastigheten i r\u00f6relsen spelar roll: ju snabbare den sker, desto mer oroande.", real_world_scenario: "Vid familjemiddagen st\u00f6tte sv\u00e4rfadern pl\u00f6tsligt stolen bak\u00e5t med stela armar i samma stund som barnen f\u00f6reslog att s\u00e4lja sommarstugan \u2014 budskapet var tydligt.", case_study_cloze: "I samma sekund som f\u00f6rslaget kom st\u00f6tte han sig med stela ____ fr\u00e5n bordet \u2014 han h\u00f6ll tydligt inte med." } },
      { concept: "OBJECT PLACEMENT", definition: "We might surround ourselves with objects-whether a pencil and paper on a work desk or a jacket on a theater chair-to establish our territory. Object placement can also signal that we are not fully interested in someone or that a relationship is in trouble. At a restaurant for instance, when things are good, we tend to move objects out of the way to get a clearer view of our companion; when they're not, we'll place flowers or a drink bottle in our line of sight to serve as a barrier across the table. It is especially telling when someone moves objects while speaking.", category: "body-language-extracted", real_world_scenario: "At the restaurant, the woman moved the flower vase so that it stood directly in the line of sight between them \u2014 the barrier across the table told him the relationship was in trouble.", case_study_cloze: "At the restaurant, she placed the flower vase in her ____ across the table \u2014 a barrier that revealed the relationship was in trouble.", sv: { concept: "F\u00f6rem\u00e5lspositionering", definition: "Vi kan omge oss med f\u00f6rem\u00e5l \u2014 vare sig det \u00e4r en penna och papper p\u00e5 arbetsbordet eller en jacka p\u00e5 teaterstolen \u2014 f\u00f6r att etablera v\u00e5rt revir. F\u00f6rem\u00e5lspositionering kan ocks\u00e5 signalera att vi inte \u00e4r helt intresserade av n\u00e5gon eller att ett f\u00f6rh\u00e5llande \u00e4r i gungning. P\u00e5 en restaurang till exempel, n\u00e4r det g\u00e5r bra, tenderar vi att flytta undan f\u00f6rem\u00e5l f\u00f6r att f\u00e5 fri sikt mot v\u00e5r middagskamrat; n\u00e4r det inte g\u00e5r bra placerar vi blommor eller en flask dryck i v\u00e5r siktlinje som en barri\u00e4r tv\u00e4rs \u00f6ver bordet. Det \u00e4r s\u00e4rskilt avsl\u00f6jande n\u00e4r n\u00e5gon flyttar f\u00f6rem\u00e5l medan de pratar.", real_world_scenario: "P\u00e5 restaurangen flyttade kvinnan vasen med blommor s\u00e5 att den stod rakt i siktlinjen mellan dem \u2014 barri\u00e4ren \u00f6ver bordet ber\u00e4ttade f\u00f6r honom att f\u00f6rh\u00e5llandet var i gungning.", case_study_cloze: "P\u00e5 restaurangen st\u00e4llde hon blomvasen i sin ____ tv\u00e4rs \u00f6ver bordet \u2014 en barri\u00e4r som avsl\u00f6jade att f\u00f6rh\u00e5llandet var i gungning." } },
      { concept: "HAND STEEPLING", definition: "The hand steeple is performed by placing the fingertips of both hands together, spreading them, and then arching the hands so that the tips of the fingers look like a church steeple. This is a universal display of confidence and is often used by those in a leadership position. Chancellor Angela Merkel of Germany is famous for steepling often. Note, however, that confidence doesn't always guarantee accuracy. A person may be wrong in their facts but confident as they speak. Nevertheless, steepling is a useful gesture to convince others of your commitment to what you are thinking or saying.", category: "body-language-extracted", real_world_scenario: "In the boardroom, the CEO steepled her fingertips in front of her as she presented the quarterly report \u2014 the gesture conveyed confidence before she even began to speak.", case_study_cloze: "With her fingertips pressed together in a ____, the CEO radiated confidence as she presented the report.", sv: { concept: "Handspirande", definition: "Handspiran utf\u00f6rs genom att placera fingertopparna p\u00e5 b\u00e5da h\u00e4nderna mot varandra, spreta ut dem och sedan v\u00e4lva h\u00e4nderna s\u00e5 att fingertopparna ser ut som en kyrkspira. Detta \u00e4r en universell markering av sj\u00e4lvf\u00f6rtroende och anv\u00e4nds ofta av personer i ledarpositioner. F\u00f6rbundskansler Angela Merkel i Tyskland \u00e4r k\u00e4nd f\u00f6r att ofta handspira. Notera dock att sj\u00e4lvf\u00f6rtroende inte alltid garanterar tr\u00e4ffs\u00e4kerhet. En person kan ha fel i sina fakta men vara sj\u00e4lvs\u00e4ker n\u00e4r hen talar. \u00c4nd\u00e5 \u00e4r handspiran en anv\u00e4ndbar gest f\u00f6r att \u00f6vertyga andra om ditt engagemang f\u00f6r det du t\u00e4nker eller s\u00e4ger.", real_world_scenario: "I styrelserummet spirerade vd:n fingertopparna framf\u00f6r sig n\u00e4r hon lade fram kvartalsrapporten \u2014 gesten f\u00f6rmedlade sj\u00e4lvf\u00f6rtroende innan hon ens b\u00f6rjat tala.", case_study_cloze: "Med fingertopparna ihop i en ____ utstr\u00e5lade vd:n sj\u00e4lvf\u00f6rtroende n\u00e4r hon lade fram rapporten." } },
      { concept: "HANDS IN READY/ACTIVE POSITION", definition: "This is where the hands are held about fourteen inches apart in front of the belly at waist level with the palms facing each other, fingers spread apart. Speakers often do this to capture an audience's attention at an important moment. This is not the rogatory position ( see #272), which requires the palms to be facing up; here the palms face each other as if the person is holding a beach ball. This is a useful gesture to build into your public-speaking repertoire.", category: "body-language-extracted", real_world_scenario: "On stage, the speaker held his hands about fourteen inches apart in front of his belly, as if holding a beach ball, right before he delivered his most important point.", case_study_cloze: "The speaker held his hands apart in front of his belly as if holding a ____, to capture the audience's attention.", sv: { concept: "H\u00e4nder i aktivt/redo-l\u00e4ge", definition: "Detta \u00e4r n\u00e4r h\u00e4nderna h\u00e5lls cirka trettiofem centimeter is\u00e4r framf\u00f6r magen i midjeh\u00f6jd med handflatorna v\u00e4nda mot varandra och fingrarna brett is\u00e4r. Talare g\u00f6r ofta detta f\u00f6r att f\u00e5nga publikens uppm\u00e4rksamhet vid ett viktigt \u00f6gonblick. Detta \u00e4r inte den rogatoriska st\u00e4llningen, som kr\u00e4ver handflatorna upp\u00e5t; h\u00e4r \u00e4r handflatorna v\u00e4nda mot varandra som om personen h\u00f6ll en strandboll. Detta \u00e4r en anv\u00e4ndbar gest att bygga in i din repertoar f\u00f6r offentliga tal.", real_world_scenario: "P\u00e5 scenen h\u00f6ll talaren h\u00e4nderna cirka trettiofem centimeter is\u00e4r framf\u00f6r magen, som om han h\u00f6ll en strandboll, precis innan han lade fram sin viktigaste po\u00e4ng.", case_study_cloze: "Talaren h\u00f6ll h\u00e4nderna is\u00e4r framf\u00f6r magen som om han h\u00f6ll en ____ f\u00f6r att f\u00e5nga publikens uppm\u00e4rksamhet." } },
      { concept: "PALM DOWN, FINGERS SPREAD", definition: "When a person makes a formal declarative statement, such as \\\"I didn't do it,\\\" with palms firmly placed down and fingers spread wide, it is more likely to be an authentic answer. I have never seen a liar successfully pull off this gesture, probably because the thinking part of the brain is out of sync with the emotional part of the brain. In other words, they know what to say-\\\"I didn't do it\\\"-they just don't know how to dramatize it because the emotional side of the brain is not fully committed.", category: "body-language-extracted", real_world_scenario: "When the employee was accused of the leak, he said 'I did not do it' with his palms pressed firmly down and fingers spread wide \u2014 the investigator noted the gesture as a sign of authenticity.", case_study_cloze: "'I did not do it,' she said with her palms ____ and fingers spread wide \u2014 a gesture liars rarely manage to pull off.", sv: { concept: "Handflatorna ned\u00e5t, fingrarna brett is\u00e4r", definition: "N\u00e4r en person g\u00f6r ett formellt deklarativt uttalande, som 'Jag gjorde det inte', med handflatorna fast placerade ned\u00e5t och fingrarna brett is\u00e4r, \u00e4r det mer troligt ett \u00e4kta svar. Jag har aldrig sett en l\u00f6gnare lyckas genomf\u00f6ra denna gest, f\u00f6rmodligen f\u00f6r att den t\u00e4nkande delen av hj\u00e4rnan inte \u00e4r i synk med den k\u00e4nslom\u00e4ssiga delen. Med andra ord: de vet vad de ska s\u00e4ga \u2014 'Jag gjorde det inte' \u2014 de vet bara inte hur de ska dramatisera det, eftersom den k\u00e4nslom\u00e4ssiga sidan av hj\u00e4rnan inte \u00e4r fullt engagerad.", real_world_scenario: "N\u00e4r den anst\u00e4llde anklagades f\u00f6r l\u00e4ckan sa han 'Jag har inte gjort det' med handflatorna pressade ned\u00e5t och fingrarna brett is\u00e4r \u2014 utredaren noterade gesten som ett tecken p\u00e5 \u00e4kthet.", case_study_cloze: "'Jag gjorde det inte,' sa hon med handflatorna ____ och fingrarna brett is\u00e4r \u2014 en gest som l\u00f6gnare s\u00e4llan lyckas genomf\u00f6ra." } },
      { concept: "HAND RESTRICTING", definition: "Researchers, Aldert Vrij in particular, have noted that when people lie, they tend to use their hands and arms less. This can be a", category: "body-language-extracted", real_world_scenario: "During the police interview, the man gestured vividly with his hands \u2014 until he was asked about his alibi, when all hand movement stopped and his hands became still.", case_study_cloze: "Researchers have noted that when people lie, they tend to use their hands and arms ____.", sv: { concept: "Begr\u00e4nsade handr\u00f6relser", definition: "Forskare, s\u00e4rskilt Aldert Vrij, har noterat att n\u00e4r m\u00e4nniskor ljuger tenderar de att anv\u00e4nda h\u00e4nderna och armarna mindre. Detta kan vara en viktig ledtr\u00e5d.", real_world_scenario: "Under polisf\u00f6rh\u00f6ret gestikulerade mannen livligt med h\u00e4nderna \u2014 tills han fick fr\u00e5gan om sitt alibi, d\u00e5 upph\u00f6rde alla handr\u00f6relser och h\u00e4nderna blev stilla.", case_study_cloze: "Forskare har noterat att n\u00e4r m\u00e4nniskor ljuger tenderar de att anv\u00e4nda h\u00e4nderna och armarna ____." } },
      { concept: "HAND WRINGING", definition: "Rubbing one's hands together communicates concern, doubt, anxiety, or insecurity. The degree of stress is reflected in how tightly the hands are wrung. Blotches of red and white skin on the fingers or hands indicate an elevated level of discomfort.", category: "body-language-extracted", real_world_scenario: "In the waiting room outside the doctor's office, the patient's daughter rubbed her hands together, harder and harder, and her fingertips shifted between red and white \u2014 the worry was impossible to hide.", case_study_cloze: "While waiting for the test results, she rubbed her ____ together, with her fingers blotched red and white.", sv: { concept: "Gnugga h\u00e4nderna", definition: "Att gnugga h\u00e4nderna mot varandra kommunicerar oro, tvivel, \u00e5ngest eller os\u00e4kerhet. Graden av stress \u00e5terspeglas i hur h\u00e5rt h\u00e4nderna gnids. R\u00f6da och vita fl\u00e4ckar p\u00e5 fingrarna eller h\u00e4nderna indikerar en f\u00f6rh\u00f6jd niv\u00e5 av obehag.", real_world_scenario: "I v\u00e4ntrummet utanf\u00f6r l\u00e4karmottagningen gned patientens dotter h\u00e4nderna mot varandra, allt h\u00e5rdare, och fingertopparna skiftade mellan r\u00f6tt och vitt \u2014 oron gick inte att d\u00f6lja.", case_study_cloze: "Medan hon v\u00e4ntade p\u00e5 provresultaten gned hon sina ____ mot varandra, med fingrarna skiftande i r\u00f6tt och vitt." } },
      { concept: "FINGER HOLDING", definition: "When we meet people for the first time or we feel a little insecure, we tend to hold our own fingers together lightly in front of us. It is a very tactile, self-soothing behavior. Prince Harry is famous for this but we all do it as we patiently wait in line or speak to someone we've never met before.", category: "body-language-extracted", real_world_scenario: "In the queue at airport security, the man held his own fingers together loosely in front of him \u2014 a soothing, tactile gesture while he waited patiently.", case_study_cloze: "Before meeting the new boss, she held her own ____ together lightly in front of her.", sv: { concept: "Att h\u00e5lla om fingrarna", definition: "N\u00e4r vi tr\u00e4ffar m\u00e4nniskor f\u00f6r f\u00f6rsta g\u00e5ngen eller k\u00e4nner oss lite os\u00e4kra tenderar vi att h\u00e5lla v\u00e5ra egna fingrar l\u00f6st ihop framf\u00f6r oss. Det \u00e4r ett mycket taktilt, lugnande beteende. Prins Harry \u00e4r k\u00e4nd f\u00f6r detta, men vi alla g\u00f6r det n\u00e4r vi t\u00e5lmodigt v\u00e4ntar i k\u00f6 eller pratar med n\u00e5gon vi aldrig tr\u00e4ffat f\u00f6rut.", real_world_scenario: "I k\u00f6n till s\u00e4kerhetskontrollen p\u00e5 flygplatsen h\u00f6ll mannen sina egna fingrar l\u00f6st ihop framf\u00f6r sig \u2014 en lugnande, taktil gest medan han v\u00e4ntade t\u00e5lmodigt.", case_study_cloze: "Innan hon tr\u00e4ffade den nya chefen h\u00f6ll hon sina egna ____ l\u00f6st ihop framf\u00f6r sig." } },
      { concept: "JITTERY HANDS", definition: "When we are excited or stressed our hands may become jittery. Jitters, of course, can also be caused by a neurological disorder, disease, or drugs, but for the most part, when a person appears otherwise healthy, we should take notice. People might accidentally knock down objects such as wineglasses when stressed, or their spoons will shake in their hands. Fingers and hands might shake uncontrollably after an accident or when we are notified of terrible news.", category: "body-language-extracted", real_world_scenario: "At the dinner party, the guest's hands shook so much that the wineglass slipped from her grip \u2014 she had just received the terrible news and could not keep her hands still.", case_study_cloze: "When the terrible news arrived, his hands became so ____ that he accidentally knocked over the wineglass.", sv: { concept: "Skakiga h\u00e4nder", definition: "N\u00e4r vi \u00e4r upphetsade eller stressade kan h\u00e4nderna bli skakiga. Darrningar kan naturligtvis ocks\u00e5 orsakas av en neurologisk sjukdom, sjukdom eller droger, men f\u00f6r det mesta, n\u00e4r en person annars verkar frisk, b\u00f6r vi l\u00e4gga m\u00e4rke till det. M\u00e4nniskor kan av misstag sl\u00e5 ner f\u00f6rem\u00e5l som vinglas n\u00e4r de \u00e4r stressade, eller s\u00e5 skakar deras skedar i h\u00e4nderna. Fingrar och h\u00e4nder kan skaka okontrollerat efter en olycka eller n\u00e4r vi f\u00e5r besked om hemska nyheter.", real_world_scenario: "Vid middagen skakade g\u00e4stens h\u00e4nder s\u00e5 mycket att vinglaset gled ur hennes grepp \u2014 hon hade just f\u00e5tt de hemska nyheterna och kunde inte h\u00e5lla h\u00e4nderna stilla.", case_study_cloze: "N\u00e4r de hemska nyheterna kom blev hans h\u00e4nder s\u00e5 ____ att han av misstag slog ner vinglaset." } },
      { concept: "HANDS AS ANCHORS", definition: "This is where we take possession of an object to let others know it is ours. It might also happen with other people, as when we're talking to someone we like and use our hand as an anchor near this person so others will stay away. You see this most often at bars or parties- men will pivot around the anchor point as if permanently attached in order to make sure others don't intrude. It is a territorial display.", category: "body-language-extracted", real_world_scenario: "At the bar, the man placed his hand on the counter right next to the woman's glass, using it as an anchor, and pivoted around that point so that other men kept away.", case_study_cloze: "At the bar, he placed his hand beside her glass as an ____ to keep other men away.", sv: { concept: "H\u00e4nder som ankare", definition: "Detta \u00e4r n\u00e4r vi tar besittning av ett f\u00f6rem\u00e5l f\u00f6r att l\u00e5ta andra veta att det \u00e4r v\u00e5rt. Det kan ocks\u00e5 ske med andra m\u00e4nniskor, som n\u00e4r vi pratar med n\u00e5gon vi gillar och anv\u00e4nder v\u00e5r hand som ett ankare n\u00e4ra personen s\u00e5 att andra h\u00e5ller sig borta. Du ser detta oftast p\u00e5 barer eller fester \u2014 m\u00e4n sv\u00e4nger runt ankarpunkten som om de var permanent f\u00e4sta f\u00f6r att se till att andra inte tr\u00e4nger sig p\u00e5. Det \u00e4r en territoriell markering.", real_world_scenario: "P\u00e5 baren lade mannen handen p\u00e5 disken strax intill kvinnans glas, som ett ankare, och sv\u00e4ngde sig kring den punkten s\u00e5 att andra m\u00e4n h\u00f6ll sig borta.", case_study_cloze: "P\u00e5 baren placerade han sin hand bredvid hennes glas som ett ____ f\u00f6r att h\u00e5lla andra m\u00e4n borta." } },
      { concept: "HAND THRUST TO FACE", definition: "This might come as the final affront in an argument. A raised palm thrust at the other person's face says to stop, go no further, or, in the common parlance, \\\"talk to the hand.\\\" This can be a very insulting gesture and certainly has no place in amiable interpersonal communication and certainly not in business.", category: "body-language-extracted", real_world_scenario: "In the middle of the argument about money, she suddenly thrust her raised palm toward his face \u2014 talk to the hand \u2014 and the room fell silent.", case_study_cloze: "In the middle of the argument, she thrust her open ____ toward his face \u2014 a gesture that said 'stop, go no further.'", sv: { concept: "Handen st\u00f6tt mot ansiktet", definition: "Detta kan komma som den slutliga f\u00f6rol\u00e4mpningen i ett gr\u00e4l. En h\u00f6jd handflata som st\u00f6ts mot den andra personens ansikte s\u00e4ger att stoppa, inte g\u00e5 l\u00e4ngre, eller som det heter i vardagsspr\u00e5k: 'prata med handen'. Detta kan vara en mycket f\u00f6rol\u00e4mpande gest och har definitivt ingen plats i v\u00e4nskaplig kommunikation och absolut inte i aff\u00e4rssammanhang.", real_world_scenario: "Mitt i gr\u00e4let om pengarna st\u00f6tte hon pl\u00f6tsligt upp sin handflata mot hans ansikte \u2014 'prata med handen' \u2014 och det blev tyst i rummet.", case_study_cloze: "Mitt i argumentet st\u00f6tte hon sin \u00f6ppna ____ mot hans ansikte \u2014 en gest som sa 'stopp, g\u00e5 inte l\u00e4ngre.'" } },
      { concept: "INTERLACED FINGERS", definition: "THUMBS UP -Statements made with thumbs up while the fingers are interlaced indicate confidence. Usually people do this with their hands on their lap or on top of a desk or table; their thumbs rising as they genuinely emphasize a point. This is a very fluid behavior that might change depending upon the emotions felt in the moment, as well as how committed the person is to what she is saying.", category: "body-language-extracted", real_world_scenario: "At the meeting, the marketing director interlaced her fingers on the table and let her thumbs rise as she emphasized her point \u2014 a fluid sign of confidence in what she was saying.", case_study_cloze: "With his fingers interlaced on the table, his ____ rose as he emphasized the point \u2014 a sign of confidence.", sv: { concept: "Fl\u00e4tade fingrar", definition: "Uttalanden som g\u00f6rs med tummarna upp medan fingrarna \u00e4r fl\u00e4tade indikerar sj\u00e4lvf\u00f6rtroende. Vanligtvis g\u00f6r m\u00e4nniskor detta med h\u00e4nderna i kn\u00e4t eller p\u00e5 ett skrivbord; tummarna reser sig n\u00e4r de verkligen betonar en po\u00e4ng. Detta \u00e4r ett mycket flytande beteende som kan f\u00f6r\u00e4ndras beroende p\u00e5 de k\u00e4nslor som upplevs i stunden, samt hur engagerad personen \u00e4r i det hon s\u00e4ger.", real_world_scenario: "Vid m\u00f6tet fl\u00e4tade marknadschefen fingrarna p\u00e5 bordet och l\u00e4t tummarna resa sig n\u00e4r hon betonade sin po\u00e4ng \u2014 ett flytande tecken p\u00e5 sj\u00e4lvf\u00f6rtroende i det hon sa.", case_study_cloze: "Med fingrarna fl\u00e4tade p\u00e5 bordet reste sig hans ____ n\u00e4r han betonade po\u00e4ngen \u2014 ett tecken p\u00e5 sj\u00e4lvf\u00f6rtroende." } },
      { concept: "THUMB MASSAGING", definition: "Thumb massaging is a mild pacifier. The hands are intertwined and the thumb on top rubs the one below it repeatedly. We usually see this when people are waiting for something to happen, though they might also do this as they are talking, if they are slightly nervous or anxious.", category: "body-language-extracted", real_world_scenario: "In the dentist's waiting room, the patient interlaced his hands and let his thumb rub the thumb beneath it, over and over, while he waited to be called in.", case_study_cloze: "While waiting for the news, her thumb massaged the other ____ over and over again.", sv: { concept: "Tummassage", definition: "Tummassage \u00e4r ett milt lugnande beteende. H\u00e4nderna \u00e4r fl\u00e4tade och tummen ovanp\u00e5 gnuggar tummen under den upprepade g\u00e5nger. Vi ser detta vanligtvis n\u00e4r m\u00e4nniskor v\u00e4ntar p\u00e5 att n\u00e5got ska h\u00e4nda, men de kan ocks\u00e5 g\u00f6ra det medan de pratar om de \u00e4r lite nerv\u00f6sa eller oroliga.", real_world_scenario: "I tandl\u00e4karens v\u00e4ntrum fl\u00e4tade patienten h\u00e4nderna och l\u00e4t tummen gnugga tummen under den, om och om igen, medan han v\u00e4ntade p\u00e5 att bli inkallad.", case_study_cloze: "Medan hon v\u00e4ntade p\u00e5 beskedet masserade hennes tumme den andra ____ om och om igen." } },
      { concept: "THUMB TWIRLING", definition: "Twiddling our thumbs is a way to pass the time or deal with small amounts of stress. The repetitive nature of it is soothing to the brain.", category: "body-language-extracted", real_world_scenario: "In the classroom, while the teacher searched for the image on the projector, the student twirled his thumbs around each other \u2014 a way of passing the time.", case_study_cloze: "Bored in the lecture, he twirled his ____ around each other to pass the time.", sv: { concept: "Tummsnurrande", definition: "Att snurra tummarna \u00e4r ett s\u00e4tt att f\u00f6rdriva tiden eller hantera sm\u00e5 m\u00e4ngder stress. Den upprepande naturen \u00e4r lugnande f\u00f6r hj\u00e4rnan.", real_world_scenario: "I klassrummet, medan l\u00e4raren letade efter bilden i projektorn, snurrade eleven sina tummar runt varandra \u2014 ett s\u00e4tt att f\u00f6rdriva tiden.", case_study_cloze: "Uttr\u00e5kad under f\u00f6rel\u00e4sningen snurrade han sina ____ runt varandra f\u00f6r att f\u00f6rdriva tiden." } },
      { concept: "THUMB UP OK SIGN", definition: "This, of course, is a very positive sign in the United States, signaling that all is fine. At one time it was used routinely to hitch a car ride. Note that in some cultures, such as the Middle East, a raised thumb is a phallic symbol and should be avoided.", category: "body-language-extracted", real_world_scenario: "At the market in Cairo, the tourist gave the vendor a thumbs up to show that the price was fine \u2014 unaware that the raised thumb is an insult in the Middle East.", case_study_cloze: "He gave the driver a thumbs up, unaware that the raised ____ is an insult in the Middle East.", sv: { concept: "Tummen upp", definition: "Detta \u00e4r naturligtvis ett mycket positivt tecken i USA som signalerar att allt \u00e4r bra. En g\u00e5ng anv\u00e4ndes det rutinm\u00e4ssigt f\u00f6r att lifta en bil. Observera att i vissa kulturer, till exempel Mellan\u00f6stern, \u00e4r en upph\u00f6jd tumme en fallossymbol och b\u00f6r undvikas.", real_world_scenario: "P\u00e5 marknaden i Kairo gav turisten f\u00f6rs\u00e4ljaren tummen upp f\u00f6r att visa att priset var okej \u2014 ovetande om att den upph\u00f6jda tummen \u00e4r en f\u00f6rol\u00e4mpning i Mellan\u00f6stern.", case_study_cloze: "Han gav chauff\u00f6ren tummen upp, ovetande om att den upph\u00f6jda ____ \u00e4r en f\u00f6rol\u00e4mpning i Mellan\u00f6stern." } },
      { concept: "SURROGATE TOUCHING", definition: "Sometimes, early on in a romantic relationship, we want to be in closer physical contact with the other person but feel it is too soon. So we transfer those wishes to an object. We might stroke our own arm or slide our hand around a glass repeatedly. Surrogate touching is a form or subconscious flirting as well as a stress reliever that often serves as an effective substitute for the touch we desire.", category: "body-language-extracted", real_world_scenario: "On the first date, she did not dare touch him yet, so she let her fingers slide slowly around her wineglass instead \u2014 a surrogate touch that substituted for the contact she longed for.", case_study_cloze: "Too soon for real contact, she let her fingers slide around the ____ \u2014 a surrogate touch for the physical contact she desired.", sv: { concept: "Surrogatber\u00f6ring", definition: "Ibland, tidigt i ett romantiskt f\u00f6rh\u00e5llande, vill vi ha n\u00e4rmare fysisk kontakt med den andra personen men k\u00e4nner att det \u00e4r f\u00f6r tidigt. S\u00e5 \u00f6verf\u00f6r vi dessa \u00f6nskningar till ett f\u00f6rem\u00e5l. Vi kan stryka v\u00e5r egen arm eller glida med handen runt ett glas upprepade g\u00e5nger. Surrogatber\u00f6ring \u00e4r en form av undermedvetet flirtande s\u00e5v\u00e4l som en stressavlastare som ofta fungerar som ett effektivt substitut f\u00f6r den ber\u00f6ring vi l\u00e4ngtar efter.", real_world_scenario: "P\u00e5 f\u00f6rsta dejten v\u00e5gade hon inte r\u00f6ra honom \u00e4nnu, s\u00e5 hon l\u00e4t ist\u00e4llet fingrarna glida sakta runt vinglaset \u2014 en surrogatber\u00f6ring som ersatte den kontakt hon l\u00e4ngtade efter.", case_study_cloze: "F\u00f6r tidigt f\u00f6r riktig kontakt, l\u00e4t hon fingrarna glida runt ____ \u2014 en surrogatber\u00f6ring f\u00f6r den fysiska kontakt hon \u00f6nskade." } },
      { concept: "RECIPROCAL TOUCHING", definition: "This is where someone reaches out to touch us and we touch back in return. Usually it is a sign of social harmony and comfort with others, so when it isn't reciprocated, there may be an issue. Often in work relations, when someone is about to get demoted or fired, there will be less reciprocal touching on the part of the supervisor in the days prior to the employee dismissal. This also happens in dating situations when there is about to be a breakup.", category: "body-language-extracted", real_world_scenario: "During the two weeks before his layoff, the employee noticed that his supervisor no longer touched him back when he patted her on the shoulder \u2014 the missing reciprocal touch was an early warning sign.", case_study_cloze: "In the days before the dismissal, the supervisor stopped ____ her touches on the shoulder \u2014 a sign that something was wrong.", sv: { concept: "\u00d6msesidig ber\u00f6ring", definition: "Detta \u00e4r n\u00e4r n\u00e5gon str\u00e4cker ut handen f\u00f6r att r\u00f6ra oss och vi r\u00f6r tillbaka. Vanligtvis \u00e4r det ett tecken p\u00e5 social harmoni och trygghet med andra, s\u00e5 n\u00e4r det inte besvaras kan det finnas ett problem. Ofta i arbetsrelationer, n\u00e4r n\u00e5gon \u00e4r p\u00e5 v\u00e4g att degraderas eller avskedas, f\u00f6rekommer det mindre \u00f6msesidig ber\u00f6ring fr\u00e5n chefens sida under dagarna f\u00f6re upps\u00e4gningen. Detta h\u00e4nder ocks\u00e5 i dejting-situationer n\u00e4r ett uppbrott \u00e4r p\u00e5 v\u00e4g.", real_world_scenario: "Under de tv\u00e5 veckorna innan upps\u00e4gningen m\u00e4rkte medarbetaren att chefen inte l\u00e4ngre r\u00f6rde tillbaka n\u00e4r hon klappade honom p\u00e5 axeln \u2014 den uteblivna \u00f6msesidiga ber\u00f6ringen var ett tidigt varningstecken.", case_study_cloze: "Dagarna f\u00f6re upps\u00e4gningen slutade chefen att ____ hennes klappar p\u00e5 axeln \u2014 ett tecken p\u00e5 att n\u00e5got var fel." } },
      { concept: "EMPHASIZING WITH HANDS", definition: "When we are comfortable, our hands naturally gesture and emphasize. In some cultures, especially around the Mediterranean, people tend to gesture more emphatically, and these gestures are highly significant in context. Great speakers also gesture frequently. Researchers tell us that when people suddenly begin to lie, they engage in fewer hand gestures-and with less emphasis. If the hands suddenly become passive or restrained, it is likely that the person is losing confidence in what he is saying, for whatever reason.", category: "body-language-extracted", real_world_scenario: "During the presentation, the salesperson gestured vividly with his hands \u2014 until the question about the quarterly figures came up, when his hands suddenly became still and passive.", case_study_cloze: "He gestured emphatically with his hands \u2014 until he started talking about the missing report, when his hands suddenly became ____.", sv: { concept: "Betona med h\u00e4nderna", definition: "N\u00e4r vi \u00e4r bekv\u00e4ma gestikulerar och betonar v\u00e5ra h\u00e4nder naturligt. I vissa kulturer, s\u00e4rskilt runt Medelhavet, gestikulerar m\u00e4nniskor mer kraftfullt, och dessa gester \u00e4r mycket betydelsefulla i sitt sammanhang. Stora talare gestikulerar ocks\u00e5 ofta. Forskare ber\u00e4ttar f\u00f6r oss att n\u00e4r m\u00e4nniskor pl\u00f6tsligt b\u00f6rjar ljuga, anv\u00e4nder de f\u00e4rre handgester \u2014 och med mindre eftertryck. Om h\u00e4nderna pl\u00f6tsligt blir passiva eller \u00e5terh\u00e5llna, \u00e4r det troligt att personen f\u00f6rlorar f\u00f6rtroendet f\u00f6r det han s\u00e4ger, av vilken anledning som helst.", real_world_scenario: "Under presentationen gestikulerade s\u00e4ljaren livligt med h\u00e4nderna \u2014 tills fr\u00e5gan om kvartalssiffrorna kom, d\u00e5 blev h\u00e4nderna pl\u00f6tsligt stilla och passiva.", case_study_cloze: "Han gestikulerade kraftigt med h\u00e4nderna \u2014 tills han b\u00f6rjade prata om den saknade rapporten, d\u00e5 blev h\u00e4nderna pl\u00f6tsligt ____." } },
      { concept: "FINGER POINTING", definition: "Almost universally, people dislike having a finger pointed at them. If you have to point, especially in a professional or romantic setting, use the full hand, fingers together, rather than a single finger. This also applies when pointing to objects. When directing someone to a chair, do so with the full hand rather than with a single finger.", category: "body-language-extracted", real_world_scenario: "When the sales manager directed the visiting client to the conference room chair, he used a single index finger, and the client visibly stiffened \u2014 pointing at people is almost universally disliked, and the full hand would have been far more diplomatic.", case_study_cloze: "When directing the guest to her seat, the host gestured with his ____ rather than a single finger, since pointing is almost universally disliked.", sv: { concept: "Fingerpekande", definition: "N\u00e4stan alla m\u00e4nniskor ogillar att f\u00e5 ett finger pekat mot sig. Om du m\u00e5ste peka, s\u00e4rskilt i professionella eller romantiska sammanhang, anv\u00e4nd hela handen med fingrarna samlade snarare \u00e4n ett enda finger. Detta g\u00e4ller \u00e4ven n\u00e4r du pekar p\u00e5 f\u00f6rem\u00e5l. N\u00e4r du visar n\u00e5gon till en stol, g\u00f6r det med hela handen snarare \u00e4n med ett enda finger.", real_world_scenario: "N\u00e4r s\u00e4ljchefen visade den bes\u00f6kande kunden till stolen i konferensrummet pekade han med ett enda pekfinger, och kunden stelnade synligt \u2014 att peka p\u00e5 m\u00e4nniskor \u00e4r n\u00e4stan universellt ogillat, och hela handen hade varit l\u00e5ngt mer diplomatiskt.", case_study_cloze: "N\u00e4r v\u00e4rden visade g\u00e4sten till hennes plats gestikulerade han med sin ____ snarare \u00e4n med ett enda finger, eftersom pekande n\u00e4stan alltid \u00e4r ogillat." } },
      { concept: "FINGER JABBING", definition: "Jabbing a finger at someone's chest or face is a highly antagonistic behavior, used to single a person out when there are issues. When ac tual physical touch is involved, it becomes even more threatening.", category: "body-language-extracted", real_world_scenario: "During the heated argument at the community meeting, the angry resident jabbed his finger toward the council member's chest \u2014 an openly antagonistic act that singled him out in front of the whole room.", case_study_cloze: "In the confrontation, he jabbed his ____ at the other man's face \u2014 a highly antagonistic way of singling him out.", sv: { concept: "Pekfingerstickande", definition: "Att sticka ett finger mot n\u00e5gons br\u00f6st eller ansikte \u00e4r ett mycket antagoniserande beteende som anv\u00e4nds f\u00f6r att peka ut en person n\u00e4r det finns problem. N\u00e4r faktisk fysisk ber\u00f6ring \u00e4r inblandad blir det \u00e4nnu mer hotfullt.", real_world_scenario: "Under det hetsiga gr\u00e4let p\u00e5 m\u00f6tet stack den uppr\u00f6rda grannen ut sitt finger mot stadsfullm\u00e4ktigeledamotens br\u00f6st \u2014 en \u00f6ppet antagoniserande handling som pekade ut honom inf\u00f6r hela rummet.", case_study_cloze: "I konfrontationen stack han sitt ____ mot den andre mannens ansikte \u2014 ett mycket antagoniserande s\u00e4tt att peka ut honom." } },
      { concept: "FINGER STRUMMING", definition: "Strumming one's fingers on a table or a leg passes the time and, like other repetitive behaviors, soothes. In professional settings you see this as people wait for someone to show up or finish talking. It is a way of saying, \\\"Come on, let's get things moving here.\\\" This is similar to cheek strumming ( see #170).", category: "body-language-extracted", real_world_scenario: "Sitting in the conference room, the senior partner strummed his fingers on the table while the late client dialed in \u2014 a quiet, repetitive way of saying, 'Come on, let's get things moving here.'", case_study_cloze: "While waiting for the projector to load, the lecturer strummed his ____ on the lectern, silently urging things along.", sv: { concept: "Trumma med fingrarna", definition: "Att trumma med fingrarna mot ett bord eller ett ben f\u00e5r tiden att g\u00e5 och lugnar, precis som andra repetitiva beteenden. I professionella sammanhang ser man detta n\u00e4r m\u00e4nniskor v\u00e4ntar p\u00e5 att n\u00e5gon ska dyka upp eller sluta prata. Det \u00e4r ett s\u00e4tt att s\u00e4ga: 'Kom igen, nu s\u00e4tter vi ig\u00e5ng h\u00e4r.'", real_world_scenario: "I konferensrummet satt den seniora del\u00e4garen och trummade med fingrarna p\u00e5 bordet medan den sena kunden kopplades in \u2014 ett stillsamt, repetitivt s\u00e4tt att s\u00e4ga 'Kom igen, nu s\u00e4tter vi ig\u00e5ng h\u00e4r.'", case_study_cloze: "Medan han v\u00e4ntade p\u00e5 att projektorn skulle starta trummade f\u00f6rel\u00e4saren med sina ____ p\u00e5 katedern, f\u00f6r att stillsamt skynda p\u00e5." } },
      { concept: "HANDS IN POCKET", definition: "Many people are comforted by placing one or both hands in their pockets while talking to others. But sometimes this is seen as too informal and in some cultures is considered rude. It should be noted that some people erroneously view keeping hands in pockets as suspicious or deceptive.", category: "body-language-extracted", real_world_scenario: "At the family dinner, the teenage nephew stood talking with his hands in his pockets, which his grandmother found rude \u2014 though for him it was simply a comfort habit, not a sign of deception.", case_study_cloze: "Some people mistakenly view keeping the hands in one's ____ as suspicious or deceptive, when it is often just a comfort behavior.", sv: { concept: "H\u00e4nderna i fickorna", definition: "M\u00e5nga m\u00e4nniskor tr\u00f6stas av att placera en eller b\u00e5da h\u00e4nderna i fickorna n\u00e4r de pratar med andra. Men ibland uppfattas det som alltf\u00f6r informellt och i vissa kulturer anses det of\u00f6rsk\u00e4mt. Det b\u00f6r noteras att vissa personer felaktigt uppfattar h\u00e4nderna i fickorna som misst\u00e4nkt eller bedr\u00e4gligt.", real_world_scenario: "Vid familjemiddagen stod ton\u00e5rssystersonen och pratade med h\u00e4nderna i fickorna, vilket hans mormor tyckte var of\u00f6rsk\u00e4mt \u2014 f\u00f6r honom var det helt enkelt en vana som k\u00e4ndes sk\u00f6n, inte ett tecken p\u00e5 bedr\u00e4geri.", case_study_cloze: "Vissa m\u00e4nniskor uppfattar felaktigt h\u00e4nderna i ____ som misst\u00e4nkt eller bedr\u00e4gligt, n\u00e4r det ofta bara \u00e4r ett beteende f\u00f6r bekv\u00e4mlighet." } },
      { concept: "MASSAGING CLOSED FIST", definition: "Massaging the closed fist with the other hand is a self-restraining and pacifying behavior. It usually means the person is struggling or worried and experiencing a lot of underlying tension. You often see this with poker players and stock traders, or wherever fortunes might be quickly won or lost. 305. SPEAKER'S FIST -Sometimes we will see a speaker make a fist while \\\"hammering home a point.\\\" This is not unusual, especially from very dramatic or enthusiastic speakers. What is unusual is watching as someone waiting his turn to speak turns his hand into a fist. This usually indicates", category: "body-language-extracted", real_world_scenario: "At the trading desk, the broker massaged his closed fist with his other hand as the stock price kept falling \u2014 a self-restraining pacifier that gave away how much underlying tension he was feeling.", case_study_cloze: "The poker player massaged his closed ____ with his other hand while the pot grew \u2014 a self-restraining pacifier that revealed his worry.", sv: { concept: "Massera sluten n\u00e4ve", definition: "Att massera den slutna n\u00e4ven med den andra handen \u00e4r ett sj\u00e4lv\u00e5terh\u00e5llande och lugnande beteende. Det betyder vanligtvis att personen k\u00e4mpar eller oroar sig och upplever mycket underliggande sp\u00e4nning. Man ser det ofta hos pokerspelare och aktiem\u00e4klare, eller varhelst f\u00f6rm\u00f6genheter snabbt kan vinnas eller f\u00f6rloras.", real_world_scenario: "Vid handelsbordet masserade m\u00e4klaren sin slutna n\u00e4ve med den andra handen medan aktiekursen fortsatte att falla \u2014 ett sj\u00e4lv\u00e5terh\u00e5llande lugnande beteende som avsl\u00f6jade hur mycket underliggande sp\u00e4nning han k\u00e4nde.", case_study_cloze: "Pokerspelaren masserade sin slutna ____ med den andra handen medan potten v\u00e4xte \u2014 ett sj\u00e4lv\u00e5terh\u00e5llande lugnande beteende som avsl\u00f6jade hans oro." } },
      { concept: "RUBBING HANDS ON PALMS", definition: "Rubbing our fingers across the palm of the hand is a pacifier. When it is done repetitively, or with increased pressure, there is high anxiety and concern. We can rub the palm either with the fingertips of the same hand or against the opposite hand.", category: "body-language-extracted", real_world_scenario: "In the exam hall, the student rubbed her fingers across her palm again and again with increasing pressure \u2014 a pacifier that betrayed just how anxious she was before the test began.", case_study_cloze: "When the manager announced the layoffs, he repeatedly rubbed his fingers across his ____ \u2014 a pacifying behavior that revealed his concern.", sv: { concept: "Gnugga handflatorna", definition: "Att gnugga fingrarna \u00f6ver handflatan \u00e4r ett lugnande beteende. N\u00e4r det g\u00f6rs upprepat eller med \u00f6kat tryck tyder det p\u00e5 h\u00f6g \u00e5ngest och oro. Vi kan gnugga handflatan med fingertopparna p\u00e5 samma hand eller mot den motsatta handen.", real_world_scenario: "I tentamenssalen gned studenten sina fingrar \u00f6ver handflatan om och om igen med allt st\u00f6rre tryck \u2014 ett lugnande beteende som avsl\u00f6jade hur \u00e5ngestfylld hon var innan provet b\u00f6rjade.", case_study_cloze: "N\u00e4r chefen tillk\u00e4nnagav upps\u00e4gningarna gned han upprepade g\u00e5nger sina fingrar \u00f6ver sin ____ \u2014 ett lugnande beteende som avsl\u00f6jade hans oro." } },
      { concept: "TEEPEE FINGER RUB", definition: "When people feel concern, stress, anxiety, or fear, they might pacify themselves by rubbing their straightened interlaced fingers back and forth against one another. The interlaced fingers provide a greater surface area to stimulate as the hands and fingers are moved back and forth relieving tension. This is one of the best indicators that something is very wrong or someone is severely stressed. This behavior is usually reserved for when things are especially bad. In less dire situations, we will instead wring our hands or rub them together without interlacing the fingers. What makes this behavior stand out is that the fingers are ramrod straight and interlaced.", category: "body-language-extracted", real_world_scenario: "When the detective mentioned her son's name, the woman interlaced her fingers, held them ramrod straight, and rubbed them back and forth against one another \u2014 a teepee finger rub that told him something was very wrong.", case_study_cloze: "With her fingers ramrod straight and interlaced, she rubbed them back and forth against one another \u2014 a ____ that signals severe stress.", sv: { concept: "Tepee-gnuggning", definition: "N\u00e4r m\u00e4nniskor k\u00e4nner oro, stress, \u00e5ngest eller r\u00e4dsla kan de lugna sig genom att gnugga sina raka, sammanfl\u00e4tade fingrar fram och tillbaka mot varandra. De sammanfl\u00e4tade fingrarna ger en st\u00f6rre yta att stimulera n\u00e4r h\u00e4nder och fingrar r\u00f6rs fram och tillbaka, vilket lindrar sp\u00e4nning. Detta \u00e4r en av de b\u00e4sta indikatorerna p\u00e5 att n\u00e5got \u00e4r allvarligt fel eller att n\u00e5gon \u00e4r sv\u00e5rt stressad. Beteendet \u00e4r vanligtvis reserverat f\u00f6r n\u00e4r det \u00e4r riktigt illa. I mindre allvarliga situationer vrider vi ist\u00e4llet h\u00e4nderna eller gnuggar dem mot varandra utan att fl\u00e4ta samman fingrarna. Det som g\u00f6r detta beteende utm\u00e4rkande \u00e4r att fingrarna \u00e4r spikraka och sammanfl\u00e4tade.", real_world_scenario: "N\u00e4r detektiven n\u00e4mnde hennes sons namn fl\u00e4tade kvinnan samman fingrarna, h\u00f6ll dem spikraka och gned dem fram och tillbaka mot varandra \u2014 en tepee-gnuggning som talade om f\u00f6r honom att n\u00e5got var allvarligt fel.", case_study_cloze: "Med spikraka och sammanfl\u00e4tade fingrar gned hon dem fram och tillbaka mot varandra \u2014 en ____ som signalerar sv\u00e5r stress." } },
      { concept: "KNUCKLE CRACKING", definition: "Knuckle cracking, in all its varieties, is a pacifying behavior. The act of knuckle cracking for some people seems to soothe tension and so we see it when they are tense or nervous or even bored. People might crack each knuckle individually or all the fingers of one hand at once. This behavior increases in frequency with stress.", category: "body-language-extracted", real_world_scenario: "During the tense custody negotiation, the father cracked his knuckles one by one under the table \u2014 the cracking grew more frequent as the discussion became more heated.", case_study_cloze: "Knuckle ____ is a pacifying behavior that increases in frequency when a person is under stress.", sv: { concept: "Kn\u00e4cka knogar", definition: "Knogkn\u00e4ckning, i alla dess varianter, \u00e4r ett lugnande beteende. F\u00f6r vissa m\u00e4nniskor tycks knogkn\u00e4ckningen lugna sp\u00e4nningar, och d\u00e4rf\u00f6r ser vi den n\u00e4r de \u00e4r sp\u00e4nda, nerv\u00f6sa eller till och med uttr\u00e5kade. M\u00e4nniskor kan kn\u00e4cka varje knoge individuellt eller alla fingrar p\u00e5 en hand samtidigt. Detta beteende \u00f6kar i frekvens med stress.", real_world_scenario: "Under den sp\u00e4nda v\u00e5rdnadsf\u00f6rhandlingen kn\u00e4ckte pappan sina knogar en i taget under bordet \u2014 kn\u00e4ckandet blev allt t\u00e4tare ju hetare diskussionen blev.", case_study_cloze: "Att ____ knogarna \u00e4r ett lugnande beteende som \u00f6kar i frekvens n\u00e4r en person \u00e4r under stress." } },
      { concept: "TAPPING SIDES OF LEGS", definition: "People will tap their legs with the palms of their hands (usually near the pockets) when they are impatient or becoming aggravated. I see this all the time in people waiting to check in at hotels. The tactile nature and the repetition make this act both a distraction and a useful pacifier.", category: "body-language-extracted", real_world_scenario: "At the hotel front desk, the weary traveler tapped the sides of his legs with his palms while waiting to check in \u2014 a clear sign he was becoming impatient with the slow queue.", case_study_cloze: "Waiting for the delayed luggage, she tapped the sides of her ____ with her palms near her pockets \u2014 a pacifier that revealed her growing irritation.", sv: { concept: "Klappa p\u00e5 benens sidor", definition: "M\u00e4nniskor klappar p\u00e5 sina ben med handflatorna (vanligtvis n\u00e4ra fickorna) n\u00e4r de \u00e4r ot\u00e5liga eller b\u00f6rjar bli irriterade. Jag ser det hela tiden hos m\u00e4nniskor som v\u00e4ntar p\u00e5 att checka in p\u00e5 hotell. Den taktila karakt\u00e4ren och upprepningen g\u00f6r handlingen b\u00e5de till en distraktion och ett anv\u00e4ndbart lugnande beteende.", real_world_scenario: "Vid hotellreceptionen klappade den tr\u00f6tte resen\u00e4ren p\u00e5 sina bensidor med handflatorna medan han v\u00e4ntade p\u00e5 att checka in \u2014 ett tydligt tecken p\u00e5 att han b\u00f6rjade bli ot\u00e5lig \u00f6ver den l\u00e5ngsamma k\u00f6n.", case_study_cloze: "Medan hon v\u00e4ntade p\u00e5 det f\u00f6rsenade bagaget klappade hon p\u00e5 sina ____ med handflatorna n\u00e4ra fickorna \u2014 ett lugnande beteende som avsl\u00f6jade hennes v\u00e4xande irritation." } },
      { concept: "FINGERS CURLING, NAILS FLICKING", definition: "Often when people are nervous, agitated, or stressed, they will curl up their fingers (usually on one hand) and flick their nails against the thumb. They might flick one finger or use a variety of them. It is a way to pacify oneself and can be both distracting and noisy for others.", category: "body-language-extracted", real_world_scenario: "In the dentist's waiting room, the boy curled his fingers and flicked his fingernails against his thumb \u2014 a small, noisy pacifier that gave away how nervous he was.", case_study_cloze: "While waiting for her results, she curled her fingers and flicked her ____ against her thumb to pacify herself.", sv: { concept: "Kr\u00f6ka fingrarna och fippla med naglarna", definition: "Ofta n\u00e4r m\u00e4nniskor \u00e4r nerv\u00f6sa, uppr\u00f6rda eller stressade kr\u00f6ker de fingrarna (vanligtvis p\u00e5 en hand) och fipplar med naglarna mot tummen. De kan fippla med ett finger eller flera olika. Det \u00e4r ett s\u00e4tt att lugna sig sj\u00e4lv och kan vara b\u00e5de distraherande och h\u00f6gljutt f\u00f6r andra.", real_world_scenario: "I v\u00e4ntrummet hos tandl\u00e4karen kr\u00f6kte pojken fingrarna och fipplade med naglarna mot tummen \u2014 ett litet, h\u00f6gljutt lugnande beteende som avsl\u00f6jade hur nerv\u00f6s han var.", case_study_cloze: "Medan hon v\u00e4ntade p\u00e5 sina provresultat kr\u00f6kte hon fingrarna och fipplade med sina ____ mot tummen f\u00f6r att lugna sig." } },
      { concept: "TENDERED HANDSHAKE", definition: "In some cultures, most notably in parts of Africa, it is customary to greet a revered or important person by holding the outstretched right hand supported underneath the forearm by the left hand. The hand is literally being tendered or offered as if it were something precious, in the hope that the person to whom it is offered will take it, thus honoring the offeror. This gesture might look odd at first to Western observers, but it is a gesture of deference and high respect and should be accepted as such.", category: "body-language-extracted", real_world_scenario: "When the village elder arrived at the ceremony, the young leader greeted him by tenderly offering his outstretched right hand, supported beneath the forearm by his left hand \u2014 in his African culture, a gesture of deep deference and high respect.", case_study_cloze: "In parts of Africa, greeting a revered person with the right hand supported under the forearm by the left hand is a sign of ____ and high respect.", sv: { concept: "V\u00f6rdnadsfullt handslag", definition: "I vissa kulturer, framf\u00f6r allt i delar av Afrika, \u00e4r det sed att h\u00e4lsa en v\u00f6rdad eller viktig person genom att h\u00e5lla fram den utstr\u00e4ckta h\u00f6gra handen underst\u00f6dd under underarmen av den v\u00e4nstra handen. Handen erbjuds bokstavligen som om den vore n\u00e5got dyrbart, i hopp om att personen som den erbjuds till ska ta den och d\u00e4rmed hedra givaren. Gesten kan se konstig ut f\u00f6r v\u00e4sterl\u00e4ndska betraktare, men den \u00e4r en gest av underd\u00e5nighet och h\u00f6g respekt och b\u00f6r tas emot som s\u00e5dan.", real_world_scenario: "N\u00e4r by\u00e4ldsten anl\u00e4nde till ceremonin h\u00e4lsade den unge ledaren genom att v\u00f6rdnadsfullt erbjuda sin utstr\u00e4ckta h\u00f6gra hand, underst\u00f6dd under underarmen av den v\u00e4nstra \u2014 i hans afrikanska kultur en gest av djup underd\u00e5nighet och h\u00f6g respekt.", case_study_cloze: "I delar av Afrika \u00e4r att h\u00e4lsa en v\u00f6rdad person med h\u00f6ger hand underst\u00f6dd under underarmen av v\u00e4nster hand ett tecken p\u00e5 ____ och h\u00f6g respekt." } },
      { concept: "RING PLAYING", definition: "Playing with a wedding band by twirling it or taking it off and putting it on-is a repetitive behavior that people sometimes used to calm their nerves or pass the time. It is not, as some people claim, an indication of marital unhappiness. It is merely a self-soothing repetitive behavior.", category: "body-language-extracted", real_world_scenario: "During the long board meeting, the CFO twirled her wedding band around her finger \u2014 not a sign of marital trouble, just a repetitive way to soothe herself and pass the time.", case_study_cloze: "Twirling a wedding band is a self-soothing repetitive behavior and is not, as some claim, a sign of ____ unhappiness.", sv: { concept: "Leka med ringen", definition: "Att leka med en vigselring genom att snurra p\u00e5 den eller ta av och p\u00e5 den \u00e4r ett repetitivt beteende som m\u00e4nniskor ibland anv\u00e4nder f\u00f6r att lugna nerverna eller f\u00e5 tiden att g\u00e5. Det \u00e4r inte, som vissa p\u00e5st\u00e5r, ett tecken p\u00e5 olycka i \u00e4ktenskapet. Det \u00e4r helt enkelt ett sj\u00e4lvlugnande repetitivt beteende.", real_world_scenario: "Under det l\u00e5nga styrelsem\u00f6tet snurrade ekonomichefen sin vigselring runt fingret \u2014 inte ett tecken p\u00e5 \u00e4ktenskapsproblem, bara ett repetitivt s\u00e4tt att lugna sig sj\u00e4lv och f\u00e5 tiden att g\u00e5.", case_study_cloze: "Att snurra p\u00e5 vigselringen \u00e4r ett sj\u00e4lvlugnande repetitivt beteende och \u00e4r inte, som vissa p\u00e5st\u00e5r, ett tecken p\u00e5 ____ olycka." } },
      { concept: "DISTANCING FROM OBJECTS", definition: "When we have negative feelings toward something or someone, we often subconsciously attempt to distance ourselves. People on a diet may push a bread basket a few inches further away at dinner or even ask that empty wineglasses be removed from a table if they dislike alcoholic beverages. I have seen criminals refuse to touch a surveillance photograph or push it back across the table because they recognize themselves in the image. These are important behaviors to note because they speak to what is uppermost on that person's mind at the moment.", category: "body-language-extracted", real_world_scenario: "At dinner, the dieter nudged the bread basket a few inches further away \u2014 and later in the interview room, the suspect refused to touch the surveillance photograph and pushed it back across the table, because he recognized himself in the image.", case_study_cloze: "The suspect refused to touch the surveillance photograph and pushed it back across the table, because he ____ himself in the image.", sv: { concept: "Distansera sig fr\u00e5n f\u00f6rem\u00e5l", definition: "N\u00e4r vi har negativa k\u00e4nslor f\u00f6r n\u00e5got eller n\u00e5gon f\u00f6rs\u00f6ker vi ofta undermedvetet distansera oss. M\u00e4nniskor p\u00e5 diet kan skjuta br\u00f6dkorgen n\u00e5gra centimeter l\u00e4ngre bort vid middagen eller till och med be att tomma vinglas tas bort fr\u00e5n bordet om de inte gillar alkohol. Jag har sett brottslingar v\u00e4gra r\u00f6ra ett \u00f6vervakningsfoto eller skjuta tillbaka det \u00f6ver bordet eftersom de k\u00e4nner igen sig sj\u00e4lva p\u00e5 bilden. Detta \u00e4r viktiga beteenden att notera eftersom de talar om vad som st\u00e5r h\u00f6gst p\u00e5 personens sinne just d\u00e5.", real_world_scenario: "Vid middagen sk\u00f6t den bantande g\u00e4sten br\u00f6dkorgen n\u00e5gra centimeter l\u00e4ngre bort \u2014 och senare i f\u00f6rh\u00f6rsrummet v\u00e4grade den misst\u00e4nkte r\u00f6ra \u00f6vervakningsfotot och sk\u00f6t tillbaka det \u00f6ver bordet, eftersom han k\u00e4nde igen sig sj\u00e4lv p\u00e5 bilden.", case_study_cloze: "Den misst\u00e4nkte v\u00e4grade r\u00f6ra \u00f6vervakningsfotot och sk\u00f6t tillbaka det \u00f6ver bordet, eftersom han ____ igen sig sj\u00e4lv p\u00e5 bilden." } },
      { concept: "CHEST HEAVING, RAPID BREATHING", definition: "A heaving chest and rapid breathing usually indicate stress, concern, fear, worry, or anger. Context of course is important as there are many reasons for this behavior, including age, recent physical exertion, anxiety, or even a heart attack. What is important is to observe and be ready to take action if necessary.", category: "body-language-extracted", real_world_scenario: "After the surgeon's update, the patient's wife stood in the corridor with her chest heaving and her breathing rapid \u2014 a signal of fear that told the nurse to keep a close watch on her.", case_study_cloze: "A heaving chest and rapid breathing usually indicate stress, concern, ____, worry, or anger.", sv: { concept: "H\u00e4vande br\u00f6st, snabb andning", definition: "Ett h\u00e4vande br\u00f6st och snabb andning tyder vanligtvis p\u00e5 stress, oro, r\u00e4dsla, \u00e4ngslan eller ilska. Sammanhanget \u00e4r f\u00f6rst\u00e5s viktigt eftersom det finns m\u00e5nga orsaker till detta beteende, inklusive \u00e5lder, nylig fysisk anstr\u00e4ngning, \u00e5ngest eller till och med en hj\u00e4rtattack. Det viktiga \u00e4r att observera och vara redo att agera om det beh\u00f6vs.", real_world_scenario: "Efter kirurgens besked stod patientens fru i korridoren med h\u00e4vande br\u00f6st och snabb andning \u2014 en signal om r\u00e4dsla som fick sjuksk\u00f6terskan att h\u00e5lla ett vakande \u00f6ga p\u00e5 henne.", case_study_cloze: "Ett h\u00e4vande br\u00f6st och snabb andning tyder vanligtvis p\u00e5 stress, oro, ____, \u00e4ngslan eller ilska." } },
      { concept: "SHALLOW, FAST BREATHING", definition: "Breathing that is shallow and fast usually indicates fear or anxiety, perhaps even a panic attack. Watch for the shallowness of a person's breath to gauge their anxiety level. The shallower and more rapid the breathing, the greater the distress. Useful is to get them to take one long inhale then exhale for as long as possible (3 to 5 seconds) then repeat. This helps to lower the breathing rate.", category: "body-language-extracted", real_world_scenario: "On the flight, the passenger's breathing turned shallow and fast as turbulence hit \u2014 the flight attendant had her take one long inhale and then exhale for as long as possible, repeating until the breathing slowed.", case_study_cloze: "To calm a panicking person, have them take one long ____ and then exhale for as long as possible for three to five seconds, and repeat.", sv: { concept: "Ytlig, snabb andning", definition: "Andning som \u00e4r ytlig och snabb tyder vanligtvis p\u00e5 r\u00e4dsla eller \u00e5ngest, kanske till och med en panikattack. L\u00e4gg m\u00e4rke till hur ytlig en persons andning \u00e4r f\u00f6r att m\u00e4ta deras \u00e5ngestniv\u00e5. Ju ytligare och snabbare andningen \u00e4r, desto st\u00f6rre \u00e4r n\u00f6den. Anv\u00e4ndbart \u00e4r att f\u00e5 dem att ta ett l\u00e5ngt inandning och sedan andas ut s\u00e5 l\u00e4nge som m\u00f6jligt (3 till 5 sekunder) och sedan upprepa. Detta hj\u00e4lper till att s\u00e4nka andningsfrekvensen.", real_world_scenario: "P\u00e5 flyget blev passagerarens andning ytlig och snabb n\u00e4r turbulensen tog i \u2014 flygv\u00e4rdinnan l\u00e4t henne ta ett l\u00e5ngt inandning och sedan andas ut s\u00e5 l\u00e4nge som m\u00f6jligt, upprepat tills andningen lugnade sig.", case_study_cloze: "F\u00f6r att lugna en person i panik, l\u00e5t dem ta ett l\u00e5ngt ____ och sedan andas ut s\u00e5 l\u00e4nge som m\u00f6jligt i tre till fem sekunder, och upprepa." } },
      { concept: "PRESSING ON CHEST", definition: "In tense situations, a person will press on their own chest/diaphragm area with the thumb and middle finger (sometimes all of", category: "body-language-extracted", real_world_scenario: "When the teacher announced a surprise pop quiz, the anxious student pressed his thumb and middle finger on his chest and diaphragm \u2014 a quiet pacifying gesture in a tense moment.", case_study_cloze: "In tense situations, people press on their own ____ or diaphragm area with the thumb and middle finger to pacify themselves.", sv: { concept: "Trycka p\u00e5 br\u00f6stet", definition: "I sp\u00e4nda situationer trycker en person p\u00e5 sitt eget br\u00f6st/mellang\u00e4rde med tummen och l\u00e5ngfingret (ibland alla fingrar) som ett lugnande beteende f\u00f6r att hantera stressen.", real_world_scenario: "N\u00e4r l\u00e4raren tillk\u00e4nnagav ett \u00f6verraskningsprov tryckte den nerv\u00f6sa eleven tummen och l\u00e5ngfingret mot br\u00f6stet och mellang\u00e4rdet \u2014 en stillsam lugnande gest i ett sp\u00e4nt \u00f6gonblick.", case_study_cloze: "I sp\u00e4nda situationer trycker m\u00e4nniskor p\u00e5 sitt eget ____ eller mellang\u00e4rde med tummen och l\u00e5ngfingret f\u00f6r att lugna sig." } },
      { concept: "CLAVICLE MASSAGING", definition: "Under stress, individuals will massage the clavicle (collarbone) on the opposite side (e.g., placing their right hand upon their left clavicle). The arm drawn across the center of the body provides a feeling of protection, while the repetitive touching of the clavicle acts to soothe the person. This area of the body is very sensitive to touch-one reason it is considered an erogenous zone.", category: "body-language-extracted", real_world_scenario: "During the tense family conversation about the house sale, the mother placed her right hand on her left clavicle and massaged it in slow circles \u2014 the arm drawn across her body gave her a feeling of protection.", case_study_cloze: "Under stress, people often massage the ____ on the opposite side of the body, a soothing touch to a very sensitive area.", sv: { concept: "Massera nyckelbenet", definition: "Under stress masserar m\u00e4nniskor nyckelbenet p\u00e5 den motsatta sidan (till exempel genom att placera h\u00f6ger hand p\u00e5 v\u00e4nster nyckelben). Armen som dras \u00f6ver kroppens mitt ger en k\u00e4nsla av skydd, medan det repetitiva r\u00f6randet av nyckelbenet lugnar personen. Detta omr\u00e5de av kroppen \u00e4r mycket k\u00e4nsligt f\u00f6r ber\u00f6ring \u2014 en anledning till att det anses vara en erogen zon.", real_world_scenario: "Under det sp\u00e4nda familjesamtalet om husf\u00f6rs\u00e4ljningen placerade mamman h\u00f6ger hand p\u00e5 v\u00e4nster nyckelben och masserade det i l\u00e5ngsamma cirklar \u2014 armen som drogs \u00f6ver kroppen gav henne en k\u00e4nsla av skydd.", case_study_cloze: "Under stress masserar m\u00e4nniskor ofta ____ p\u00e5 den motsatta sidan av kroppen, en lugnande ber\u00f6ring av ett mycket k\u00e4nsligt omr\u00e5de." } },
      { concept: "PULLING CLOTHING TO VENTILATE", definition: "Pulling on the front of a shirt or other", category: "body-language-extracted", real_world_scenario: "During the difficult salary talk, the employee pulled the front of his shirt away from his chest to let air in \u2014 his body temperature had risen with the stress of the conversation.", case_study_cloze: "When stress raises a person's body temperature, they may pull on the front of their ____ to let air in and cool down.", sv: { concept: "Dra i kl\u00e4derna f\u00f6r att v\u00e4dra", definition: "Att dra i framsidan av en skjorta eller annat plagg f\u00f6r att v\u00e4dra och svalka kroppen. Detta sker ofta n\u00e4r n\u00e5gon \u00e4r stressad, eftersom kroppstemperaturen stiger under press, men det kan ocks\u00e5 ses i n\u00e4rvaro av n\u00e5gon vi tycker \u00e4r attraktiv.", real_world_scenario: "Under det sv\u00e5ra l\u00f6nesamtalet drog medarbetaren framsidan av skjortan ut fr\u00e5n br\u00f6stet f\u00f6r att sl\u00e4ppa in luft \u2014 kroppstemperaturen hade stigit med stressen i samtalet.", case_study_cloze: "N\u00e4r stress h\u00f6jer en persons kroppstemperatur kan de dra i framsidan av sin ____ f\u00f6r att sl\u00e4ppa in luft och svalka sig." } },
      { concept: "SITTING BACK", definition: "Pushing our chair back and leaning away from others at a table is in essence a distancing behavior that gives us additional insulation, so we can think and contemplate. Individuals who are unconvinced or still considering a point often will move slightly away until they are ready to engage, and then they will once again sit forward. For some it is a way to communicate they are taking themselves out for a few minutes to ponder this, or, and this is where other facial behaviors are useful, if they have decided they cannot support what is being discussed and so the pulling away is demonstrative of how they feel.", category: "body-language-extracted", real_world_scenario: "During the pitch, the investor pushed his chair back and leaned away the moment the founder mentioned the price \u2014 he was unconvinced, and only when the roadmap was explained did he sit forward again.", case_study_cloze: "When a listener leans back in his chair, it may mean he is unconvinced or still ____, and he will lean forward again once ready to engage.", sv: { concept: "Luta sig tillbaka", definition: "Att skjuta stolen bak\u00e5t och luta sig bort fr\u00e5n andra vid ett bord \u00e4r i huvudsak ett distanserande beteende som ger oss extra isolering, s\u00e5 att vi kan t\u00e4nka och begrunda. Personer som inte \u00e4r \u00f6vertygade eller fortfarande \u00f6verv\u00e4ger en po\u00e4ng flyttar sig ofta n\u00e5got undan tills de \u00e4r redo att engagera sig, och sedan sitter de \u00e5ter fram\u00e5tlutade. F\u00f6r vissa \u00e4r det ett s\u00e4tt att kommunicera att de tar n\u00e5gra minuters paus f\u00f6r att begrunda detta, eller, och det \u00e4r h\u00e4r andra ansiktsbeteenden \u00e4r anv\u00e4ndbara, om de har beslutat att de inte kan st\u00f6dja det som diskuteras, s\u00e5 \u00e4r bortflyttningen demonstrativ f\u00f6r hur de k\u00e4nner.", real_world_scenario: "Under pitchm\u00f6tet sk\u00f6t investeraren stolen bak\u00e5t och lutade sig bort i samma stund som grundaren n\u00e4mnde priset \u2014 han var inte \u00f6vertygad, och f\u00f6rst n\u00e4r f\u00e4rdplanen f\u00f6rklarades lutade han sig fram\u00e5t igen.", case_study_cloze: "N\u00e4r en lyssnare lutar sig tillbaka i stolen kan det betyda att han inte \u00e4r \u00f6vertygad eller fortfarande ____, och att han lutar sig fram\u00e5t igen n\u00e4r han \u00e4r redo att engagera sig." } },
      { concept: "SITTING FORWARD", definition: "When we are ready to negotiate in good faith, or compromise, we tend to move from a leaning-back position to a sitting- forward position. This often telegraphs that we have made up our minds to move forward. One has to be careful, if sitting at a table or desk that is", category: "body-language-extracted", real_world_scenario: "When the two managers finally agreed on the delivery timeline, both leaned forward in their chairs at the same moment \u2014 a shift that telegraphed their readiness to negotiate in good faith and move forward.", case_study_cloze: "Moving from a leaning-back position to a ____ position often signals that a person has decided to negotiate in good faith.", sv: { concept: "Luta sig fram\u00e5t", definition: "N\u00e4r vi \u00e4r redo att f\u00f6rhandla i god tro, eller kompromissa, tenderar vi att r\u00f6ra oss fr\u00e5n en tillbakalutad position till en fram\u00e5tlutad position. Detta signalerar ofta att vi har best\u00e4mt oss f\u00f6r att g\u00e5 fram\u00e5t. Man m\u00e5ste vara f\u00f6rsiktig, om man sitter vid ett bord eller skrivbord som \u00e4r...", real_world_scenario: "N\u00e4r de tv\u00e5 cheferna till slut enades om leveranstiden lutade sig b\u00e5da fram\u00e5t i sina stolar i samma \u00f6gonblick \u2014 en f\u00f6r\u00e4ndring som signalerade att de var redo att f\u00f6rhandla i god tro och g\u00e5 fram\u00e5t.", case_study_cloze: "Att flytta sig fr\u00e5n en tillbakalutad position till en ____ position signalerar ofta att en person har beslutat sig f\u00f6r att f\u00f6rhandla i god tro." } },
      { concept: "TURNING AWAY/VENTRAL DENIAL", definition: "Our ventral or belly side is one of the most vulnerable places on the body. We will turn it away from others when we don't like them, they make us uneasy, or we don't like what they say. Upon meeting someone you don't care for, your facial greeting might be friendly but your belly will subconsciously shift away-what is called ventral denial-in essence denying that person your most vulnerable side. This can even take place among friends if something disagreeable is said. A good way to remember this: \\\"Belly away don't want you to stay; belly away don't like what you say.\\\"", category: "body-language-extracted", real_world_scenario: "At the networking event, the executive smiled warmly when the pushy salesman approached, yet her shoulders and belly rotated away from him \u2014 ventral denial at work, her face saying hello while her torso said the opposite.", case_study_cloze: "Even when a greeting is friendly, the belly may subconsciously turn away from someone we dislike \u2014 a behavior called ____.", sv: { concept: "V\u00e4nda sig bort/ventral f\u00f6rnekelse", definition: "V\u00e5r ventrala eller magsida \u00e4r en av kroppens mest s\u00e5rbara platser. Vi v\u00e4nder bort den fr\u00e5n andra n\u00e4r vi inte gillar dem, n\u00e4r de g\u00f6r oss obekv\u00e4ma eller n\u00e4r vi inte gillar det de s\u00e4ger. N\u00e4r du m\u00f6ter n\u00e5gon du inte tycker om kan din ansiktsh\u00e4lsning vara v\u00e4nlig, men magen kommer undermedvetet att v\u00e4nda sig undan \u2014 det som kallas ventral f\u00f6rnekelse \u2014 i praktiken f\u00f6rnekar man den andra personen sin mest s\u00e5rbara sida. Detta kan till och med ske bland v\u00e4nner om n\u00e5got obehagligt s\u00e4gs. Ett bra s\u00e4tt att komma ih\u00e5g det: 'Mage bort vill inte att du stannar; mage bort gillar inte det du s\u00e4ger.'", real_world_scenario: "P\u00e5 minglet log chefen varmt n\u00e4r den p\u00e5flugne s\u00e4ljaren n\u00e4rmade sig, men hennes axlar och mage vred sig bort fr\u00e5n honom \u2014 ventral f\u00f6rnekelse i aktion, ansiktet sa hej medan b\u00e5len sa motsatsen.", case_study_cloze: "\u00c4ven n\u00e4r h\u00e4lsningen \u00e4r v\u00e4nlig kan magen undermedvetet v\u00e4nda sig bort fr\u00e5n n\u00e5gon vi inte gillar \u2014 ett beteende som kallas ____." } },
      { concept: "BELLY/VENTRAL FRONTING", definition: "When we like someone, we will turn our belly, or ventral side, toward her. We can see this behavior even in infants. It communicates that a person is interested and feels comfortable. When we meet someone while sitting down, if we like the person, we will, over time, reveal our shoulders and torso to that person as well. In summary, we show our gradual interest in others through ventral fronting.", category: "body-language-extracted", real_world_scenario: "At the first date, the woman kept her shoulders and torso turned fully toward her companion all evening, even leaning in over the table \u2014 a gradual ventral fronting that showed genuine interest.", case_study_cloze: "When we like someone, we turn our ____ side toward them \u2014 a signal of interest and comfort seen even in infants.", sv: { concept: "Mage/ventral frontning", definition: "N\u00e4r vi gillar n\u00e5gon v\u00e4nder vi magen, eller den ventrala sidan, mot henne. Vi kan se detta beteende \u00e4ven hos sp\u00e4dbarn. Det kommunicerar att en person \u00e4r intresserad och k\u00e4nner sig bekv\u00e4m. N\u00e4r vi tr\u00e4ffar n\u00e5gon sittande, om vi gillar personen, kommer vi med tiden att blotta axlar och b\u00e5l mot personen ocks\u00e5. Sammanfattningsvis visar vi v\u00e5rt gradvisa intresse f\u00f6r andra genom ventral frontning.", real_world_scenario: "P\u00e5 den f\u00f6rsta dejten h\u00f6ll kvinnan axlar och b\u00e5l v\u00e4nda helt mot sin f\u00f6ljeslagare hela kv\u00e4llen, och lutade sig till och med in \u00f6ver bordet \u2014 en gradvis ventral frontning som visade ett genuint intresse.", case_study_cloze: "N\u00e4r vi gillar n\u00e5gon v\u00e4nder vi v\u00e5r ____ sida mot dem \u2014 en signal om intresse och trygghet som syns redan hos sp\u00e4dbarn." } },
      { concept: "POSTURAL ECHOING (MIRRORING)", definition: "Our torso tends to echo the posture of those with whom we feel comfortable; this is called isopraxis. When standing with friends, people might find themselves mirroring one another's relaxed posture, a good sign that people are at ease together. In dating we will see one person lean forward, and the other, if comfortable, mimicking that behavior. Mirroring suggests agreement in conversation, mood, or temperament.", category: "body-language-extracted", real_world_scenario: "At the coffee shop, the two friends sat in identical relaxed postures without noticing, mirroring each other's lean \u2014 a good sign they were completely at ease together.", case_study_cloze: "When two people mirror one another's posture, it usually suggests ____ in conversation, mood, or temperament.", sv: { concept: "Postural ekande (spegling)", definition: "V\u00e5r b\u00e5l tenderar att eka h\u00e5llningen hos dem vi k\u00e4nner oss bekv\u00e4ma med; detta kallas isopraxis. N\u00e4r man st\u00e5r med v\u00e4nner kan man uppt\u00e4cka att man speglar varandras avslappnade h\u00e5llning, ett gott tecken p\u00e5 att m\u00e4nniskor trivs tillsammans. Vid dejting ser man att den ena lutar sig fram\u00e5t och den andra, om personen \u00e4r bekv\u00e4m, h\u00e4rmar beteendet. Spegling tyder p\u00e5 samst\u00e4mmighet i konversation, st\u00e4mning eller temperament.", real_world_scenario: "P\u00e5 kaf\u00e9et satt de tv\u00e5 v\u00e4nnerna i identiska avslappnade st\u00e4llningar utan att m\u00e4rka det och speglade varandras lutning \u2014 ett gott tecken p\u00e5 att de trivdes helt i varandras s\u00e4llskap.", case_study_cloze: "N\u00e4r tv\u00e5 m\u00e4nniskor speglar varandras h\u00e5llning tyder det vanligtvis p\u00e5 ____ i konversation, st\u00e4mning eller temperament." } },
      { concept: "RIGID SITTING", definition: "A person who sits very rigidly without moving for long periods is undergoing stress. This is part of the freeze response, often seen in forensic settings, police interviews, and depositions, when people are so", category: "body-language-extracted", real_world_scenario: "In the deposition room, the witness sat perfectly rigid in his chair for nearly an hour without shifting a muscle \u2014 the stillness of the freeze response under stress.", case_study_cloze: "A person who sits very ____ without moving for long periods is undergoing stress, part of the freeze response often seen in police interviews.", sv: { concept: "Stel sittst\u00e4llning", definition: "En person som sitter mycket stelt utan att r\u00f6ra sig under l\u00e5nga perioder \u00e4r under stress. Detta \u00e4r en del av frysresponsen, ofta sett i r\u00e4ttsmedicinska milj\u00f6er, polisf\u00f6rh\u00f6r och f\u00f6rh\u00f6r under ed, n\u00e4r m\u00e4nniskor \u00e4r s\u00e5...", real_world_scenario: "I f\u00f6rh\u00f6rsrummet satt vittnet helt stelt i stolen i n\u00e4stan en timme utan att r\u00f6ra en muskel \u2014 stillheten i frysresponsen under stress.", case_study_cloze: "En person som sitter mycket ____ utan att r\u00f6ra sig under l\u00e5nga perioder \u00e4r under stress, en del av frysresponsen som ofta ses i polisf\u00f6rh\u00f6r." } },
      { concept: "MOVING CHAIR AWAY", definition: "This is a form of distancing when leaning away from others is just not enough. Literally, the person just moves the chair further and further back or away as if no one would notice. I have seen acrimonious discussions in academia where one professor moved completely away from the table to the corner of the room near the window -as if this were somehow normal. This behavior is motivated on a subconscious level to protect one's ventral side through distancing from a perceived threat, even if the threat is mere words or ideas.", category: "body-language-extracted", real_world_scenario: "During the acrimonious faculty meeting, the professor quietly moved his chair further and further back until he sat by the window, far from the table \u2014 subconscious distancing from a conflict he could not stop.", case_study_cloze: "When leaning away is not enough, a person may simply ____ the chair further and further back to protect their ventral side.", sv: { concept: "Flytta stolen bort", definition: "Detta \u00e4r en form av distansering n\u00e4r det inte r\u00e4cker att luta sig bort fr\u00e5n andra. Bokstavligen flyttar personen bara stolen l\u00e4ngre och l\u00e4ngre bak\u00e5t eller bort, som om ingen skulle m\u00e4rka det. Jag har sett h\u00e4tska diskussioner i akademiska kretsar d\u00e4r en professor flyttade sig helt bort fr\u00e5n bordet till h\u00f6rnet av rummet n\u00e4ra f\u00f6nstret \u2014 som om detta p\u00e5 n\u00e5got s\u00e4tt var normalt. Detta beteende drivs p\u00e5 en undermedveten niv\u00e5 av att skydda sin ventrala sida genom distansering fr\u00e5n ett upplevt hot, \u00e4ven om hotet bara \u00e4r ord eller id\u00e9er.", real_world_scenario: "Under det h\u00e4tska l\u00e4rarm\u00f6tet flyttade professorn tyst sin stol l\u00e4ngre och l\u00e4ngre bort tills han satt vid f\u00f6nstret, l\u00e5ngt fr\u00e5n bordet \u2014 en undermedveten distansering fr\u00e5n en konflikt han inte kunde stoppa.", case_study_cloze: "N\u00e4r det inte r\u00e4cker att luta sig bort kan en person helt enkelt ____ stolen l\u00e4ngre och l\u00e4ngre bak\u00e5t f\u00f6r att skydda sin ventrala sida." } },
      { concept: "BODY SLOUCHING", definition: "Slouching projects relaxation or indifference, depending on context. It is a perception-management technique often used by teenagers in dealing with their parents to demonstrate they don't care. In any formal professional setting, slouching should be avoided.", category: "body-language-extracted", real_world_scenario: "Asked to clean his room, the teenager slumped down in the kitchen chair with his shoulders low \u2014 slouching as a perception-management statement that he did not care.", case_study_cloze: "Teenagers often slouch when dealing with their parents as a way to demonstrate that they ____.", sv: { concept: "Sjunkna ihop", definition: "Att sjunka ihop utstr\u00e5lar avslappning eller likgiltighet, beroende p\u00e5 sammanhang. Det \u00e4r en intrycksstyrningsteknik som ofta anv\u00e4nds av ton\u00e5ringar i umg\u00e4nget med sina f\u00f6r\u00e4ldrar f\u00f6r att visa att de inte bryr sig. I alla formella professionella sammanhang b\u00f6r man undvika att sjunka ihop.", real_world_scenario: "N\u00e4r han blev ombedd att st\u00e4da rummet sj\u00f6nk ton\u00e5ringen ihop i k\u00f6ksstolen med l\u00e5ga axlar \u2014 att sjunka ihop som ett s\u00e4tt att styra intrycket och visa att han inte brydde sig.", case_study_cloze: "Ton\u00e5ringar sjunker ofta ihop i umg\u00e4nget med sina f\u00f6r\u00e4ldrar som ett s\u00e4tt att visa att de ____." } },
      { concept: "DOUBLING OVER", definition: "People in emotional turmoil might bend forward at the waist while seated or standing, as though experiencing intestinal distress. Usually they do this with their arms tucked across their stomach. We see this behavior in hospitals and anyplace else where people might receive especially bad or shocking news.", category: "body-language-extracted", real_world_scenario: "When the doctor gave her the diagnosis, the woman doubled over at the waist with her arms tucked across her stomach, as though struck hard in the gut by the news.", case_study_cloze: "People in emotional turmoil may ____ at the waist with their arms tucked across their stomach, as though experiencing intestinal distress.", sv: { concept: "Vika sig dubbel", definition: "M\u00e4nniskor i k\u00e4nslom\u00e4ssig uppr\u00f6rdhet kan b\u00f6ja sig fram\u00e5t i midjan sittande eller st\u00e5ende, som om de upplevde tarmbesv\u00e4r. Vanligtvis g\u00f6r de detta med armarna instoppade \u00f6ver magen. Vi ser detta beteende p\u00e5 sjukhus och p\u00e5 alla andra platser d\u00e4r m\u00e4nniskor kan f\u00e5 s\u00e4rskilt d\u00e5liga eller chockerande nyheter.", real_world_scenario: "N\u00e4r l\u00e4karen gav henne diagnosen vek kvinnan sig dubbel i midjan med armarna instoppade \u00f6ver magen, som om beskedet hade tr\u00e4ffat henne h\u00e5rt i solar plexus.", case_study_cloze: "M\u00e4nniskor i k\u00e4nslom\u00e4ssig uppr\u00f6rdhet kan ____ sig i midjan med armarna instoppade \u00f6ver magen, som om de upplevde tarmbesv\u00e4r." } },
      { concept: "FETAL POSITION", definition: "Under extreme psychological stress people might enter the fetal position. This is sometimes seen during intense arguments between couples, where one partner is so overwhelmed with emotions she will bring her knees up and sit in the fetal position-silent-to deal with the stress. She might also gather a pillow or some other object to hold against her belly ( see #339).", category: "body-language-extracted", real_world_scenario: "During the intense argument, his wife went silent, drew her knees up to her chest, and sat curled in the fetal position on the sofa with a pillow pressed against her belly \u2014 completely overwhelmed by emotion.", case_study_cloze: "Under extreme psychological stress, a person may bring the knees up and sit in the ____ position, silent, to cope with the stress.", sv: { concept: "Fosterst\u00e4llning", definition: "Under extrem psykisk stress kan m\u00e4nniskor inta fosterst\u00e4llning. Detta ses ibland under intensiva gr\u00e4l mellan partners, d\u00e4r en partner \u00e4r s\u00e5 \u00f6verv\u00e4ldigad av k\u00e4nslor att hon drar upp kn\u00e4na och sitter i fosterst\u00e4llning \u2014 tyst \u2014 f\u00f6r att hantera stressen. Hon kan ocks\u00e5 samla en kudde eller n\u00e5got annat f\u00f6rem\u00e5l att h\u00e5lla mot magen.", real_world_scenario: "Under det intensiva gr\u00e4let tystnade hans fru, drog upp kn\u00e4na mot br\u00f6stet och satt hopkrupen i fosterst\u00e4llning i soffan med en kudde tryckt mot magen \u2014 helt \u00f6verv\u00e4ldigad av k\u00e4nslor.", case_study_cloze: "Under extrem psykisk stress kan en person dra upp kn\u00e4na och sitta i ____ st\u00e4llning, tyst, f\u00f6r att hantera stressen." } },
      { concept: "BODY CHILL", definition: "Stress can cause individuals to feel cold in an otherwise", category: "body-language-extracted", real_world_scenario: "The suspect began to shiver in the warm interview room when the evidence was laid out on the table \u2014 a body chill that the stress had triggered in an otherwise warm environment.", case_study_cloze: "Even in a warm room, stress can cause a person to feel cold and shiver \u2014 a phenomenon known as a ____.", sv: { concept: "Kroppsrysning", definition: "Stress kan f\u00e5 m\u00e4nniskor att k\u00e4nna sig kalla i en annars varm milj\u00f6. Kroppen kan b\u00f6rja darra eller rysa som svar p\u00e5 det nerv\u00f6sa trycket, \u00e4ven n\u00e4r temperaturen \u00e4r behaglig.", real_world_scenario: "Den misst\u00e4nkte b\u00f6rjade rysa i det varma f\u00f6rh\u00f6rsrummet n\u00e4r bevisen lades fram p\u00e5 bordet \u2014 en kroppsrysning som stressen hade utl\u00f6st i en annars varm milj\u00f6.", case_study_cloze: "\u00c4ven i ett varmt rum kan stress f\u00e5 en person att k\u00e4nna sig kall och rysa \u2014 ett fenomen som kallas ____." } },
      { concept: "DRESSING THE TORSO", definition: "Because our torso displays most of our clothing, it is important to mention here that clothing communicates and can give advantages to the wearer. Clothes often serve to project status within a culture. From name brands to the colors that we wear, clothing makes a difference in how we are perceived. It can make us more submissive or more authoritarian, or it can propel us into the job that we want. It can also communicate where we are from or even where we are going as well as what issues we might be having. In every culture studied, clothes play a significant role. It is one more thing we must consider when we assess individuals to decode information they convey about themselves.", category: "body-language-extracted", real_world_scenario: "For the job interview, Erik chose a dark tailored suit instead of his usual hoodie \u2014 aware that the clothes on his torso would project status and seriousness before he had said a single word.", case_study_cloze: "From name brands to the colors we wear, our ____ makes a difference in how others perceive us.", sv: { concept: "Kl\u00e4dsel p\u00e5 b\u00e5len", definition: "Eftersom v\u00e5r b\u00e5l visar upp det mesta av v\u00e5ra kl\u00e4der \u00e4r det viktigt att n\u00e4mna att kl\u00e4der kommunicerar och kan ge b\u00e4raren f\u00f6rdelar. Kl\u00e4der tj\u00e4nar ofta till att projicera status inom en kultur. Fr\u00e5n varum\u00e4rken till de f\u00e4rger vi b\u00e4r g\u00f6r kl\u00e4der skillnad i hur vi uppfattas. De kan g\u00f6ra oss mer undergivna eller mer auktorit\u00e4ra, eller s\u00e5 kan de f\u00f6ra oss in i jobbet vi vill ha. De kan ocks\u00e5 kommunicera var vi kommer ifr\u00e5n eller vart vi \u00e4r p\u00e5 v\u00e4g, liksom vilka problem vi kan ha. I varje studerad kultur spelar kl\u00e4der en betydande roll. Det \u00e4r ytterligare en sak vi m\u00e5ste beakta n\u00e4r vi bed\u00f6mer m\u00e4nniskor f\u00f6r att avkoda information de f\u00f6rmedlar om sig sj\u00e4lva.", real_world_scenario: "Inf\u00f6r anst\u00e4llningsintervjun valde Erik en m\u00f6rk skr\u00e4ddarsydd kostym i st\u00e4llet f\u00f6r sin vanliga hoodie \u2014 medveten om att kl\u00e4derna p\u00e5 b\u00e5len skulle f\u00f6rmedla status och seriositet innan han sagt ett enda ord.", case_study_cloze: "Fr\u00e5n varum\u00e4rken till de f\u00e4rger vi b\u00e4r g\u00f6r v\u00e5ra ____ skillnad i hur andra uppfattar oss." } },
      { concept: "BELLY COVERING DURING PREGNANCY", definition: "Women often cover their suprasternal notch or throat with a hand when they feel concerned or insecure. But when they are pregnant, they will often raise their hand as if to go to the neck but then quickly move it to cover their belly, seemingly to protect their fetus.", category: "body-language-extracted", real_world_scenario: "During the heated staff meeting, the pregnant accountant raised her hand toward her neck \u2014 then, mid-motion, redirected it to rest protectively over her belly.", case_study_cloze: "When concerned, a pregnant woman may raise her hand toward her neck but then quickly move it to cover her ____, seemingly to protect her fetus.", sv: { concept: "T\u00e4cka magen under graviditet", definition: "Kvinnor t\u00e4cker ofta sitt \u00f6vre br\u00f6stben eller halsen med en hand n\u00e4r de k\u00e4nner sig bekymrade eller otrygga. Men n\u00e4r de \u00e4r gravida lyfter de ofta handen som f\u00f6r att g\u00e5 till halsen men flyttar den sedan snabbt till att t\u00e4cka magen, tydligen f\u00f6r att skydda fostret.", real_world_scenario: "Under det hetsiga personalm\u00f6tet lyfte den gravida revisorn handen mot halsen \u2014 och v\u00e4nde sedan, mitt i r\u00f6relsen, om och l\u00e4t den vila skyddande \u00f6ver magen.", case_study_cloze: "N\u00e4r en gravid kvinna k\u00e4nner sig bekymrad kan hon lyfta handen mot halsen men sedan snabbt flytta den till att t\u00e4cka sin ____, tydligen f\u00f6r att skydda fostret." } },
      { concept: "BELLY RUBBING", definition: "Pregnant women will often repeatedly rub their belly to deal with discomfort, but also subconsciously to protect the fetus. Because it is a repetitive tactile behavior, it also serves as a pacifier and some researchers say it even helps to release oxytocin into the bloodstream.", category: "body-language-extracted", real_world_scenario: "As she waited for her ultrasound appointment, the expectant mother gently rubbed her belly in slow circles \u2014 a repetitive, soothing motion that comforted both her and her unborn baby.", case_study_cloze: "Pregnant women often rub their ____ repetitively \u2014 a pacifying behavior that researchers say may even release oxytocin.", sv: { concept: "Gnugga magen", definition: "Gravida kvinnor gnuggar ofta upprepade g\u00e5nger sin mage f\u00f6r att hantera obehag, men ocks\u00e5 undermedvetet f\u00f6r att skydda fostret. Eftersom det \u00e4r ett repetitivt taktilt beteende fungerar det ocks\u00e5 som ett lugnande medel, och vissa forskare s\u00e4ger att det till och med hj\u00e4lper till att frig\u00f6ra oxytocin i blodomloppet.", real_world_scenario: "Medan hon v\u00e4ntade p\u00e5 sin ultraljudstid gned den blivande mamman f\u00f6rsiktigt sin mage i l\u00e5ngsamma cirklar \u2014 en repetitiv, lugnande r\u00f6relse som tr\u00f6stade b\u00e5de henne och hennes of\u00f6dda barn.", case_study_cloze: "Gravida kvinnor gnuggar ofta upprepade g\u00e5nger sin ____ \u2014 ett lugnande beteende som forskare menar till och med kan frig\u00f6ra oxytocin." } },
      { concept: "HIP/BUTTOCK SHIFTING", definition: "Hip swiveling or buttock wiggling is a way of dealing with stress, boredom, or the fatigue of sitting in one place. People might also do this during contentious debates, either when their emotions have been riled up or just afterward, as a process of calming down. You rarely see this with couples early on in their relationship; it tends to show up, if at all, down the road when there are issues being discussed.", category: "body-language-extracted", real_world_scenario: "During the heated family debate about the inheritance, the aunt kept shifting her hips and wiggling in her chair \u2014 a way of calming her riled-up emotions in the middle of the argument.", case_study_cloze: "Hip swiveling or buttock wiggling is a way of dealing with stress, ____, or the fatigue of sitting in one place.", sv: { concept: "Flytta p\u00e5 h\u00f6fterna/ruva p\u00e5 stussen", definition: "H\u00f6ftsv\u00e4ngning eller gungande p\u00e5 stussen \u00e4r ett s\u00e4tt att hantera stress, uttr\u00e5kning eller tr\u00f6ttheten av att sitta stilla p\u00e5 en plats. M\u00e4nniskor kan ocks\u00e5 g\u00f6ra detta under hetsiga debatter, antingen n\u00e4r deras k\u00e4nslor har hetsats upp eller direkt efter\u00e5t, som en process f\u00f6r att lugna ner sig. Du ser s\u00e4llan detta hos par tidigt i deras f\u00f6rh\u00e5llande; det brukar dyka upp, om alls, l\u00e4ngre fram n\u00e4r det finns fr\u00e5gor som diskuteras.", real_world_scenario: "Under den hetsiga familjedebatten om arvet flyttade mostern hela tiden p\u00e5 h\u00f6fterna och gungade i stolen \u2014 ett s\u00e4tt att lugna sina upphetsade k\u00e4nslor mitt i gr\u00e4let.", case_study_cloze: "H\u00f6ftsv\u00e4ngning eller gungande p\u00e5 stussen \u00e4r ett s\u00e4tt att hantera stress, ____ eller tr\u00f6ttheten av att sitta stilla p\u00e5 en plats." } },
      { concept: "HIP RUBBING", definition: "Under stress, people will rub the side of their hips and legs as a pacifier. It is also used to dry sweaty hands when feeling nervous. You see this gesture as students prepare to take a test or as travelers go through customs.", category: "body-language-extracted", real_world_scenario: "Standing in the customs line, the traveler rubbed the sides of her hips and legs \u2014 a pacifier under stress that also helped dry her sweaty palms.", case_study_cloze: "Before a difficult exam, students may rub the sides of their ____ and legs as a pacifier, sometimes to dry sweaty hands.", sv: { concept: "Gnugga h\u00f6fterna", definition: "Under stress gnuggar m\u00e4nniskor sidorna av sina h\u00f6fter och ben som ett lugnande beteende. Det anv\u00e4nds ocks\u00e5 f\u00f6r att torka svettiga h\u00e4nder n\u00e4r man \u00e4r nerv\u00f6s. Du ser denna gest n\u00e4r studenter f\u00f6rbereder sig f\u00f6r ett prov eller n\u00e4r resen\u00e4rer g\u00e5r igenom tullen.", real_world_scenario: "I k\u00f6n till tullen gned resen\u00e4ren sidorna av sina h\u00f6fter och ben \u2014 ett lugnande beteende under stress som ocks\u00e5 hj\u00e4lpte henne att torka svettiga handflator.", case_study_cloze: "Inf\u00f6r ett sv\u00e5rt prov kan studenter gnugga sidorna av sina ____ och ben som ett lugnande beteende, ibland f\u00f6r att torka svettiga h\u00e4nder." } },
      { concept: "GENITAL TOUCHING", definition: "Teachers often report how young boys, and sometimes girls, will touch or pull at their genitals through their clothing. This is quite natural; the genitals contain an extraordinary number of nerve endings, which, when touched, not only soothe or calm children, but feels pleasant. Eventually kids outgrow this behavior, and it is not unusual or anything to be overly concerned about.", category: "body-language-extracted", real_world_scenario: "The kindergarten teacher smiled at the little boy absently touching himself through his pants while he listened to the story \u2014 a natural, self-soothing habit that children outgrow.", case_study_cloze: "Young children sometimes touch or pull at their ____ through their clothing \u2014 a natural behavior, since the area has many nerve endings that soothe them.", sv: { concept: "R\u00f6ra vid k\u00f6nsorganen", definition: "L\u00e4rare rapporterar ofta hur sm\u00e5 pojkar, och ibland flickor, r\u00f6r vid eller drar i sina k\u00f6nsorgan genom kl\u00e4derna. Detta \u00e4r helt naturligt; k\u00f6nsorganen inneh\u00e5ller ett extraordin\u00e4rt antal nerv\u00e4ndar, som n\u00e4r de ber\u00f6rs inte bara lugnar barn utan ocks\u00e5 k\u00e4nns behagligt. S\u00e5 sm\u00e5ningom v\u00e4xer barn ifr\u00e5n detta beteende, och det \u00e4r varken ovanligt eller n\u00e5got att oroa sig alltf\u00f6r mycket \u00f6ver.", real_world_scenario: "F\u00f6rskoll\u00e4raren log \u00e5t den lille pojken som tankspritt r\u00f6rde vid sig genom byxorna medan han lyssnade p\u00e5 sagan \u2014 en naturlig, sj\u00e4lvlugnande vana som barn v\u00e4xer ifr\u00e5n.", case_study_cloze: "Sm\u00e5 barn r\u00f6r ibland vid eller drar i sina ____ genom kl\u00e4derna \u2014 ett naturligt beteende, eftersom omr\u00e5det har m\u00e5nga nerv\u00e4ndar som lugnar dem." } },
      { concept: "CROTCH GRABBING", definition: "This behavior, made famous by Michael Jackson while dancing, shocked many when first performed, yet today it is quite common in entertainers. There are many theories as to why some men do this: to garner attention, as a manhood display, or merely to adjust for comfort. On adult males, it can be quite disturbing if done repetitively and at a close distance such as an office, as women have reported to me. It certainly should be avoided in public.", category: "body-language-extracted", real_world_scenario: "At the office party, the colleague repeatedly grabbed his crotch while chatting close to the women he was talking with \u2014 a behavior they found disturbing, and one that should certainly be avoided in public.", case_study_cloze: "Repetitive ____ at a close distance, such as in an office, can be quite disturbing to those nearby and should be avoided in public.", sv: { concept: "Ta sig i skrevet", definition: "Detta beteende, gjort k\u00e4nt av Michael Jackson n\u00e4r han dansade, chockerade m\u00e5nga n\u00e4r det f\u00f6rst upptr\u00e4dde, men idag \u00e4r det ganska vanligt bland underh\u00e5llare. Det finns m\u00e5nga teorier om varf\u00f6r vissa m\u00e4n g\u00f6r detta: f\u00f6r att v\u00e4cka uppm\u00e4rksamhet, som en manlighetsmarkering, eller bara f\u00f6r att justera f\u00f6r bekv\u00e4mlighet. Hos vuxna m\u00e4n kan det vara ganska st\u00f6rande om det g\u00f6rs upprepat och p\u00e5 n\u00e4ra h\u00e5ll, som p\u00e5 ett kontor, vilket kvinnor har rapporterat till mig. Det b\u00f6r definitivt undvikas offentligt.", real_world_scenario: "P\u00e5 kontorsfesten tog kollegan upprepade g\u00e5nger sig i skrevet medan han pratade n\u00e4ra kvinnorna han stod med \u2014 ett beteende de fann st\u00f6rande, och ett som definitivt b\u00f6r undvikas offentligt.", case_study_cloze: "Upprepade ____ p\u00e5 n\u00e4ra h\u00e5ll, till exempel p\u00e5 ett kontor, kan vara ganska st\u00f6rande f\u00f6r dem i n\u00e4rheten och b\u00f6r undvikas offentligt." } },
      { concept: "GENITAL FRAMING", definition: "Often done by cowboys in movies or in photographs, this is where the man places the thumbs inside the pants or hooks them on", category: "body-language-extracted", real_world_scenario: "In the country-western bar, the singer hooked his thumbs on his belt at his hips while he sang \u2014 a cowboy-style pose that framed the genital area as a confident, masculine display.", case_study_cloze: "A man may hook his ____ on his belt at his hips in a cowboy pose, a gesture called genital framing that displays masculinity.", sv: { concept: "Inramning av skrevet", definition: "Ofta gjort av cowboys i filmer eller p\u00e5 fotografier: mannen placerar tummarna innanf\u00f6r byxorna eller hakar fast dem p\u00e5 b\u00e4ltet, vilket ramar in och framh\u00e4ver det genitala omr\u00e5det som en maskulinitets- och sj\u00e4lvs\u00e4kerhetsmarkering.", real_world_scenario: "P\u00e5 countrybaren h\u00e4ngde s\u00e5ngaren tummarna i b\u00e4ltet vid h\u00f6fterna medan han sj\u00f6ng \u2014 en cowboystil som ramade in skrevpartiet som en sj\u00e4lvs\u00e4ker, maskulin markering.", case_study_cloze: "En man kan haka sina ____ p\u00e5 b\u00e4ltet vid h\u00f6fterna i en cowboyst\u00e4llning, en gest som kallas inramning av skrevet och som visar maskulinitet." } },
      { concept: "SITTING KNEES FAR APART", definition: "Often referred to as \\\"manspreading,\\\" this is where a man sits, often on public transportation, with the knees far apart. This is considered rude due to how much space a person takes up in this position, and the less-than-diplomatic display of the inner legs and the crotch, and it is inconsiderate.", category: "body-language-extracted", real_world_scenario: "On the crowded morning bus, the passenger sat with his knees spread wide, taking up a seat and a half while other commuters squeezed past \u2014 a classic case of manspreading that annoyed everyone nearby.", case_study_cloze: "Sitting with the knees far apart on public transportation is often called ____ and is considered rude and inconsiderate.", sv: { concept: "Sitta med kn\u00e4na brett is\u00e4r", definition: "Ofta kallat 'manspreading': en man sitter, ofta p\u00e5 kollektivtrafik, med kn\u00e4na brett is\u00e4r. Detta anses of\u00f6rsk\u00e4mt p\u00e5 grund av hur mycket plats en person tar upp i denna position, och den mindre diplomatiska exponeringen av innersidorna av benen och skrevet, och det \u00e4r h\u00e4nsynsl\u00f6st.", real_world_scenario: "P\u00e5 den fullsatta morgonbussen satt passageraren med kn\u00e4na brett is\u00e4r och tog upp en och en halv sittplats medan andra resen\u00e4rer fick tr\u00e4nga sig f\u00f6rbi \u2014 ett klassiskt fall av manspreading som irriterade alla i n\u00e4rheten.", case_study_cloze: "Att sitta med kn\u00e4na brett is\u00e4r p\u00e5 kollektivtrafiken kallas ofta ____ och anses of\u00f6rsk\u00e4mt och h\u00e4nsynsl\u00f6st." } },
      { concept: "SPATIAL DISTANCING", definition: "The anthropologist Edward T. Hall coined the term proxemics to describe the need all animals have for personal space. If someone stands too close to us, we are uncomfortable. Our spatial needs are based on both culture and personal preference. Most Americans feel comfortable in public spaces at a distance of 12 to 25 feet from others; in social spaces 4 to 12 feet is preferred; while our personal space is comfortable at about 1.5 to 4 feet. When it comes to our intimate space, anything less than a foot, we are very sensitive to who gets that close. These are of course approximations, as it is different for everyone and varies with culture, nationality, location, and even time of day. At night we might not feel comfortable walking near a stranger who is closer than ten feet.", category: "body-language-extracted", real_world_scenario: "At the crowded networking event, the man stepped back twice when the recruiter leaned in too close \u2014 his personal space, roughly one and a half to four feet, had been invaded.", case_study_cloze: "Edward T. Hall coined the term ____ to describe the need all animals have for personal space.", sv: { concept: "Rumslig distansering", definition: "Antropologen Edward T. Hall myntade termen proxemik f\u00f6r att beskriva det behov alla djur har av personligt utrymme. Om n\u00e5gon st\u00e5r f\u00f6r n\u00e4ra oss k\u00e4nner vi oss obekv\u00e4ma. V\u00e5ra rumsliga behov baseras b\u00e5de p\u00e5 kultur och personliga preferenser. De flesta amerikaner k\u00e4nner sig bekv\u00e4ma p\u00e5 allm\u00e4nna platser p\u00e5 ett avst\u00e5nd av 12 till 25 fot fr\u00e5n andra; i sociala utrymmen f\u00f6redras 4 till 12 fot; medan v\u00e5rt personliga utrymme \u00e4r bekv\u00e4mt p\u00e5 cirka 1,5 till 4 fot. N\u00e4r det g\u00e4ller v\u00e5rt intima utrymme, mindre \u00e4n en fot, \u00e4r vi mycket k\u00e4nsliga f\u00f6r vem som kommer s\u00e5 n\u00e4ra. Dessa \u00e4r naturligtvis uppskattningar, eftersom det skiljer sig f\u00f6r alla och varierar med kultur, nationalitet, plats och till och med tid p\u00e5 dygnet. P\u00e5 natten kanske vi inte k\u00e4nner oss bekv\u00e4ma med att g\u00e5 n\u00e4ra en fr\u00e4mling som \u00e4r n\u00e4rmare \u00e4n tio fot.", real_world_scenario: "P\u00e5 det tr\u00e5nga minglet tog mannen tv\u00e5 steg bak\u00e5t n\u00e4r rekryteraren lutade sig in f\u00f6r n\u00e4ra \u2014 hans personliga utrymme, ungef\u00e4r 1,5 till 4 fot, hade invaderats.", case_study_cloze: "Edward T. Hall myntade termen ____ f\u00f6r att beskriva det behov alla djur har av personligt utrymme." } },
      { concept: "TERRITORIAL STANCE", definition: "We use our legs as a form of territorial display by how we stand. The further apart our feet, the greater the territorial display.", category: "body-language-extracted", real_world_scenario: "At the police briefing, the lead detective stood with his feet planted far apart in front of the whiteboard \u2014 the wide stance broadcast his authority to the whole room before he said a word.", case_study_cloze: "The supervisor's wide ____ as he stood before the team made his territorial claim obvious to everyone.", sv: { concept: "Bredbent st\u00e4llning", definition: "Vi anv\u00e4nder benen som en form av territoriell markering genom hur vi st\u00e5r. Ju l\u00e4ngre is\u00e4r f\u00f6tterna st\u00e5r, desto st\u00f6rre \u00e4r den territoriella markeringen.", real_world_scenario: "Vid polisbriefingen stod den ledande kommissarien med f\u00f6tterna brett is\u00e4r framf\u00f6r whiteboarden \u2014 den bredbenta st\u00e4llningen signalerade auktoritet till hela rummet innan han sagt ett ord.", case_study_cloze: "Chefens bredbenta ____ framf\u00f6r teamet gjorde hans territoriella anspr\u00e5k uppenbart f\u00f6r alla." } },
      { concept: "SETTING PACE DURING WALK", definition: "Whoever sets the walking pace in a group is usually the person in charge. We will speed up or slow down for the most senior person or group leader. Even teenagers will do this, deferring to the most socially prominent one among them by walking at that person's pace. This might mean the last person in a group is the leader and is setting the pace to walk no faster. In analyzing groups remember that it is not who is in front but rather who sets the pace that is in charge.", category: "body-language-extracted", real_world_scenario: "Walking to the conference room, the CEO strolled at a leisurely pace while the junior staff around her unconsciously slowed down to match her \u2014 she was setting the tempo, and everyone fell in line.", case_study_cloze: "During the group walk to the meeting, everyone slowed to match the director's pace, revealing that whoever sets the ____ is the one in charge.", sv: { concept: "Att s\u00e4tta promenadtempot", definition: "Den som s\u00e4tter promenadtempot i en grupp \u00e4r oftast den som best\u00e4mmer. Vi \u00f6kar eller saktar ner farten f\u00f6r den mest seniora personen eller gruppledaren. \u00c4ven ton\u00e5ringar g\u00f6r detta och anpassar sig till den socialt mest framtr\u00e4dande i gruppen genom att g\u00e5 i den personens takt. Det kan inneb\u00e4ra att den sista personen i gruppen \u00e4r ledaren och s\u00e4tter tempot genom att inte g\u00e5 snabbare. N\u00e4r man analyserar grupper ska man komma ih\u00e5g att det inte \u00e4r den som g\u00e5r l\u00e4ngst fram utan den som s\u00e4tter tempot som har makten.", real_world_scenario: "P\u00e5 v\u00e4g till konferensrummet gick VD:n i ett lugnt tempo medan de yngre medarbetarna runt henne omedvetet saktade in f\u00f6r att matcha henne \u2014 hon satte tempot och alla f\u00f6ll in i ledet.", case_study_cloze: "N\u00e4r gruppen gick till m\u00f6tet saktade alla in i direkt\u00f6rens tempo, vilket visade att den som s\u00e4tter ____ \u00e4r den som best\u00e4mmer." } },
      { concept: "HOLDING LEGS TOGETHER, SITTING", definition: "Our level of confidence is often revealed by how we sit. Legs that suddenly come together suggest insecurity. In part, of course, the way we sit is cultural, but some people will move their legs with great reliability depending on how they feel emotionally, revealing their degree of self-assurance. Keep in mind that in many places, women will sit with their knees together as a matter of social convention.", category: "body-language-extracted", real_world_scenario: "In the university seminar, the exchange student's knees suddenly came together when the professor asked her to defend her thesis \u2014 the shift from relaxed to pressed-together legs exposed her sudden insecurity.", case_study_cloze: "In the job interview, the candidate's knees that suddenly came ____ betrayed her insecurity about the question.", sv: { concept: "Benen ihop, sittande", definition: "V\u00e5r sj\u00e4lvs\u00e4kerhet avsl\u00f6jas ofta av hur vi sitter. Ben som pl\u00f6tsligt f\u00f6rs ihop tyder p\u00e5 os\u00e4kerhet. S\u00e4ttet vi sitter p\u00e5 \u00e4r f\u00f6rst\u00e5s delvis kulturellt, men vissa m\u00e4nniskor r\u00f6r sina ben mycket tillf\u00f6rlitligt beroende p\u00e5 hur de m\u00e5r k\u00e4nslom\u00e4ssigt, vilket avsl\u00f6jar deras grad av sj\u00e4lvs\u00e4kerhet. Kom ih\u00e5g att kvinnor i m\u00e5nga kulturer sitter med kn\u00e4na ihop som en social konvention.", real_world_scenario: "P\u00e5 seminariet f\u00f6rdes utbytesstudentens kn\u00e4n pl\u00f6tsligt ihop n\u00e4r professorn bad henne f\u00f6rsvara sin tes \u2014 \u00f6verg\u00e5ngen fr\u00e5n avslappnade till ihopf\u00f6rda ben avsl\u00f6jade hennes pl\u00f6tsliga os\u00e4kerhet.", case_study_cloze: "P\u00e5 intervjun avsl\u00f6jade kandidatens pl\u00f6tsligt ihopf\u00f6rda ____ hennes os\u00e4kerhet inf\u00f6r fr\u00e5gan." } },
      { concept: "LEGS SPREADING APART, SITTING", definition: "Legs that are suddenly set wider apart while sitting during an interview or a conversation suggest greater comfort or confidence. This is a universal territorial display; the farther apart they are, the more territory is being claimed. This behavior is more pronounced in men.", category: "body-language-extracted", real_world_scenario: "Halfway through the car negotiation, the customer leaned back and spread his legs wide in the chair \u2014 a silent signal that he was now confident and comfortable in the deal.", case_study_cloze: "As the interview went well, the candidate's legs spreading ____ apart signaled growing confidence.", sv: { concept: "Benen brett is\u00e4r, sittande", definition: "Ben som pl\u00f6tsligt st\u00e4lls bredare is\u00e4r medan man sitter under en intervju eller ett samtal tyder p\u00e5 st\u00f6rre bekv\u00e4mlighet eller sj\u00e4lvf\u00f6rtroende. Detta \u00e4r en universell territoriell markering; ju l\u00e4ngre is\u00e4r benen \u00e4r, desto mer territorium g\u00f6rs anspr\u00e5k p\u00e5. Beteendet \u00e4r mer utpr\u00e4glat hos m\u00e4n.", real_world_scenario: "Mitt i bilf\u00f6rhandlingen lutade sig kunden tillbaka och spred benen brett i stolen \u2014 en tyst signal om att han nu k\u00e4nde sig trygg och n\u00f6jd med uppl\u00e4gget.", case_study_cloze: "N\u00e4r intervjun gick bra spred kandidaten benen ____ i stolen, ett tecken p\u00e5 v\u00e4xande sj\u00e4lvf\u00f6rtroende." } },
      { concept: "ANKLES LOCKING", definition: "While sitting down, especially in a formal setting, people will often bring their ankles together and interlock them. I look for people who suddenly perform this gesture when something controversial or difficult is being discussed; it usually signals that they are restraining themselves, expressing reservation, or showing hesitation or psychological discomfort.", category: "body-language-extracted", real_world_scenario: "In the meeting about the budget cuts, the department head crossed his ankles and locked them the moment the layoffs were mentioned \u2014 he was holding back his objections.", case_study_cloze: "During the dispute about the contract, the lawyer locked his ____ the moment the sensitive topic came up.", sv: { concept: "L\u00e5sta anklar", definition: "N\u00e4r vi sitter, s\u00e4rskilt i formella sammanhang, f\u00f6r m\u00e4nniskor ofta ihop anklarna och l\u00e5ser dem. Jag ser efter personer som pl\u00f6tsligt g\u00f6r denna gest n\u00e4r n\u00e5got kontroversiellt eller sv\u00e5rt diskuteras; det signalerar vanligtvis att de h\u00e5ller sig tillbaka, uttrycker f\u00f6rbeh\u00e5ll eller visar tvekan eller psykiskt obehag.", real_world_scenario: "Under m\u00f6tet om nedsk\u00e4rningarna l\u00e5ste avdelningschefen ihop anklarna i samma \u00f6gonblick som personalneddragningarna n\u00e4mndes \u2014 han h\u00f6ll tillbaka sina inv\u00e4ndningar.", case_study_cloze: "Under tvisten om kontraktet l\u00e5ste advokaten sina ____ ihop n\u00e4r den k\u00e4nsliga fr\u00e5gan kom upp." } },
      { concept: "KNEE CLASPING, LEANING BACK", definition: "A firm knee clasp can signify that a person is self-restraining. You often see this among nervous job applicants. The feet are on the ground, the knees tightly clasped, and because of stress, the person is leaning back rather rigidly.", category: "body-language-extracted", real_world_scenario: "In the waiting room before her interview, the nervous applicant sat rigidly with her knees tightly clasped and leaned back in the chair, gripping her own legs as if holding herself together.", case_study_cloze: "The nervous student sat with his knees firmly ____ and leaning back, a sign of self-restraint during the oral exam.", sv: { concept: "Kn\u00e4na greppade, lutad bak\u00e5t", definition: "Ett fast grepp om kn\u00e4na kan betyda att en person h\u00e5ller sig sj\u00e4lv tillbaka. Det ses ofta hos nerv\u00f6sa jobbs\u00f6kande. F\u00f6tterna st\u00e5r p\u00e5 golvet, kn\u00e4na h\u00e5lls h\u00e5rt samman, och p\u00e5 grund av stress lutar sig personen bak\u00e5t p\u00e5 ett stelt s\u00e4tt.", real_world_scenario: "I v\u00e4ntrummet inf\u00f6r intervjun satt den nerv\u00f6sa kandidaten stelt med kn\u00e4na h\u00e5rt greppade och lutade sig bak\u00e5t i stolen, som om hon h\u00f6ll sig sj\u00e4lv samman.", case_study_cloze: "Den nerv\u00f6sa studenten satt med kn\u00e4na h\u00e5rt ____ och lutade sig bak\u00e5t, ett tecken p\u00e5 sj\u00e4lvbeh\u00e4rskning under den muntliga tentan." } },
      { concept: "LEG DRAPING", definition: "Subconsciously, individuals who feel confident or superior will drape their leg over a desk, chair, or object-even other people-as a way of establishing a territorial claim. Some bosses do this regularly, sitting in one chair and draping their leg over another.", category: "body-language-extracted", real_world_scenario: "The regional manager regularly draped her leg over the armrest of the empty chair next to her during team meetings \u2014 claiming the extra seat as her territory without saying a word.", case_study_cloze: "The director's habit of ____ her leg over the adjacent chair announced her territorial claim.", sv: { concept: "Benet \u00f6ver m\u00f6beln", definition: "Omedvetet l\u00e4gger personer som k\u00e4nner sig sj\u00e4lvs\u00e4kra eller \u00f6verl\u00e4gsna benet \u00f6ver ett skrivbord, en stol eller ett f\u00f6rem\u00e5l \u2013 till och med \u00f6ver andra m\u00e4nniskor \u2013 som ett s\u00e4tt att g\u00f6ra anspr\u00e5k p\u00e5 territorium. Vissa chefer g\u00f6r detta regelbundet och sitter i en stol med benet h\u00e4ngt \u00f6ver en annan.", real_world_scenario: "Regionchefen lade regelbundet benet \u00f6ver armst\u00f6det p\u00e5 den tomma stolen bredvid sig under m\u00f6tena \u2014 hon gjorde anspr\u00e5k p\u00e5 den extra stolen som sitt territorium utan att s\u00e4ga ett ord.", case_study_cloze: "Direkt\u00f6rens vana att l\u00e4gga ____ \u00f6ver den intilliggande stolen visade tydligt hennes territoriella anspr\u00e5k." } },
      { concept: "LEG RUBBING", definition: "Rubbing the tops of our quadriceps-a gesture known as a leg cleanser-works to pacify us when we are under high stress. It can be easy to miss, since it usually occurs under a table or desk.", category: "body-language-extracted", real_world_scenario: "Under the desk during the final exam, the student repeatedly rubbed the tops of his thighs \u2014 the pacifying gesture was hidden from view but betrayed his high stress.", case_study_cloze: "Hidden under the table, the witness's repeated ____ of his thighs revealed his stress during the questioning.", sv: { concept: "L\u00e5rgnidning", definition: "Att gnugga ovansidan av l\u00e5rmusklerna \u2013 en gest som kallas benreng\u00f6ring \u2013 lugnar oss n\u00e4r vi \u00e4r under h\u00f6g stress. Det \u00e4r l\u00e4tt att missa, eftersom det oftast sker under ett bord eller skrivbord.", real_world_scenario: "Under sluttentan gned studenten upprepat ovansidan av l\u00e5ren under b\u00e4nken \u2014 den lugnande gesten var dold men avsl\u00f6jade \u00e4nd\u00e5 hans h\u00f6ga stress.", case_study_cloze: "G\u00f6md under bordet avsl\u00f6jade vittnets upprepade ____ av l\u00e5ren hans stress under f\u00f6rh\u00f6ret." } },
      { concept: "KNEE RUBBING", definition: "We see repeated scratching or rubbing of the area just above the knee in people who are feeling stress or anticipating something exciting. Like most repetitive behaviors, it serves to pacify, assuaging the excitement or tension.", category: "body-language-extracted", real_world_scenario: "Before the penalty shootout, the goalkeeper repeatedly scratched the spot just above his knee while the referee set the ball \u2014 the repetitive rubbing pacified his rising tension.", case_study_cloze: "Waiting for the results, the patient rubbed the area above his ____ over and over, trying to soothe his anticipation.", sv: { concept: "Kn\u00e4gnidning", definition: "Vi ser upprepad kliande eller gnidning av omr\u00e5det strax ovanf\u00f6r kn\u00e4et hos personer som k\u00e4nner stress eller f\u00f6rv\u00e4ntar sig n\u00e5got sp\u00e4nnande. Liksom de flesta upprepade beteenden lugnar det och mildrar upphetsningen eller sp\u00e4nningen.", real_world_scenario: "F\u00f6re straffl\u00e4ggningen kliade m\u00e5lvakten upprepat p\u00e5 omr\u00e5det strax ovanf\u00f6r kn\u00e4et medan domaren st\u00e4llde upp bollen \u2014 den upprepade gnidningen lugnade hans v\u00e4xande sp\u00e4nning.", case_study_cloze: "Medan han v\u00e4ntade p\u00e5 resultatet gned patienten p\u00e5 omr\u00e5det ovanf\u00f6r ____ om och om igen f\u00f6r att lugna f\u00f6rv\u00e4ntningarna." } },
      { concept: "ANKLE SCRATCHING", definition: "In tense situations it is not unusual for a person to scratch at the ankles. It serves both to relieve stress and to ventilate the skin. We often see this in high-stakes situations such as a large pot in a poker game or in a forensic interview when a difficult question is asked.", category: "body-language-extracted", real_world_scenario: "At the poker table with a huge pot in play, one player scratched at his ankles twice before calling the big bet \u2014 the high-stakes situation made his stress visible in his feet.", case_study_cloze: "In the forensic interview, the suspect's sudden ____ at his ankles followed the difficult question.", sv: { concept: "Att klia sig p\u00e5 anklarna", definition: "I sp\u00e4nda situationer \u00e4r det inte ovanligt att en person kliar sig p\u00e5 anklarna. Det lindrar b\u00e5de stress och ventilerar huden. Vi ser ofta detta i situationer med h\u00f6ga insatser, som vid en stor pott i poker eller i ett f\u00f6rh\u00f6r n\u00e4r en sv\u00e5r fr\u00e5ga st\u00e4lls.", real_world_scenario: "Vid pokerbordet med en stor pott i spel kliade sig en spelare p\u00e5 anklarna tv\u00e5 g\u00e5nger innan han synade den stora satsningen \u2014 den h\u00f6ga insatsen syntes i f\u00f6tterna.", case_study_cloze: "I f\u00f6rh\u00f6ret f\u00f6ljde den misst\u00e4nktes pl\u00f6tsliga ____ p\u00e5 anklarna direkt p\u00e5 den sv\u00e5ra fr\u00e5gan." } },
      { concept: "KNEE FLEXING", definition: "This behavior is performed by quickly flexing the knees forward while standing, which causes the person to sink down rather noticeably. Usually the person immediately recovers. This is a very juvenile behavior, almost akin to the beginnings of a temper tantrum. I have seen grown men do this at the car-rental counter when told the car they requested is not available.", category: "body-language-extracted", real_world_scenario: "At the car-rental counter, the customer's knees buckled briefly when he was told his reserved car was gone \u2014 a quick juvenile sink that looked like the start of a tantrum before he recovered.", case_study_cloze: "Told his flight was overbooked, the man's knees briefly ____ forward as he sank down, a flash of childish frustration.", sv: { concept: "Kn\u00e4flexning", definition: "Beteendet utf\u00f6rs genom att snabbt b\u00f6ja kn\u00e4na fram\u00e5t i st\u00e5ende position, vilket g\u00f6r att personen sjunker ihop m\u00e4rkbart. Vanligtvis \u00e5terh\u00e4mtar sig personen direkt. Det \u00e4r ett mycket barnsligt beteende, n\u00e4stan som b\u00f6rjan p\u00e5 ett utbrott. Jag har sett vuxna m\u00e4n g\u00f6ra detta vid biluthyrningsdisken n\u00e4r de f\u00e5tt veta att den bil de best\u00e4llt inte finns tillg\u00e4nglig.", real_world_scenario: "Vid biluthyrningsdisken vek sig kundens kn\u00e4n kort n\u00e4r han fick veta att hans bokade bil var slut \u2014 ett snabbt, barnsligt sjunkande som liknade b\u00f6rjan p\u00e5 ett utbrott innan han h\u00e4mtade sig.", case_study_cloze: "N\u00e4r mannen fick veta att flyget var \u00f6verbokat ____ kn\u00e4na fram\u00e5t s\u00e5 att han sj\u00f6nk ihop \u2014 en kort, barnslig frustration." } },
      { concept: "DRAGGING FEET", definition: "We often seen children drag their feet back and forth", category: "body-language-extracted", real_world_scenario: "On the way to the dentist's office, the seven-year-old dragged his feet back and forth across the pavement, slowing the walk to a crawl \u2014 the reluctance was in every step.", case_study_cloze: "The child kept ____ his feet to delay the walk to school.", sv: { concept: "Sl\u00e4pande f\u00f6tter", definition: "Vi ser ofta barn sl\u00e4pa f\u00f6tterna fram och tillbaka.", real_world_scenario: "P\u00e5 v\u00e4g till tandl\u00e4karen sl\u00e4pade sju\u00e5ringen f\u00f6tterna fram och tillbaka \u00f6ver trottoaren och gjorde promenaden dubbelt s\u00e5 l\u00e5ng \u2014 motviljan syntes i varenda steg.", case_study_cloze: "Barnet fortsatte att ____ med f\u00f6tterna f\u00f6r att f\u00f6rdr\u00f6ja promenaden till skolan." } },
      { concept: "ANKLE QUIVERING", definition: "Some people while standing will repetitively twist or quiver their foot to the side at the ankle, in a show of restlessness, agitation, animosity, or irritation. This is very perceptible because the shaking causes the whole body to move.", category: "body-language-extracted", real_world_scenario: "In the security line, the traveler's ankle began to quiver side to side, shaking his whole body slightly \u2014 the irritation with the slow queue was impossible to hide.", case_study_cloze: "While she waited for the delayed meeting, her foot's repetitive ____ at the ankle shook her whole leg in irritation.", sv: { concept: "Darr p\u00e5 fotleden", definition: "Vissa m\u00e4nniskor vrider eller darrar upprepat foten \u00e5t sidan vid ankeln i st\u00e5ende position, som ett uttryck f\u00f6r rastl\u00f6shet, uppr\u00f6rdhet, fientlighet eller irritation. Det \u00e4r mycket m\u00e4rkbart eftersom skakningen f\u00e5r hela kroppen att r\u00f6ra sig.", real_world_scenario: "I s\u00e4kerhetsk\u00f6n b\u00f6rjade resen\u00e4rens fotled darra fr\u00e5n sida till sida s\u00e5 att hela kroppen skakade l\u00e4tt \u2014 irritationen \u00f6ver den l\u00e5ngsamma k\u00f6n gick inte att d\u00f6lja.", case_study_cloze: "Medan hon v\u00e4ntade p\u00e5 det f\u00f6rsenade m\u00f6tet fick fotens upprepade ____ vid ankeln hela benet att skaka i irritation." } },
      { concept: "STANDING LEG CROSSING (COMFORT)", definition: "We cross our legs while standing when we are alone or if we feel comfortable with the people around us. The minute someone causes us the slightest psychological discomfort, we will uncross the legs in case we need to quickly distance or defend ourselves from the offending person. You may notice this in elevators, where a lone rider will uncross the legs the minute a stranger enters.", category: "body-language-extracted", real_world_scenario: "Alone in the elevator, the woman stood comfortably with her legs crossed \u2014 the moment a stranger stepped in, she uncrossed them and planted both feet on the floor.", case_study_cloze: "In the elevator, the man crossed his legs while alone, but ____ them the instant a stranger entered.", sv: { concept: "Benkorsning i st\u00e5ende (bekv\u00e4mlighet)", definition: "Vi korsar benen i st\u00e5ende st\u00e4llning n\u00e4r vi \u00e4r ensamma eller n\u00e4r vi k\u00e4nner oss bekv\u00e4ma med m\u00e4nniskorna omkring oss. I samma \u00f6gonblick som n\u00e5gon orsakar oss minsta psykiska obehag korsar vi upp benen igen f\u00f6r att snabbt kunna ta avst\u00e5nd eller f\u00f6rsvara oss mot den besv\u00e4rande personen. Du kan m\u00e4rka detta i hissar, d\u00e4r en ensam \u00e5kande korsar upp benen i samma stund en fr\u00e4mling kliver in.", real_world_scenario: "Ensam i hissen stod kvinnan bekv\u00e4mt med benen korsade \u2014 i samma \u00f6gonblick som en fr\u00e4mling klev in korsade hon upp benen och st\u00e4llde b\u00e5da f\u00f6tterna p\u00e5 golvet.", case_study_cloze: "I hissen stod mannen med benen korsade n\u00e4r han var ensam, men ____ upp dem s\u00e5 fort en fr\u00e4mling klev in." } },
      { concept: "LEG KICKING, SITTING", definition: "A leg crossed over the knee that goes from shaking or twitching (repetitive movement) to sudden kicking up and down after a question is asked indicates high discomfort with the question. This is not a pacifier, unless the person does it all the time. It is a subconscious act of kicking away something objectionable. Sudden leg kicks, in response to a question or a statement, are usually associated with strong negative feelings.", category: "body-language-extracted", real_world_scenario: "During the interview about the missing funds, the accountant's crossed leg suddenly kicked up and down twice after the question about the signature \u2014 the kick betrayed strong negative feelings about the topic.", case_study_cloze: "After the awkward question, her crossed leg ____ up and down, revealing her discomfort with the subject.", sv: { concept: "Benet sparkar, sittande", definition: "Ett ben korsat \u00f6ver kn\u00e4et som g\u00e5r fr\u00e5n skakande eller ryckande (upprepad r\u00f6relse) till pl\u00f6tsliga sparkar upp och ner efter att en fr\u00e5ga st\u00e4llts tyder p\u00e5 stort obehag inf\u00f6r fr\u00e5gan. Detta \u00e4r ingen lugnande gest, om inte personen g\u00f6r det hela tiden. Det \u00e4r en undermedveten handling att sparka bort n\u00e5got o\u00f6nskat. Pl\u00f6tsliga sparkar som svar p\u00e5 en fr\u00e5ga eller ett uttalande f\u00f6rknippas vanligtvis med starka negativa k\u00e4nslor.", real_world_scenario: "Under utredningen av de f\u00f6rsvunna medlen sparkade revisorns korsade ben pl\u00f6tsligt upp och ner tv\u00e5 g\u00e5nger efter fr\u00e5gan om signaturen \u2014 sparken avsl\u00f6jade starka negativa k\u00e4nslor inf\u00f6r \u00e4mnet.", case_study_cloze: "Efter den obekv\u00e4ma fr\u00e5gan ____ hennes korsade ben upp och ner, vilket avsl\u00f6jade hennes obehag inf\u00f6r \u00e4mnet." } },
      { concept: "JUMPING (JOY)", definition: "Positive emotions drive this gravity-defying behavior that is displayed around the world. Primates also will jump for joy, much like humans do, when they sense they are about to get a treat. Our limbic system, the emotional center of the brain, directs this behavior automatically, which is why when a player scores a point spectators jump up all at once, without being told to.", category: "body-language-extracted", real_world_scenario: "At the championship match, the whole crowd jumped up in unison when the winning goal went in \u2014 the limbic system fired before anyone thought about it.", case_study_cloze: "When the lottery numbers matched, she ____ up off the sofa in joy before she could stop herself.", sv: { concept: "Gl\u00e4djehopp", definition: "Positiva k\u00e4nslor driver detta tyngdkraftstrotsande beteende som f\u00f6rekommer \u00f6ver hela v\u00e4rlden. \u00c4ven primater hoppar av gl\u00e4dje, ungef\u00e4r som m\u00e4nniskor, n\u00e4r de k\u00e4nner p\u00e5 sig att de ska f\u00e5 en godbit. V\u00e5rt limbiska system, hj\u00e4rnans emotionella centrum, styr detta beteende automatiskt, vilket \u00e4r varf\u00f6r \u00e5sk\u00e5dare hoppar upp alla p\u00e5 en g\u00e5ng n\u00e4r en spelare g\u00f6r m\u00e5l, utan att n\u00e5gon sagt \u00e5t dem.", real_world_scenario: "N\u00e4r det avg\u00f6rande m\u00e5let gick in hoppade hela publiken upp p\u00e5 en g\u00e5ng \u2014 det limbiska systemet reagerade innan n\u00e5gon hann t\u00e4nka.", case_study_cloze: "N\u00e4r numren i lotteriet st\u00e4mde hoppade hon ____ fr\u00e5n soffan av gl\u00e4dje innan hon hann hejda sig." } },
      { concept: "FROZEN FEET", definition: "Feet that suddenly go \\\"flat\\\" and stop moving indicate concerns or insecurities. We tend to freeze movement when we are threatened or worried, an evolutionary response that keeps us from being noticed by predators.", category: "body-language-extracted", real_world_scenario: "During the customs interview, the traveler's feet, which had been tapping freely, suddenly went flat and completely still the moment the officer mentioned the receipt \u2014 the freeze said the topic mattered.", case_study_cloze: "The suspect's suddenly ____ feet signaled that the officer's question had triggered deep concern.", sv: { concept: "Frysta f\u00f6tter", definition: "F\u00f6tter som pl\u00f6tsligt g\u00e5r till att bli 'platta' och slutar r\u00f6ra sig tyder p\u00e5 oro eller os\u00e4kerhet. Vi tenderar att frysa till n\u00e4r vi k\u00e4nner oss hotade eller bekymrade, en evolution\u00e4r respons som hindrar oss fr\u00e5n att bli uppt\u00e4ckta av rovdjur.", real_world_scenario: "Under tullf\u00f6rh\u00f6ret blev resen\u00e4rens f\u00f6tter, som tickat fritt, pl\u00f6tsligt 'platta' och helt stilla i samma \u00f6gonblick som tj\u00e4nstemannen n\u00e4mnde kvittot \u2014 frysningen sa att \u00e4mnet betydde n\u00e5got.", case_study_cloze: "Den misst\u00e4nktes pl\u00f6tsligt ____ f\u00f6tter signalerade att fr\u00e5gan v\u00e4ckt djup oro." } },
      { concept: "FOOT WITHDRAWING", definition: "During job interviews, interviewees will suddenly withdraw their feet and tuck them in under their chairs when they are asked sensitive questions they might not like. The movement is sometimes rather noticeable, closely following a question that is difficult to answer, such as \\\"Have you ever been fired from a job?\\\" At home, teens might do this when asked where they were the night before.", category: "body-language-extracted", real_world_scenario: "When the interviewer asked if she had ever been fired, the candidate's feet suddenly slid back and tucked under her chair \u2014 the withdrawal answered the question before she did.", case_study_cloze: "Asked about his whereabouts the night before, the teen's feet slid ____ under his chair.", sv: { concept: "Foten dras in", definition: "Under anst\u00e4llningsintervjuer drar de intervjuade pl\u00f6tsligt in f\u00f6tterna och stoppar in dem under stolen n\u00e4r de f\u00e5r k\u00e4nsliga fr\u00e5gor de kanske inte gillar. R\u00f6relsen \u00e4r ibland ganska m\u00e4rkbar och f\u00f6ljer t\u00e4tt efter en fr\u00e5ga som \u00e4r sv\u00e5r att besvara, som 'Har du n\u00e5gonsin blivit avskedad fr\u00e5n ett jobb?' Hemma kan ton\u00e5ringar g\u00f6ra detta n\u00e4r de f\u00e5r fr\u00e5gan var de var kv\u00e4llen innan.", real_world_scenario: "N\u00e4r intervjuaren fr\u00e5gade om hon n\u00e5gonsin blivit avskedad gled kandidatens f\u00f6tter pl\u00f6tsligt bak\u00e5t och stoppades in under stolen \u2014 indragningen besvarade fr\u00e5gan innan hon \u00f6ppnade munnen.", case_study_cloze: "N\u00e4r ton\u00e5ringen fick fr\u00e5gan var han hade varit kv\u00e4llen innan gled f\u00f6tterna ____ under stolen." } },
      { concept: "PLAYING FOOTSIES", definition: "When we like another person, our feet will be drawn to them. When we like them romantically, our feet might move almost", category: "body-language-extracted", real_world_scenario: "Across the restaurant table on their third date, her foot kept drifting toward his under the table, and his toes met hers halfway \u2014 the feet were doing the flirting that words had not started yet.", case_study_cloze: "Under the dinner table, her toes meeting his was the classic ____ that revealed mutual interest.", sv: { concept: "Fotflirt", definition: "N\u00e4r vi tycker om en annan person dras v\u00e5ra f\u00f6tter till dem. N\u00e4r vi tycker om dem romantiskt kan v\u00e5ra f\u00f6tter r\u00f6ra sig n\u00e4stan", real_world_scenario: "P\u00e5 restaurangen p\u00e5 deras tredje dejt gled hennes fot hela tiden mot hans under bordet och hans t\u00e5r m\u00f6tte hennes halvv\u00e4gs \u2014 f\u00f6tterna flirtade medan orden \u00e4nnu var tysta.", case_study_cloze: "Under middagen var hennes t\u00e5r som m\u00f6tte hans under bordet en klassisk ____ som avsl\u00f6jade \u00f6msesidigt intresse." } },
      { concept: "FOOT ROCKING", definition: "This is another repetitive behavior that serves to pacify us. We might do this when we're waiting for someone to hurry up-the rocking shifts from the heels to the toes, back and forth. Since this elevates us as we rock forward, it is also somewhat of a gravity-defying behavior. Foot rocking can both alleviate boredom and demonstrate that a person is in charge.", category: "body-language-extracted", real_world_scenario: "Standing outside the restroom, the mother rocked from heels to toes and back while her toddler took forever \u2014 the rocking both passed the time and signaled who was in charge of the schedule.", case_study_cloze: "Waiting for the late colleague, the manager's ____ from heels to toes betrayed his growing impatience.", sv: { concept: "Gungande p\u00e5 f\u00f6tterna", definition: "Detta \u00e4r \u00e4nnu ett upprepat beteende som lugnar oss. Vi kan g\u00f6ra detta n\u00e4r vi v\u00e4ntar p\u00e5 att n\u00e5gon ska skynda sig \u2013 gungningen v\u00e4xlar fr\u00e5n h\u00e4larna till t\u00e5rna, fram och tillbaka. Eftersom det lyfter oss n\u00e4r vi gungar fram\u00e5t \u00e4r det ocks\u00e5 ett n\u00e5got tyngdkraftstrotsande beteende. Fotgungande kan b\u00e5de lindra uttr\u00e5kning och visa att en person best\u00e4mmer.", real_world_scenario: "Utanf\u00f6r toaletten gungade mamman fr\u00e5n h\u00e4lar till t\u00e5r och tillbaka medan sm\u00e5barnet dr\u00f6jde \u2014 gungningen f\u00f6rdrev tiden och visade vem som best\u00e4mde \u00f6ver schemat.", case_study_cloze: "Medan han v\u00e4ntade p\u00e5 den f\u00f6rsenade kollegan avsl\u00f6jade chefens ____ fr\u00e5n h\u00e4lar till t\u00e5r hans v\u00e4xande ot\u00e5lighet." } },
      { concept: "FOOT TURNING AWAY", definition: "When we're talking to someone, we might signal that we need to leave by gradually or suddenly pointing one foot toward the door. This is our nonverbal way of communicating \\\"I have to go.\\\" It is an intention cue, and if the person we're talking to ignores it, we can become very irritated. Be mindful of others, and recognize that when their foot turns away, chances are they have to go.", category: "body-language-extracted", real_world_scenario: "Mid-conversation in the hallway, the colleague's foot slowly turned and pointed toward the exit while he nodded along \u2014 the intention cue said 'I have to go' more honestly than his words.", case_study_cloze: "While his boss kept talking, the employee's foot ____ toward the door, signaling that he needed to leave.", sv: { concept: "Foten v\u00e4nds bort", definition: "N\u00e4r vi pratar med n\u00e5gon kan vi signalera att vi m\u00e5ste g\u00e5 genom att gradvis eller pl\u00f6tsligt peka ena foten mot d\u00f6rren. Det \u00e4r v\u00e5rt icke-verbala s\u00e4tt att s\u00e4ga 'jag m\u00e5ste g\u00e5'. Det \u00e4r en avsiktsmark\u00f6r, och om personen vi pratar med ignorerar den kan vi bli mycket irriterade. Var uppm\u00e4rksam p\u00e5 andra och f\u00f6rst\u00e5 att n\u00e4r deras fot v\u00e4nds bort \u00e4r chansen stor att de m\u00e5ste g\u00e5.", real_world_scenario: "Mitt i samtalet i korridoren vred kollegan l\u00e5ngsamt foten mot utg\u00e5ngen medan han nickade inst\u00e4mmande \u2014 avsiktsmark\u00f6ren sa 'jag m\u00e5ste g\u00e5' mer \u00e4rligt \u00e4n orden.", case_study_cloze: "Medan chefen fortsatte prata pekade medarbetarens fot ____ mot d\u00f6rren, en signal om att han beh\u00f6vde g\u00e5." } },
      { concept: "TOES POINTING INWARD/PIGEON TOES", definition: "Some people turn their toes inward (sometimes called \\\"pigeon toes\\\") when they are insecure, shy, or introverted, or when they feel particularly vulnerable. This behavior, which is generally seen in children but also in some adults, demonstrates some sort of emotional need or apprehension.", category: "body-language-extracted", real_world_scenario: "Standing in front of the class for her first presentation, the shy student's toes turned inward in a pigeon-toed stance \u2014 the vulnerability showed in her feet.", case_study_cloze: "Feeling exposed at the party, he stood with his toes turned ____, the pigeon-toed posture of someone feeling vulnerable.", sv: { concept: "T\u00e5rna in\u00e5tv\u00e4nda", definition: "Vissa m\u00e4nniskor v\u00e4nder t\u00e5rna in\u00e5t (ibland kallat 'duvt\u00e5r') n\u00e4r de \u00e4r os\u00e4kra, blyga eller in\u00e5tv\u00e4nda, eller n\u00e4r de k\u00e4nner sig s\u00e4rskilt s\u00e5rbara. Detta beteende, som i allm\u00e4nhet ses hos barn men ocks\u00e5 hos en del vuxna, visar n\u00e5got slags k\u00e4nslom\u00e4ssigt behov eller \u00e4ngslan.", real_world_scenario: "Inf\u00f6r sin f\u00f6rsta presentation stod den blyga studenten med t\u00e5rna v\u00e4nda in\u00e5t i en duvt\u00e5sst\u00e4llning \u2014 s\u00e5rbarheten syntes i f\u00f6tterna.", case_study_cloze: "P\u00e5 festen stod han med t\u00e5rna v\u00e4nda ____ i en duvt\u00e5sst\u00e4llning som avsl\u00f6jade hans s\u00e5rbarhet." } },
      { concept: "EXPOSING SOLES OF FEET", definition: "In many parts of the world, especially the Middle East, Africa, and parts of Asia, displaying the sole of one's foot or shoe is insulting. When traveling abroad, be careful how you sit-resting the ankle on a knee exposes your soles. It is usually preferable to either keep both feet on the ground or to drape one leg over the opposite knee so that the sole is pointing downward.", category: "body-language-extracted", real_world_scenario: "At the business meeting in Dubai, the visiting manager crossed his leg so his sole pointed at the host \u2014 a cultural faux pas that nearly derailed the negotiation before it started.", case_study_cloze: "In the Middle East, showing the ____ of your foot to a host is considered a deep insult.", sv: { concept: "Att visa fotsulorna", definition: "I m\u00e5nga delar av v\u00e4rlden, s\u00e4rskilt Mellan\u00f6stern, Afrika och delar av Asien, \u00e4r det en f\u00f6rol\u00e4mpning att visa fotsulan eller skosulan. N\u00e4r du reser utomlands ska du vara f\u00f6rsiktig med hur du sitter \u2013 att vila ankeln p\u00e5 kn\u00e4et blottar sulorna. Det \u00e4r oftast b\u00e4ttre att antingen ha b\u00e5da f\u00f6tterna p\u00e5 golvet eller att l\u00e4gga ett ben \u00f6ver det motsatta kn\u00e4et s\u00e5 att sulan pekar ned\u00e5t.", real_world_scenario: "P\u00e5 aff\u00e4rsm\u00f6tet i Dubai lade den bes\u00f6kande chefen benet i kors s\u00e5 att fotsulan pekade mot v\u00e4rdarna \u2014 en kulturell miss som n\u00e4stan f\u00e4llde f\u00f6rhandlingen innan den b\u00f6rjat.", case_study_cloze: "I Mellan\u00f6stern anses det vara en djup f\u00f6rol\u00e4mpning att visa ____ p\u00e5 foten f\u00f6r sin v\u00e4rd." } },
      { concept: "BOUNCY HAPPY FEET", definition: "We sometimes register an emotional high with happy feet-the feet are animated and jumpy. This is certainly visible in children, when you tell them you're taking them to a theme park, for example. But we also see it in adults. Poker players, for instance, might bounce their feet under the table when they have a monster hand. While the feet themselves might not be visible, often they will cause the clothing to shake or tremble all the way up to the shoulders.", category: "body-language-extracted", real_world_scenario: "When the father announced the trip to Disney World, the twins' feet started bouncing under the breakfast table, shaking the whole tablecloth \u2014 happy feet in its purest form.", case_study_cloze: "The poker player's feet ____ under the table when he looked at his monster hand, shaking the cloth ever so slightly.", sv: { concept: "Glada studsande f\u00f6tter", definition: "Vi registrerar ibland ett k\u00e4nslom\u00e4ssigt toppl\u00e4ge med glada f\u00f6tter \u2013 f\u00f6tterna \u00e4r livliga och studsiga. Detta syns verkligen hos barn, till exempel n\u00e4r du ber\u00e4ttar att ni ska \u00e5ka till ett n\u00f6jesf\u00e4lt. Men vi ser det ocks\u00e5 hos vuxna. Pokerspelare kan till exempel studsa med f\u00f6tterna under bordet n\u00e4r de har en monsterhand. \u00c4ven om f\u00f6tterna i sig inte syns f\u00e5r de ofta kl\u00e4derna att skaka eller darra \u00e4nda upp till axlarna.", real_world_scenario: "N\u00e4r pappan ber\u00e4ttade att de skulle \u00e5ka till Disney World b\u00f6rjade tvillingarnas f\u00f6tter studsa under frukostbordet s\u00e5 att hela duken skakade \u2014 glada f\u00f6tter i sin renaste form.", case_study_cloze: "Pokerspelarens f\u00f6tter ____ under bordet n\u00e4r han s\u00e5g sin monsterhand, vilket fick tyget att darra l\u00e4tt." } },
      { concept: "FOOT TAPPING", definition: "This is a familiar behavior used to pass the time, to keep tempo with music, or, like finger strumming, to indicate that we are becoming impatient. Usually just the front of the foot is involved, while the heel remains grounded, but it can also be done with the heel of the foot.", category: "body-language-extracted", real_world_scenario: "In the doctor's waiting room, the man tapped his foot against the floor in a steady rhythm, heel grounded while the front of the foot rose \u2014 the tempo of his impatience.", case_study_cloze: "The impatient patient's ____ against the floor grew faster as the doctor ran late.", sv: { concept: "Fotknackande", definition: "Detta \u00e4r ett v\u00e4lbekant beteende som anv\u00e4nds f\u00f6r att f\u00f6rdriva tiden, h\u00e5lla takten till musik eller, som fingerstrummande, visa att vi b\u00f6rjar bli ot\u00e5liga. Vanligtvis \u00e4r bara framdelen av foten inblandad medan h\u00e4len f\u00f6rblir p\u00e5 golvet, men det kan ocks\u00e5 g\u00f6ras med h\u00e4len.", real_world_scenario: "I v\u00e4ntrummet hos doktorn knackade mannen med foten mot golvet i en j\u00e4mn rytm, h\u00e4len kvar p\u00e5 golvet medan framdelen h\u00f6jdes \u2014 ot\u00e5lighetens tempo.", case_study_cloze: "Den ot\u00e5lige patientens ____ mot golvet blev allt snabbare i takt med att l\u00e4karen kom f\u00f6r sent." } },
      { concept: "TOE WIGGLING", definition: "Ever find yourself wiggling your toes? Chances are you were feeling good about something, excited, or eagerly anticipating an event. The movement of the toes stimulates nerves that help to alleviate boredom or stress and can signal excitement in much the way happy feet do.", category: "body-language-extracted", real_world_scenario: "With her feet hidden under the desk, the assistant wiggled her toes inside her shoes as the boss described the promotion \u2014 an invisible sign of private delight.", case_study_cloze: "Feeling good about the offer, he ____ his toes inside his shoes, a small hidden sign of excitement.", sv: { concept: "Vicka p\u00e5 t\u00e5rna", definition: "Har du n\u00e5gonsin m\u00e4rkt att du vickar p\u00e5 t\u00e5rna? Chansen \u00e4r stor att du m\u00e5dde bra av n\u00e5got, var upphetsad eller s\u00e5g fram emot en h\u00e4ndelse. T\u00e5rt\u00f6relserna stimulerar nerver som hj\u00e4lper till att lindra uttr\u00e5kning eller stress och kan signalera upphetsning p\u00e5 samma s\u00e4tt som glada f\u00f6tter g\u00f6r.", real_world_scenario: "Med f\u00f6tterna dolda under skrivbordet vickade assistenten p\u00e5 t\u00e5rna inuti skorna n\u00e4r chefen ber\u00e4ttade om befordran \u2014 en osynlig signal om privat gl\u00e4dje.", case_study_cloze: "N\u00f6jd \u00f6ver erbjudandet vickade han p\u00e5 ____ inuti skorna, en liten dold signal om upphetsning." } },
      { concept: "AGITATED FEET", definition: "Every parent recognizes the agitated feet of a child who wants to leave the table to go play. Often our feet will telegraph that we want to leave, even in a boardroom full of adults, through excessive uncomfortable movements. These might include repetitive shifting, movement from side to side, foot withdrawal, or repetitively raising and lowering the heels of the feet.", category: "body-language-extracted", real_world_scenario: "At the family dinner, the five-year-old shifted and squirmed, raising and lowering his heels again and again \u2014 his feet told everyone he wanted to go play before he asked.", case_study_cloze: "In the boardroom, the manager's ____ feet, shifting side to side, revealed his wish to end the meeting.", sv: { concept: "Rastl\u00f6sa f\u00f6tter", definition: "Varje f\u00f6r\u00e4lder k\u00e4nner igen det rastl\u00f6sa fotbeteendet hos ett barn som vill l\u00e4mna bordet f\u00f6r att leka. Ofta signalerar v\u00e5ra f\u00f6tter att vi vill g\u00e5, \u00e4ven i ett styrelserum fullt av vuxna, genom \u00f6verdrivna obekv\u00e4ma r\u00f6relser. Det kan handla om upprepade f\u00f6rskjutningar, r\u00f6relse fr\u00e5n sida till sida, att dra in foten eller att upprepat h\u00f6ja och s\u00e4nka h\u00e4larna.", real_world_scenario: "Vid familjemiddagen vred och vred sig fem\u00e5ringen och h\u00f6jde och s\u00e4nkte h\u00e4larna om och om igen \u2014 f\u00f6tterna talade om f\u00f6r alla att han ville g\u00e5 och leka innan han ens fr\u00e5gade.", case_study_cloze: "I styrelserummet avsl\u00f6jade chefens ____ f\u00f6tter som skiftade fr\u00e5n sida till sida hans \u00f6nskan att avsluta m\u00f6tet." } },
      { concept: "NERVOUS PACING", definition: "Many people will pace when they are stressed. This acts as a pacifier, as all repetitive behaviors do.", category: "body-language-extracted", real_world_scenario: "In the hospital corridor, the father paced back and forth outside the operating room, the repetitive walking soothing his anxiety while he waited for news.", case_study_cloze: "Waiting for the test results, the patient ____ back and forth in the corridor to calm his nerves.", sv: { concept: "Nerv\u00f6st vankande", definition: "M\u00e5nga m\u00e4nniskor vankar av och an n\u00e4r de \u00e4r stressade. Det fungerar som en lugnande gest, som alla upprepade beteenden g\u00f6r.", real_world_scenario: "I sjukhuskorridoren vankade pappan av och an utanf\u00f6r operationssalen \u2014 det upprepade vankandet lugnade hans oro medan han v\u00e4ntade p\u00e5 besked.", case_study_cloze: "Medan han v\u00e4ntade p\u00e5 provsvaren ____ patienten av och an i korridoren f\u00f6r att lugna nerverna." } },
      { concept: "LEG TANTRUMS", definition: "These are most often seen in children when they twist, move, and energetically stomp their legs, letting everyone know how they feel. And it's not just children, from time to time you will see adults do the same, as I did when an executive was bumped from a flight. This is a reminder that the legs also demonstrate emotions, and because these are the largest muscles in the body, they do so with maximum effect.", category: "body-language-extracted", real_world_scenario: "At the supermarket checkout, the toddler twisted and stomped her legs on the floor of the cart, letting the whole store know she was done shopping \u2014 the legs made the feeling unmistakable.", case_study_cloze: "The grown man's energetic leg ____ and stomping at the airport gate showed his fury at being bumped from the flight.", sv: { concept: "Benvredslutbrott", definition: "Dessa ses oftast hos barn som vrider, r\u00f6r och stampar energiskt med benen f\u00f6r att l\u00e5ta alla veta hur de k\u00e4nner. Och det \u00e4r inte bara barn \u2013 d\u00e5 och d\u00e5 ser du vuxna g\u00f6ra detsamma, som jag gjorde n\u00e4r en chef blev borttagen fr\u00e5n ett flyg. Det p\u00e5minner om att \u00e4ven benen visar k\u00e4nslor, och eftersom de \u00e4r kroppens st\u00f6rsta muskler g\u00f6r de det med maximal effekt.", real_world_scenario: "Vid kassan i matbutiken vred och stampade sm\u00e5flickan med benen i kundvagnen s\u00e5 att hela aff\u00e4ren f\u00f6rstod att hon var klar med att handla \u2014 benen gjorde k\u00e4nslan om\u00f6jlig att missa.", case_study_cloze: "Den vuxne mannens vilda ____ med benen vid gaten visade hans raseri \u00f6ver att ha blivit borttagen fr\u00e5n flyget." } },
      { concept: "FOOT STOMPING", definition: "Children are not the only ones who stomp their feet to make their feelings known. We often see this when people are exasperated or they have reached the limit of their patience. I've observed men and women stomping their feet in lines that move too slowly. Usually the foot is only stomped once, just to get noticed.", category: "body-language-extracted", real_world_scenario: "In the slow-moving bank queue, the woman stomped her foot once, sharply, when the line stopped for the third time \u2014 one emphatic stamp that said her patience was gone.", case_study_cloze: "After ten minutes in the unmoving queue, he ____ his foot once to make his exasperation known.", sv: { concept: "Fotstampning", definition: "Det \u00e4r inte bara barn som stampar med f\u00f6tterna f\u00f6r att visa vad de k\u00e4nner. Vi ser ofta detta n\u00e4r m\u00e4nniskor \u00e4r f\u00f6rtretade eller har n\u00e5tt gr\u00e4nsen f\u00f6r sitt t\u00e5lamod. Jag har sett b\u00e5de m\u00e4n och kvinnor stampa med f\u00f6tterna i k\u00f6er som r\u00f6r sig f\u00f6r l\u00e5ngsamt. Vanligtvis stampas det bara en g\u00e5ng, f\u00f6r att bli sedd.", real_world_scenario: "I den l\u00e5ngsamma bankk\u00f6n stampade kvinnan till med foten en enda g\u00e5ng, skarpt, n\u00e4r k\u00f6n stannade f\u00f6r tredje g\u00e5ngen \u2014 en betonad stampning som sa att t\u00e5lamodet var slut.", case_study_cloze: "Efter tio minuter i den stillast\u00e5ende k\u00f6n stampade han till med ____ en g\u00e5ng f\u00f6r att visa sin f\u00f6rtret." } },
      { concept: "SHOE DANGLE", definition: "When some people, especially women, are comfortable around others, they will dangle their shoe near the instep of the foot. This is often seen in dating situations. The shoe will be slipped back on the very instant a woman feels uncomfortable or no longer likes what the other person is saying.", category: "body-language-extracted", real_world_scenario: "At dinner, her shoe dangled from her toes as she listened to him talk; the moment he mentioned his ex-girlfriend, the shoe slipped quietly back on.", case_study_cloze: "The woman's ____ dangling from her foot slipped back on the instant she heard something she disliked.", sv: { concept: "Dinglande sko", definition: "N\u00e4r vissa m\u00e4nniskor, s\u00e4rskilt kvinnor, \u00e4r bekv\u00e4ma i andras s\u00e4llskap dinglar de med skon vid fotvalvet. Detta ses ofta i dejtsammanhang. Skon s\u00e4tts p\u00e5 igen i samma \u00f6gonblick som en kvinna k\u00e4nner sig obekv\u00e4m eller inte l\u00e4ngre gillar vad den andra personen s\u00e4ger.", real_world_scenario: "Under middagen dinglade hennes sko fr\u00e5n t\u00e5rna medan hon lyssnade p\u00e5 honom; i samma \u00f6gonblick som han n\u00e4mnde sitt ex gled skon tyst p\u00e5 igen.", case_study_cloze: "Kvinnans dinglande ____ gled p\u00e5 igen i samma \u00f6gonblick som hon h\u00f6rde n\u00e5got hon inte gillade." } },
      { concept: "HAIR", definition: "Sitting conveniently on top of the head, our hair conveys so much when it comes to nonverbal communication. Healthy hair is something all humans look for, even on a subconscious level. Hair that is dirty, unkempt, pulled out, or uncared for may suggest poor health or even mental illness.", category: "body-language-extracted", real_world_scenario: "At the support group meeting, the woman's greasy, unkempt hair and bitten-off strands told the counselor more about her state than her cheerful words did \u2014 neglected hair as a signal of struggle.", case_study_cloze: "The nurse noted the patient's ____ hair, a possible sign of poor health or distress.", sv: { concept: "H\u00e5r", definition: "V\u00e5rt h\u00e5r, som sitter praktiskt taget p\u00e5 toppen av huvudet, f\u00f6rmedlar s\u00e5 mycket i icke-verbal kommunikation. Friskt h\u00e5r \u00e4r n\u00e5got alla m\u00e4nniskor s\u00f6ker efter, \u00e4ven p\u00e5 ett undermedvetet plan. H\u00e5r som \u00e4r smutsigt, okammat, plockat eller ov\u00e5rdat kan tyda p\u00e5 d\u00e5lig h\u00e4lsa eller till och med psykisk sjukdom.", real_world_scenario: "Vid m\u00f6tet i st\u00f6dgruppen ber\u00e4ttade kvinnans feta, ov\u00e5rdade h\u00e5r och avbitna toppar mer f\u00f6r terapeuten \u00e4n hennes glada ord gjorde \u2014 f\u00f6rsummat h\u00e5r som signal f\u00f6r psykisk oh\u00e4lsa.", case_study_cloze: "Sjuksk\u00f6terskan noterade patientens ____ h\u00e5r, en m\u00f6jlig signal p\u00e5 d\u00e5lig h\u00e4lsa eller psykisk oh\u00e4lsa." } },
      { concept: "POINTING AT FOREHEAD", definition: "Pointing a finger at the forehead or making a screwing motion with the finger while pointing at the forehead is very insulting-it means that the observer is ill informed, stupid, or crazy. This is a culturally based cue, generally seen in Germany, Switzerland, and", category: "body-language-extracted", real_world_scenario: "In the German pub, the tourist watched in shock as the local man pointed at his own forehead and twisted his finger when the tourist claimed the bill was wrong \u2014 a silent verdict of 'you must be crazy'.", case_study_cloze: "The gesture of pointing a finger at the ____ is considered deeply insulting in Germany and Switzerland.", sv: { concept: "Peka mot pannan", definition: "Att peka med fingret mot pannan eller g\u00f6ra en skruvande r\u00f6relse med fingret mot pannan \u00e4r mycket kr\u00e4nkande \u2013 det betyder att personen \u00e4r illa informerad, dum eller galen. Detta \u00e4r en kulturell signal som i allm\u00e4nhet ses i Tyskland, Schweiz och", real_world_scenario: "P\u00e5 krogen i Tyskland s\u00e5g turisten chockad p\u00e5 n\u00e4r lokalen pekade mot sin egen panna och vred fingret n\u00e4r turisten h\u00e4vdade att notan var fel \u2014 en tyst dom p\u00e5 'du m\u00e5ste vara galen'.", case_study_cloze: "Gest att peka fingret mot ____ anses vara djupt kr\u00e4nkande i Tyskland och Schweiz." } },
      { concept: "EYEBROW NARROWING/KNITTING", definition: "The area between the eyes and just above the nose is called the glabella, and when the glabella becomes narrow or furrowed, it usually means there is an issue, concern, or dislike. This universal sign may happen very quickly and thus can be difficult to detect, but it is an accurate reflection of sentiments. Some people will knit their brow when they hear something troubling or are trying to make sense of what they're being told. The sentiment is communicated with the >< emoji.", category: "body-language-extracted", real_world_scenario: "During the budget presentation, the CFO's glabella furrowed into a quick frown when the new costs were announced \u2014 the flash of concern appeared and vanished in under a second.", case_study_cloze: "The furrowed ____ between the manager's eyes appeared the moment the layoffs were mentioned.", sv: { concept: "Rynkade \u00f6gonbryn", definition: "Omr\u00e5det mellan \u00f6gonen och strax ovanf\u00f6r n\u00e4san kallas glabella, och n\u00e4r glabellan blir smal eller rynkig betyder det oftast att det finns ett problem, en oro eller ogillande. Denna universella signal kan ske mycket snabbt och \u00e4r d\u00e4rf\u00f6r sv\u00e5r att uppt\u00e4cka, men den \u00e4r en korrekt spegling av k\u00e4nslor. Vissa m\u00e4nniskor rynkar pannan n\u00e4r de h\u00f6r n\u00e5got orov\u00e4ckande eller f\u00f6rs\u00f6ker f\u00f6rst\u00e5 vad de f\u00e5r h\u00f6ra. K\u00e4nslan f\u00f6rmedlas med >< emojin.", real_world_scenario: "Under budgetpresentationen rynkades ekonomichefens glabella ihop i en snabb bekymmersrynka n\u00e4r de nya kostnaderna presenterades \u2014 oron blixtrade fram och f\u00f6rsvann p\u00e5 under en sekund.", case_study_cloze: "Den rynkade ____ mellan chefen \u00f6gon d\u00f6k upp i samma \u00f6gonblick som neddragningarna n\u00e4mndes." } },
      { concept: "CRYING", definition: "Crying serves a variety of personal as well as social purposes, most notably providing a cathartic emotional release. Unfortunately, children also learn quickly that crying can be used as a tool to manipulate, and some adults don't hesitate to use it similarly. In observing a person's behavior, crying should not be given any more weight than other signals that a person is having a hard time. Crying, if it occurs with great frequency, can also let us know when someone is clinically depressed or struggling psychologically.", category: "body-language-extracted", real_world_scenario: "When the employee burst into tears over the delayed project, her manager remembered that crying should carry no more weight than other signals \u2014 the tears were real stress, but so were the trembling voice and the rushed words.", case_study_cloze: "The child's quick ____ at being denied a treat showed how crying can become a tool for manipulation.", sv: { concept: "Gr\u00e5t", definition: "Gr\u00e5t tj\u00e4nar en m\u00e4ngd personliga s\u00e5v\u00e4l som sociala syften, framf\u00f6r allt en kathartisk k\u00e4nslom\u00e4ssig befrielse. Tyv\u00e4rr l\u00e4r sig barn snabbt att gr\u00e5t kan anv\u00e4ndas som ett verktyg f\u00f6r att manipulera, och en del vuxna tvekar inte att anv\u00e4nda det p\u00e5 samma s\u00e4tt. N\u00e4r man observerar en persons beteende ska gr\u00e5t inte ges st\u00f6rre vikt \u00e4n andra signaler p\u00e5 att en person har det sv\u00e5rt. Gr\u00e5t som f\u00f6rekommer med h\u00f6g frekvens kan ocks\u00e5 ber\u00e4tta n\u00e4r n\u00e5gon \u00e4r kliniskt deprimerad eller k\u00e4mpar psykiskt.", real_world_scenario: "N\u00e4r medarbetaren brast i gr\u00e5t \u00f6ver det f\u00f6rsenade projektet mindes chefen att gr\u00e5t inte ska v\u00e4ga tyngre \u00e4n andra signaler \u2014 t\u00e5rarna var \u00e4kta stress, men likas\u00e5 den darrande r\u00f6sten och de snabba orden.", case_study_cloze: "Barnets snabba ____ n\u00e4r det nekades en godbit visade hur gr\u00e5t kan bli ett verktyg f\u00f6r manipulation." } },
      { concept: "EYELIDS FLUTTERING", definition: "Sudden eyelid fluttering suggests that something is wrong or that a person is struggling with something (think of the actor Hugh Grant, who often flutters his eyes on-screen when he has issues or has messed something up). People often flutter their eyes when they are struggling to find the right word or can't believe what they just heard or witnessed. Incredulity is often observed as eyelid fluttering.", category: "body-language-extracted", real_world_scenario: "When the accountant heard the bonus had been canceled, his eyelids fluttered for a split second \u2014 the rapid blinking betrayed his disbelief before he managed a neutral face.", case_study_cloze: "Struggling to find the right word, the speaker's ____ fluttered, revealing his struggle.", sv: { concept: "Fladdrande \u00f6gonlock", definition: "Pl\u00f6tsligt fladdrande \u00f6gonlock tyder p\u00e5 att n\u00e5got \u00e4r fel eller att en person k\u00e4mpar med n\u00e5got (t\u00e4nk p\u00e5 sk\u00e5despelaren Hugh Grant, som ofta fladdrar med \u00f6gonen p\u00e5 film n\u00e4r han har problem eller har st\u00e4llt till det). M\u00e4nniskor fladdrar ofta med \u00f6gonen n\u00e4r de k\u00e4mpar f\u00f6r att hitta r\u00e4tt ord eller inte kan tro det de just h\u00f6rt eller sett. H\u00e4pnad observeras ofta som fladdrande \u00f6gonlock.", real_world_scenario: "N\u00e4r revisorn fick h\u00f6ra att bonusen var inst\u00e4lld fladdrade \u00f6gonlocken i en br\u00e5kdels sekund \u2014 de snabba blinkningarna avsl\u00f6jade hans h\u00e4pnad innan han hann l\u00e4gga band p\u00e5 sig.", case_study_cloze: "N\u00e4r talaren k\u00e4mpade f\u00f6r att hitta r\u00e4tt ord ____ \u00f6gonlocken, vilket avsl\u00f6jade hans anstr\u00e4ngning." } },
      { concept: "SQUINTING", definition: "Squinting is an easy way to register displeasure or concern, especially when we hear or see something we don't like. Some people squint whenever they hear something bothersome, making this an accurate reflection of their feelings. But keep in mind that we also squint when we are simply focusing on something or trying to make sense of something we have heard, so context is crucial in interpreting this behavior.", category: "body-language-extracted", real_world_scenario: "At the used-car lot, the customer squinted when the salesman quoted the final price \u2014 the narrowed eyes registered displeasure before he could choose his words.", case_study_cloze: "The boss's ____ as he listened to the excuse showed his displeasure with the explanation.", sv: { concept: "Kisa med \u00f6gonen", definition: "Att kisa \u00e4r ett enkelt s\u00e4tt att visa missn\u00f6je eller oro, s\u00e4rskilt n\u00e4r vi h\u00f6r eller ser n\u00e5got vi inte gillar. Vissa m\u00e4nniskor kisar n\u00e4rhelst de h\u00f6r n\u00e5got besv\u00e4rande, vilket g\u00f6r det till en korrekt spegling av deras k\u00e4nslor. Men kom ih\u00e5g att vi ocks\u00e5 kisar n\u00e4r vi helt enkelt fokuserar p\u00e5 n\u00e5got eller f\u00f6rs\u00f6ker f\u00f6rst\u00e5 n\u00e5got vi h\u00f6rt, s\u00e5 sammanhanget \u00e4r avg\u00f6rande f\u00f6r att tolka beteendet.", real_world_scenario: "P\u00e5 bilfirman kisade kunden n\u00e4r s\u00e4ljaren sa slutpriset \u2014 de ihopknipta \u00f6gonen visade missn\u00f6jet innan han hann v\u00e4lja sina ord.", case_study_cloze: "Chefens ____ medan han lyssnade p\u00e5 bortf\u00f6rklaringen visade hans missn\u00f6je med svaret." } },
      { concept: "EYE ADORNMENT", definition: "Since the time of the Egyptian pyramids, women and men across the globe have adorned their eyes (eyelids, under the eye, the sides, etc.) with a variety of colors to make themselves more aesthetically appealing. Using inks, dyes, minerals, and oils, people have made this part of their cultural traditions, and it has been passed down to our modern society for a reason: it works. We are attracted to eyes, even more so when they are adorned with colors. We are also attracted to long, thick eyelashes -something that mostly women but some men accentuate to make themselves more appealing.", category: "body-language-extracted", real_world_scenario: "At the wedding, the bride's darkly lined eyes drew every gaze in the room \u2014 thousands of years after the Egyptians, adorning the eyes still works to attract.", case_study_cloze: "Since the Egyptian pyramids, people have used ____ to adorn their eyes and make themselves more attractive.", sv: { concept: "Att pryda \u00f6gonen", definition: "\u00c4nda sedan de egyptiska pyramidernas tid har kvinnor och m\u00e4n \u00f6ver hela v\u00e4rlden prytt sina \u00f6gon (\u00f6gonlock, under \u00f6gat, sidorna etc.) med en m\u00e4ngd olika f\u00e4rger f\u00f6r att g\u00f6ra sig mer estetiskt tilltalande. Med hj\u00e4lp av bl\u00e4ck, f\u00e4rg\u00e4mnen, mineraler och oljor har m\u00e4nniskor gjort detta till en del av sina kulturella traditioner, och det har f\u00f6rts vidare till v\u00e5rt moderna samh\u00e4lle av en anledning: det fungerar. Vi dras till \u00f6gon, \u00e4nnu mer n\u00e4r de \u00e4r prydda med f\u00e4rger. Vi dras ocks\u00e5 till l\u00e5nga, tjocka \u00f6gonfransar \u2013 n\u00e5got som mest kvinnor men en del m\u00e4n framh\u00e4ver f\u00f6r att g\u00f6ra sig mer tilltalande.", real_world_scenario: "P\u00e5 br\u00f6llopet drog brudens m\u00f6rkt sminkade \u00f6gon blickarna till sig fr\u00e5n hela rummet \u2014 tusentals \u00e5r efter egyptierna fungerar det fortfarande att pryda \u00f6gonen f\u00f6r att locka.", case_study_cloze: "\u00c4nda sedan de egyptiska pyramiderna har m\u00e4nniskor prytt sina ____ f\u00f6r att g\u00f6ra sig mer attraktiva." } },
      { concept: "LISTENING", definition: "Active listening is an essential nonverbal in both professional and personal settings. It communicates that we are interested, receptive, or empathetic. Good listeners yield their turn, wait to speak, and are patient when others are speaking. To accom plish this we make sure that we face the person we are interested in hearing so that both ears can receive the message.", category: "body-language-extracted", real_world_scenario: "In the argument with her teenager, the mother turned her whole body toward him and waited until he finished before speaking \u2014 active listening that defused the fight.", case_study_cloze: "The good listener faced the speaker so that both ____ could receive the message.", sv: { concept: "Aktivt lyssnande", definition: "Aktivt lyssnande \u00e4r en viktig icke-verbal signal i b\u00e5de yrkeslivet och privatlivet. Det f\u00f6rmedlar att vi \u00e4r intresserade, mottagliga eller empatiska. Bra lyssnare l\u00e4mnar \u00f6ver ordet, v\u00e4ntar med att prata och \u00e4r t\u00e5lmodiga n\u00e4r andra talar. F\u00f6r att \u00e5stadkomma detta ser vi till att v\u00e4nda oss mot den person vi vill h\u00f6ra s\u00e5 att b\u00e5da \u00f6ronen kan ta emot budskapet.", real_world_scenario: "I gr\u00e4let med ton\u00e5ringen v\u00e4nde mamman hela kroppen mot honom och v\u00e4ntade tills han var klar innan hon talade \u2014 aktivt lyssnande som avv\u00e4pnade konflikten.", case_study_cloze: "Den gode lyssnaren v\u00e4nde sig mot talaren s\u00e5 att b\u00e5da ____ kunde ta emot budskapet." } },
      { concept: "MOUTH STRETCHING", definition: "When we are afraid or realize we made a mistake, we often find ourselves involuntarily exposing the bottom row of clenched teeth as the corners of the mouth stretch substantially downward and to the side. This is often seen when we are reminded that we forgot to bring something important.", category: "body-language-extracted", real_world_scenario: "At the airport, the traveler suddenly stretched his mouth downward and to the side, exposing his clenched bottom teeth, when the security officer asked for his boarding pass \u2014 he realized he had left it in his other jacket.", case_study_cloze: "When the manager reminded her about the forgotten report, Maria's mouth stretched downward and exposed her clenched bottom teeth \u2014 an involuntary ____ reaction to realizing her mistake.", sv: { concept: "Munstr\u00e4ckning", definition: "N\u00e4r vi \u00e4r r\u00e4dda eller inser att vi har gjort ett misstag blottar vi ofta ofrivilligt den nedre raden av sammanbitna t\u00e4nder medan mungiporna str\u00e4cks kraftigt ned\u00e5t och \u00e5t sidan. Detta syns ofta n\u00e4r vi p\u00e5minns om att vi har gl\u00f6mt att ta med oss n\u00e5got viktigt.", real_world_scenario: "P\u00e5 flygplatsen str\u00e4ckte resen\u00e4ren pl\u00f6tsligt munnen ned\u00e5t och \u00e5t sidan och blottade de sammanbitna nedre t\u00e4nderna n\u00e4r s\u00e4kerhetspersonalen bad om hans boardingkort \u2014 han ins\u00e5g att han hade l\u00e4mnat det i den andra jackan.", case_study_cloze: "N\u00e4r chefen p\u00e5minde henne om den gl\u00f6mda rapporten str\u00e4cktes Marias mun ned\u00e5t och blottade de nedre t\u00e4nderna \u2014 en ofrivillig ____ som avsl\u00f6jade att hon ins\u00e5g sitt misstag." } },
      { concept: "YAWNING", definition: "Yawning is an excellent pacifier, as it relieves pent-up stress by stimulating nerves in the jaw; specifically the temporomandibular joint. It was also recently discovered that the rapid intake of air when we yawn cools the blood circulating within the palate of the mouth and, like a car radiator, the blood going to the brain. Yawning may indicate that someone is too hot or, as I often found during interviews, that an interviewee was severely stressed. Babies wrapped too warmly will also yawn with greater frequency as they sleep to help them cool down.", category: "body-language-extracted", real_world_scenario: "During the tense family meeting about the mortgage, her brother yawned repeatedly even though no one was tired \u2014 a classic pacifier that released his pent-up stress rather than a sign of boredom.", case_study_cloze: "Even well-rested people may ____ under stress, since the jaw movement pacifies them by stimulating nerves in the temporomandibular joint.", sv: { concept: "G\u00e4spning", definition: "Att g\u00e4spa \u00e4r ett utm\u00e4rkt s\u00e4tt att lugna sig, eftersom det lindrar uppd\u00e4md stress genom att stimulera nerverna i k\u00e4ken, specifikt k\u00e4kleden. Det har ocks\u00e5 nyligen uppt\u00e4ckts att det snabba luftintaget n\u00e4r vi g\u00e4spar kyler blodet som cirkulerar i gommens slemhinna och, som en bilkylare, \u00e4ven blodet som g\u00e5r till hj\u00e4rnan. G\u00e4spning kan tyda p\u00e5 att n\u00e5gon har det f\u00f6r varmt eller, som jag ofta s\u00e5g under intervjuer, att en intervjuperson var kraftigt stressad. Bebisar som \u00e4r f\u00f6r varmt kl\u00e4dda g\u00e4spar ocks\u00e5 oftare medan de sover f\u00f6r att kyla ner sig.", real_world_scenario: "Under det sp\u00e4nda familjem\u00f6tet om bol\u00e5net g\u00e4spade hennes bror g\u00e5ng p\u00e5 g\u00e5ng trots att ingen var tr\u00f6tt \u2014 en klassisk lugnande gest som sl\u00e4ppte ut uppd\u00e4md stress snarare \u00e4n ett tecken p\u00e5 uttr\u00e5kning.", case_study_cloze: "\u00c4ven v\u00e4lvilade m\u00e4nniskor kan ____ under stress, eftersom k\u00e4kr\u00f6relsen lugnar dem genom att stimulera nerverna i k\u00e4kleden." } },
      { concept: "SMOKING", definition: "People who smoke do so more often when they are stressed. Note any deviations from a person's normal smoking routine as evidence of how stressed they may be. They may be so stressed they lose count of how many cigarettes they have lit. Excessive smoking also leads to tobacco stains on the fingers and, of course, the stench in their hands.", category: "body-language-extracted", real_world_scenario: "At the office, Daniel noticed that his colleague, who normally smoked two cigarettes a day, had lit five before lunch \u2014 the deviation from her normal smoking routine showed how stressed she was.", case_study_cloze: "A smoker who lights one cigarette after another without keeping count is clearly stressed \u2014 note any ____ from a person's normal smoking routine.", sv: { concept: "R\u00f6kning", definition: "M\u00e4nniskor som r\u00f6ker g\u00f6r det oftare n\u00e4r de \u00e4r stressade. L\u00e4gg m\u00e4rke till avvikelser fr\u00e5n en persons normala r\u00f6kvanor som bevis p\u00e5 hur stressade de kan vara. De kan vara s\u00e5 stressade att de tappar r\u00e4kningen p\u00e5 hur m\u00e5nga cigaretter de har t\u00e4nt. \u00d6verdriven r\u00f6kning leder ocks\u00e5 till nikotinfl\u00e4ckar p\u00e5 fingrarna och f\u00f6rst\u00e5s stanken p\u00e5 h\u00e4nderna.", real_world_scenario: "P\u00e5 kontoret m\u00e4rkte Daniel att hans kollega, som vanligtvis r\u00f6kte tv\u00e5 cigaretter om dagen, hade t\u00e4nt fem f\u00f6re lunchen \u2014 avvikelsen fr\u00e5n hennes normala r\u00f6kvanor visade hur stressad hon var.", case_study_cloze: "En r\u00f6kare som t\u00e4nder den ena cigaretten efter den andra utan att h\u00e5lla r\u00e4kningen \u00e4r tydligt stressad \u2014 notera alla ____ fr\u00e5n personens normala r\u00f6kvanor." } },
      { concept: "OVEREATING", definition: "Under stress some people will overeat, sometimes going far beyond their normal food intake. I have seen people during a football game consume vast amounts of food, to the point of getting sick, their anxiety over the status of their favorite team transferred to their appetite.", category: "body-language-extracted", real_world_scenario: "During the championship game, his father devoured an entire pizza, a bag of chips and three sodas in a single quarter \u2014 his anxiety over the team's performance transferred directly into his appetite.", case_study_cloze: "Some people respond to stress by ____, eating far beyond their normal food intake as their anxiety is transferred to their appetite.", sv: { concept: "\u00d6ver\u00e4tning", definition: "Under stress \u00e4ter vissa m\u00e4nniskor f\u00f6r mycket, ibland l\u00e5ngt ut\u00f6ver sin normala matkonsumtion. Jag har sett m\u00e4nniskor under en fotbollsmatch f\u00f6rt\u00e4ra enorma m\u00e4ngder mat, \u00e4nda tills de blev illam\u00e5ende, medan deras oro \u00f6ver favoritlagets status \u00f6verf\u00f6rdes till deras aptit.", real_world_scenario: "Under finalmatchen tryckte hans pappa i sig en hel pizza, en p\u00e5se chips och tre l\u00e4skburkar under en enda kvart \u2014 hans oro \u00f6ver lagets prestation \u00f6verf\u00f6rdes rakt till aptiten.", case_study_cloze: "Vissa m\u00e4nniskor reagerar p\u00e5 stress genom ____ och \u00e4ter l\u00e5ngt ut\u00f6ver sin normala m\u00e4ngd mat n\u00e4r deras oro \u00f6verf\u00f6rs till aptiten." } },
      { concept: "TONGUE INSULTS", definition: "In almost all cultures the sticking out of the tongue is used as an insult, a display of disgust or dislike. Children use this technique from a very young age when they want to insult one another. Pacific Island warriors such as the M ori will dramatically stick their tongue out and down as a way to intimidate and insult. Coupled with very wide eyes, a stuck-out tongue can be quite intimidating, and it is still used to this day in M ori haka ceremonies.", category: "body-language-extracted", real_world_scenario: "On the playground, eight-year-old Emma stuck out her tongue at her brother after he tore up her drawing, and he knew exactly what the gesture meant \u2014 an insult that needs no words.", case_study_cloze: "Across almost all cultures, sticking out the tongue is used as an ____, a display of disgust or dislike that children master at a very young age.", sv: { concept: "Tungan som f\u00f6rol\u00e4mpning", definition: "I n\u00e4stan alla kulturer anv\u00e4nds att r\u00e4cka ut tungan som en f\u00f6rol\u00e4mpning, ett uttryck f\u00f6r avsky eller ogillande. Barn anv\u00e4nder denna teknik fr\u00e5n mycket tidig \u00e5lder n\u00e4r de vill f\u00f6rol\u00e4mpa varandra. Stilla havets \u00f6-krigare, som maorierna, r\u00e4cker dramatiskt ut tungan och ned\u00e5t som ett s\u00e4tt att skr\u00e4mma och f\u00f6rol\u00e4mpa. I kombination med mycket vida \u00f6gon kan en utstr\u00e4ckt tunga vara ganska skr\u00e4mmande, och den anv\u00e4nds fortfarande i maoriernas hakaceremonier.", real_world_scenario: "P\u00e5 lekplatsen r\u00e4ckte \u00e5tta\u00e5riga Emma ut tungan mot sin bror efter att han rivit s\u00f6nder hennes teckning, och han f\u00f6rstod exakt vad gesten betydde \u2014 en f\u00f6rol\u00e4mpning som inte beh\u00f6ver ord.", case_study_cloze: "I n\u00e4stan alla kulturer anv\u00e4nds utstr\u00e4ckt tunga som en ____, en uppvisning av avsky eller ogillande som barn bem\u00e4strar i mycket tidig \u00e5lder." } },
      { concept: "TONGUE PROTRUDING", definition: "Oftentimes, while performing a complex task, people will stick out their tongue, usually to one side or the other, or drape it over their lower lip. I had an accountant who did this as he entered numbers into a calculator, and I see it all the time at the university when students are taking tests. This tongue placement serves dual purposes: it pacifies us while simultaneously communicating to others that we are busy and should not be disturbed. Michael Jordan famously did this while playing basketball; when his tongue was out, two points usually soon followed.", category: "body-language-extracted", real_world_scenario: "In the exam hall, the student stuck his tongue out to one side as he worked through the calculus problems \u2014 the gesture pacified him and silently told his classmates he was busy and should not be disturbed.", case_study_cloze: "When people concentrate on a complex task, they often ____, a behavior that pacifies them and signals to others that they are busy.", sv: { concept: "Att sticka ut tungan", definition: "Ofta, n\u00e4r m\u00e4nniskor utf\u00f6r en komplex uppgift, sticker de ut tungan, vanligtvis \u00e5t ena eller andra sidan, eller l\u00e5ter den vila \u00f6ver underl\u00e4ppen. Jag hade en revisor som gjorde detta n\u00e4r han knappade in siffror p\u00e5 en minir\u00e4knare, och jag ser det hela tiden p\u00e5 universitetet n\u00e4r studenter skriver prov. Denna tungplacering tj\u00e4nar tv\u00e5 syften: den lugnar oss och kommunicerar samtidigt till andra att vi \u00e4r upptagna och inte b\u00f6r st\u00f6ras. Michael Jordan gjorde detta ber\u00f6mt n\u00e4r han spelade basket; n\u00e4r tungan var ute f\u00f6ljde oftast tv\u00e5 po\u00e4ng strax efter.", real_world_scenario: "I tentasalen stack studenten ut tungan \u00e5t sidan medan han l\u00f6ste matteuppgifterna \u2014 gesten lugnade honom och sa tyst till klasskamraterna att han var upptagen och inte borde st\u00f6ras.", case_study_cloze: "N\u00e4r m\u00e4nniskor koncentrerar sig p\u00e5 en komplex uppgift ____ de ofta tungan, ett beteende som lugnar dem och signalerar till andra att de \u00e4r upptagna." } },
      { concept: "TONGUE PRESSING AGAINST PALATE", definition: "People might press their tongue against the roof of their mouth when they are struggling with something. It is seen in people taking tests, filling out applications, after missing a shot in basketball, or when somebody needs psychological comforting. The mouth is generally left slightly open, allowing observers to at least partially see the tongue.", category: "body-language-extracted", real_world_scenario: "Her teenage son pressed his tongue against the roof of his mouth after missing the game-winning free throw, his mouth slightly open as he processed the disappointment and comforted himself.", case_study_cloze: "When someone struggles with a problem and presses their tongue against the roof of their mouth, the mouth is usually left slightly ____.", sv: { concept: "Tungan tryckt mot gommen", definition: "M\u00e4nniskor kan trycka tungan mot gommen n\u00e4r de k\u00e4mpar med n\u00e5got. Det syns hos m\u00e4nniskor som g\u00f6r prov, fyller i ans\u00f6kningar, efter en missad basketkorg eller n\u00e4r n\u00e5gon beh\u00f6ver psykologisk tr\u00f6st. Munnen l\u00e4mnas oftast n\u00e5got \u00f6ppen, s\u00e5 att betraktare \u00e5tminstone delvis kan se tungan.", real_world_scenario: "Hennes ton\u00e5rsson tryckte tungan mot gommen efter att ha missat det avg\u00f6rande straffkastet, med munnen l\u00e4tt \u00f6ppen medan han bearbetade besvikelsen och tr\u00f6stade sig sj\u00e4lv.", case_study_cloze: "N\u00e4r n\u00e5gon k\u00e4mpar med ett problem och trycker tungan mot gommen l\u00e4mnas munnen oftast n\u00e5got ____." } },
      { concept: "UPTALK", definition: "Uptalk is when people inflect their tone up at the end of a", category: "body-language-extracted", real_world_scenario: "In the job interview, the candidate ended every answer with a rising tone, so that even statements like 'I have five years of experience' sounded like questions \u2014 an uptalk pattern that undercut her confidence.", case_study_cloze: "When a speaker raises the tone at the end of a statement so that it sounds like a question, the speaker is using ____.", sv: { concept: "Upp\u00e5tintonation", definition: "Uptalk \u00e4r n\u00e4r m\u00e4nniskor h\u00f6jer tonen i slutet av en mening, s\u00e5 att p\u00e5st\u00e5enden l\u00e5ter som fr\u00e5gor.", real_world_scenario: "I anst\u00e4llningsintervjun avslutade kandidaten varje svar med stigande ton, s\u00e5 att \u00e4ven p\u00e5st\u00e5enden som 'Jag har fem \u00e5rs erfarenhet' l\u00e4t som fr\u00e5gor \u2014 upp\u00e5tintonationen underminerade hennes sj\u00e4lvf\u00f6rtroende.", case_study_cloze: "N\u00e4r en talare h\u00f6jer tonen i slutet av ett p\u00e5st\u00e5ende s\u00e5 att det l\u00e5ter som en fr\u00e5ga, anv\u00e4nder talaren ____." } },
      { concept: "STUTTERING/STAMMERING", definition: "Some individuals pathologically stutter (repeating syllables as they try to speak). For some it can be quite debilitating, as in the case of England's King George VI, famously depicted by Colin Firth in the 2010 movie The King's Speech. For many of us who do not stutter pathologically, a high degree of stress or anxiety can cause us to temporarily stutter or stammer.", category: "body-language-extracted", real_world_scenario: "In the police interview, the normally fluent suspect began to stammer and repeat syllables whenever the officer mentioned the night of the robbery \u2014 high stress can make anyone temporarily stutter.", case_study_cloze: "For people who do not stutter pathologically, a high degree of ____ or anxiety can cause them to temporarily stutter or stammer.", sv: { concept: "Stamning", definition: "Vissa individer stammar patologiskt (upprepar stavelser n\u00e4r de f\u00f6rs\u00f6ker tala). F\u00f6r vissa kan det vara mycket handikappande, som i fallet med Englands kung Georg VI, ber\u00f6mt skildrad av Colin Firth i 2010 \u00e5rs film The King's Speech. F\u00f6r m\u00e5nga av oss som inte stammar patologiskt kan en h\u00f6g grad av stress eller \u00e5ngest f\u00e5 oss att tillf\u00e4lligt stamma eller hacka i talet.", real_world_scenario: "I polisf\u00f6rh\u00f6ret b\u00f6rjade den annars talf\u00f6re misst\u00e4nkte hacka och upprepa stavelser s\u00e5 fort polisen n\u00e4mnde kv\u00e4llen f\u00f6r r\u00e5net \u2014 h\u00f6g stress kan f\u00e5 vem som helst att stamma tillf\u00e4lligt.", case_study_cloze: "F\u00f6r m\u00e4nniskor som inte stammar patologiskt kan en h\u00f6g grad av ____ eller \u00e5ngest f\u00e5 dem att tillf\u00e4lligt stamma eller hacka i talet." } },
      { concept: "SILENCE", definition: "A prolonged silence, or even just a \\\"pregnant pause,\\\" may speak volumes. Sometimes, when we cannot remember information or we are contemplating something, a silence is unintentional. But other times it is very much intended, as when a negotiator may go temporarily silent to get the other party to fill in the void. Silence can be used to communicate that the person is pondering, recollecting, considering, processing, or is nonplussed. Great actors use it effectively, as do interviewers.", category: "body-language-extracted", real_world_scenario: "The car dealer quoted a price and then went quiet, letting the silence hang in the showroom; the customer, uncomfortable with the void, spoke first and raised his own offer.", case_study_cloze: "A negotiator may go temporarily silent on purpose, using the ____ to pressure the other party to fill the void.", sv: { concept: "Tystnad", definition: "En utdragen tystnad, eller bara en 'b\u00f6rdig paus', kan s\u00e4ga mycket. Ibland, n\u00e4r vi inte kan minnas information eller begrundar n\u00e5got, \u00e4r tystnaden oavsiktlig. Men andra g\u00e5nger \u00e4r den mycket avsiktlig, som n\u00e4r en f\u00f6rhandlare tillf\u00e4lligt blir tyst f\u00f6r att f\u00e5 motparten att fylla tomrummet. Tystnad kan anv\u00e4ndas f\u00f6r att kommunicera att personen funderar, minns, \u00f6verv\u00e4ger, bearbetar eller \u00e4r st\u00e4lld. Stora sk\u00e5despelare anv\u00e4nder den effektivt, liksom intervjuare.", real_world_scenario: "Bilhandlaren sa ett pris och blev sedan tyst, och l\u00e4t tystnaden h\u00e4nga kvar i bilhallen; kunden, som k\u00e4nde sig obekv\u00e4m i tomrummet, talade f\u00f6rst och h\u00f6jde sitt eget bud.", case_study_cloze: "En f\u00f6rhandlare kan medvetet bli tillf\u00e4lligt tyst och anv\u00e4nda ____ f\u00f6r att pressa motparten att fylla tomrummet." } },
      { concept: "INCESSANT TALKING", definition: "We have all met people who seem to never stop talking. They might simply be nervous, or they might be inconsiderate of others and focused only on themselves. Context is key. In the aftermath of an accident, a person might ramble, talking nonstop. This is caused by shock. But at a party, the man who talks your ear off is letting you know who he thinks it most important-and it's not you.", category: "body-language-extracted", real_world_scenario: "After the fender bender, the driver of the other car talked nonstop for ten minutes, jumping between insurance, the weather and his grandchildren \u2014 shock, not rudeness, was driving the ramble.", case_study_cloze: "In the aftermath of an accident, a person may ramble and talk nonstop; this outpouring of words is usually caused by ____.", sv: { concept: "Oavbrutet pratande", definition: "Vi har alla tr\u00e4ffat m\u00e4nniskor som aldrig verkar sluta prata. De kan helt enkelt vara nerv\u00f6sa, eller s\u00e5 kan de vara h\u00e4nsynsl\u00f6sa mot andra och bara fokuserade p\u00e5 sig sj\u00e4lva. Sammanhanget \u00e4r avg\u00f6rande. Efter en olycka kan en person pladdra p\u00e5 och prata oavbrutet. Detta orsakas av chock. Men p\u00e5 en fest l\u00e5ter mannen som pratar \u00f6ronen av dig dig f\u00f6rst\u00e5 vem han anser vara viktigast \u2014 och det \u00e4r inte du.", real_world_scenario: "Efter krocken pratade f\u00f6raren i den andra bilen oavbrutet i tio minuter och hoppade mellan f\u00f6rs\u00e4kringen, v\u00e4dret och barnbarnen \u2014 det var chock, inte oh\u00f6vlighet, som drev pladdret.", case_study_cloze: "I efterdyningarna av en olycka kan en person pladdra p\u00e5 och prata oavbrutet; detta ordfl\u00f6de orsakas vanligtvis av ____." } },
      { concept: "LAUGHTER", definition: "Laughter is a universal display of amusement, happiness, and joy. We know that when we laugh we experience less stress and even less pain; indeed, the act of laughing may have arisen in us as a protective evolutionary benefit. There are, of course, many different sorts of laughter: unrestrained cackles when we hear a genuinely hilarious joke; the joyous laughter of children; the obsequious laughter of those who seek to flatter a leader. How someone laughs says a lot, and should be examined for the true depth of sentiment and context when you're in doubt.", category: "body-language-extracted", real_world_scenario: "At the wedding reception, the grandfather's unrestrained cackle at a harmless joke was far louder than the joke deserved \u2014 his joy was genuine, and the laughter signaled real amusement.", case_study_cloze: "When we hear a genuinely hilarious joke, we may burst into unrestrained ____, a universal display of amusement that relieves stress and even pain.", sv: { concept: "Skratt", definition: "Skratt \u00e4r en universell uppvisning av n\u00f6je, gl\u00e4dje och lycka. Vi vet att n\u00e4r vi skrattar upplever vi mindre stress och till och med mindre sm\u00e4rta; faktiskt kan sj\u00e4lva skrattandet ha uppst\u00e5tt hos oss som en skyddande evolution\u00e4r f\u00f6rdel. Det finns f\u00f6rst\u00e5s m\u00e5nga olika sorters skratt: oh\u00e4mmade gapskratt n\u00e4r vi h\u00f6r ett genuint roligt sk\u00e4mt; barns gl\u00e4djefyllda skratt; det inst\u00e4llsamma skrattet fr\u00e5n dem som s\u00f6ker smickra en ledare. Hur n\u00e5gon skrattar s\u00e4ger mycket, och det b\u00f6r unders\u00f6kas f\u00f6r den sanna k\u00e4nslans djup och sammanhang n\u00e4r du tvivlar.", real_world_scenario: "P\u00e5 br\u00f6llopsfesten skrattade morfadern oh\u00e4mmat \u00e5t ett oskyldigt sk\u00e4mt \u2014 mycket h\u00f6gre \u00e4n sk\u00e4mtet f\u00f6rtj\u00e4nade; gl\u00e4djen var \u00e4kta, och skrattet avsl\u00f6jade genuint n\u00f6je.", case_study_cloze: "N\u00e4r vi h\u00f6r ett genuint roligt sk\u00e4mt kan vi brista ut i ett oh\u00e4mmat ____, en universell uppvisning av n\u00f6je som lindrar stress och till och med sm\u00e4rta." } },
      { concept: "LIP QUIVERING", definition: "The quivering of the edges of the lips, no matter how slight, in the absence of alcohol or neurological disorders, indicates discomfort, concern, fear, or other issues. Young people when questioned by parents or other adults in positions of authority often display quivering lips, as do honest people who have never been confronted by law enforcement officers before. I have also heard from human resources personnel that some young people's lips will quiver when they are asked if they use illicit drugs.", category: "body-language-extracted", real_world_scenario: "When his father asked where he had been all night, the teenager's lips began to quiver slightly \u2014 a sign of fear and discomfort that appeared even though he tried to keep his voice steady.", case_study_cloze: "Even the slightest quivering of the lips, in the absence of alcohol or neurological disorders, indicates ____, concern, fear, or other issues.", sv: { concept: "Darrande l\u00e4ppar", definition: "Att l\u00e4ppkanterna darrar, hur svagt det \u00e4n \u00e4r, i fr\u00e5nvaro av alkohol eller neurologiska sjukdomar, tyder p\u00e5 obehag, oro, r\u00e4dsla eller andra problem. Unga m\u00e4nniskor som f\u00f6rh\u00f6rs av f\u00f6r\u00e4ldrar eller andra vuxna i auktoritetsst\u00e4llning visar ofta darrande l\u00e4ppar, liksom \u00e4rliga m\u00e4nniskor som aldrig tidigare konfronterats av polis. Jag har ocks\u00e5 h\u00f6rt fr\u00e5n personalansvariga att vissa ungas l\u00e4ppar darrar n\u00e4r de fr\u00e5gas om de anv\u00e4nder droger.", real_world_scenario: "N\u00e4r hans pappa fr\u00e5gade var han hade varit hela kv\u00e4llen b\u00f6rjade ton\u00e5ringens l\u00e4ppar darra l\u00e4tt \u2014 ett tecken p\u00e5 r\u00e4dsla och obehag som syntes trots att han f\u00f6rs\u00f6kte h\u00e5lla r\u00f6sten stadig.", case_study_cloze: "\u00c4ven den minsta darrningen av l\u00e4pparna, i fr\u00e5nvaro av alkohol eller neurologiska sjukdomar, tyder p\u00e5 ____, oro, r\u00e4dsla eller andra problem." } },
      { concept: "UPSIDE", definition: "DOWN LIPS -When the lips are compressed and the corners of the mouth turn downward, things are really bad emotionally. This is a strong indicator of high stress or discomfort. This behavior is difficult to fake, so it is very accurate. Be careful, however, because some people have naturally downturned mouths. This indicator is similar to the \\\"grouper\\\" mouth ( see #156), but in this case the lips either are very tightly compressed or have disappeared completely.", category: "body-language-extracted", real_world_scenario: "When the doctor told him the scans showed nothing, the patient's lips compressed tightly and the corners of his mouth turned sharply downward \u2014 for a moment, the upside-down lips betrayed his true distress.", case_study_cloze: "When the lips are compressed and the corners of the mouth turn downward, the ____ signal high stress or discomfort, and this behavior is very difficult to fake.", sv: { concept: "Ner\u00e5tv\u00e4nda l\u00e4ppar", definition: "NED\u00c5TV\u00c4NDA L\u00c4PPAR -N\u00e4r l\u00e4pparna \u00e4r sammanpressade och mungiporna v\u00e4nds ned\u00e5t \u00e4r det verkligen d\u00e5ligt k\u00e4nslom\u00e4ssigt. Detta \u00e4r en stark indikator p\u00e5 h\u00f6g stress eller obehag. Detta beteende \u00e4r sv\u00e5rt att fejka, s\u00e5 det \u00e4r mycket tillf\u00f6rlitligt. Var dock f\u00f6rsiktig, eftersom vissa m\u00e4nniskor naturligt har ned\u00e5tv\u00e4nda mungipor. Denna indikator liknar 'surmunnen' (se #156), men i detta fall \u00e4r l\u00e4pparna antingen h\u00e5rt sammanpressade eller har f\u00f6rsvunnit helt.", real_world_scenario: "N\u00e4r l\u00e4karen ber\u00e4ttade att r\u00f6ntgenunders\u00f6kningen inte visade n\u00e5got pressade patienten ihop l\u00e4pparna och mungiporna drogs skarpt ned\u00e5t \u2014 f\u00f6r ett \u00f6gonblick f\u00f6rr\u00e5dde de ner\u00e5tv\u00e4nda l\u00e4pparna hans verkliga f\u00f6rtvivlan.", case_study_cloze: "N\u00e4r l\u00e4pparna \u00e4r sammanpressade och mungiporna v\u00e4nds ned\u00e5t signalerar ____ h\u00f6g stress eller obehag, och detta beteende \u00e4r mycket sv\u00e5rt att fejka." } },
      { concept: "SMILE", definition: "A genuine smile is an instant, surefire way to communicate friendliness and goodwill. Around the world it signals warmth, friendliness, and social harmony. Watching someone smile, especially babies, brings us joy. In family relations, dating, and business a smile opens doors as well as hearts. There are a variety of smiles, including social smiles for those whom", category: "body-language-extracted", real_world_scenario: "When the cashier looked up and gave her a genuine smile, the corners of his eyes crinkling, the customer's bad mood lifted \u2014 a warm smile opens doors in business, dating and family life alike.", case_study_cloze: "A genuine smile signals warmth, friendliness and social harmony, and it opens ____ as well as hearts.", sv: { concept: "Leende", definition: "Ett \u00e4kta leende \u00e4r ett omedelbart, s\u00e4kert s\u00e4tt att kommunicera v\u00e4nlighet och v\u00e4lvilja. \u00d6ver hela v\u00e4rlden signalerar det v\u00e4rme, v\u00e4nlighet och social harmoni. Att se n\u00e5gon le, s\u00e4rskilt bebisar, ger oss gl\u00e4dje. I familjerelationer, dejting och aff\u00e4rsliv \u00f6ppnar ett leende b\u00e5de d\u00f6rrar och hj\u00e4rtan. Det finns en m\u00e4ngd olika leenden, inklusive sociala leenden f\u00f6r dem vi inte k\u00e4nner s\u00e5 v\u00e4l.", real_world_scenario: "N\u00e4r kass\u00f6rskan tittade upp och gav henne ett \u00e4kta leende med krusade \u00f6gonvr\u00e5r l\u00e4ttades kundens d\u00e5liga hum\u00f6r \u2014 ett varmt leende \u00f6ppnar d\u00f6rrar b\u00e5de i aff\u00e4rslivet, i dejting och i familjelivet.", case_study_cloze: "Ett \u00e4kta leende signalerar v\u00e4rme, v\u00e4nlighet och social harmoni, och det \u00f6ppnar ____ s\u00e5v\u00e4l som hj\u00e4rtan." } },
      { concept: "UPPER LIP RISE", definition: "Disgust, negative sentiments, disdain, or dislike will cause the upper corner of the lip on one side of the mouth to rise slightly or \\\"tent\\\" upward. When the sentiments are strong, the rise can be very noticeable, distorting the upper lip toward the nose and exposing the teeth, almost in a snarl. This is a sign of utter dislike or disgust.", category: "body-language-extracted", real_world_scenario: "During the tasting, the food critic's upper lip rose slightly on one side, tenting toward his nose, as he sampled the sauce \u2014 an involuntary sign of utter dislike that no polite words could hide.", case_study_cloze: "Disgust or disdain causes the upper corner of the lip to rise, sometimes distorting the lip toward the ____ in almost a snarl.", sv: { concept: "\u00d6verl\u00e4ppen h\u00f6js", definition: "Avsky, negativa k\u00e4nslor, f\u00f6rakt eller ogillande f\u00e5r det \u00f6vre l\u00e4pph\u00f6rnet p\u00e5 ena sidan av munnen att h\u00f6jas n\u00e5got eller 't\u00e4lta' upp\u00e5t. N\u00e4r k\u00e4nslorna \u00e4r starka kan h\u00f6jningen vara mycket m\u00e4rkbar och f\u00f6rvr\u00e4nger \u00f6verl\u00e4ppen mot n\u00e4san och blottar t\u00e4nderna, n\u00e4stan som i ett morrande. Detta \u00e4r ett tecken p\u00e5 totalt ogillande eller avsky.", real_world_scenario: "Under provsmakningen h\u00f6jdes matkritikerns \u00f6verl\u00e4pp n\u00e5got p\u00e5 ena sidan, t\u00e4ltad upp mot n\u00e4san, n\u00e4r han smakade p\u00e5 s\u00e5sen \u2014 en ofrivillig signal om totalt ogillande som inga artiga ord kunde d\u00f6lja.", case_study_cloze: "Avsky eller f\u00f6rakt f\u00e5r det \u00f6vre l\u00e4pph\u00f6rnet att h\u00f6jas, ibland s\u00e5 att l\u00e4ppen f\u00f6rvr\u00e4ngs mot ____ n\u00e4stan som i ett morrande." } },
      { concept: "UPPER", definition: "LIP TONGUE RUBBING -Some people reflect their positive emotions by licking their upper lip briskly back and forth. Because the tongue is in essence defying gravity (going for the upper lip), positive emotions are more likely involved. This is differentiated from the usual lip licking, which is done on the lower lip and is associated with stress release. As with all body-language indicators, there are exceptions, and some people rub the upper lip to relieve stress, so look for other confirming behaviors to guide you in drawing conclusions.", category: "body-language-extracted", real_world_scenario: "As she described her vacation plans, she briskly licked her upper lip back and forth \u2014 unlike lower-lip licking, this upward tongue motion tends to accompany positive emotions.", case_study_cloze: "Licking the ____ briskly back and forth is more often linked to positive emotions, while licking the lower lip is usually associated with stress release.", sv: { concept: "Tungan mot \u00f6verl\u00e4ppen", definition: "TUNGAN MOT \u00d6VERL\u00c4PPEN -Vissa m\u00e4nniskor visar sina positiva k\u00e4nslor genom att snabbt slicka \u00f6verl\u00e4ppen fram och tillbaka. Eftersom tungan i huvudsak trotsar tyngdkraften (den g\u00e5r mot \u00f6verl\u00e4ppen) \u00e4r positiva k\u00e4nslor mer sannolika. Detta skiljer sig fr\u00e5n vanligt l\u00e4ppslickande, som g\u00f6rs p\u00e5 underl\u00e4ppen och \u00e4r f\u00f6rknippat med stressavlastning. Som med alla kroppsspr\u00e5ksindikatorer finns det undantag, och vissa m\u00e4nniskor gnider \u00f6verl\u00e4ppen f\u00f6r att lindra stress, s\u00e5 leta efter andra bekr\u00e4ftande beteenden f\u00f6r att v\u00e4gleda dig n\u00e4r du drar slutsatser.", real_world_scenario: "N\u00e4r hon beskrev sina semesterplaner slickade hon snabbt \u00f6verl\u00e4ppen fram och tillbaka \u2014 till skillnad fr\u00e5n slickande p\u00e5 underl\u00e4ppen tenderar denna upp\u00e5triktade tungr\u00f6relse att \u00e5tf\u00f6lja positiva k\u00e4nslor.", case_study_cloze: "Att snabbt slicka ____ fram och tillbaka \u00e4r oftare f\u00f6rknippat med positiva k\u00e4nslor, medan l\u00e4ppslickande p\u00e5 underl\u00e4ppen brukar h\u00f6ra ihop med stressavlastning." } },
      { concept: "PUFFING OUT CHEEKS", definition: "The puffing out of the cheeks, without exhaling, often signifies doubt, deliberation, or caution. This is often seen in people who are not quite sure what to do next or who are apprehensive. It is not unusual to see someone hold this pose for quite a while as they work out the solution to a problem.", category: "body-language-extracted", real_world_scenario: "At the car dealership, the buyer puffed out his cheeks and held the pose for nearly a minute as he weighed whether to accept the offer \u2014 doubt and deliberation written on his face.", case_study_cloze: "Puffing out the cheeks without exhaling often signifies ____, deliberation, or caution in someone who is not quite sure what to do next.", sv: { concept: "Puffa upp kinderna", definition: "Att puffa upp kinderna utan att andas ut betyder ofta tvivel, eftertanke eller f\u00f6rsiktighet. Detta ses ofta hos m\u00e4nniskor som inte riktigt vet vad de ska g\u00f6ra h\u00e4rn\u00e4st eller som \u00e4r \u00e4ngsliga. Det \u00e4r inte ovanligt att se n\u00e5gon h\u00e5lla denna st\u00e4llning ganska l\u00e4nge medan de arbetar fram en l\u00f6sning p\u00e5 ett problem.", real_world_scenario: "P\u00e5 bilfirman puffade k\u00f6paren upp kinderna och h\u00f6ll st\u00e4llningen i n\u00e4stan en minut medan han v\u00e4gde om han skulle acceptera erbjudandet \u2014 tvivel och eftertanke stod skrivna i ansiktet.", case_study_cloze: "Att puffa upp kinderna utan att andas ut betyder ofta ____, eftertanke eller f\u00f6rsiktighet hos n\u00e5gon som inte riktigt vet vad han eller hon ska g\u00f6ra h\u00e4rn\u00e4st." } },
      { concept: "CHIN UP", definition: "When the chin is out and up it communicates confidence-thus the saying \\\"chin up.\\\" In certain European cultures (German, French, Russian, and Italian, among others) the chin is generally raised higher than normal to signify confidence, pride, and in certain cases, arrogance.", category: "body-language-extracted", real_world_scenario: "In the courtroom, the witness raised his chin high and squared his shoulders as he answered the lawyer's questions, signaling confidence \u2014 or, in this context, a touch of pride.", case_study_cloze: "When the chin is out and up, it communicates ____, which is why we say 'chin up'.", sv: { concept: "Hakan upp", definition: "N\u00e4r hakan \u00e4r framskjuten och h\u00f6jd kommunicerar det sj\u00e4lvf\u00f6rtroende \u2014 d\u00e4rav tales\u00e4ttet 'chin up'. I vissa europeiska kulturer (tyska, franska, ryska och italienska, bland andra) h\u00e5lls hakan generellt h\u00f6gre \u00e4n normalt f\u00f6r att signalera sj\u00e4lvf\u00f6rtroende, stolthet och i vissa fall arrogans.", real_world_scenario: "I r\u00e4ttssalen h\u00f6jde vittnet hakan h\u00f6gt och r\u00e4tade p\u00e5 axlarna n\u00e4r han svarade p\u00e5 advokatens fr\u00e5gor, vilket signalerade sj\u00e4lvf\u00f6rtroende \u2014 eller, i detta sammanhang, en gnutta stolthet.", case_study_cloze: "N\u00e4r hakan \u00e4r framskjuten och h\u00f6jd kommunicerar det ____, vilket \u00e4r varf\u00f6r vi s\u00e4ger 'chin up'." } },
      { concept: "CHIN", definition: "MUSCLE QUIVERING -The sudden quivering of chin muscles indicates fear, concern, anxiety, or apprehension. People who are about to cry will also do this. The mentalis muscle, which covers the chin and causes the skin to quiver, is one of the muscles that most reflects our emotions, according to Dr. David Givens. Sometimes the chin will reflect emotional turmoil even before the eyes.", category: "body-language-extracted", real_world_scenario: "Her eyes were dry, but the tiny quiver of the mentalis muscle in her chin gave her away \u2014 the chin often reflects emotional turmoil even before the eyes do.", case_study_cloze: "The sudden quivering of chin muscles indicates fear or anxiety, and people who are about to ____ will often do this.", sv: { concept: "Darrande hakmuskler", definition: "HAKMUSKELDARRNING -En pl\u00f6tslig darrning i hakmusklerna tyder p\u00e5 r\u00e4dsla, oro, \u00e5ngest eller \u00e4ngslan. M\u00e4nniskor som \u00e4r p\u00e5 v\u00e4g att gr\u00e5ta g\u00f6r ocks\u00e5 detta. Mentalismuskein, som t\u00e4cker hakan och f\u00e5r huden att darra, \u00e4r en av de muskler som mest speglar v\u00e5ra k\u00e4nslor, enligt Dr. David Givens. Ibland speglar hakan k\u00e4nslom\u00e4ssig turbulens redan innan \u00f6gonen g\u00f6r det.", real_world_scenario: "Hennes \u00f6gon var torra, men den lilla darrningen i mentalismuskein i hakan avsl\u00f6jade henne \u2014 hakan speglar ofta k\u00e4nslom\u00e4ssig turbulens redan innan \u00f6gonen g\u00f6r det.", case_study_cloze: "En pl\u00f6tslig darrning i hakmusklerna tyder p\u00e5 r\u00e4dsla eller \u00e5ngest, och m\u00e4nniskor som \u00e4r p\u00e5 v\u00e4g att ____ g\u00f6r ofta detta." } },
      { concept: "NECK STIFFENING", definition: "When people are attentive and receptive, and especially when they feel comfortable, they will tilt their neck to the side, exposing more of the neck than usual. If the feeling of comfort fades, however, their neck quickly becomes rigid. A stiff neck signifies hyperalertness and vigilance, and might suggest that a person takes issue with something that was just said, or has a serious matter to discuss. When a person goes from a relaxed state to a quick stiffening of the neck, it is a sure sign that something is amiss.", category: "body-language-extracted", real_world_scenario: "The couple had been talking comfortably, his neck tilted to expose it, until she mentioned his ex-wife \u2014 his neck snapped rigid in an instant, a sure sign that something was amiss.", case_study_cloze: "A person who goes from a relaxed state to a quick stiffening of the ____ is showing hyperalertness and vigilance \u2014 a sure sign that something is wrong.", sv: { concept: "Nacken stelnar", definition: "N\u00e4r m\u00e4nniskor \u00e4r uppm\u00e4rksamma och mottagliga, och s\u00e4rskilt n\u00e4r de k\u00e4nner sig bekv\u00e4ma, lutar de nacken \u00e5t sidan och blottar mer av nacken \u00e4n vanligt. Om k\u00e4nslan av bekv\u00e4mlighet bleknar blir dock nacken snabbt stel. En stel nacke signalerar hypervaksamhet och vaksamhet, och kan tyda p\u00e5 att en person inv\u00e4nder mot n\u00e5got som just sagts eller har en allvarlig sak att diskutera. N\u00e4r en person g\u00e5r fr\u00e5n ett avslappnat tillst\u00e5nd till att nacken snabbt stelnar \u00e4r det ett s\u00e4kert tecken p\u00e5 att n\u00e5got \u00e4r fel.", real_world_scenario: "Paret hade pratat avslappnat, mannen med nacken lutad och blottad, tills hon n\u00e4mnde hans ex-fru \u2014 nacken stelnade p\u00e5 ett \u00f6gonblick, en s\u00e4ker signal att n\u00e5got var fel.", case_study_cloze: "En person som g\u00e5r fr\u00e5n ett avslappnat tillst\u00e5nd till att nacken snabbt ____ visar hypervaksamhet och vaksamhet \u2014 ett s\u00e4kert tecken p\u00e5 att n\u00e5got \u00e4r fel." } },
      { concept: "KOWTOWING", definition: "This is a slight bending forward of the upper torso and shoulders, which may be intentional or subconscious. Around the globe, it is performed in some variant in the presence of a higher authority. In Asia, people bow out of respect, just as the queen's subjects do in London. The origin of kowtowing has much to do with our primate legacy, where everyone bends lower to the alpha male-in our case, someone of higher authority. As a testament to its universality, when the conquistadores reached the New World, they found that Native Americans also bowed or kowtowed to their king, just as they themselves had done in Queen Isabella's court.", category: "body-language-extracted", real_world_scenario: "In the boardroom, the junior manager bent his upper torso forward slightly every time the CEO spoke, kowtowing to the higher authority just as courtiers once bowed to the queen.", case_study_cloze: "Around the globe, people perform a slight bending forward of the upper torso in the presence of a higher ____ \u2014 a vestige of our primate legacy.", sv: { concept: "Kowtow-bugning", definition: "Detta \u00e4r en l\u00e4tt fram\u00e5tb\u00f6jning av \u00f6verkroppen och axlarna, som kan vara avsiktlig eller omedveten. Runt om i v\u00e4rlden utf\u00f6rs den i n\u00e5gon variant i n\u00e4rvaro av en h\u00f6gre auktoritet. I Asien bugar m\u00e4nniskor av respekt, precis som drottningens unders\u00e5tar g\u00f6r i London. Ursprunget till kowtow har mycket att g\u00f6ra med v\u00e5rt primatarv, d\u00e4r alla b\u00f6jer sig l\u00e4gre f\u00f6r alfahanen \u2014 i v\u00e5rt fall n\u00e5gon med h\u00f6gre auktoritet. Som ett bevis p\u00e5 dess universalitet: n\u00e4r conquistadorerna n\u00e5dde Nya v\u00e4rlden fann de att urinv\u00e5narna ocks\u00e5 bugade eller kowtowade inf\u00f6r sin kung, precis som de sj\u00e4lva hade gjort i drottning Isabellas hov.", real_world_scenario: "I styrelserummet lutade den yngre managern \u00f6verkroppen l\u00e4tt fram\u00e5t varje g\u00e5ng vd:n talade, och bugade sig inf\u00f6r den h\u00f6gre auktoriteten precis som hovm\u00e4n en g\u00e5ng bugade inf\u00f6r drottningen.", case_study_cloze: "Runt om i v\u00e4rlden utf\u00f6r m\u00e4nniskor en l\u00e4tt fram\u00e5tb\u00f6jning av \u00f6verkroppen i n\u00e4rvaro av en h\u00f6gre ____ \u2014 ett arv fr\u00e5n v\u00e5rt primatf\u00f6rflutna." } },
      { concept: "HUGGING", definition: "Hugging, in all its forms, is universally indicative of closeness, good feelings, warmth, and cooperation. While in some cultures a brief social hug, an abrazo (in Latin America), can serve as a greeting gesture similar to shaking hands, how it is performed can indicate how the participants feel about each other. Consider American athletes and movie stars giving each other bro hugs. As an observer, I always note the hug and the facial expressions to give me a reliable sense of how two individuals really feel about each other.", category: "body-language-extracted", real_world_scenario: "At the family reunion, the two brothers who had been estranged for years gave each other a long, tight embrace; watching their faces during the hug told the whole story of their reconciliation.", case_study_cloze: "A long, tight ____ with warm facial expressions indicates closeness, while a brief social abrazo may merely serve as a greeting, like a handshake.", sv: { concept: "Kramar", definition: "Kramar, i alla former, \u00e4r universellt ett tecken p\u00e5 n\u00e4rhet, goda k\u00e4nslor, v\u00e4rme och samarbete. Medan en kort social kram i vissa kulturer, en abrazo (i Latinamerika), kan fungera som en h\u00e4lsningsgest liknande handskakning, kan hur den utf\u00f6rs visa hur deltagarna k\u00e4nner f\u00f6r varandra. T\u00e4nk p\u00e5 amerikanska idrottare och filmstj\u00e4rnor som ger varandra bro-kramar. Som observat\u00f6r noterar jag alltid kramen och ansiktsuttrycken f\u00f6r att f\u00e5 en tillf\u00f6rlitlig k\u00e4nsla av hur tv\u00e5 individer verkligen k\u00e4nner f\u00f6r varandra.", real_world_scenario: "P\u00e5 sl\u00e4ktkalaset gav de tv\u00e5 br\u00f6derna, som varit ov\u00e4nner i flera \u00e5r, varandra en l\u00e5ng, h\u00e5rd kram; att se deras ansikten under kramen ber\u00e4ttade hela historien om deras f\u00f6rsoning.", case_study_cloze: "En l\u00e5ng, h\u00e5rd ____ med varma ansiktsuttryck tyder p\u00e5 n\u00e4rhet, medan en kort social abrazo bara kan fungera som en h\u00e4lsning, likt en handskakning." } },
      { concept: "ELBOWS SPREADING OUT", definition: "When people are strong and confident, they will gradually take up more space, spreading their elbows across a table or desk. This tends to be subconscious, and they are generally not aware that they are publicizing their self-assuredness.", category: "body-language-extracted", real_world_scenario: "In the sales negotiation, the confident vendor slowly spread his elbows across the table, taking up more and more space without realizing it \u2014 his self-assuredness was publicizing itself.", case_study_cloze: "When people are strong and confident, they subconsciously take up more space by spreading their ____ across a table or desk.", sv: { concept: "Armb\u00e5gar som sprids ut", definition: "N\u00e4r m\u00e4nniskor \u00e4r starka och sj\u00e4lvs\u00e4kra tar de gradvis upp mer plats och sprider ut armb\u00e5garna \u00f6ver ett bord eller skrivbord. Detta tenderar att vara omedvetet, och de \u00e4r vanligtvis inte medvetna om att de offentligg\u00f6r sin sj\u00e4lvs\u00e4kerhet.", real_world_scenario: "I s\u00e4ljf\u00f6rhandlingen spred den sj\u00e4lvs\u00e4kre s\u00e4ljaren l\u00e5ngsamt ut armb\u00e5garna \u00f6ver bordet och tog upp mer och mer plats utan att m\u00e4rka det \u2014 hans sj\u00e4lvs\u00e4kerhet offentliggjorde sig sj\u00e4lv.", case_study_cloze: "N\u00e4r m\u00e4nniskor \u00e4r starka och sj\u00e4lvs\u00e4kra tar de omedvetet upp mer plats genom att sprida ut ____ \u00f6ver ett bord eller skrivbord." } },
      { concept: "SELF", definition: "TOUCHING WHILE ANSWERING -Take notice of people who while answering a question are pacifying (any hand-to-body touching or stroking)", category: "body-language-extracted", real_world_scenario: "During the interview, whenever the applicant mentioned her previous employer, she stroked her arm and touched her neck \u2014 self-touching while answering a question is a pacifying behavior worth noticing.", case_study_cloze: "Take notice when a person answers a question while touching or stroking parts of their body \u2014 such ____ behavior signals discomfort or stress.", sv: { concept: "Sj\u00e4lvber\u00f6ring vid svar", definition: "SJ\u00c4LVBER\u00d6RING VID SVAR -L\u00e4gg m\u00e4rke till m\u00e4nniskor som medan de svarar p\u00e5 en fr\u00e5ga lugnar sig sj\u00e4lva (genom vilken hand-till-kropp-ber\u00f6ring eller strykning som helst).", real_world_scenario: "Under intervjun str\u00f6k s\u00f6kanden sig \u00f6ver armen och r\u00f6rde vid nacken varje g\u00e5ng hon n\u00e4mnde sin f\u00f6rra arbetsgivare \u2014 sj\u00e4lvber\u00f6ring medan man svarar p\u00e5 en fr\u00e5ga \u00e4r ett lugnande beteende v\u00e4rt att notera.", case_study_cloze: "L\u00e4gg m\u00e4rke till n\u00e4r en person svarar p\u00e5 en fr\u00e5ga samtidigt som de r\u00f6r vid eller stryker delar av kroppen \u2014 s\u00e5dan ____ signalerar obehag eller stress." } },
      { concept: "PALMS", definition: "UP DISPLAY -Also known as the rogatory hand position, this is a universal behavior of humility, compliance, or cooperation, used by people who want to be accepted or believed. The presentation of the palms of the hands facing up is a universal way of saying \\\"My hands are clean,\\\" \\\"There is nothing hidden here,\\\" \\\"I implore you,\\\" or \\\"I am at your command.\\\" It is also used in religious ceremonies to demonstrate humility and piety.", category: "body-language-extracted", real_world_scenario: "The pastor opened his hands, palms facing up, as he asked the congregation for forgiveness \u2014 the universal gesture of humility and openness that says 'my hands are clean.'", case_study_cloze: "Showing the palms of the hands facing up is a universal way of saying 'I implore you' or 'there is nothing hidden here' \u2014 a display of ____ and cooperation.", sv: { concept: "Upp\u00e5tv\u00e4nda handflator", definition: "UPP\u00c5TV\u00c4NDA HANDFLATOR -\u00c4ven k\u00e4nd som den rogatoriska handpositionen, detta \u00e4r ett universellt beteende av \u00f6dmjukhet, undergivenhet eller samarbetsvilja, som anv\u00e4nds av m\u00e4nniskor som vill bli accepterade eller trodda. Att visa upp\u00e5tv\u00e4nda handflator \u00e4r ett universellt s\u00e4tt att s\u00e4ga 'mina h\u00e4nder \u00e4r rena', 'det finns inget dolt h\u00e4r', 'jag b\u00f6nfaller dig' eller 'jag st\u00e5r till ditt f\u00f6rfogande'. Det anv\u00e4nds ocks\u00e5 i religi\u00f6sa ceremonier f\u00f6r att visa \u00f6dmjukhet och fromhet.", real_world_scenario: "Pastorn \u00f6ppnade h\u00e4nderna med handflatorna upp\u00e5t n\u00e4r han bad f\u00f6rsamlingen om f\u00f6rl\u00e5telse \u2014 den universella gesten av \u00f6dmjukhet och \u00f6ppenhet som s\u00e4ger 'mina h\u00e4nder \u00e4r rena'.", case_study_cloze: "Att visa upp\u00e5tv\u00e4nda handflator \u00e4r ett universellt s\u00e4tt att s\u00e4ga 'jag b\u00f6nfaller dig' eller 'det finns inget dolt h\u00e4r' \u2014 en uppvisning av ____ och samarbetsvilja." } },
      { concept: "FINGERS CLOSE TOGETHER", definition: "When we feel concerned, bewildered, humbled, scared, or cornered, we subconsciously make the space between our fingers smaller. In the extreme, when we are very concerned, we curl up our fingers so they are not sticking out. Here, our limbic brain ensures that our fingers are not loose when there is a threat.", category: "body-language-extracted", real_world_scenario: "As the headmaster read out the list of students who had to retake the exam, the boy in the back row curled his fingers tightly together, making his hands small \u2014 his limbic brain shrinking the threat.", case_study_cloze: "When we feel scared or cornered, our limbic brain makes us subconsciously make the space between our ____ smaller.", sv: { concept: "Fingrar t\u00e4tt ihop", definition: "N\u00e4r vi k\u00e4nner oss bekymrade, f\u00f6rvirrade, \u00f6dmjukade, r\u00e4dda eller tr\u00e4ngda minskar vi omedvetet utrymmet mellan fingrarna. I extremen, n\u00e4r vi \u00e4r mycket bekymrade, knyter vi fingrarna s\u00e5 att de inte sticker ut. H\u00e4r ser v\u00e5r limbiska hj\u00e4rna till att fingrarna inte \u00e4r l\u00f6sa n\u00e4r det finns ett hot.", real_world_scenario: "N\u00e4r rektorn l\u00e4ste upp listan \u00f6ver elever som m\u00e5ste skriva om provet kn\u00f6t pojken i sista raden fingrarna h\u00e5rt ihop och gjorde h\u00e4nderna sm\u00e5 \u2014 den limbiska hj\u00e4rnan som krympte hotet.", case_study_cloze: "N\u00e4r vi k\u00e4nner oss r\u00e4dda eller tr\u00e4ngda ser v\u00e5r limbiska hj\u00e4rna till att vi omedvetet minskar utrymmet mellan ____." } },
      { concept: "HOLDING ON TO FURNITURE", definition: "If people hold on to their chair, or the edge of a desk or podium, as they make a declarative statement, they are communicating doubt and insecurity. I have sometimes seen this when people sign a contract they are reluctant to endorse but must. As an observer, you should always question what insecurity is driving this", category: "body-language-extracted", real_world_scenario: "As the executive signed the merger agreement he had privately opposed, he gripped the edge of the conference table with his free hand \u2014 doubt and insecurity visible despite his confident words.", case_study_cloze: "When someone grips the edge of a desk or podium while making a declarative statement, they are communicating ____ and insecurity.", sv: { concept: "Att h\u00e5lla i m\u00f6bler", definition: "Om m\u00e4nniskor h\u00e5ller i stolen eller kanten p\u00e5 ett skrivbord eller podium n\u00e4r de g\u00f6r ett best\u00e4mt uttalande, kommunicerar de tvivel och os\u00e4kerhet. Jag har ibland sett detta n\u00e4r m\u00e4nniskor skriver under ett kontrakt de motvilligt godk\u00e4nner men m\u00e5ste. Som observat\u00f6r b\u00f6r du alltid ifr\u00e5gas\u00e4tta vilken os\u00e4kerhet som driver detta.", real_world_scenario: "N\u00e4r direkt\u00f6ren skrev under sammanslagningsavtalet han privat motsatt sig greppade han med den lediga handen om kanten p\u00e5 konferensbordet \u2014 tvivel och os\u00e4kerhet synliga trots de sj\u00e4lvs\u00e4kra orden.", case_study_cloze: "N\u00e4r n\u00e5gon h\u00e5ller i kanten av ett skrivbord eller podium samtidigt som de g\u00f6r ett best\u00e4mt uttalande, kommunicerar de ____ och os\u00e4kerhet." } },
      { concept: "GIVING THE FINGER", definition: "Pioneering psychologist Paul Ekman first noted how individuals who harbor animosity toward others will subconsciously give \\\"the finger\\\" (the indecent finger is usually the middle or longest finger as in \\\"F-- you!\\\") by scratching their face or body with it, or even just pushing their eyeglasses back into place. It is a subconscious sign of disrespect.", category: "body-language-extracted", real_world_scenario: "During the disciplinary meeting, the angry employee kept pushing his eyeglasses back into place with his middle finger \u2014 a subconscious 'giving the finger' that revealed his animosity without a word.", case_study_cloze: "People who harbor animosity may subconsciously give 'the finger' by scratching their face with it or pushing their ____ back into place.", sv: { concept: "Att ge l\u00e5ngfingret", definition: "Pionj\u00e4rpsykologen Paul Ekman noterade f\u00f6rst hur individer som hyser fiendskap mot andra omedvetet ger 'l\u00e5ngfingret' (det oanst\u00e4ndiga fingret \u00e4r vanligtvis l\u00e5ngfingret, som i 'F-- you!') genom att klia sig i ansiktet eller p\u00e5 kroppen med det, eller till och med bara genom att skjuta tillbaka glas\u00f6gonen. Det \u00e4r en omedveten signal om respektl\u00f6shet.", real_world_scenario: "Under arbetsplatstr\u00e4ffen fortsatte den arga medarbetaren att skjuta tillbaka glas\u00f6gonen med l\u00e5ngfingret \u2014 ett omedvetet 'l\u00e5ngfinger' som avsl\u00f6jade hans fiendskap utan ett ord.", case_study_cloze: "M\u00e4nniskor som hyser fiendskap kan omedvetet ge 'l\u00e5ngfingret' genom att klia sig i ansiktet med det eller skjuta tillbaka ____ med det." } },
      { concept: "PREENING", definition: "It is not only birds that preen. Preening can take many forms: adjusting a tie, repositioning a bracelet, smoothing out a wrinkle on a shirt, fixing one's hair, reapplying lipstick, plucking an eyebrow. We preen when we care enough to want to look our best. Hair preening when we are interested in someone romantically is especially common. The repeated stroking of the hair also gets us noticed. Interestingly, when attorneys do something so simple as pulling at their jacket (a preening behavior) as the jury enters the room, they are subconsciously perceived by jurors as more likable.", category: "body-language-extracted", real_world_scenario: "Before her date arrived, she checked her reflection, smoothed her dress and ran her fingers through her hair \u2014 preening that said she cared enough to look her best.", case_study_cloze: "Adjusting a tie, fixing one's hair or reapplying lipstick are all forms of ____, grooming behaviors we perform when we care about looking our best.", sv: { concept: "Sj\u00e4lvputsning", definition: "Det \u00e4r inte bara f\u00e5glar som putsar sig. Putsning kan ta m\u00e5nga former: justera en slips, flytta p\u00e5 ett armband, sl\u00e4ta ut en skrynkla p\u00e5 en skjorta, fixa h\u00e5ret, l\u00e4gga om l\u00e4ppstiftet, plocka ett \u00f6gonbryn. Vi putsar oss n\u00e4r vi bryr oss tillr\u00e4ckligt f\u00f6r att vilja se ut som b\u00e4st. H\u00e5rputsning n\u00e4r vi \u00e4r romantiskt intresserade av n\u00e5gon \u00e4r s\u00e4rskilt vanlig. Att upprepat stryka \u00f6ver h\u00e5ret g\u00f6r ocks\u00e5 att vi blir uppm\u00e4rksammade. Intressant nog, n\u00e4r advokater g\u00f6r n\u00e5got s\u00e5 enkelt som att dra i jackan (ett putsningsbeteende) n\u00e4r juryn kommer in i rummet, uppfattas de undermedvetet av jurymedlemmarna som mer sympatiska.", real_world_scenario: "Innan dejten kom tittade hon sig i spegeln, sl\u00e4tade ut kl\u00e4nningen och drog fingrarna genom h\u00e5ret \u2014 putsning som visade att hon brydde sig tillr\u00e4ckligt f\u00f6r att se ut som b\u00e4st.", case_study_cloze: "Att justera en slips, fixa h\u00e5ret eller l\u00e4gga om l\u00e4ppstiftet \u00e4r alla former av ____, beteenden vi utf\u00f6r n\u00e4r vi bryr oss om att se ut som b\u00e4st." } },
      { concept: "PREENING (DISMISSIVE)", definition: "There is another kind of preening, intended to be dismissive or disrespectful-almost the opposite of what I just described. The act of picking lint or hair from clothes or cleaning one's nails when being addressed by another person is inconsiderate at best, disrespectful, even contemptuous, at worst.", category: "body-language-extracted", real_world_scenario: "While her colleague explained the project delays, the manager picked lint off her jacket and cleaned her nails without looking up \u2014 a dismissive form of preening that was contemptuous at worst.", case_study_cloze: "Picking lint or hair from one's clothes while another person is speaking is an inconsiderate form of ____ meant to be dismissive.", sv: { concept: "Sj\u00e4lvputsning (avf\u00e4rdande)", definition: "Det finns en annan typ av putsning, avsedd att vara avf\u00e4rdande eller respektl\u00f6s \u2014 n\u00e4stan motsatsen till det jag just beskrev. Att plocka ludd eller h\u00e5r fr\u00e5n kl\u00e4derna eller reng\u00f6ra naglarna n\u00e4r man tilltalas av en annan person \u00e4r h\u00e4nsynsl\u00f6st i b\u00e4sta fall, respektl\u00f6st, till och med f\u00f6raktfullt i v\u00e4rsta fall.", real_world_scenario: "Medan hennes kollega f\u00f6rklarade projektets f\u00f6rseningar plockade chefen ludd fr\u00e5n jackan och rengjorde naglarna utan att titta upp \u2014 en avf\u00e4rdande form av putsning som i v\u00e4rsta fall var f\u00f6raktfull.", case_study_cloze: "Att plocka ludd eller h\u00e5r fr\u00e5n kl\u00e4derna medan en annan person talar \u00e4r en h\u00e4nsynsl\u00f6s form av ____ som \u00e4r avsedd att vara avf\u00e4rdande." } },
      { concept: "NAMASTE", definition: "In this traditional Indian greeting, the hands are placed palms together directly in front of the chest, fingers pointed upward, elbows out, sometimes followed with a small bow or forward lean and a smile. It is used as a formal greeting-in a sense it replaces the handshake-and can also be used to say \\\"so long.\\\" This gesture has a deeper meaning than the Western handshake and must be received with respect.", category: "body-language-extracted", real_world_scenario: "When the guest of honor arrived at the wedding in Mumbai, the host pressed his palms together in front of his chest, fingers pointing up, and bowed slightly \u2014 a namaste that replaced the handshake with respect.", case_study_cloze: "In the traditional Indian greeting, the hands are placed palms together in front of the chest, sometimes followed by a small bow \u2014 this gesture is called ____.", sv: { concept: "Namaste", definition: "I denna traditionella indiska h\u00e4lsning placeras h\u00e4nderna med handflatorna ihop direkt framf\u00f6r br\u00f6stet, fingrarna pekande upp\u00e5t, armb\u00e5garna ut, ibland f\u00f6ljt av en liten bugning eller fram\u00e5tlutning och ett leende. Det anv\u00e4nds som en formell h\u00e4lsning \u2014 i viss mening ers\u00e4tter den handskakningen \u2014 och kan ocks\u00e5 anv\u00e4ndas f\u00f6r att s\u00e4ga 'hej d\u00e5'. Denna gest har en djupare betydelse \u00e4n den v\u00e4sterl\u00e4ndska handskakningen och m\u00e5ste tas emot med respekt.", real_world_scenario: "N\u00e4r hedersg\u00e4sten anl\u00e4nde till br\u00f6llopet i Mumbai tryckte v\u00e4rden ihop handflatorna framf\u00f6r br\u00f6stet med fingrarna upp\u00e5t och bugade l\u00e4tt \u2014 en namaste som ersatte handskakningen med respekt.", case_study_cloze: "I den traditionella indiska h\u00e4lsningen placeras h\u00e4nderna med handflatorna ihop framf\u00f6r br\u00f6stet, ibland f\u00f6ljt av en liten bugning \u2014 denna gest kallas ____." } },
      { concept: "LEANING AWAY", definition: "Leaning away from a person is a form of distancing. If we are sitting next to someone who says something objectionable, we may subtly inch away from him. We often see this on talk shows. Rarely do we realize just how far away we lean from others when we find them disagreeable.", category: "body-language-extracted", real_world_scenario: "On the talk show, the guest leaned back and inched away from the host whenever politics came up; the harder the host pushed, the farther the guest's chair seemed to move.", case_study_cloze: "If we sit next to someone who says something objectionable, we may subtly ____ from them, rarely realizing how far we actually lean.", sv: { concept: "Att luta sig bort", definition: "Att luta sig bort fr\u00e5n en person \u00e4r en form av distansering. Om vi sitter bredvid n\u00e5gon som s\u00e4ger n\u00e5got anst\u00f6tligt kan vi om\u00e4rkligt krypa undan fr\u00e5n honom eller henne. Vi ser detta ofta p\u00e5 talkshows. S\u00e4llan inser vi hur l\u00e5ngt vi lutar oss bort fr\u00e5n andra n\u00e4r vi finner dem motbjudande.", real_world_scenario: "I talkshowen lutade sig g\u00e4sten tillbaka och kr\u00f6p undan fr\u00e5n programledaren varje g\u00e5ng politik kom p\u00e5 tal; ju h\u00e5rdare programledaren pressade, desto l\u00e4ngre verkade g\u00e4stens stol glida bort.", case_study_cloze: "Om vi sitter bredvid n\u00e5gon som s\u00e4ger n\u00e5got anst\u00f6tligt kan vi om\u00e4rkligt ____ fr\u00e5n personen, s\u00e4llan medvetna om hur l\u00e5ngt vi faktiskt lutar oss bort." } },
      { concept: "BELLY/VENTRAL COVERING", definition: "The sudden covering of the belly with objects such as a purse or book bag suggests insecurity or discomfort with what is being discussed. People will use everything from pillows (a couple arguing at home) to pets to their own knees to protect their ventral side when they feel threatened or vulnerable.", category: "body-language-extracted", real_world_scenario: "At the family dinner, when the topic of the eviction notice came up, the mother pulled the cushion from the sofa onto her lap and hugged it \u2014 covering her ventral side against the uncomfortable subject.", case_study_cloze: "Suddenly covering the belly with a purse, book bag or pillow suggests ____ or discomfort with what is being discussed.", sv: { concept: "T\u00e4ckande av buken", definition: "Att pl\u00f6tsligt t\u00e4cka buken med f\u00f6rem\u00e5l som en handv\u00e4ska eller skolv\u00e4ska tyder p\u00e5 os\u00e4kerhet eller obehag inf\u00f6r det som diskuteras. M\u00e4nniskor anv\u00e4nder allt fr\u00e5n kuddar (ett par som br\u00e5kar hemma) till husdjur och sina egna kn\u00e4n f\u00f6r att skydda ventralsidan n\u00e4r de k\u00e4nner sig hotade eller s\u00e5rbara.", real_world_scenario: "P\u00e5 familjemiddagen, n\u00e4r \u00e4mnet vr\u00e4kningsbeskedet kom p\u00e5 tal, drog mamman soffkudden ner i kn\u00e4t och kramade den \u2014 t\u00e4ckande av ventralsidan mot det obekv\u00e4ma \u00e4mnet.", case_study_cloze: "Att pl\u00f6tsligt t\u00e4cka buken med en handv\u00e4ska, skolv\u00e4ska eller kudde tyder p\u00e5 ____ eller obehag inf\u00f6r det som diskuteras." } },
      { concept: "EJECTION", definition: "SEAT EFFECT -A person in a stressful interview or who has been accused of something might sit in a chair as if ready to be ejected from a military jet, gripping the armrests tightly. This, too, is part of the freeze response, and indicates deep distress or feeling threatened. What makes this behavior stand out is how rigid these individuals look, as if hanging on metaphorically for dear life.", category: "body-language-extracted", real_world_scenario: "In the disciplinary hearing, the accused accountant sat bolt upright, gripping the armrests of the chair as if bracing for ejection from a jet \u2014 rigid and frozen, as part of the freeze response.", case_study_cloze: "A person who sits gripping the armrests tightly, as if ready to be ejected from a military jet, is showing the ____ \u2014 part of the freeze response.", sv: { concept: "Katapultstolseffekten", definition: "KATAPULTSTOLSEFFEKTEN -En person i en stressig intervju, eller n\u00e5gon som anklagats f\u00f6r n\u00e5got, kan sitta i en stol som om de vore redo att kastas ut ur ett milit\u00e4rt jetplan, med h\u00e5rt grepp om armst\u00f6den. Detta \u00e4r ocks\u00e5 en del av frysresponsen och tyder p\u00e5 djup \u00e5ngest eller en k\u00e4nsla av hot. Det som g\u00f6r detta beteende s\u00e5 utm\u00e4rkande \u00e4r hur stela dessa individer ser ut, som om de h\u00e4ngde kvar, bildligt talat, f\u00f6r livet.", real_world_scenario: "I det disciplin\u00e4ra samtalet satt den anklagade revisorn spikrakt, med h\u00e5rt grepp om stolens armst\u00f6d som om hon f\u00f6rberedde sig f\u00f6r utskjutning ur ett jetplan \u2014 stel och frusen, som en del av frysresponsen.", case_study_cloze: "En person som sitter med h\u00e5rt grepp om armst\u00f6den, som om de vore redo att kastas ut ur ett milit\u00e4rt jetplan, uppvisar ____ \u2014 en del av frysresponsen." } },
      { concept: "HIP SWAYING", definition: "When bored, we might find ourselves standing and swaying our hips side to side, as if cradling and rocking a baby to sleep. Swaying our hips causes the fluid and hairs in our inner ear to move, and that sensation is very soothing. This is different from hip-torso rocking ( see #353), which is forward and back.", category: "body-language-extracted", real_world_scenario: "Waiting in the long checkout line, the bored shopper began to sway her hips gently side to side, rocking as if cradling a baby \u2014 the movement soothes by gently stimulating the inner ear.", case_study_cloze: "When bored, we may stand and sway our ____ side to side; the sensation of the inner-ear fluid moving is very soothing.", sv: { concept: "Att sv\u00e4nga p\u00e5 h\u00f6fterna", definition: "N\u00e4r vi \u00e4r uttr\u00e5kade kan vi st\u00e5 och sv\u00e4nga h\u00f6fterna fr\u00e5n sida till sida, som om vi vagga ett barn till s\u00f6mns. Att sv\u00e4nga h\u00f6fterna f\u00e5r v\u00e4tskan och h\u00e5ren i inner\u00f6rat att r\u00f6ra sig, och den k\u00e4nslan \u00e4r mycket lugnande. Detta skiljer sig fr\u00e5n h\u00f6ft-\u00f6verkroppsvaggande (se #353), som \u00e4r fram och tillbaka.", real_world_scenario: "Medan hon v\u00e4ntade i den l\u00e5nga k\u00f6n i mataff\u00e4ren b\u00f6rjade den uttr\u00e5kade kunden sv\u00e4nga h\u00f6fterna f\u00f6rsiktigt fr\u00e5n sida till sida, vaggande som om hon h\u00f6ll ett barn \u2014 r\u00f6relsen lugnar genom att f\u00f6rsiktigt stimulera inner\u00f6rat.", case_study_cloze: "N\u00e4r vi \u00e4r uttr\u00e5kade kan vi st\u00e5 och sv\u00e4nga ____ fr\u00e5n sida till sida; k\u00e4nslan av att v\u00e4tskan i inner\u00f6rat r\u00f6r sig \u00e4r mycket lugnande." } },
      { concept: "TERRITORIAL CHALLENGE", definition: "During a heated argument a person might intentionally invade your personal space, getting just inches away from your face (figuratively \\\"in your face\\\"), puffing out the chest, and glaring. This violation of space serves to intimidate, and might be a prelude to a physical assault.", category: "body-language-extracted", real_world_scenario: "In the parking-lot argument, the angry driver stepped inches from the other man's face, puffed out his chest and glared \u2014 a territorial challenge that invaded personal space and threatened violence.", case_study_cloze: "During a heated argument, a person who invades your personal space, puffing out the chest and glaring, is making a ____.", sv: { concept: "Territoriell utmaning", definition: "Under ett h\u00e4ftigt gr\u00e4l kan en person medvetet invadera ditt personliga utrymme, komma bara centimeter fr\u00e5n ditt ansikte (bildligt talat 'mitt i ansiktet p\u00e5 dig'), med uppsv\u00e4lld br\u00f6stkorg och gl\u00f6dande blick. Denna kr\u00e4nkning av utrymmet syftar till att skr\u00e4mmas och kan vara en upptakt till ett fysiskt \u00f6verfall.", real_world_scenario: "I br\u00e5ket p\u00e5 parkeringen klev den ilskna bilf\u00f6raren in p\u00e5 centimeteravst\u00e5nd fr\u00e5n den andra mannens ansikte, sp\u00e4nde br\u00f6stkorgen och glodde \u2014 en territoriell utmaning som invaderade det personliga utrymmet och hotade med v\u00e5ld.", case_study_cloze: "Under ett h\u00e4ftigt gr\u00e4l invaderar en person som tr\u00e4nger sig in p\u00e5 ditt personliga utrymme, sp\u00e4nner br\u00f6stkorgen och glodar, ditt utrymme i en ____." } },
      { concept: "KNEE", definition: "HIGH SELF-HUGGING -We often see teenagers hug their own legs by bringing the knees up to chest level. This can be very comforting and helps them enjoy a moment as they listen to music or to help them deal with emotions. I have also seen some criminals do this while being interviewed to help deal with stress.", category: "body-language-extracted", real_world_scenario: "The teenager curled up in the armchair, knees pulled to her chest, hugging her own legs as she listened to music \u2014 a self-hug that comforted her through the difficult day.", case_study_cloze: "Bringing the knees up to chest level and hugging one's own legs is a ____ behavior that comforts teenagers dealing with emotions.", sv: { concept: "Kn\u00e4h\u00f6g sj\u00e4lvkram", definition: "KN\u00c4H\u00d6G SJ\u00c4LVKRAM -Vi ser ofta ton\u00e5ringar krama sina egna ben genom att dra upp kn\u00e4na till br\u00f6sth\u00f6jd. Detta kan vara mycket tr\u00f6stande och hj\u00e4lper dem att njuta av ett \u00f6gonblick medan de lyssnar p\u00e5 musik eller hj\u00e4lper dem att hantera k\u00e4nslor. Jag har ocks\u00e5 sett vissa brottslingar g\u00f6ra detta under intervjuer f\u00f6r att hantera stress.", real_world_scenario: "Ton\u00e5ringen kr\u00f6p ihop i f\u00e5t\u00f6ljen med kn\u00e4na uppdragna mot br\u00f6stet och kramade sina egna ben medan hon lyssnade p\u00e5 musik \u2014 en sj\u00e4lvkram som tr\u00f6stade henne genom den sv\u00e5ra dagen.", case_study_cloze: "Att dra upp kn\u00e4na till br\u00f6sth\u00f6jd och krama sina egna ben \u00e4r ett ____ beteende som tr\u00f6star ton\u00e5ringar som hanterar k\u00e4nslor." } },
      { concept: "UNCOOPERATIVE LEGS AND FEET", definition: "Children and sometimes adults will", category: "body-language-extracted", real_world_scenario: "At the hair salon, the five-year-old refused to sit still, kicking her legs and wriggling her feet whenever the scissors came near \u2014 uncooperative legs and feet signaling that she did not want to be there.", case_study_cloze: "Children who do not want to do something will often show it through ____ legs and feet, kicking and wriggling in protest.", sv: { concept: "Omedg\u00f6rliga ben och f\u00f6tter", definition: "Barn och ibland vuxna sparkar med benen eller f\u00f6tterna, eller visar annars motst\u00e5nd med dem, n\u00e4r de inte vill g\u00f6ra det som kr\u00e4vs av dem.", real_world_scenario: "P\u00e5 frisersalongen v\u00e4grade fem\u00e5ringen att sitta still, sparkade med benen och vred p\u00e5 f\u00f6tterna varje g\u00e5ng saxen kom n\u00e4ra \u2014 omedg\u00f6rliga ben och f\u00f6tter som signalerade att hon inte ville vara d\u00e4r.", case_study_cloze: "Barn som inte vill g\u00f6ra n\u00e5got visar det ofta med ____ ben och f\u00f6tter, genom att sparka och vifta i protest." } },]
  }
];
